INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-analysis-qual-discourse-foucauldian-2', 'kg-analysis-qual-discourse-foucauldian', 2, 'بر اساس آثار فوکو، به بررسی «ارک» (dispositif)، رژیم‌های حقیقت، و شکل‌های قدرت می‌پردازد. در رسانه‌شناسی برای مطالعات نظارت، ژنرال‌سازی و ساخت‌هویت به‌کار می‌رود.', '43b3034ed7ff2c09ddf22351da60de2c49426cda8f2f39b1a843fcd7a309d2a5', 294, 'kc-kg-analysis-qual-discourse-foucauldian-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='43b3034ed7ff2c09ddf22351da60de2c49426cda8f2f39b1a843fcd7a309d2a5', token_count=294, vector_point_id='kc-kg-analysis-qual-discourse-foucauldian-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
