INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-analysis-qual-discourse-laclau-mouffe-2', 'kg-analysis-qual-discourse-laclau-mouffe', 2, 'با محوریت «هگemony in Post-Marxist Theory»، گفتمان را پدیدار سیاسی و ساخت‌هویت می‌داند. مفاهیمی چون گره‌زدن، چگال‌سازی، آنتاگونیسم و «نقطه‌ی بسته» (closure) ابزار تحلیل رسانه‌های سیاسی است.', '3930d1ecf7d0d03594dacee188f50c0072af47df1d53369b816fe56baaaba55d', 343, 'kc-kg-analysis-qual-discourse-laclau-mouffe-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3930d1ecf7d0d03594dacee188f50c0072af47df1d53369b816fe56baaaba55d', token_count=343, vector_point_id='kc-kg-analysis-qual-discourse-laclau-mouffe-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
