INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-analysis-qual-interp-herm-0', 'kg-analysis-qual-interp-herm', 1, 'تحلیل هرمنوتیکی (Hermeneutic Analysis) نوع: ANALYSIS دایره‌ی تفسیر: متن از درون و بافت، از طریق خوانش مکرر معنا می‌یابد.', 'd0008702b0a6245c7b2df412fe8df52facda705a38bb3edb2400b89868bf62fb', 218, 'kc-kg-analysis-qual-interp-herm-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d0008702b0a6245c7b2df412fe8df52facda705a38bb3edb2400b89868bf62fb', token_count=218, vector_point_id='kc-kg-analysis-qual-interp-herm-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
