INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-analysis-qual-phenomenological-ipa-0', 'kg-analysis-qual-phenomenological-ipa', 1, 'تحلیل پدیدارشناختی تفسیری (IPA) (Interpretative Phenomenological Analysis (IPA)) نوع: ANALYSIS تحلیل تفسیریِ تجربه‌ی زیسته با تأکید بر دوقطبی‌ی تجربه‌ی فردی و تفسیر محقق.', 'c1e38515df447ad759f63e8bdce1b977b178c767ccc8bbfa032a08f5db599075', 309, 'kc-kg-analysis-qual-phenomenological-ipa-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c1e38515df447ad759f63e8bdce1b977b178c767ccc8bbfa032a08f5db599075', token_count=309, vector_point_id='kc-kg-analysis-qual-phenomenological-ipa-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-analysis-qual-phenomenological-ipa-2', 'kg-analysis-qual-phenomenological-ipa', 2, 'با محوریت سیم و مک‌کارثی، IPA روی تجربه‌ی فردی و تفسیر محقق در هم‌زمانی تأکید دارد. برای مطالعات رسانه‌ایِ تجربه‌محور (مثلاً تجربه‌ی کاربری پلتفرم‌های رسانه) مناسب است.', '5c1de3bb86bda8a29c825239a6332204f1f1643133fb0522f292300210141267', 305, 'kc-kg-analysis-qual-phenomenological-ipa-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5c1de3bb86bda8a29c825239a6332204f1f1643133fb0522f292300210141267', token_count=305, vector_point_id='kc-kg-analysis-qual-phenomenological-ipa-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
