INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-analysis-qual-semiotic-barthes-0', 'kg-analysis-qual-semiotic-barthes', 1, 'تحلیل نشانه‌شناختی بارت (Barthesian Semiotic Analysis) نوع: ANALYSIS لایه‌ی دوگانه‌ی معنا (denotation/connotation) و اسطوره‌سازی در رسانه.', 'e8c9124548593ee9a12fc73e5d35de024e509c2eb14a4c3917fadd9a542c0369', 250, 'kc-kg-analysis-qual-semiotic-barthes-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e8c9124548593ee9a12fc73e5d35de024e509c2eb14a4c3917fadd9a542c0369', token_count=250, vector_point_id='kc-kg-analysis-qual-semiotic-barthes-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-analysis-qual-semiotic-barthes-2', 'kg-analysis-qual-semiotic-barthes', 2, 'بارت، معنای سطحی (denotation) و لایه‌ی دوم (connotation) را می‌گمارد و «اسطوره‌سازی» رسانه را تحلیل می‌کند. در تحلیل تصویر، لوگو و متن رسانه‌ای کاربرد گسترده دارد.', 'b5e4631541898e8bcf7d72a9bebdc90df205b1d2fc585232344c24ad784f91a9', 296, 'kc-kg-analysis-qual-semiotic-barthes-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b5e4631541898e8bcf7d72a9bebdc90df205b1d2fc585232344c24ad784f91a9', token_count=296, vector_point_id='kc-kg-analysis-qual-semiotic-barthes-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
