INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-analysis-qual-thematic-reflexive-0', 'kg-analysis-qual-thematic-reflexive', 1, 'تحلیل مضمون بازتابی (Reflexive Thematic Analysis) نوع: ANALYSIS شیوه‌ای که نقش فعال و تفسیری محقق را در انتخاب مضمون برجسته می‌کند.', 'edffad447e5f611339596b4a7d705baba338945c8e5eeec29961d2cdf6692508', 238, 'kc-kg-analysis-qual-thematic-reflexive-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='edffad447e5f611339596b4a7d705baba338945c8e5eeec29961d2cdf6692508', token_count=238, vector_point_id='kc-kg-analysis-qual-thematic-reflexive-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
