INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-classical-marxism-0', 'kg-approach-classical-marxism', 1, 'مارکسیسم کلاسیک (Classical Marxism) نوع: APPROACH رویکرد مبنا-فراساختاری (base-superstructure) که در آن رسانه، صنعت چاپ و نشر، زیرساخت اقتصادی را بازتاب می‌دهد.', 'f17b68c92288fef4100eaff700c2d3af21d43e809fdab56b93a6702e54f8b93e', 290, 'kc-kg-approach-classical-marxism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f17b68c92288fef4100eaff700c2d3af21d43e809fdab56b93a6702e54f8b93e', token_count=290, vector_point_id='kc-kg-approach-classical-marxism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-classical-marxism-2', 'kg-approach-classical-marxism', 2, 'در این رویکرد رسانه عین اقتصاد است؛ مالکیت رسانه‌ای همان مالکیت ابزار تولید است و پیام‌رسانی شکل نرم‌تر تبلیغات طبقاتی تلقی می‌شود.', '20160635935da0d5a29253cd50145cebbcab967c8d77870791fdb42b5f9668dd', 238, 'kc-kg-approach-classical-marxism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='20160635935da0d5a29253cd50145cebbcab967c8d77870791fdb42b5f9668dd', token_count=238, vector_point_id='kc-kg-approach-classical-marxism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-classical-marxism-3', 'kg-approach-classical-marxism', 3, 'مادی‌تاریخ و بنیان‌گرایی (base-superstructure).', 'fd2106c0ab191eb4cea2eeecb562ab47b3e86717d464b2940a02f36885743001', 85, 'kc-kg-approach-classical-marxism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fd2106c0ab191eb4cea2eeecb562ab47b3e86717d464b2940a02f36885743001', token_count=85, vector_point_id='kc-kg-approach-classical-marxism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
