INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-classical-positivism-0', 'kg-approach-classical-positivism', 1, 'اثبات‌گرایی کلاسیک (Classical Positivism) نوع: APPROACH صورت صریح و مطلق‌گرایانه‌ی اثبات‌گرایی؛ واقعیت عینی، حقیقت واحد و قابل‌کشف با روش‌های کمّی و قیاسی است.', '6cdf456c705bc88c86a9b0735845fd8738bfbda211420686033c7a5854fa8867', 289, 'kc-kg-approach-classical-positivism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6cdf456c705bc88c86a9b0735845fd8738bfbda211420686033c7a5854fa8867', token_count=289, vector_point_id='kc-kg-approach-classical-positivism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-classical-positivism-2', 'kg-approach-classical-positivism', 2, 'صورت کلاسیک و نهاد‌شناختی‌ترین پارادایم اثبات‌گرایی. در این رویکرد، حقیقت مطلق و عینی از داده‌های تجربی قابل‌کشف است و روش‌های کمّی تنها راه شناخت علمی معتبرند. در سند (بخش ۴) به‌عنوان زیرشاخه‌ی اثبات‌گرایی ثبت شده است.', '8a720e7d7e2d34d27f9e84df1f7c0988b6b02e200062ad5d29367d945da16a64', 398, 'kc-kg-approach-classical-positivism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8a720e7d7e2d34d27f9e84df1f7c0988b6b02e200062ad5d29367d945da16a64', token_count=398, vector_point_id='kc-kg-approach-classical-positivism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-classical-positivism-3', 'kg-approach-classical-positivism', 3, 'عینی‌گرایی مطلق؛ منطق قیاسی؛ بی‌طرفی پژوهشگر.', 'd14211cf58f3a45543cb65b8cd257c580291453c38e00d7d9129b38cec62a124', 81, 'kc-kg-approach-classical-positivism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d14211cf58f3a45543cb65b8cd257c580291453c38e00d7d9129b38cec62a124', token_count=81, vector_point_id='kc-kg-approach-classical-positivism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-classical-positivism-4', 'kg-approach-classical-positivism', 4, '["حقیقت واحد و مطلق، از داده‌های تجربی کشف می‌شود","روش‌های کمّی، تنها راه شناخت علمی معتبر است"]', 'fa26dfdd46c398355e9d1c203458d621c5b894fb226b2e73cbd0503d630669d8', 176, 'kc-kg-approach-classical-positivism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fa26dfdd46c398355e9d1c203458d621c5b894fb226b2e73cbd0503d630669d8', token_count=176, vector_point_id='kc-kg-approach-classical-positivism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
