INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-classical-pragmatism-2', 'kg-approach-classical-pragmatism', 2, 'پیرس معنای مفاهیم را «کلیه پیامدهای عملی ممکن» می‌داند؛ جیمز «عمل‌گرایی در تئوری» و دیویی «حل مسئله» و «آموزش‌محوری» را مطرح می‌کند.', '6d5157a6cd1291ddbe4f8293b6630c0b87bb1bf4933f9d6c762a7a803dce0022', 239, 'kc-kg-approach-classical-pragmatism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6d5157a6cd1291ddbe4f8293b6630c0b87bb1bf4933f9d6c762a7a803dce0022', token_count=239, vector_point_id='kc-kg-approach-classical-pragmatism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
