INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-co-created-knowledge-0', 'kg-approach-co-created-knowledge', 1, 'دانش هم‌آفرین (Co-created Knowledge) (Co-created Knowledge) نوع: APPROACH رویکردی که دانش را محصول تعامل پژوهشگر و موضوع می‌داند، نه صرفاً تولید یک‌جانبه‌ی پژوهشگر.', '9309c1c56c7dd42059bb06568b6d9b59a4854e4700e4e38528d5a1ada1bed60a', 298, 'kc-kg-approach-co-created-knowledge-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9309c1c56c7dd42059bb06568b6d9b59a4854e4700e4e38528d5a1ada1bed60a', token_count=298, vector_point_id='kc-kg-approach-co-created-knowledge-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-co-created-knowledge-2', 'kg-approach-co-created-knowledge', 2, 'در سند (بخش ۴) به‌عنوان زیرشاخه‌ی مشارکتی ثبت شده است. در پژوهش‌های مشارکتی، داده‌ها و تحلیل، هم‌زمان با موضوعات ساخته می‌شوند و نتیجه، متعلق به جامعه‌ی محلی است.', '1985b793025083d2a3908dd52992f563c83bacaa0022e93c66e40e285216d1db', 294, 'kc-kg-approach-co-created-knowledge-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1985b793025083d2a3908dd52992f563c83bacaa0022e93c66e40e285216d1db', token_count=294, vector_point_id='kc-kg-approach-co-created-knowledge-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
