INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-communicative-action-0', 'kg-approach-communicative-action', 1, 'کنش ارتباطی (Communicative Action) نوع: APPROACH کنش ارتباطی یورگن هابرماس که توافقی‌گرایی و عقلانیت ارتباطی را در مرکز قرار می‌دهد.', 'cb5c36c1f16b8e9dbf117790c6ba7a2c14fcb99965354003ae5a4ae88deeec65', 239, 'kc-kg-approach-communicative-action-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cb5c36c1f16b8e9dbf117790c6ba7a2c14fcb99965354003ae5a4ae88deeec65', token_count=239, vector_point_id='kc-kg-approach-communicative-action-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-communicative-action-2', 'kg-approach-communicative-action', 2, 'هابرماس کنش را دو نوع می‌داند: کنش استراتژیک (هدف‌محور) و کنش ارتباطی (توافق‌محور). در کنش ارتباطی، کنشگران برای رسیدن به «فهم مشترک» گفتگو می‌کنند. در رسانه، «میدان عمومی» و «گفتگوی عمومی» نمونه‌های بارز کنش ارتباطی است.', 'ab635da185aa9bf4555cf7d715b3f366e22a039efc711f1341fcfa5d5bf44804', 401, 'kc-kg-approach-communicative-action-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ab635da185aa9bf4555cf7d715b3f366e22a039efc711f1341fcfa5d5bf44804', token_count=401, vector_point_id='kc-kg-approach-communicative-action-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-communicative-action-3', 'kg-approach-communicative-action', 3, 'نظریه عمل ارتباطی هابرماس.', '75b1a38925b134df04b6c0ca1de98fbd944a2c921b85445329aa29d16c55af7b', 47, 'kc-kg-approach-communicative-action-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='75b1a38925b134df04b6c0ca1de98fbd944a2c921b85445329aa29d16c55af7b', token_count=47, vector_point_id='kc-kg-approach-communicative-action-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-communicative-action-4', 'kg-approach-communicative-action', 4, '["کنش ارتباطی برای فهم مشترک است","میدان عمومی مبنای کنش ارتباطی است"]', '9bebcefd90caa4da8202fc54994be0f1231a898ebded0c61fb5ccb6129bb7efd', 127, 'kc-kg-approach-communicative-action-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9bebcefd90caa4da8202fc54994be0f1231a898ebded0c61fb5ccb6129bb7efd', token_count=127, vector_point_id='kc-kg-approach-communicative-action-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
