INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-communicative-action-6', 'kg-approach-communicative-action', 6, '1981-2000', '2aa6540ae7bf5b4846e682e61d81ad74b3121d6f0bf0a6612f62d82087160864', 16, 'kc-kg-approach-communicative-action-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2aa6540ae7bf5b4846e682e61d81ad74b3121d6f0bf0a6612f62d82087160864', token_count=16, vector_point_id='kc-kg-approach-communicative-action-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-communicative-action-7', 'kg-approach-communicative-action', 7, '["Habermas (1981), Theory of Communicative Action"]', 'b7768cdddc184ae005d8140b62c3e6004106e74a2a72cb6824df3efa53e67c57', 92, 'kc-kg-approach-communicative-action-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b7768cdddc184ae005d8140b62c3e6004106e74a2a72cb6824df3efa53e67c57', token_count=92, vector_point_id='kc-kg-approach-communicative-action-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-complementary-0', 'kg-approach-complementary', 1, 'رویکردهای مکمل (تطبیقی، تاریخی، انتقادی، مشارکتی، طراحی‌محور، محاسباتی) (Complementary Approaches (Comparative, Historical, Critical, Participatory, Design-based, Computational)) نوع: APPROACH گروهی از رویکردهای روش‌شناختی که برای موضوعات و پرسش‌های خاص، فراتر از سه‌گانه‌ی کمّی/کیفی/آمیخته، به کار می‌روند.', 'beb508d4fad4821e8aed655de9fd2f47083e1c1a69c4c2f9bcd4573790602f48', 558, 'kc-kg-approach-complementary-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='beb508d4fad4821e8aed655de9fd2f47083e1c1a69c4c2f9bcd4573790602f48', token_count=558, vector_point_id='kc-kg-approach-complementary-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-complementary-2', 'kg-approach-complementary', 2, 'رویکردهای مکمل، روش‌شناسی‌هایی را در بر می‌گیرند که برای موضوعات و پرسش‌های خاص، فراتر از رویکردهای کمّی، کیفی و آمیخته، به کار می‌روند. این رویکردها شامل: پژوهش تطبیقی (مقایسه بین کشورها/فرهنگ‌ها/دوره‌ها)، پژوهش تاریخی (تحلیل اسناد و منابع تاریخی)، پژوهش انتقادی (افشای ایدئولوژی و قدرت)، پژوهش مشارکتی (هم‌آفرینی دانش با مشارکت‌کنندگان)، پژوهش مبتنی بر طراحی (design-based research) و پژوهش محاسباتی (تحلیل داده‌های بزرگ و الگوریتمی) است. این رویکردها می‌توانند روی مبانی فلسفی گوناگون (از اثبات‌گرایی تا انتقادی) استوار شوند و در علوم ارتباطات کاربرد گسترده دارند.', '6093f57f3722b7019194641021e666dd6f95bb5e20027afcba06faf2652b4d39', 1030, 'kc-kg-approach-complementary-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6093f57f3722b7019194641021e666dd6f95bb5e20027afcba06faf2652b4d39', token_count=1030, vector_point_id='kc-kg-approach-complementary-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-complementary-3', 'kg-approach-complementary', 3, 'هر یک از این رویکردها، ریشه در سنت‌های فکری گوناگونی دارد (تطبیقی در جامعه‌شناسی تطبیقی قرن نوزدهم، تاریخی در روش‌تاریخ‌نگاری انتظامی، انتقادی در مکتب فرانکفورت، مشارکتی در سنت فریره، طراحی‌محور در آموزش و فناوری، محاسباتی در علم داده و هوش مصنوعی).', '0c48691c66c12a38d2c7023a58501da35bed8beb066f038c3c7072d65c3f240f', 452, 'kc-kg-approach-complementary-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0c48691c66c12a38d2c7023a58501da35bed8beb066f038c3c7072d65c3f240f', token_count=452, vector_point_id='kc-kg-approach-complementary-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-complementary-4', 'kg-approach-complementary', 4, 'متنوع: از اثبات‌گرایی (در تطبیقی کمّی) تا انتقادی و پسااستعماری (در انتقادی) تا پراگماتیسم (در طراحی‌محور) تا عمل‌گرایی (در محاسباتی).', '50f7862170e6a4eb89ecbe7b0322b09244897e709dd5310f61b6e0b3faaba25c', 243, 'kc-kg-approach-complementary-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='50f7862170e6a4eb89ecbe7b0322b09244897e709dd5310f61b6e0b3faaba25c', token_count=243, vector_point_id='kc-kg-approach-complementary-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-complementary-5', 'kg-approach-complementary', 5, '["هر رویکرد مکمل، برای پرسش‌های خاص و بافت‌های خاص مناسب است","پژوهش تطبیقی، از مقایسه‌ی نظام‌مند بین نمونه‌ها استفاده می‌کند","پژوهش تاریخی، اسناد و منابع را به‌عنوان داده می‌شمارد","پژوهش محاسباتی، داده‌های بزرگ و الگوریتم‌ها را ابزار تحلیل می‌داند","پژوهش طراحی‌محور، هم‌زمان پژوهش و طراحی/ساخت است"]', '12d2d5b6cc509c258b537fb77109bdccc87a569b67cb4d132bf46c724c144f04', 550, 'kc-kg-approach-complementary-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='12d2d5b6cc509c258b537fb77109bdccc87a569b67cb4d132bf46c724c144f04', token_count=550, vector_point_id='kc-kg-approach-complementary-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-complementary-6', 'kg-approach-complementary', 6, '["پائولو فریره (مشارکتی)","کارل بوریس (انتقادی)","جان کریسول (تطبیقی)"]', '0a161b274c7f4f5de61da7e7caa40d8f527a7ff1a5c8d27458afb8c6fbf54bf2', 129, 'kc-kg-approach-complementary-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0a161b274c7f4f5de61da7e7caa40d8f527a7ff1a5c8d27458afb8c6fbf54bf2', token_count=129, vector_point_id='kc-kg-approach-complementary-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
