INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-complementary-12', 'kg-approach-complementary', 12, '["هر رویکرد، برای پرسش‌های خاص مناسب است و قابل تعمیم نیست","ممکن است مرز روش‌ها مبهم شود"]', '6195268d80f2de8df92251ada3fd13af595dd9a627b59cc8523910218b3a535f', 165, 'kc-kg-approach-complementary-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6195268d80f2de8df92251ada3fd13af595dd9a627b59cc8523910218b3a535f', token_count=165, vector_point_id='kc-kg-approach-complementary-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-complementary-13', 'kg-approach-complementary', 13, '["نقد پراگماتیست: ممکن است به «هر چه کار کند» تقلیل برسد","نقد انتقادی: ممکن است ساختار قدرت نادیده برود"]', '767cc9323a6c70a96f45fa97c44e18767f9f458ed6b78f747f767de62b132af8', 192, 'kc-kg-approach-complementary-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='767cc9323a6c70a96f45fa97c44e18767f9f458ed6b78f747f767de62b132af8', token_count=192, vector_point_id='kc-kg-approach-complementary-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
