INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-complex-systems-0', 'kg-approach-complex-systems', 1, 'سیستم‌های پیچیده (Complex Systems) نوع: APPROACH رویکرد به تحلیل سیستم‌های پیچیده با ویژگی‌های ناهمگن، غیرخطی و نوسانی.', '8baf44588aec89c3ab4f286fd473a8df490561b1fd12753fcb9a56aa54f558b7', 216, 'kc-kg-approach-complex-systems-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8baf44588aec89c3ab4f286fd473a8df490561b1fd12753fcb9a56aa54f558b7', token_count=216, vector_point_id='kc-kg-approach-complex-systems-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-complex-systems-2', 'kg-approach-complex-systems', 2, 'سیستم‌های پیچیده ویژگی‌هایی مانند «نوسانات» (emergence)، «نقطه عطف» (tipping points) و «عدم قطعیت» دارند؛ در رسانه، انتشار اطلاعات، شکل‌گیری شایعه و الگوریتم‌های شبکه‌های اجتماعی نمونه‌های بارز این سیستم‌هاست.', 'b440591033ac21ed7d95f73c6d49a7268b616c0e51ad2147cffab21c5f97209b', 379, 'kc-kg-approach-complex-systems-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b440591033ac21ed7d95f73c6d49a7268b616c0e51ad2147cffab21c5f97209b', token_count=379, vector_point_id='kc-kg-approach-complex-systems-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
