INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-crit-realism-post-0', 'kg-approach-crit-realism-post', 1, 'واقع‌گرایی انتقادی (در پساثبات‌گرایی) (Critical Realism (in Post-positivism)) نوع: APPROACH صورتی از پساثبات‌گرایی که واقعیت را دارای ساختارهای علّی پنهان می‌داند و پژوهش باید از سطح تجربه به ساختار برسد.', '7d85b8f13ef671e564a96115aa64bb2bec2667e1c45835b452756900fea75c35', 370, 'kc-kg-approach-crit-realism-post-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7d85b8f13ef671e564a96115aa64bb2bec2667e1c45835b452756900fea75c35', token_count=370, vector_point_id='kc-kg-approach-crit-realism-post-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-crit-realism-post-2', 'kg-approach-crit-realism-post', 2, 'در سند (بخش ۴) به‌عنوان زیرشاخه‌ی پساثبات‌گرایی ثبت شده است. این صورت، با واقع‌گرایی انتقادی به‌عنوان پارادایم مستقل (که در زیر پارادایم واقع‌گرایی ثبت شده) متمایز است؛ اینجا به‌عنوان زیرشاخه‌ی پساثبات‌گرایی استفاده می‌شود.', 'c29eb89f9a9203d6344f5dac83eefc60ce9c1709f7a1a557206cf638c2959f65', 405, 'kc-kg-approach-crit-realism-post-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c29eb89f9a9203d6344f5dac83eefc60ce9c1709f7a1a557206cf638c2959f65', token_count=405, vector_point_id='kc-kg-approach-crit-realism-post-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
