INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-critical-hermeneutics-0', 'kg-approach-critical-hermeneutics', 1, 'هرمنوتیک انتقادی (Critical Hermeneutics) نوع: APPROACH هرمنوتیک انتقادی پاول ریکور و یورگن هابرماس که تفسیر را با نقد ایدئولوژیک ترکیب می‌کند.', '43a53f1584535902b4dde7d94ee9a40afe9a34af3523ef4b1015eb47e6d76f39', 258, 'kc-kg-approach-critical-hermeneutics-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='43a53f1584535902b4dde7d94ee9a40afe9a34af3523ef4b1015eb47e6d76f39', token_count=258, vector_point_id='kc-kg-approach-critical-hermeneutics-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-critical-hermeneutics-2', 'kg-approach-critical-hermeneutics', 2, 'در هرمنوتیک انتقادی، تفسیر فقط فهم نیست بلکه «آزادسازی از ایدئولوژی» است. رسانه در این دیدگاه هم میدان فهم است و هم میدان ایدئولوژی که باید نقد شود.', '7a8b2046921b49868b9db39cbd681ff46d0a2d9758132c20c38feb93b87b2186', 269, 'kc-kg-approach-critical-hermeneutics-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7a8b2046921b49868b9db39cbd681ff46d0a2d9758132c20c38feb93b87b2186', token_count=269, vector_point_id='kc-kg-approach-critical-hermeneutics-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-critical-hermeneutics-3', 'kg-approach-critical-hermeneutics', 3, 'هرمنوتیک و نظریه انتقادی فراکفورت.', '0dda26cd3652cb6ced8e50347a71449fe1a864224ef09d6119ab0fb816d90cda', 61, 'kc-kg-approach-critical-hermeneutics-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0dda26cd3652cb6ced8e50347a71449fe1a864224ef09d6119ab0fb816d90cda', token_count=61, vector_point_id='kc-kg-approach-critical-hermeneutics-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
