INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-critical-realism-paradigm-0', 'kg-approach-critical-realism-paradigm', 1, 'واقع‌گرایی انتقادی (به‌عنوان پارادایم مستقل) (Critical Realism (as Standalone Paradigm)) نوع: APPROACH صورتی از واقع‌گرایی که واقعیت را لایه‌بندی‌شده می‌داند: سطح تجربه، سطح رخداد، و سطح ساختار علّی.', 'd94ffe093cf0519130b7aec1542bf130948d25aa0979c27c4bf0cbc7d02aa709', 361, 'kc-kg-approach-critical-realism-paradigm-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d94ffe093cf0519130b7aec1542bf130948d25aa0979c27c4bf0cbc7d02aa709', token_count=361, vector_point_id='kc-kg-approach-critical-realism-paradigm-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-critical-realism-paradigm-2', 'kg-approach-critical-realism-paradigm', 2, 'در سند (بخش ۴) به‌عنوان زیرشاخه‌ی واقع‌گرایی ثبت شده است (به‌عنوان پارادایم مستقل واقع‌گرایی، نه زیرشاخه‌ی پساثبات‌گرایی). با واقع‌گرایی انتقادی در پساثبات‌گرایی متمایز است.', '40cfa03ab7ca6bf536e4f31184d7705db51855f408627c6087371632fa426b5a', 314, 'kc-kg-approach-critical-realism-paradigm-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='40cfa03ab7ca6bf536e4f31184d7705db51855f408627c6087371632fa426b5a', token_count=314, vector_point_id='kc-kg-approach-critical-realism-paradigm-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
