INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-decolonial-knowledge-2', 'kg-approach-decolonial-knowledge', 2, 'در سند (بخش ۴) به‌عنوان زیرشاخه‌ی پسااستعماری ثبت شده است. در پژوهش‌های رسانه‌ای، تحلیل انتقادی رسانه‌های غربی و تولید دانش بومی، در این سنت جای می‌گیرد.', 'd591065394c90e47eda6269aeec91e861924e687503bc00b9f968d19c49bad16', 278, 'kc-kg-approach-decolonial-knowledge-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d591065394c90e47eda6269aeec91e861924e687503bc00b9f968d19c49bad16', token_count=278, vector_point_id='kc-kg-approach-decolonial-knowledge-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
