INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-decolonization-0', 'kg-approach-decolonization', 1, 'نظریه استعمارزدایی (Decolonial Theory) نوع: APPROACH نظریه استعمارزدایی که فراتر از «پسااستعمار» به «پساکلونیالیسم» و «پساستعمار» می‌پردازد.', 'bfb9f1439af0d670a3518d23d9c4d285ccb0541916ac9f8c2b059ba79530ab9d', 254, 'kc-kg-approach-decolonization-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bfb9f1439af0d670a3518d23d9c4d285ccb0541916ac9f8c2b059ba79530ab9d', token_count=254, vector_point_id='kc-kg-approach-decolonization-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-decolonization-2', 'kg-approach-decolonization', 2, 'در نظریه استعمارزدایی (Mignolo, Quijano, Maldonado-Torres)، ساختارهای قدرت استعماری در «متافیزیک کلاسیک» و «زبان و رسانه» بازتولید می‌شوند. رسانه در این دیدگاه ابزار کلیدی «پساکلونیالیسم» است.', '3811eb104de60fbcc7cd7e18e478553f48add5b69d9bf3cea9d794928cf0dc11', 349, 'kc-kg-approach-decolonization-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3811eb104de60fbcc7cd7e18e478553f48add5b69d9bf3cea9d794928cf0dc11', token_count=349, vector_point_id='kc-kg-approach-decolonization-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-decolonization-3', 'kg-approach-decolonization', 3, 'پساکلونیالیسم و جنوب جهانی.', '765f852b4603d752e6db274c8ea64685ba6abeb68cdc4786aca31bd95fbeb2c4', 49, 'kc-kg-approach-decolonization-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='765f852b4603d752e6db274c8ea64685ba6abeb68cdc4786aca31bd95fbeb2c4', token_count=49, vector_point_id='kc-kg-approach-decolonization-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
