INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-empiricism-0', 'kg-approach-empiricism', 1, 'تجربه‌گرایی (Empiricism) (Empiricism) نوع: APPROACH سنت فلسفی-روش‌شناختی که بنای همه‌ی دانش معتبر را بر تجربه‌ی حسی و مشاهده‌ی نظام‌مند می‌داند.', 'ce8d6d93d4a5f6cbf1470d22197ed710aace02479c8295c2120d1c946d377c6f', 261, 'kc-kg-approach-empiricism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ce8d6d93d4a5f6cbf1470d22197ed710aace02479c8295c2120d1c946d377c6f', token_count=261, vector_point_id='kc-kg-approach-empiricism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-empiricism-2', 'kg-approach-empiricism', 2, 'تجربه‌گرایی ریشه‌ی فلسفی اثبات‌گرایی است؛ دانش از تجربه می‌آید، نه از عقل محض. در پژوهش‌های ارتباطات، مشاهده‌ی مستقیم رفتار مخاطب، آزمایش‌های آزمایشگاهی و سنجش‌های کمّیِ مبتنی بر داده‌های تجربی، در این سنت جای می‌گیرند. در سند (بخش ۴) به‌عنوان زیرشاخه‌ی اثبات‌گرایی ثبت شده است.', 'b8781becd04abf29d2c95618b61c035aeca653ddfede5a963edeed004bea38bc', 505, 'kc-kg-approach-empiricism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b8781becd04abf29d2c95618b61c035aeca653ddfede5a963edeed004bea38bc', token_count=505, vector_point_id='kc-kg-approach-empiricism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-empiricism-3', 'kg-approach-empiricism', 3, 'دانش‌پذیری فقط از تجربه؛ مشهورترین چهره‌ها: لاک، هیوم، برکلی.', 'aabff255fff4092509ed912cabc0b97e9946b6c09b4ef5396c3027c0e8d1bfc3', 110, 'kc-kg-approach-empiricism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='aabff255fff4092509ed912cabc0b97e9946b6c09b4ef5396c3027c0e8d1bfc3', token_count=110, vector_point_id='kc-kg-approach-empiricism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-empiricism-4', 'kg-approach-empiricism', 4, '["دانش معتبر، ریشه در تجربه‌ی حسی دارد","مشاهده‌ی نظام‌مند، منبع اصلی داده است"]', '3f32d10133a5828134550fca6fc283d48d8a6311cf08bf29bb0c2e2ae7666600', 145, 'kc-kg-approach-empiricism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3f32d10133a5828134550fca6fc283d48d8a6311cf08bf29bb0c2e2ae7666600', token_count=145, vector_point_id='kc-kg-approach-empiricism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
