INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-falsificationism-0', 'kg-approach-falsificationism', 1, 'ابطال‌گرایی (Falsificationism) (Falsificationism) نوع: APPROACH منطق پژوهشی که معتبر بودن یک نظریه را به ابطال‌پذیری آن شرط می‌کند: نظریه‌ای علمی است که بتوان آن را با یک داده ابطال کرد.', '014f64c9cf21f3bc3f94bc0f014b973758793b5e0f3682974c2d96260e685a64', 338, 'kc-kg-approach-falsificationism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='014f64c9cf21f3bc3f94bc0f014b973758793b5e0f3682974c2d96260e685a64', token_count=338, vector_point_id='kc-kg-approach-falsificationism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-falsificationism-2', 'kg-approach-falsificationism', 2, 'سنت فکری کارل پوپر که بنای پساثبات‌گرایی را تشکیل می‌دهد. در پژوهش‌های کمّی، طراحی آزمون فرضیه با «فرضیه‌ی صفر» و آزمون‌های آماری، در این منطق استوار است. در سند (بخش ۴) به‌عنوان زیرشاخه‌ی پساثبات‌گرایی ثبت شده است.', '63de8df2339c3e7000bb932f76ca0ecac5d11d6ba20a70a2efc7a190bb090426', 390, 'kc-kg-approach-falsificationism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='63de8df2339c3e7000bb932f76ca0ecac5d11d6ba20a70a2efc7a190bb090426', token_count=390, vector_point_id='kc-kg-approach-falsificationism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-falsificationism-3', 'kg-approach-falsificationism', 3, 'ابطال‌پذیری به‌عنوان معیار تمایز علمی/غیرعلمی.', 'c8340aa873fc5437b43599a30f9b0b51106bb13ea1c062f94580b50ccd28c1f2', 83, 'kc-kg-approach-falsificationism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c8340aa873fc5437b43599a30f9b0b51106bb13ea1c062f94580b50ccd28c1f2', token_count=83, vector_point_id='kc-kg-approach-falsificationism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-falsificationism-4', 'kg-approach-falsificationism', 4, '["نظریه‌ای علمی است که ابطال‌پذیر باشد","آزمون فرضیه، آزمون «ابطال» است نه «اثبات»"]', 'ee4bec207a8a075362f6cac166305c81d54a8ece6cbe26097523f33945e6a11b', 152, 'kc-kg-approach-falsificationism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ee4bec207a8a075362f6cac166305c81d54a8ece6cbe26097523f33945e6a11b', token_count=152, vector_point_id='kc-kg-approach-falsificationism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
