INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-feminist-epistemology-0', 'kg-approach-feminist-epistemology', 1, 'معرفت‌شناسی فمینیستی (Feminist Epistemology) (Feminist Epistemology) نوع: APPROACH رویکرد معرفت‌شناختی که دانش را از دید تجربه‌ی زنان می‌پرسد و «بی‌طرفی» را خود نوعی موضع می‌داند.', '386c6c7e0a1734aa8fb14c9fd52045a4467ce9c68ed161bd57772a8fd77b10a5', 325, 'kc-kg-approach-feminist-epistemology-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='386c6c7e0a1734aa8fb14c9fd52045a4467ce9c68ed161bd57772a8fd77b10a5', token_count=325, vector_point_id='kc-kg-approach-feminist-epistemology-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
