INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-gramscian-0', 'kg-approach-gramscian', 1, 'گرامشی (Gramscianism) نوع: APPROACH جریان نئومارکسیستی مبتنی بر نظریه هژمونی آنتونین گرامشی که سلطه را فرآیند کسب اجماع فرهنگی می‌داند.', '375d554c49192e144a3e36aab722a0c1e4a67a26dc63fb6c2860a8fc81acc0a1', 245, 'kc-kg-approach-gramscian-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='375d554c49192e144a3e36aab722a0c1e4a67a26dc63fb6c2860a8fc81acc0a1', token_count=245, vector_point_id='kc-kg-approach-gramscian-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-gramscian-2', 'kg-approach-gramscian', 2, 'گرامشی هژمونی را فرآیندی پویا می‌داند که در آن حاکمان برای تداوم قدرت، علاوه بر زور، اجماع فرهنگی می‌سازند. در رسانه، بازنمایی‌ها مکانیزم اصلی تولید هژمونی و «جنگ موقعیت‌ها» (war of positions) است.', 'af9cfc45801439807306e61c5dcb31304b1d6bbe2863f43c5c57f1fac03a191f', 358, 'kc-kg-approach-gramscian-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='af9cfc45801439807306e61c5dcb31304b1d6bbe2863f43c5c57f1fac03a191f', token_count=358, vector_point_id='kc-kg-approach-gramscian-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
