INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-hermeneutic-phenomenology-0', 'kg-approach-hermeneutic-phenomenology', 1, 'پدیدارشناسی هرمنوتیکی (Hermeneutic Phenomenology) نوع: APPROACH ترکیب پدیدارشناسی و هرمنوتیک در «دایره هرمنوتیکی» گادامر برای فهم معنادار پدیده‌های رسانه‌ای.', 'a61d73a746094fbad845740bafa933bd8967bb7352849d546d393b1cb0cc7fcd', 285, 'kc-kg-approach-hermeneutic-phenomenology-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a61d73a746094fbad845740bafa933bd8967bb7352849d546d393b1cb0cc7fcd', token_count=285, vector_point_id='kc-kg-approach-hermeneutic-phenomenology-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-hermeneutic-phenomenology-2', 'kg-approach-hermeneutic-phenomenology', 2, 'این رویکرد تجربه زیسته و تفسیر معنا را با هم می‌آمیزد؛ در رسانه، معنای پیام از «افق» مخاطب و «ترکیب افق‌ها» (gadamer) ساخته می‌شود.', 'a85835256a8a5fc010dfd05d0e80f450b778c411bd868c2ad36f2931f3103ee5', 238, 'kc-kg-approach-hermeneutic-phenomenology-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a85835256a8a5fc010dfd05d0e80f450b778c411bd868c2ad36f2931f3103ee5', token_count=238, vector_point_id='kc-kg-approach-hermeneutic-phenomenology-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
