INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-intersectionality-0', 'kg-approach-intersectionality', 1, 'بین‌ابذیی (Intersectionality) (Intersectionality) نوع: APPROACH رویکردی که تعامل هم‌زمان چند محور سلطه (جنسیت، نژاد، طبقه، ...) را بررسی می‌کند.', '8817561b1391cafe64d6bd8359f313dda9921a191ee8f2a6bd272281082a534b', 261, 'kc-kg-approach-intersectionality-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8817561b1391cafe64d6bd8359f313dda9921a191ee8f2a6bd272281082a534b', token_count=261, vector_point_id='kc-kg-approach-intersectionality-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
