INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-mixed-methods-0', 'kg-approach-mixed-methods', 1, 'رویکرد آمیخته (Mixed Methods Approach) نوع: APPROACH رویکردی روش‌شناختی که برای پاسخ به پرسش‌های پیچیده، داده‌های کمّی و کیفی را به‌صورت ترکیبی و نظام‌مند به کار می‌گیرد.', 'df37614b7f11a2e8a68cc11b7d064e90c047f71aabec5db283e98f8bb8beaf9a', 309, 'kc-kg-approach-mixed-methods-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='df37614b7f11a2e8a68cc11b7d064e90c047f71aabec5db283e98f8bb8beaf9a', token_count=309, vector_point_id='kc-kg-approach-mixed-methods-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-mixed-methods-2', 'kg-approach-mixed-methods', 2, 'رویکرد آمیخته (mixed methods)، مبانی روش‌شناختی پژوهش‌هایی را مشخص می‌کند که هم‌زمان از داده‌های کمّی و کیفی استفاده می‌کنند. در این رویکرد، ترکیب روش‌ها نه صرفاً برای جمع‌آوری داده بیشتر، بلکه برای تقویت اعتبار، فهم کامل‌تر و پاسخ به پرسش‌های چندلایه است. پراگماتیسم، بنیان فلسفی اصلی این رویکرد است اما می‌تواند روی مبانی دیگر هم استوار شود. طرح‌های آمیخته شامل همگرا (convergent)، متوالی اکتشافی (explanatory sequential)، متوالی تبیینی (exploratory sequential)، چندمرحله‌ای (multiphase) و تعبیه‌شده (embedded) است.', 'd99985beb339684ee9b9bb18453e299f2c7117c8fa604ca80fb6cb5beabd8915', 939, 'kc-kg-approach-mixed-methods-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d99985beb339684ee9b9bb18453e299f2c7117c8fa604ca80fb6cb5beabd8915', token_count=939, vector_point_id='kc-kg-approach-mixed-methods-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-mixed-methods-3', 'kg-approach-mixed-methods', 3, 'با بازگشت پراگماتیسم در روش‌شناسی اجتماعی (۱۹۸۰-۱۹۹۰) و با کارهای Creswell, Tashakkori & Teddlie در طراحی و اجرای پژوهش‌های آمیخته در ۱۹۹۰-۲۰۱۰ نهادینه شد.', '6d3a4457ef3771951169a61a7cfc2bd16bd1e9ea96637b7c504dbaaa471b06a5', 281, 'kc-kg-approach-mixed-methods-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6d3a4457ef3771951169a61a7cfc2bd16bd1e9ea96637b7c504dbaaa471b06a5', token_count=281, vector_point_id='kc-kg-approach-mixed-methods-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-mixed-methods-4', 'kg-approach-mixed-methods', 4, 'بنیاد فلسفی: معمولاً پراگماتیسم (و گاه واقع‌گرایی انتقادی)؛ هستی‌شناسی: واقعیت چندوجهی و تعاملی؛ معرفت‌شناسی: عمل‌محور و پرسش‌محور؛ روش‌شناسی: ترکیبی کمّی-کیفی.', '5e6bc59387bb7cfb3c622ed9bb1db1b8765323fb2f27dc612fd9667630948c81', 290, 'kc-kg-approach-mixed-methods-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5e6bc59387bb7cfb3c622ed9bb1db1b8765323fb2f27dc612fd9667630948c81', token_count=290, vector_point_id='kc-kg-approach-mixed-methods-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-mixed-methods-5', 'kg-approach-mixed-methods', 5, '["ترکیب داده‌های کمّی و کیفی، درک کامل‌تری از پدیده می‌دهد","پرسش پژوهش، تعیین‌کننده‌ی طرح آمیخته است","یکپارچگی (integration) داده‌ها، در مرحله‌ی تحلیل کلیدی است","اعتبار، از ترکیب روش‌ها تقویت می‌شود (triangulation)"]', '8c65f768585226e5969eca6de1c9aaec0500db5f6cccf5fabdd5727d2996c395', 398, 'kc-kg-approach-mixed-methods-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8c65f768585226e5969eca6de1c9aaec0500db5f6cccf5fabdd5727d2996c395', token_count=398, vector_point_id='kc-kg-approach-mixed-methods-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
