INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-mixed-methods-14', 'kg-approach-mixed-methods', 14, '["Creswell, J.W. & Plano Clark, V.L. (2018). Designing and Conducting Mixed Methods Research","Tashakkori, A. & Teddlie, C. (2010). SAGE Handbook of Mixed Methods in Social & Behavioral Research","Onwuegbuzie, T.C. & Johnson, R.B. (2006). The Philosophy of Mixed Methods"]', '963c33c7a3c3aaf08314a8d7b0bf113847a98c4659c748c42fff088733080b69', 494, 'kc-kg-approach-mixed-methods-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='963c33c7a3c3aaf08314a8d7b0bf113847a98c4659c748c42fff088733080b69', token_count=494, vector_point_id='kc-kg-approach-mixed-methods-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-orientalism-0', 'kg-approach-orientalism', 1, 'شرق‌شناسی (Orientalism) نوع: APPROACH نقد ادوارد سعید از بازنمایی استعماری شرق در زبان، رسانه و فرهنگ غرب.', '70073559cb3ed6e1d34cf838cf1436e2d182b2e287c395edebac2b53b8051f71', 192, 'kc-kg-approach-orientalism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='70073559cb3ed6e1d34cf838cf1436e2d182b2e287c395edebac2b53b8051f71', token_count=192, vector_point_id='kc-kg-approach-orientalism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-orientalism-2', 'kg-approach-orientalism', 2, 'سعید (1978) نشان می‌دهد «شرق» یک ساختار بازنمایی است، نه واقعیت جغرافیایی؛ در رسانه، بازنمایی‌های «شرق‌ی مرموز، خرافاتی و عقب‌مانده» نمونه‌های بارز شرق‌شناسی رسانه‌ای است.', '68ea45ab10b3d438f54e0893acedef3cc46253997195be8d4e3d8ccc0ce95b56', 310, 'kc-kg-approach-orientalism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='68ea45ab10b3d438f54e0893acedef3cc46253997195be8d4e3d8ccc0ce95b56', token_count=310, vector_point_id='kc-kg-approach-orientalism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-orientalism-3', 'kg-approach-orientalism', 3, 'پسااستعمارگرایی و ساختارگرایی.', 'fa7aba09326e0c570fc9b8b4221cbeb7a5e4b8fd8003a53a0f501c10db57b5ef', 54, 'kc-kg-approach-orientalism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fa7aba09326e0c570fc9b8b4221cbeb7a5e4b8fd8003a53a0f501c10db57b5ef', token_count=54, vector_point_id='kc-kg-approach-orientalism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-orientalism-4', 'kg-approach-orientalism', 4, '["«شرق» ساختار بازنمایی است","رسانه ابزار بازتولید بازنمایی استعماری است"]', '9c87ab903937c9ca385453b9157eb86460edb8e194e76f13badb7cd95b0e0bb6', 134, 'kc-kg-approach-orientalism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9c87ab903937c9ca385453b9157eb86460edb8e194e76f13badb7cd95b0e0bb6', token_count=134, vector_point_id='kc-kg-approach-orientalism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
