INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-participatory-research-0', 'kg-approach-participatory-research', 1, 'پژوهش مشارکتی (Participatory Research) (Participatory Research) نوع: APPROACH رویکردی که موضوعات پژوهش را به‌عنوان شریک فعال در فرایند پژوهش می‌داند، نه فقط منبع داده.', 'ccff590713f046e9f9cda78be4a6115e441951c35c8d500676d2838ebdc16400', 303, 'kc-kg-approach-participatory-research-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ccff590713f046e9f9cda78be4a6115e441951c35c8d500676d2838ebdc16400', token_count=303, vector_point_id='kc-kg-approach-participatory-research-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-participatory-research-2', 'kg-approach-participatory-research', 2, 'در سند (بخش ۴) به‌عنوان زیرشاخه‌ی مشارکتی ثبت شده است و در بخش ۵ (رویکردهای مکمل) نیز نام برده شده است. در علوم ارتباطات، ارزیابی مشارکتی و پژوهش‌های اجتماعی رسانه در این سنت جای می‌گیرند.', 'a6f7d0372c212a4c94a9bb519945b8ddc7afc9bfee3426eae7283bb0e96301f2', 341, 'kc-kg-approach-participatory-research-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a6f7d0372c212a4c94a9bb519945b8ddc7afc9bfee3426eae7283bb0e96301f2', token_count=341, vector_point_id='kc-kg-approach-participatory-research-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
