INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-philosophical-hermeneutics-0', 'kg-approach-philosophical-hermeneutics', 1, 'هرمنوتیک فلسفی (Philosophical Hermeneutics) نوع: APPROACH هرمنوتیک هایدگری و گادامری که فهم را «وجودشناختی» و نه صرفا روشی می‌داند.', '595dadb3fde6f441d77a8837bcb4123b787b2041166362c6a0196c0d6ce355b8', 238, 'kc-kg-approach-philosophical-hermeneutics-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='595dadb3fde6f441d77a8837bcb4123b787b2041166362c6a0196c0d6ce355b8', token_count=238, vector_point_id='kc-kg-approach-philosophical-hermeneutics-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-philosophical-hermeneutics-2', 'kg-approach-philosophical-hermeneutics', 2, 'در هرمنوتیک فلسفی، فهم «دایره هرمنوتیکی» است: پیش‌فهم، تفسیر و بازفهم. در رسانه، فهم پیام همیشه از پیش‌فهم مخاطب آغاز می‌شود.', '141cff903d8af4bcae1eed64042136c160f33a2bd63b4f342ea9b0641ca5643c', 227, 'kc-kg-approach-philosophical-hermeneutics-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='141cff903d8af4bcae1eed64042136c160f33a2bd63b4f342ea9b0641ca5643c', token_count=227, vector_point_id='kc-kg-approach-philosophical-hermeneutics-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
