INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-positionality-2', 'kg-approach-positionality', 2, 'در سند (بخش ۴) به‌عنوان زیرشاخه‌ی فمینیستی ثبت شده است. در پژوهش‌های کیفی و انتقادی، پژوهشگر باید موضع‌مندی خود را صریح کند تا خواننده بتواند تأثیر آن بر داده‌ها و تحلیل را بسنجد.', 'db6168fe1d5be51a891924e17f6aa4e52b8d50095952f8a6668587c435411f6b', 325, 'kc-kg-approach-positionality-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='db6168fe1d5be51a891924e17f6aa4e52b8d50095952f8a6668587c435411f6b', token_count=325, vector_point_id='kc-kg-approach-positionality-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
