INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-postcolonial-studies-2', 'kg-approach-postcolonial-studies', 2, 'مطالعات پسااستعماری به میراث استعمار در زبان، بازنمایی، هویت و رسانه می‌پردازد. در رسانه، «جریان شمال-جنوب»، «مغز و حاشیه» و «بازنمایی جنوب» موضوعات کلیدی این رشته‌اند.', '23e53b6011609aad0c13f399cf2e673b32507dcbd7d417b1a0e3cb90b2875be2', 305, 'kc-kg-approach-postcolonial-studies-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='23e53b6011609aad0c13f399cf2e673b32507dcbd7d417b1a0e3cb90b2875be2', token_count=305, vector_point_id='kc-kg-approach-postcolonial-studies-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
