INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-problem-solving-2', 'kg-approach-problem-solving', 2, 'در سند (بخش ۴) به‌عنوان زیرشاخه‌ی پراگماتیسم ثبت شده است. در علوم ارتباطات، پژوهش‌های کاربردی (سنجش اثربخشی رسانه، طراحی تجربه کاربر) در این منطق استوارند.', '607e2c95911712ce3d4ede3426d6f5e7c7aa821461179f3330b4caa7cfa4ab90', 281, 'kc-kg-approach-problem-solving-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='607e2c95911712ce3d4ede3426d6f5e7c7aa821461179f3330b4caa7cfa4ab90', token_count=281, vector_point_id='kc-kg-approach-problem-solving-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
