INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-qualitative-0', 'kg-approach-qualitative', 1, 'رویکرد کیفی (Qualitative Approach) نوع: APPROACH رویکردی روش‌شناختی که با فهم تجربه‌های زیسته، تفسیر معنا و تحلیل بافت، به دنبال درک عمیق پدیده‌های اجتماعی است.', '2f011a27a619756bce41f0bbaf79483a802efb5dfb3ee874912ae9782a71a8e7', 290, 'kc-kg-approach-qualitative-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2f011a27a619756bce41f0bbaf79483a802efb5dfb3ee874912ae9782a71a8e7', token_count=290, vector_point_id='kc-kg-approach-qualitative-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-qualitative-2', 'kg-approach-qualitative', 2, 'رویکرد کیفی، مبانی روش‌شناختی پژوهش‌های مبتنی بر داده‌های غیرعدد (متن، گفتار، تصویر، رفتار) را مشخص می‌کند. در این رویکرد، پژوهشگر با فهم تجربه‌ی زیسته، تفسیر معنا، تحلیل روایت و گفتمان و مطالعه‌ی بافت، به دنبال درک عمیق و زمینه‌مند پدیده است. این رویکرد معمولاً با پارادایم تفسیرگرایی و برساخت‌گرایی پیوند دارد و بنیان روش‌های نظریه‌پردازی داده‌بنیاد، قوم‌نگاری، تحلیل گفتمان و پژوهش روایی است.', '2ba8992fc26f306e84a6d1251fa62227e47fcdd401c6ddaa0bc7523d047c4961', 718, 'kc-kg-approach-qualitative-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2ba8992fc26f306e84a6d1251fa62227e47fcdd401c6ddaa0bc7523d047c4961', token_count=718, vector_point_id='kc-kg-approach-qualitative-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-qualitative-3', 'kg-approach-qualitative', 3, 'از سنت تفسیرگرایی و برساخت‌گرایی در علوم اجتماعی (Weber, Dilthey, Berger & Luckmann) و با گسترش روش‌های کیفی در ۱۹۷۰-۱۹۹۰ نهادینه شد.', '0df46f5da2ab1001587b477b59b6d269b3ad21bb5ea71e60bd00c081b92a7ac7', 241, 'kc-kg-approach-qualitative-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0df46f5da2ab1001587b477b59b6d269b3ad21bb5ea71e60bd00c081b92a7ac7', token_count=241, vector_point_id='kc-kg-approach-qualitative-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-qualitative-4', 'kg-approach-qualitative', 4, 'بنیاد فلسفی: معمولاً تفسیرگرایی یا برساخت‌گرایی (و گاه فمینیستی و مشارکتی)؛ هستی‌شناسی: واقعیت برساخت معنایی؛ معرفت‌شناسی: ذهنی و تعاملی؛ روش‌شناسی: کیفی و استقرایی.', '7839b7f8c42851629ffafb5ad3794d4adadbe334a1bb97cb8128b67c9235d8e8', 300, 'kc-kg-approach-qualitative-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7839b7f8c42851629ffafb5ad3794d4adadbe334a1bb97cb8128b67c9235d8e8', token_count=300, vector_point_id='kc-kg-approach-qualitative-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-qualitative-5', 'kg-approach-qualitative', 5, '["داده‌ها، معنادار و زمینه‌مند هستند و از بیرون قابل‌سنجش مطلق نیستند","هدف، فهم عمیق و تفسیر معناست، نه تبیین علّی","روش‌ها باید انعطاف‌پذیر و بافت‌محور باشند","نتایج، قابل‌انتقال (transferable)‌اند، نه قابل‌تعمیم آماری"]', '5d5dc44f5bf934e32981616e642e2d2e56342fc15b01c50b105ea791a1c0bf9e', 403, 'kc-kg-approach-qualitative-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5d5dc44f5bf934e32981616e642e2d2e56342fc15b01c50b105ea791a1c0bf9e', token_count=403, vector_point_id='kc-kg-approach-qualitative-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
