INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-qualitative-14', 'kg-approach-qualitative', 14, '["Creswell, J.W. (2014). Qualitative Inquiry and Research Design","Strauss, A. & Corbin, J. (1990). Basics of Qualitative Research","Miles, M.B., Huberman, A.M. & Saldaña, J. (2014). Qualitative Data Analysis"]', '4382f2077c3b63ef03a57b9a853088e73465a258c777d137add54434cde8b190', 381, 'kc-kg-approach-qualitative-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4382f2077c3b63ef03a57b9a853088e73465a258c777d137add54434cde8b190', token_count=381, vector_point_id='kc-kg-approach-qualitative-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-quantitative-0', 'kg-approach-quantitative', 1, 'رویکرد کمّی (Quantitative Approach) نوع: APPROACH رویکردی روش‌شناختی که با اندازه‌گیری متغیرها، آزمون فرضیه‌ها و تحلیل آماری، به دنبال تبیین علّی و تعمیم‌پذیری نتایج است.', 'd93df0bc3abe7d0f3e8d807e4e119478272c52a8cdb95225dc117e1e0e248172', 309, 'kc-kg-approach-quantitative-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d93df0bc3abe7d0f3e8d807e4e119478272c52a8cdb95225dc117e1e0e248172', token_count=309, vector_point_id='kc-kg-approach-quantitative-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-quantitative-2', 'kg-approach-quantitative', 2, 'رویکرد کمّی، مبانی روش‌شناختی پژوهش‌های مبتنی بر داده‌های عددی و تحلیل آماری را مشخص می‌کند. در این رویکرد، پژوهشگر با تعریف متغیرها، آزمون فرضیه‌ها، اندازه‌گیری روابط و همبستگی‌ها و تبیین علّی، به دنبال کشف روابط عمومی و قابل‌تعمیم است. این رویکرد معمولاً با پارادایم اثبات‌گرایی و پساثبات‌گرایی پیوند دارد اما در چارچوب پراگماتیستی (رویکرد آمیخته) هم کاربرد دارد. در علوم ارتباطات، پیمایش‌ها، آزمایش‌ها و پژوهش‌های همبستگی در این رویکرد جای می‌گیرند.', 'ba0da716356bd7185d832868902c7c4648afefee5c13e507c1c697ec748789c0', 821, 'kc-kg-approach-quantitative-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ba0da716356bd7185d832868902c7c4648afefee5c13e507c1c697ec748789c0', token_count=821, vector_point_id='kc-kg-approach-quantitative-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-quantitative-3', 'kg-approach-quantitative', 3, 'از سنت اثبات‌گرایی و علم‌گرایی در علوم اجتماعی (دوره‌ی کلمبیا و شیکاگو، ۱۹۳۰-۱۹۶۰) و با گسترش آمار و روش‌های کمّی در ۱۹۶۰-۱۹۸۰ نهادینه شد.', '6844869dd6146bc739b978e87c056f56560348d4c31fac763ab0b3e594f81bc0', 250, 'kc-kg-approach-quantitative-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6844869dd6146bc739b978e87c056f56560348d4c31fac763ab0b3e594f81bc0', token_count=250, vector_point_id='kc-kg-approach-quantitative-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-quantitative-4', 'kg-approach-quantitative', 4, 'بنیاد فلسفی: معمولاً اثبات‌گرایی یا پساثبات‌گرایی (و گاه پراگماتیسم)؛ هستی‌شناسی: واقعیت عینی و قابل‌سنجش؛ معرفت‌شناسی: عینی و بی‌طرف؛ روش‌شناسی: کمّی و قیاسی.', 'd57f29128c18f0ab47f533cea4535f9cc31ef196d0c48d2127e5871acff24fcc', 289, 'kc-kg-approach-quantitative-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d57f29128c18f0ab47f533cea4535f9cc31ef196d0c48d2127e5871acff24fcc', token_count=289, vector_point_id='kc-kg-approach-quantitative-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-quantitative-5', 'kg-approach-quantitative', 5, '["داده‌ها باید قابل‌سنجش و عددی باشند","پژوهش با طرح فرضیه و آزمون نظام‌مند آن آغاز می‌شود","روابط علّی و همبستگی، هدف اصلی هستند","نتایج باید قابل‌تعمیم آماری باشند"]', 'fe6eeea94c8449b04d72410a3248c0face715c91a9bee2bba6619cbdf979bb74', 303, 'kc-kg-approach-quantitative-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fe6eeea94c8449b04d72410a3248c0face715c91a9bee2bba6619cbdf979bb74', token_count=303, vector_point_id='kc-kg-approach-quantitative-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
