INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-social-interactionism-0', 'kg-approach-social-interactionism', 1, 'کنش متقابل اجتماعی (Social Interactionism) نوع: APPROACH رویکردی گسترده‌تر از نمادین که تعاملات را در بافت اجتماعی-مادی (نه صرفا نمادین) تحلیل می‌کند.', 'faf1c4ef896395ce19631fef63fd780d034507e4992221c63ce0921c3136408c', 272, 'kc-kg-approach-social-interactionism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='faf1c4ef896395ce19631fef63fd780d034507e4992221c63ce0921c3136408c', token_count=272, vector_point_id='kc-kg-approach-social-interactionism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-social-interactionism-2', 'kg-approach-social-interactionism', 2, 'کنش متقابل اجتماعی (Goffman, Erving Goffman, Mead, Simmel) به بافت‌های اجتماعی (غرفه‌ی نمایش، گروه، جمعیت) و الگوهای تکرارشونده تعامل توجه دارد. در رسانه، تعاملات اجتماعی در فضای دیجیتال (تعامل، پاسخ، به‌ اشتراک‌گذاری) نمونه‌های معاصر این رویکردند.', '4be89f5de83ea13b317afd448dc1d6e22af3c14c0da06a91d95c0ce977b22325', 450, 'kc-kg-approach-social-interactionism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4be89f5de83ea13b317afd448dc1d6e22af3c14c0da06a91d95c0ce977b22325', token_count=450, vector_point_id='kc-kg-approach-social-interactionism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
