INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-social-interpretation-0', 'kg-approach-social-interpretation', 1, 'تفسیر اجتماعی (Social Interpretation) (Social Interpretation) نوع: APPROACH صورتی از تفسیرگرایی که معنای پدیده‌های اجتماعی را در تعاملات روزمره و ساختارهای فرهنگی می‌جوید.', '1c730eeb2e604a298adb373016899b6636343123ef4e44911c462024eb7af423', 310, 'kc-kg-approach-social-interpretation-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1c730eeb2e604a298adb373016899b6636343123ef4e44911c462024eb7af423', token_count=310, vector_point_id='kc-kg-approach-social-interpretation-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-social-interpretation-2', 'kg-approach-social-interpretation', 2, 'در سند (بخش ۴) به‌عنوان زیرشاخه‌ی تفسیرگرایی ثبت شده است. در این رویکرد، تحلیل پدیده‌های رسانه‌ای (خبر، برنامه، تعامل) از منظر معنا و بافت اجتماعی انجام می‌شود، نه از منظر علل و نتایج عددی.', 'ac3f4caa63125b732a7b53ed577afff6407a2ed5eda3227fbffcf1381606dc75', 343, 'kc-kg-approach-social-interpretation-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ac3f4caa63125b732a7b53ed577afff6407a2ed5eda3227fbffcf1381606dc75', token_count=343, vector_point_id='kc-kg-approach-social-interpretation-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
