INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-social-phenomenology-2', 'kg-approach-social-phenomenology', 2, 'شوتز پدیدارشناسی را با جامعه‌شناسی ترکیب می‌کند: «جهان اجتماعی» از فهم متقابل کنشگران ساخته می‌شود و رسانه، یکی از ابزارهای اصلی ساخت این جهان است.', '4b48c9dcce8727f44beb67817bb0d6627cf38a8d120c769424692b7e606f72e1', 267, 'kc-kg-approach-social-phenomenology-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4b48c9dcce8727f44beb67817bb0d6627cf38a8d120c769424692b7e606f72e1', token_count=267, vector_point_id='kc-kg-approach-social-phenomenology-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
