INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-social-pragmatism-2', 'kg-approach-social-pragmatism', 2, 'پراگماتیسم اجتماعی (دوی، میاد، مین) عمل‌گرایی را در بافت اجتماعی‌تر می‌کشد: تعاملات اجتماعی، هویت و رسانه در «بازاندازی جهان» (world-building) نقش دارند.', 'a1cc539fdcecfdc6f7229751e0a69d7726107264555e96d81c34328e670a9679', 278, 'kc-kg-approach-social-pragmatism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a1cc539fdcecfdc6f7229751e0a69d7726107264555e96d81c34328e670a9679', token_count=278, vector_point_id='kc-kg-approach-social-pragmatism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
