INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-structural-functionalism-0', 'kg-approach-structural-functionalism', 1, 'کارکردگرایی ساختاری (Structural Functionalism) نوع: APPROACH جریان نئوکارکردگرای تالت پارسونز که جامعه را به‌عنوان سیستمی از الگوهای هنجاری تحلیل می‌کند.', 'da903d8522004b7c330e6b386e0372759c9a6a3c3f82839a862bba714f42478f', 278, 'kc-kg-approach-structural-functionalism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='da903d8522004b7c330e6b386e0372759c9a6a3c3f82839a862bba714f42478f', token_count=278, vector_point_id='kc-kg-approach-structural-functionalism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-structural-functionalism-2', 'kg-approach-structural-functionalism', 2, 'پارسونز چهار کارکرد AGIL (همگرایی، هدف‌یابی، یکپارچگی، حفظ الگو) را برای هر جامعه تعریف می‌کند. رسانه در این دیدگاه در خدمت کارکردهای همگرایی و یکپارچگی اجتماعی است.', '39a5d308383da4d39ffb7f2d7dda2daafeaf9b35265d5be8e5cf5bd7b98e60c9', 300, 'kc-kg-approach-structural-functionalism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='39a5d308383da4d39ffb7f2d7dda2daafeaf9b35265d5be8e5cf5bd7b98e60c9', token_count=300, vector_point_id='kc-kg-approach-structural-functionalism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
