INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-structured-action-0', 'kg-approach-structured-action', 1, 'نظریه کنش ساختاری (Structured Action Theory) نوع: APPROACH رویکرد گیدنز و بوردیو که در آن کنش هم ساختار می‌سازد و هم از ساختار تأثیر می‌پذیرد.', 'df5a42410f4203954820adf549bee7104927dd9adda9c26b2b1437d4d7155676', 258, 'kc-kg-approach-structured-action-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='df5a42410f4203954820adf549bee7104927dd9adda9c26b2b1437d4d7155676', token_count=258, vector_point_id='kc-kg-approach-structured-action-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-structured-action-2', 'kg-approach-structured-action', 2, 'در نظریه کنش ساختاری (structured action)، کنش و ساختار در چرخه‌ای از «دوسریایی» (duality) با هم در می‌آیند: کنش هم تولیدکننده ساختار است و هم محصول آن. در رسانه، الگوریتم‌ها هم کنش مخاطب را شکل می‌دهند و هم از کنش مخاطب ساخته می‌شوند.', '245deff2c540ae274b4cc19d5127fbc5281a0f79bd785feb0d40c3334c367c86', 425, 'kc-kg-approach-structured-action-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='245deff2c540ae274b4cc19d5127fbc5281a0f79bd785feb0d40c3334c367c86', token_count=425, vector_point_id='kc-kg-approach-structured-action-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-structured-action-3', 'kg-approach-structured-action', 3, 'دوسریایی گیدنز و نظریه میدان بوردیو.', '7f6da73c3c57e94584abc2398f1e8a8f7ce0878a575e74efc65668ae7e7be3bf', 65, 'kc-kg-approach-structured-action-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f6da73c3c57e94584abc2398f1e8a8f7ce0878a575e74efc65668ae7e7be3bf', token_count=65, vector_point_id='kc-kg-approach-structured-action-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-structured-action-4', 'kg-approach-structured-action', 4, '["کنش و ساختار در چرخه‌ای دوسریایی‌اند","ساختار هم ابزار کنش و هم نتیجه آن است"]', '346e5dbb74c1e0aad999c7934fe91131584bef36d3141cd23caee8243c8a0342', 145, 'kc-kg-approach-structured-action-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='346e5dbb74c1e0aad999c7934fe91131584bef36d3141cd23caee8243c8a0342', token_count=145, vector_point_id='kc-kg-approach-structured-action-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
