INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-symbolic-interactionism-0', 'kg-approach-symbolic-interactionism', 1, 'تعامل‌گرایی نمادین (Symbolic Interactionism) نوع: APPROACH رویکرد جامعه‌شناختی-ارتباطی که بر نقش نمادها (زبان، علامت، رفتار) در ساخت معنا و خود تمرکز دارد.', '92cebb9a598e5720e633e5ad1bd40079f41769bcacdf81411e1485b4f2bbf076', 281, 'kc-kg-approach-symbolic-interactionism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='92cebb9a598e5720e633e5ad1bd40079f41769bcacdf81411e1485b4f2bbf076', token_count=281, vector_point_id='kc-kg-approach-symbolic-interactionism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-symbolic-interactionism-2', 'kg-approach-symbolic-interactionism', 2, 'در تعامل‌گرایی نمادین، انسان‌ها بر اساس معنایی که چیزها برایشان دارند عمل می‌کنند؛ معنای چیزها از تعاملات اجتماعی برمی‌آید و از طریق تفسیر فرآیندی اصلاح می‌شود. رسانه و رسانه‌های دیجیتال، میدان اصلی این تعاملات نمادین امروز هستند.', '516cee0b4b66b88bfbf596cfc1348e437c3fef7bff5572cdb105188dc7e1505b', 418, 'kc-kg-approach-symbolic-interactionism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='516cee0b4b66b88bfbf596cfc1348e437c3fef7bff5572cdb105188dc7e1505b', token_count=418, vector_point_id='kc-kg-approach-symbolic-interactionism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-symbolic-interactionism-3', 'kg-approach-symbolic-interactionism', 3, 'پراگماتیسم میادی و پدیدارشناسی هوزرل.', 'ba48e0165176d0ea65d3d5b099377c47641bfcc295ce3b686fd87e91c72f3bd8', 67, 'kc-kg-approach-symbolic-interactionism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ba48e0165176d0ea65d3d5b099377c47641bfcc295ce3b686fd87e91c72f3bd8', token_count=67, vector_point_id='kc-kg-approach-symbolic-interactionism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
