INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-verstehen-0', 'kg-approach-verstehen', 1, 'فهم کنش اجتماعی (Verstehen) (Understanding Social Action (Verstehen)) نوع: APPROACH روش فهم کنش اجتماعی بر پایه‌ی ماکس وبر؛ پژوهشگر باید «منطق» کنش دیگران را از داخل، از نظر خود کنشگر، درک کند.', '6c0a7b9fdbb3f53623a6de5e3f74f06b4dc5f814688d1df772c0084f8481e569', 350, 'kc-kg-approach-verstehen-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6c0a7b9fdbb3f53623a6de5e3f74f06b4dc5f814688d1df772c0084f8481e569', token_count=350, vector_point_id='kc-kg-approach-verstehen-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-verstehen-2', 'kg-approach-verstehen', 2, 'در سند (بخش ۴) به‌عنوان زیرشاخه‌ی تفسیرگرایی ثبت شده است. «فهم» (Verstehen) در مقابل «تبیین» (Erklären) قرار می‌گیرد: فهم یعنی درک معنایی که کنشگر به کنش خود می‌دهد.', '81745099a49d2a7839ec51f7a0a0c822012cb489cddcac8988b2ac36437172a8', 300, 'kc-kg-approach-verstehen-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='81745099a49d2a7839ec51f7a0a0c822012cb489cddcac8988b2ac36437172a8', token_count=300, vector_point_id='kc-kg-approach-verstehen-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-verstehen-3', 'kg-approach-verstehen', 3, 'وبر؛ کنش اجتماعی؛ Verstehen در مقابل Erklären.', '1d17e3a7e81ca10d5b42cc56fc9542a8ef2b956edc1e99bf5d8f9ebb35166eba', 83, 'kc-kg-approach-verstehen-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1d17e3a7e81ca10d5b42cc56fc9542a8ef2b956edc1e99bf5d8f9ebb35166eba', token_count=83, vector_point_id='kc-kg-approach-verstehen-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-approach-verstehen-4', 'kg-approach-verstehen', 4, '["هدف، فهم معنایی کنشگر است نه تبیین علّی از بیرون","پژوهشگر باید «از داخل» کنش را درک کند"]', 'e8b0c4f3574b050c83c7f940d8fd86904a97931efff44d0cd7e087b7835af778', 167, 'kc-kg-approach-verstehen-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e8b0c4f3574b050c83c7f940d8fd86904a97931efff44d0cd7e087b7835af778', token_count=167, vector_point_id='kc-kg-approach-verstehen-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
