INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-concept-hyperreality-6', 'kg-concept-hyperreality', 6, '["فلسفه","مطالعات رسانه","مطالعات فرهنگی"]', '369dff5812b83da335c41e3f3a320e36e369ed23a7691560bcedeea5a05008da', 76, 'kc-kg-concept-hyperreality-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='369dff5812b83da335c41e3f3a320e36e369ed23a7691560bcedeea5a05008da', token_count=76, vector_point_id='kc-kg-concept-hyperreality-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-concept-hyperreality-7', 'kg-concept-hyperreality', 7, '["تحلیل رسانه‌ی دیجیتال و فراواقعیت","مطالعات تصویر و رسانه","نقد «واقعیت» رسانه‌ای"]', '9d650fa80d9e007430a574b2cbb2aaebaea191d6ffa7d0cea0668b3e41fb993d', 154, 'kc-kg-concept-hyperreality-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9d650fa80d9e007430a574b2cbb2aaebaea191d6ffa7d0cea0668b3e41fb993d', token_count=154, vector_point_id='kc-kg-concept-hyperreality-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
