INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-concept-meta-communication-0', 'kg-concept-meta-communication', 1, 'فراارتباط (Meta-communication) نوع: CONCEPT مفهوم بنیادین مکتب پالو آلتو: هر ارتباط، نه‌تنها محتوا (content) بلکه «معنای رابطه» (meta-message) را هم می‌رساند؛ «چگونگی» گفتن، مهم‌تر از «چه» گفتن است.', 'ab189dfb2e1ae90ff55b5555ff5223412412623072bc248b3892c97afe3a6c0d', 359, 'kc-kg-concept-meta-communication-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ab189dfb2e1ae90ff55b5555ff5223412412623072bc248b3892c97afe3a6c0d', token_count=359, vector_point_id='kc-kg-concept-meta-communication-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-concept-meta-communication-2', 'kg-concept-meta-communication', 2, 'فراارتباط (Meta-communication) در نظریه‌ی پالو آلتو به این معناست که هر پیام، هم‌زمان هم «درباره‌ی محتوا» و هم «دربارة‌ی رابطه» صحبت می‌کند. لحن، بیان و بافت، «فراارتباط»‌اند و معنای واقعی رابطه را تعیین می‌کنند.', '30bd3171e691f6be52cd9c93c918e7856a91ffe6f86ec9e5e2e061212d5aa9e8', 385, 'kc-kg-concept-meta-communication-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='30bd3171e691f6be52cd9c93c918e7856a91ffe6f86ec9e5e2e061212d5aa9e8', token_count=385, vector_point_id='kc-kg-concept-meta-communication-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
