INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-concept-simulacra-6', 'kg-concept-simulacra', 6, '["فلسفه","مطالعات رسانه","مطالعات فرهنگی"]', '369dff5812b83da335c41e3f3a320e36e369ed23a7691560bcedeea5a05008da', 76, 'kc-kg-concept-simulacra-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='369dff5812b83da335c41e3f3a320e36e369ed23a7691560bcedeea5a05008da', token_count=76, vector_point_id='kc-kg-concept-simulacra-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-concept-simulacra-7', 'kg-concept-simulacra', 7, '["تحلیل فراواقعیت در رسانه","مطالعات تصویر و رسانه","نقد «واقعیت» رسانه‌ای"]', 'a125c56d7f23edcb929c79e6ed3bf8dc1bd7add542ce0276f640912755a7c905', 138, 'kc-kg-concept-simulacra-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a125c56d7f23edcb929c79e6ed3bf8dc1bd7add542ce0276f640912755a7c905', token_count=138, vector_point_id='kc-kg-concept-simulacra-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
