INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-concept-surveillance-0', 'kg-concept-surveillance', 1, 'نظارت دیجیتال (Digital Surveillance) نوع: CONCEPT مفهوم «نظارت دیجیتال» (digital surveillance) به فرآیند جمع‌آوری و تحلیل داده‌های رفتار کاربران توسط پلتفرم‌های دیجیتال اشاره دارد.', 'a517ee504a29c6d1412c12d1249e4d595a0b5114fc636c3e1a99c8682caf33f1', 327, 'kc-kg-concept-surveillance-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a517ee504a29c6d1412c12d1249e4d595a0b5114fc636c3e1a99c8682caf33f1', token_count=327, vector_point_id='kc-kg-concept-surveillance-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-concept-surveillance-2', 'kg-concept-surveillance', 2, 'این مفهوم (که در نظریه سرمایه‌داری نظارتی Zuboff (2019) استفاده شد) به فرآیند جمع‌آوری و تحلیل داده‌های رفتار کاربران توسط پلتفرم‌های دیجیتال اشاره دارد. نظارت دیجیتال، ساختار قدرت رسانه‌ای را دگرگون می‌کند.', '9266c1bf8bf39081e5bbb6841ac502a5406d05e8036eb54e713e91fd9451d5ea', 376, 'kc-kg-concept-surveillance-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9266c1bf8bf39081e5bbb6841ac502a5406d05e8036eb54e713e91fd9451d5ea', token_count=376, vector_point_id='kc-kg-concept-surveillance-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
