INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-design-experimental-2', 'kg-design-experimental', 2, 'طرح آزمایشی با دستکاری متغیر مستقل، تصادفی‌سازی و وجود گروه کنترل، قوی‌ترین طرح برای آزمون رابطه‌ی علّی در پژوهش‌های کمّی است. در پژوهش‌های علوم ارتباطات عمدتاً در آزمایش اثربخشی پیام، تبلیغ و رسانه به کار می‌رود.', 'baeba51ff257268cc601393879e027fb022f7b2d4edfde155715fbd2c3710593', 387, 'kc-kg-design-experimental-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='baeba51ff257268cc601393879e027fb022f7b2d4edfde155715fbd2c3710593', token_count=387, vector_point_id='kc-kg-design-experimental-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
