INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-ethics-digital-research-ethics-0', 'kg-ethics-digital-research-ethics', 1, 'اخلاق پژوهش دیجیتال (Digital Research Ethics) نوع: ETHICS اصول اخلاقی پژوهش‌هایی که داده‌ها را از فضای دیجیتال جمع‌آوری می‌کنند.', '009f0801ce3f80a6ea0bb8c26957a71c5f09c2a723472709ebf82dc222cee206', 232, 'kc-kg-ethics-digital-research-ethics-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='009f0801ce3f80a6ea0bb8c26957a71c5f09c2a723472709ebf82dc222cee206', token_count=232, vector_point_id='kc-kg-ethics-digital-research-ethics-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
