INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-correlation-0', 'kg-framework-correlation', 1, 'تحلیل همبستگی (Correlation Analysis) نوع: FRAMEWORK خانواده‌ای از شاخص‌های کمّی برای اندازه‌گیری قوّت و جهت رابطه‌ی دو متغیر', 'ba30dd8e50171983f497671d1e83bf2cc4dec325eb001f87c4a908e5741a7a8c', 225, 'kc-kg-framework-correlation-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ba30dd8e50171983f497671d1e83bf2cc4dec325eb001f87c4a908e5741a7a8c', token_count=225, vector_point_id='kc-kg-framework-correlation-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-correlation-2', 'kg-framework-correlation', 2, 'مجموعه‌ای از شاخص‌ها (پیرسون، اسپیرمن، کندال) که اندازه‌ی همبستگی بین دو متغیر را در بازه‌ی ۱− تا ۱+ نشان می‌دهند؛ انتخاب شاخص به مقیاس و توزیع داده بستگی دارد.', '708ac1173431cad4c0127505b52995c98afcb01dc4913b4f38ff92c45585512f', 290, 'kc-kg-framework-correlation-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='708ac1173431cad4c0127505b52995c98afcb01dc4913b4f38ff92c45585512f', token_count=290, vector_point_id='kc-kg-framework-correlation-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
