INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-discourse-0', 'kg-framework-critical-discourse', 1, 'تحلیل گفتمان انتقادی (Critical Discourse Analysis (CDA)) نوع: FRAMEWORK چارچوب نظری تحلیل گفتمان انتقادی که بر تحلیل «رابطه‌ی گفتمان، قدرت و ایدئولوژی» در بافت اجتماعی تمرکز دارد و بر نابرابری و سلطه تأکید دارد.', 'fcbf5c8b0818e8378ae37f2a9ee8a67a31ad5d80f28f35906afe32676554d798', 383, 'kc-kg-framework-critical-discourse-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fcbf5c8b0818e8378ae37f2a9ee8a67a31ad5d80f28f35906afe32676554d798', token_count=383, vector_point_id='kc-kg-framework-critical-discourse-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-discourse-2', 'kg-framework-critical-discourse', 2, 'تحلیل گفتمان انتقادی (Critical Discourse Analysis) از نورمن فان دایک (1993) و واندایک (Fairclough, 1992) شکل گرفت. این چارچوب، رابطه‌ی گفتمان، قدرت و ایدئولوژی را تحلیل می‌کند و بر «نابرابری» و «سلطه» در بافت اجتماعی تأکید دارد. در رسانه، برای تحلیل ایدئولوژی و بازنمایی قدرت کاربرد دارد.', 'c41610b101524333078cfa540a9d3550ff7c3c36f52a406431729938dff037e1', 523, 'kc-kg-framework-critical-discourse-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c41610b101524333078cfa540a9d3550ff7c3c36f52a406431729938dff037e1', token_count=523, vector_point_id='kc-kg-framework-critical-discourse-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-discourse-3', 'kg-framework-critical-discourse', 3, '["نورمن فان دایک","نورمن فایرکلوف","تِیو فان دایک"]', 'bfb24f05f19badff62dea1fff337a304f7d6da0406fc6a0746b44fadcc2de4f3', 92, 'kc-kg-framework-critical-discourse-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bfb24f05f19badff62dea1fff337a304f7d6da0406fc6a0746b44fadcc2de4f3', token_count=92, vector_point_id='kc-kg-framework-critical-discourse-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
