INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-discourse-6', 'kg-framework-critical-discourse', 6, '["زبان‌شناسی","مطالعات رسانه","مطالعات فرهنگی","فلسفه"]', '1d7b16b5b9b8b945b2551dfc1861c42d51bd25d3e8619f34fd32c10c2d204ee1', 99, 'kc-kg-framework-critical-discourse-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1d7b16b5b9b8b945b2551dfc1861c42d51bd25d3e8619f34fd32c10c2d204ee1', token_count=99, vector_point_id='kc-kg-framework-critical-discourse-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-discourse-7', 'kg-framework-critical-discourse', 7, '["تحلیل ایدئولوژی در رسانه","تحلیل قدرت در گفتمان","مطالعات بازنمایی انتقادی"]', 'f828e55e2e42515cf4fe9d6fbc0871a78f7caaa196bef193947cb855a869a10a', 141, 'kc-kg-framework-critical-discourse-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f828e55e2e42515cf4fe9d6fbc0871a78f7caaa196bef193947cb855a869a10a', token_count=141, vector_point_id='kc-kg-framework-critical-discourse-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-discourse-8', 'kg-framework-critical-discourse', 8, '["Fairclough (1992). Discourse and Social Change","van Dijk (1993). The Principles of Critical Discourse Analysis"]', 'd7d5cfb1ce4ca00c202b4bd32849db670b3babb43fc456cdd2ffd7a77364afcd', 209, 'kc-kg-framework-critical-discourse-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d7d5cfb1ce4ca00c202b4bd32849db670b3babb43fc456cdd2ffd7a77364afcd', token_count=209, vector_point_id='kc-kg-framework-critical-discourse-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-theory-0', 'kg-framework-critical-theory', 1, 'چارچوب نظری انتقادی (Critical Theory Framework) نوع: FRAMEWORK چارچوب نظری انتقادی که از «مکتب فرانکفورت» استخراج شده و بر «نقد ایدئولوژی»، «نقد سلطه» و «رهایی‌بخشی» تأکید می‌کند؛ چارچوبی که در مطالعات رسانه، اقتصاد سیاسی رسانه و تحلیل ایدئولوژی کاربرد دارد.', 'fc02f9dac53b7b1b4183de0422668435dda30cd258437af24ba9771ef3d330dd', 469, 'kc-kg-framework-critical-theory-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fc02f9dac53b7b1b4183de0422668435dda30cd258437af24ba9771ef3d330dd', token_count=469, vector_point_id='kc-kg-framework-critical-theory-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-theory-2', 'kg-framework-critical-theory', 2, 'چارچوب نظری انتقادی (Critical Theory Framework) که از «مکتب فرانکفورت» استخراج شده، بر «نقد ایدئولوژی»، «نقد سلطه» و «رهایی‌بخشی» تأکید می‌کند. این چارچوب، در مطالعات رسانه، اقتصاد سیاسی رسانه و تحلیل ایدئولوژی کاربرد دارد. چارچوب نظری انتقادی، رسانه را به‌عنوان «ابزار سلطه» و «بازتولید ایدئولوژی» تحلیل می‌کند و «رهایی‌بخشی» (emancipation) را به‌عنوان «هدف نهایی» تعریف می‌کند.', '98a57a94c747dea7c1da570629a716bdc9131379adf81ec2efc06566918ec754', 689, 'kc-kg-framework-critical-theory-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='98a57a94c747dea7c1da570629a716bdc9131379adf81ec2efc06566918ec754', token_count=689, vector_point_id='kc-kg-framework-critical-theory-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-theory-3', 'kg-framework-critical-theory', 3, 'مبانی فلسفی چارچوب نظری انتقادی، بر «نظریه‌ی انتقادی» (critical theory) مکتب فرانکفورت استوار است. این چارچوب، «عقلانیت ابزاری» (instrumental rationality) و «سلطه» (domination) را «موضوع نقد» قرار می‌دهد و «رهایی‌بخشی» (emancipation) را «هدف نهایی» تعریف می‌کند.', 'ddd613b52ce0f3d5d06cd86af7fe8b0802a529082ccf26619c230c17c019c175', 476, 'kc-kg-framework-critical-theory-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ddd613b52ce0f3d5d06cd86af7fe8b0802a529082ccf26619c230c17c019c175', token_count=476, vector_point_id='kc-kg-framework-critical-theory-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-theory-4', 'kg-framework-critical-theory', 4, '["رسانه، «ابزار سلطه» است و «ایدئولوژی» را بازتولید می‌کند","«نقد ایدئولوژی»، «راه‌حل» است نه «نقد صرف»","«رهایی‌بخشی» (emancipation)، «هدف نهایی» پژوهش است","«عقلانیت ابزاری»، «موضوع نقد» است","پژوهش انتقادی، «کاربردی» است و «تغییر اجتماعی» را هدف دارد"]', '7802a469533cd3c04a650fc3ae36324292299aa7e693424c01b380d143750374', 463, 'kc-kg-framework-critical-theory-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7802a469533cd3c04a650fc3ae36324292299aa7e693424c01b380d143750374', token_count=463, vector_point_id='kc-kg-framework-critical-theory-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-theory-5', 'kg-framework-critical-theory', 5, '["ماکس هورکهایمر","تئودور آدورنو","هربرت ماركوزه","یورگن هابرماس"]', 'e6b81e31393df454f40055dbcc7c7fa9e26731ab61cbea54e50f0e72df757545', 119, 'kc-kg-framework-critical-theory-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e6b81e31393df454f40055dbcc7c7fa9e26731ab61cbea54e50f0e72df757545', token_count=119, vector_point_id='kc-kg-framework-critical-theory-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-theory-6', 'kg-framework-critical-theory', 6, '["مطالعات رسانه","اقتصاد سیاسی","فلسفه","جامعه‌شناسی"]', '7f73b5594d7250f0d4573341628af309f134081753308d6ef7b6a0aa7aa24d9f', 98, 'kc-kg-framework-critical-theory-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f73b5594d7250f0d4573341628af309f134081753308d6ef7b6a0aa7aa24d9f', token_count=98, vector_point_id='kc-kg-framework-critical-theory-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-theory-7', 'kg-framework-critical-theory', 7, '["تحلیل ایدئولوژی در رسانه","تحلیل سلطه در اقتصاد سیاسی رسانه","تحلیل «رهایی‌بخشی» در پژوهش رسانه‌ای"]', 'be3d3a0966e260822e8dec4f320872fa0b06ddf7a4e2ea69f17eefbea5fb3012', 185, 'kc-kg-framework-critical-theory-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='be3d3a0966e260822e8dec4f320872fa0b06ddf7a4e2ea69f17eefbea5fb3012', token_count=185, vector_point_id='kc-kg-framework-critical-theory-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
