INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-critical-theory-10', 'kg-framework-critical-theory', 10, '["نقد از سوی روش‌گرایان: چارچوب انتقادی، «نظریه‌پرداز» است نه «پژوهشگر»"]', '8d50a65a7e3798748126702e1ed43b4344d6bf7a2f853d426847bfa2ac90a6b2', 132, 'kc-kg-framework-critical-theory-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8d50a65a7e3798748126702e1ed43b4344d6bf7a2f853d426847bfa2ac90a6b2', token_count=132, vector_point_id='kc-kg-framework-critical-theory-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
