INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-cultivation-analysis-0', 'kg-framework-cultivation-analysis', 1, 'چارچوب تحلیل کاشت (Cultivation Analysis Framework) نوع: FRAMEWORK چارچوبی که فرآیند «کاشت» (cultivation) نگرش‌های مخاطب توسط تماشای طولانی‌مدت تلویزیون را نشان می‌دهد.', '943fead9e85de5bc657f54d1c9beaaaf22d01220e25a02b7deec04d05a983f69', 303, 'kc-kg-framework-cultivation-analysis-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='943fead9e85de5bc657f54d1c9beaaaf22d01220e25a02b7deec04d05a983f69', token_count=303, vector_point_id='kc-kg-framework-cultivation-analysis-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-cultivation-analysis-2', 'kg-framework-cultivation-analysis', 2, 'Gerbner و همکاران (1969-1980) چارچوب تحلیل کاشت را در سه سطح تعریف کردند: ۱) «تصویرسازی» (mainstreaming): تماشای زیاد تلویزیون، نگرش‌های مخاطبان مختلف را به‌شکل یکسان (mainstream) می‌کند؛ ۲) «ترس» (resonance): تماشای زیاد تلویزیون، نگرش‌های مخاطبان با شرایط مشابه (مثلاً خشونت) را تقویت می‌کند؛ ۳) «خشم» (anxiety): تماشای زیاد تلویزیون، نگرش‌های ترس و انزجار را تقویت می‌کند.', '52e9fc620eab868c85f171c142838fb8db75d0942ca46b28649d3f9721e0a418', 681, 'kc-kg-framework-cultivation-analysis-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='52e9fc620eab868c85f171c142838fb8db75d0942ca46b28649d3f9721e0a418', token_count=681, vector_point_id='kc-kg-framework-cultivation-analysis-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-cultivation-analysis-3', 'kg-framework-cultivation-analysis', 3, '["George Gerbner"]', 'd2227fda280784a9d37792d5dbe6f68ff7847df561ddf020e0b657f2c3f8b577', 32, 'kc-kg-framework-cultivation-analysis-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d2227fda280784a9d37792d5dbe6f68ff7847df561ddf020e0b657f2c3f8b577', token_count=32, vector_point_id='kc-kg-framework-cultivation-analysis-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
