INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-culture-industry-0', 'kg-framework-culture-industry', 1, 'نقد صنعت فرهنگ (Culture Industry Critique) نوع: FRAMEWORK چارچوب تحلیلی مکتب فرانکفورت که فرهنگ و سرگرمی‌های توده را «صنعت فرهنگ» می‌نامد؛ تولید انبوه کالاهای فرهنگی که با کالاسازی تفریح، نقد و مقاومت مخاطب را فرو می‌نشاند.', 'dd116103cc90ecbe0a620d72a3f5d643e3fa00f39ab89bcd78c1ac8b7614825e', 405, 'kc-kg-framework-culture-industry-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dd116103cc90ecbe0a620d72a3f5d643e3fa00f39ab89bcd78c1ac8b7614825e', token_count=405, vector_point_id='kc-kg-framework-culture-industry-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-culture-industry-2', 'kg-framework-culture-industry', 2, 'آدورنو و هورکهایمر در «دیالکتیک روشنگری» مفهوم «صنعت فرهنگ» (Kulturindustrie) را مطرح کردند: رسانه‌های توده، سرگرمی «تکنیکی‌شده» می‌سازند که همسان‌ساز است، نیازهای جعلی می‌آفریند و با پذیرش وضع موجود، زمینه‌ی بازتولید سلطه را فراهم می‌کند.', '4518def9e4a8bc876802bcf6dc61fbcc146581eec4df96220184984d76b856de', 434, 'kc-kg-framework-culture-industry-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4518def9e4a8bc876802bcf6dc61fbcc146581eec4df96220184984d76b856de', token_count=434, vector_point_id='kc-kg-framework-culture-industry-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
