INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-descriptive-statistics-2', 'kg-framework-descriptive-statistics', 2, 'مجموعه‌ای از روش‌ها که داده‌ها را با شاخص‌های مرکزی (میانگین، میانه، نما) و پراکندگی (واریانس، انحراف معیار) خلاصه می‌کنند تا ساختار و توزیع داده خوانا شود.', '07ce6e3df1c7c99583dbbca969011743b64c8ff51e646313843dbb4a1d045001', 283, 'kc-kg-framework-descriptive-statistics-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='07ce6e3df1c7c99583dbbca969011743b64c8ff51e646313843dbb4a1d045001', token_count=283, vector_point_id='kc-kg-framework-descriptive-statistics-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
