INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-discourse-analysis-0', 'kg-framework-discourse-analysis', 1, 'تحلیل گفتمان (Discourse Analysis) نوع: FRAMEWORK چارچوب نظری تحلیل گفتمان که بر تحلیل «گفتمان» (discourse) به‌عنوان فرایند ساختن معنا در بافت اجتماعی-زبانی تمرکز دارد و رابطه‌ی زبان و قدرت را بررسی می‌کند.', '878f9a9e75a29a86a37a81182be9bce3832929decfd90417c35b602ae0f19a9d', 372, 'kc-kg-framework-discourse-analysis-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='878f9a9e75a29a86a37a81182be9bce3832929decfd90417c35b602ae0f19a9d', token_count=372, vector_point_id='kc-kg-framework-discourse-analysis-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-discourse-analysis-2', 'kg-framework-discourse-analysis', 2, 'تحلیل گفتمان (Discourse Analysis) از فوکو (1969) و فمینیست‌ها (1970s) شکل گرفت. گفتمان، «فرایند ساختن معنا» در بافت اجتماعی-زبانی است و رابطه‌ی زبان، قدرت و ایدئولوژی را تحلیل می‌کند. این چارچوب، پایه‌ی تحلیل گفتمان انتقادی (CDA) است.', 'aa2186aa105bd6f3ea89aada915388e8674a2c77bc293a2035d8063b7b0a420a', 425, 'kc-kg-framework-discourse-analysis-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='aa2186aa105bd6f3ea89aada915388e8674a2c77bc293a2035d8063b7b0a420a', token_count=425, vector_point_id='kc-kg-framework-discourse-analysis-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
