INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-discourse-analysis-7', 'kg-framework-discourse-analysis', 7, '["تحلیل گفتمان رسانه‌ای","تحلیل قدرت و ایدئولوژی","مطالعات بازنمایی"]', 'c722a7a8ccff0b79bdc7cc4f064c39aa749fa269592b3546f825a17409f64725', 125, 'kc-kg-framework-discourse-analysis-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c722a7a8ccff0b79bdc7cc4f064c39aa749fa269592b3546f825a17409f64725', token_count=125, vector_point_id='kc-kg-framework-discourse-analysis-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-discourse-analysis-8', 'kg-framework-discourse-analysis', 8, '["Foucault (1969). The Order of Discourse","van Dijk (2008). Discourse and Power"]', 'e4d0b113423586b5f3955d1e04cfd87bd8d8f44dbb06ee1cab1d1eace3dc4442', 149, 'kc-kg-framework-discourse-analysis-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e4d0b113423586b5f3955d1e04cfd87bd8d8f44dbb06ee1cab1d1eace3dc4442', token_count=149, vector_point_id='kc-kg-framework-discourse-analysis-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-hegemony-0', 'kg-framework-hegemony', 1, 'چارچوب هژمونی و بازنمایی (Hegemony and Representation Framework) نوع: FRAMEWORK چارچوب هژمونی و بازنمایی که از «مکتب بیرمنگام» استخراج شده و بر «هژمونی فرهنگی»، «بازنمایی» و «مقاومت» تأکید می‌کند؛ چارچوبی که در مطالعات رسانه، تحلیل هویت و تحلیل گفتمان کاربرد دارد.', 'c4c08f4a5c1909a06452c6f6394682c842b1f8f0a7ef76f6788caf245b837223', 479, 'kc-kg-framework-hegemony-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c4c08f4a5c1909a06452c6f6394682c842b1f8f0a7ef76f6788caf245b837223', token_count=479, vector_point_id='kc-kg-framework-hegemony-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-hegemony-2', 'kg-framework-hegemony', 2, 'چارچوب هژمونی و بازنمایی (Hegemony and Representation Framework) که از «مکتب بیرمنگام» استخراج شده، بر «هژمونی فرهنگی»، «بازنمایی» و «مقاومت» تأکید می‌کند. این چارچوب، در مطالعات رسانه، تحلیل هویت و تحلیل گفتمان کاربرد دارد. چارچوب هژمونی و بازنمایی، رسانه را به‌عنوان «میدان قدرت» و «زمین بازی معنابخشی» تحلیل می‌کند و «مقاومت» و «فعالیت» مخاطب را «موضوع پژوهش» قرار می‌دهد.', '4daf0e3047fc270e5ec12708b5c90f6b1ee72de22c02fd05d45ab3e62f16fc58', 681, 'kc-kg-framework-hegemony-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4daf0e3047fc270e5ec12708b5c90f6b1ee72de22c02fd05d45ab3e62f16fc58', token_count=681, vector_point_id='kc-kg-framework-hegemony-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-hegemony-3', 'kg-framework-hegemony', 3, 'مبانی فلسفی چارچوب هژمونی و بازنمایی، بر «نظریه‌ی هژمونی» (hegemony theory) گرامشی و «نظریه‌ی بازنمایی» (representation theory) استیون هال استوار است. این چارچوب، «هژمونی» (hegemony) و «بازنمایی» (representation) را «موضوع تحلیل» قرار می‌دهد و «مقاومت» (resistance) و «فعالیت» (agency) مخاطب را «موضوع پژوهش» قرار می‌دهد.', '13f35efd70a6d630139ae22d46859d3c61dd75c1a245ee410463cf7febe2d01a', 583, 'kc-kg-framework-hegemony-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='13f35efd70a6d630139ae22d46859d3c61dd75c1a245ee410463cf7febe2d01a', token_count=583, vector_point_id='kc-kg-framework-hegemony-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-hegemony-4', 'kg-framework-hegemony', 4, '["رسانه، «میدان قدرت» است و «هژمونی» را بازتولید می‌کند","«بازنمایی» (representation)، «بازنمایی‌پذیر» است","«مقاومت» (resistance)، «موضوع پژوهش» است","«هویت» (identity)، «بازنمایی‌شده» است","«مخاطب» (audience)، «فعال» است نه «منفی»"]', '0fb655c4dae4222a8e046be98b737205167d6a8e5c83067553afc8be011647f8', 425, 'kc-kg-framework-hegemony-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0fb655c4dae4222a8e046be98b737205167d6a8e5c83067553afc8be011647f8', token_count=425, vector_point_id='kc-kg-framework-hegemony-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-hegemony-5', 'kg-framework-hegemony', 5, '["استیون هال","آنتونیو گرامشی","ریچارد هورگارت","دیوید مورلی"]', 'b9ed5ea13f781d21efed458762a55694da36eba6df881c91f0359ad3c3a4f38e', 112, 'kc-kg-framework-hegemony-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b9ed5ea13f781d21efed458762a55694da36eba6df881c91f0359ad3c3a4f38e', token_count=112, vector_point_id='kc-kg-framework-hegemony-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-hegemony-6', 'kg-framework-hegemony', 6, '["مطالعات فرهنگی","مطالعات رسانه","زبان‌شناسی","فمینیسم"]', '98a1a1ad59d7ccd38c2419c849bbf41ed5300cf3176c7270329d23b60ce9887b', 103, 'kc-kg-framework-hegemony-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='98a1a1ad59d7ccd38c2419c849bbf41ed5300cf3176c7270329d23b60ce9887b', token_count=103, vector_point_id='kc-kg-framework-hegemony-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
