INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-media-bias-0', 'kg-framework-media-bias', 1, 'نظریه‌ی سوگیری رسانه‌ای (Medium Bias Theory) نوع: FRAMEWORK چارچوب نظری مکتب تورنتو (هارولد اینیس) که هر فناوری رسانه «سوگیری» (bias) ذاتی به زمان یا مکان دارد و این سوگیری، ساختار تمدن را شکل می‌دهد.', '1062b884ee8f4a92ca4471d15c02da45820fa07746f74a9b88b6e607368e4c8a', 363, 'kc-kg-framework-media-bias-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1062b884ee8f4a92ca4471d15c02da45820fa07746f74a9b88b6e607368e4c8a', token_count=363, vector_point_id='kc-kg-framework-media-bias-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-media-bias-2', 'kg-framework-media-bias', 2, 'نظریه‌ی سوگیری رسانه‌ای (Medium Bias Theory) هارولد اینیس، هر رسانه را بر اساس «سوگیری» ذاتی به مکان (space) یا زمان (time) تحلیل می‌کند: رسانه‌های مکان‌محور (مانند کاغذ) تمدن‌های گسترده‌ی مکانی می‌سازند؛ رسانه‌های زمان‌محور (مانند سنجاقک) تمدن‌های معنوی می‌سازند.', '706c908f297bf58e530a3ef20d60053e50d8339c2050ebb129644054fdf58f4c', 479, 'kc-kg-framework-media-bias-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='706c908f297bf58e530a3ef20d60053e50d8339c2050ebb129644054fdf58f4c', token_count=479, vector_point_id='kc-kg-framework-media-bias-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
