INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-media-environment-0', 'kg-framework-media-environment', 1, 'نظریه‌ی محیط رسانه‌ای (Media Environment Theory) نوع: FRAMEWORK چارچوب نظری مکتب تورنتو (ویسکوفیت) که رسانه‌ها را «محیط» (environment) ادراک انسان می‌داند و تأثیرات «عمیق‌تر از محتوا» رسانه بر ادراک را تحلیل می‌کند.', '5b5fa710561f0d0c3ec645d1ba411765af76fbc921ef68f65d78e39a32cd46c4', 390, 'kc-kg-framework-media-environment-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5b5fa710561f0d0c3ec645d1ba411765af76fbc921ef68f65d78e39a32cd46c4', token_count=390, vector_point_id='kc-kg-framework-media-environment-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-media-environment-2', 'kg-framework-media-environment', 2, 'نظریه‌ی محیط رسانه‌ای (Media Ecology) نیلسون و ویسکوفیت، رسانه را «محیط» ادراک انسان می‌داند. تأثیرات «عمیق‌تر از محتوا» (deeper than content) رسانه بر ادراک و رفتار را تحلیل می‌کند و «اثرات زیست‌محیطی» رسانه را بررسی می‌کند.', '0e48fb0a657fb7de949d22e91a961bc581ac82ae94492236f575f5947fb04fe2', 409, 'kc-kg-framework-media-environment-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0e48fb0a657fb7de949d22e91a961bc581ac82ae94492236f575f5947fb04fe2', token_count=409, vector_point_id='kc-kg-framework-media-environment-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
