INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-medium-extension-0', 'kg-framework-medium-extension', 1, 'نظریه‌ی رسانه به‌مثابه‌ی امتداد انسان (Medium as Human Extension) نوع: FRAMEWORK چارچوب نظری مکتب تورنتو (ماکولان) که رسانه را «امتداد» (extension) اندام و ادراک انسان می‌داند: هر فناوری رسانه‌ای، بخشی از بدن و ذهن انسان را بیرون می‌راند.', '96d11edd2cb448709396109779ad8bd21b57178787fa2911de4b237e85a542a8', 432, 'kc-kg-framework-medium-extension-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='96d11edd2cb448709396109779ad8bd21b57178787fa2911de4b237e85a542a8', token_count=432, vector_point_id='kc-kg-framework-medium-extension-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-medium-extension-2', 'kg-framework-medium-extension', 2, 'نظریه‌ی «رسانه به‌مثابه‌ی امتداد» (Medium as Human Extension) ماکولان، رسانه را «امتداد» اندام، ادراک و عصب انسان می‌داند: نور، امتداد پوست است؛ چرخ‌دست، امتداد دست؛ تلویزیون، امتداد سیستم عصبی. این چارچوب، تحلیل اثرات رسانه‌ای را بر ادراک متمرکز می‌کند.', '328235e5502c395ea92ade98eed6f54e622b3d4e701239e347b100b524df0fbb', 461, 'kc-kg-framework-medium-extension-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='328235e5502c395ea92ade98eed6f54e622b3d4e701239e347b100b524df0fbb', token_count=461, vector_point_id='kc-kg-framework-medium-extension-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
