INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-medium-extension-8', 'kg-framework-medium-extension', 8, '["McLuhan (1964). Understanding Media"]', '80ac1936a2146e2efa38b42d0e40621cf9bb933bfa36167a4683cb23d28b0aea', 70, 'kc-kg-framework-medium-extension-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='80ac1936a2146e2efa38b42d0e40621cf9bb933bfa36167a4683cb23d28b0aea', token_count=70, vector_point_id='kc-kg-framework-medium-extension-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-medium-theory-0', 'kg-framework-medium-theory', 1, 'چارچوب نظریه‌ی رسانه‌ای (Medium Theory Framework) نوع: FRAMEWORK چارچوب نظریه‌ی رسانه‌ای که از «مکتب تورنتو» استخراج شده و بر «رسانه به‌مثابه‌ی امتداد انسان»، «محیط رسانه‌ای» و «تاریخ رسانه» تأکید می‌کند؛ چارچوبی که در مطالعات رسانه، فناوری و تاریخ رسانه کاربرد دارد.', '1f71f3995f88d6288d03b9ebc82fc7ac993694cf0592f9b2fc141db964b39b0a', 485, 'kc-kg-framework-medium-theory-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1f71f3995f88d6288d03b9ebc82fc7ac993694cf0592f9b2fc141db964b39b0a', token_count=485, vector_point_id='kc-kg-framework-medium-theory-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-medium-theory-2', 'kg-framework-medium-theory', 2, 'چارچوب نظریه‌ی رسانه‌ای (Medium Theory Framework) که از «مکتب تورنتو» استخراج شده، بر «رسانه به‌مثابه‌ی امتداد انسان»، «محیط رسانه‌ای» و «تاریخ رسانه» تأکید می‌کند. این چارچوب، در مطالعات رسانه، فناوری و تاریخ رسانه کاربرد دارد. چارچوب نظریه‌ی رسانه‌ای، «رسانه» را به‌عنوان «امتداد انسان» (extension of man) تحلیل می‌کند و «محیط رسانه‌ای» (media environment) و «تاریخ رسانه» (history of media) را «موضوع تحلیل» قرار می‌دهد.', 'c020c6a5d5c91ea861a3449118747f8d6e94bbd5c2f3fa2dd134b7b43a640d35', 769, 'kc-kg-framework-medium-theory-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c020c6a5d5c91ea861a3449118747f8d6e94bbd5c2f3fa2dd134b7b43a640d35', token_count=769, vector_point_id='kc-kg-framework-medium-theory-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-medium-theory-3', 'kg-framework-medium-theory', 3, 'مبانی فلسفی چارچوب نظریه‌ی رسانه‌ای، بر «نظریه‌ی رسانه‌ای» (medium theory) مارشال مک‌لوهان (Marshall McLuhan) استوار است. این چارچوب، «رسانه» (medium) و «فناوری» (technology) را «موضوع تحلیل» قرار می‌دهد و «محیط رسانه‌ای» (media environment) و «تاریخ رسانه» (history of media) را «موضوع پژوهش» قرار می‌دهد.', '850ea608813792f60a128f189631dbf410bb5b9676cada564831da0af793be1a', 556, 'kc-kg-framework-medium-theory-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='850ea608813792f60a128f189631dbf410bb5b9676cada564831da0af793be1a', token_count=556, vector_point_id='kc-kg-framework-medium-theory-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-medium-theory-4', 'kg-framework-medium-theory', 4, '["رسانه، «امتداد انسان» است","«محیط رسانه‌ای»، «هویت» و «نظم» اجتماعی را بازتولید می‌کند","«تاریخ رسانه»، «ریشه‌ها» و «پیامدها» را نشان می‌دهد","«شکل» رسانه، «معنا» و «نظم» اجتماعی را می‌سازد","رسانه‌های جدید، «محیط» جدید می‌سازند"]', '021e2929e4bc054cf3cbd73c6d5ae5fa1bc31f9ba6acaad18c12e9133cc53888', 421, 'kc-kg-framework-medium-theory-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='021e2929e4bc054cf3cbd73c6d5ae5fa1bc31f9ba6acaad18c12e9133cc53888', token_count=421, vector_point_id='kc-kg-framework-medium-theory-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
