INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-medium-theory-6', 'kg-framework-medium-theory', 6, '["مطالعات رسانه","فناوری","تاریخ","فرهنگ"]', 'b49412610066d315b0f76a03658439de873c27463842ed8d2a36954dd07190ff', 76, 'kc-kg-framework-medium-theory-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b49412610066d315b0f76a03658439de873c27463842ed8d2a36954dd07190ff', token_count=76, vector_point_id='kc-kg-framework-medium-theory-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
