INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-meta-narrative-critique-0', 'kg-framework-meta-narrative-critique', 1, 'نقد روایت‌های کلان (Meta-narrative Critique) نوع: FRAMEWORK چارچوب نظری سنت پست‌مدرن (لیوتار) که «روایت‌های کلان» (metanarratives) — پیشرفت، آزادی، حقیقت، تاریخ — را به چالش می‌کشد و «اعتماد به روایت‌های کلان» (incredulity toward metanarratives) را اعلام می‌کند.', 'b8f2f334f5f5148cb4589e2961c55fc0f4c2038191ade89459583679d9d2f1fe', 476, 'kc-kg-framework-meta-narrative-critique-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b8f2f334f5f5148cb4589e2961c55fc0f4c2038191ade89459583679d9d2f1fe', token_count=476, vector_point_id='kc-kg-framework-meta-narrative-critique-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-meta-narrative-critique-2', 'kg-framework-meta-narrative-critique', 2, 'نقد روایت‌های کلان (Meta-narrative Critique) از لیوتار (1979) می‌آید. «روایت‌های کلان» (مانند پیشرفت، آزادی، حقیقت، تاریخ) در پست‌مدرنیسم «اعتبار» خود را از دست داده‌اند و «اعتماد به روایت‌های کلان» (incredulity toward metanarratives) اعلام می‌شود.', 'd152699cc9b4eb4b979940b2418a71986f9357453750f7fe256f87989b920102', 450, 'kc-kg-framework-meta-narrative-critique-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d152699cc9b4eb4b979940b2418a71986f9357453750f7fe256f87989b920102', token_count=450, vector_point_id='kc-kg-framework-meta-narrative-critique-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
