INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-multivariate-analysis-2', 'kg-framework-multivariate-analysis', 2, 'مجموعه‌ای از روش‌ها (تحلیل عاملی، خوشه‌ای، تشخیصی) که هم‌زمان چند متغیر را بررسی می‌کنند تا ساختارهای پنهان، گروه‌بندی‌ها یا الگوهای داده را کشف کنند.', 'e15561ab4e45831e4b6d088d17b08ece38c50f45ab0972862b65c8fabf10a1ba', 272, 'kc-kg-framework-multivariate-analysis-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e15561ab4e45831e4b6d088d17b08ece38c50f45ab0972862b65c8fabf10a1ba', token_count=272, vector_point_id='kc-kg-framework-multivariate-analysis-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
