INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-participatory-0', 'kg-framework-participatory', 1, 'چارچوب مشارکتی (Participatory Framework) نوع: FRAMEWORK چارچوبی که فرآیند مشارکت فعال مخاطب در تولید و تفسیر محتوا را در چهار سطح نشان می‌دهد.', 'b8d42d1b5a7cc0d34af82a7ed30fb5ba2253c38398ec8edba7d049d2528e44eb', 258, 'kc-kg-framework-participatory-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b8d42d1b5a7cc0d34af82a7ed30fb5ba2253c38398ec8edba7d049d2528e44eb', token_count=258, vector_point_id='kc-kg-framework-participatory-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-participatory-2', 'kg-framework-participatory', 2, 'Jenkins (2006) چارچوب مشارکتی را در چهار سطح تعریف کرد: ۱) مشارکت در تولید محتوا (user-generated content)؛ ۲) مشارکت در توزیع محتوا (sharing)؛ ۳) مشارکت در تفسیر محتوا (discussion)؛ ۴) مشارکت در تولید معنا (remixing). این چارچوب در مطالعات فرهنگ مشارکتی استفاده می‌شود.', 'de53c5b041c7d8cc6cc1cbb48e2ca37ffa1465f1de27ddfcc9ee3fa4d397c418', 489, 'kc-kg-framework-participatory-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='de53c5b041c7d8cc6cc1cbb48e2ca37ffa1465f1de27ddfcc9ee3fa4d397c418', token_count=489, vector_point_id='kc-kg-framework-participatory-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
