INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-peircean-semiotics-0', 'kg-framework-peircean-semiotics', 1, 'نشانه‌شناسی پیرسی (Peircean Semiotics) نوع: FRAMEWORK چارچوب نظری نشانه‌شناسی بر پایه‌ی چارلز سندرس پیرس: نشانه‌ها سه نوع‌اند — «آیکون» (icon)، «نشان» (index) و «نماد» (symbol) — و معنا در فرایند تفسیر (interpretation) ساخته می‌شود.', 'd5508481c226495133dcf73814b49c17556789f3106e2eb5728223a11719c3ec', 421, 'kc-kg-framework-peircean-semiotics-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d5508481c226495133dcf73814b49c17556789f3106e2eb5728223a11719c3ec', token_count=421, vector_point_id='kc-kg-framework-peircean-semiotics-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-peircean-semiotics-2', 'kg-framework-peircean-semiotics', 2, 'نشانه‌شناسی پیرسی (Peircean Semiotics) بر سه‌گانه‌ی «آیکون»، «نشان» و «نماد» استوار است و معنا را فرایندی «تفسیری» (interpretive) می‌داند. این چارچوب، بر «رابطه» نشانه و تفسیرکننده تأکید دارد و در تحلیل رسانه و فرهنگ کاربرد دارد.', 'a3189c9eed745e7d7acf95d57fd721efec3204e3d269736adff1702d6ed94fae', 416, 'kc-kg-framework-peircean-semiotics-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a3189c9eed745e7d7acf95d57fd721efec3204e3d269736adff1702d6ed94fae', token_count=416, vector_point_id='kc-kg-framework-peircean-semiotics-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
