INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-political-framing-0', 'kg-framework-political-framing', 1, 'چارچوب چارچوب‌بندی سیاسی (Political Framing Framework) نوع: FRAMEWORK چارچوبی که فرآیند چارچوب‌بندی مسائل سیاسی توسط رسانه را در چهار عنصر (تأکید، تفسیر، تمایل، حل‌وفصل) نشان می‌دهد.', '5050078f3db34aa1bdb2116bdfe9dbf4a2c82841cca5cf1e2904b8a1d2c1fd51', 330, 'kc-kg-framework-political-framing-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5050078f3db34aa1bdb2116bdfe9dbf4a2c82841cca5cf1e2904b8a1d2c1fd51', token_count=330, vector_point_id='kc-kg-framework-political-framing-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-political-framing-2', 'kg-framework-political-framing', 2, 'Entman (1993) چارچوب چارچوب‌بندی را در چهار عنصر تعریف کرد: ۱) «تأکید» (highlighting): انتخاب برخی وجوه رویداد؛ ۲) «تفسیر» (interpretation): ارائه‌ی توضیح برای رویداد؛ ۳) «تمایل» (evaluating): ارزیابی مثبت یا منفی رویداد؛ ۴) «حل‌وفصل» (prescribing): پیشنهاد راه‌حل برای رویداد. این چارچوب در مطالعات ارتباطات سیاسی استفاده می‌شود.', 'e10d36470f54ed7ba88006a1f99aba61ed1bb9c2018a8a71d733ab7c14d3397c', 600, 'kc-kg-framework-political-framing-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e10d36470f54ed7ba88006a1f99aba61ed1bb9c2018a8a71d733ab7c14d3397c', token_count=600, vector_point_id='kc-kg-framework-political-framing-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-political-framing-3', 'kg-framework-political-framing', 3, '["Robert Entman"]', '6cd001cf74c7aedfaf4540bbf4a4896e7f581dbaf9c527cbee7ee30b5c4b6376', 30, 'kc-kg-framework-political-framing-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6cd001cf74c7aedfaf4540bbf4a4896e7f581dbaf9c527cbee7ee30b5c4b6376', token_count=30, vector_point_id='kc-kg-framework-political-framing-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
