INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-public-sphere-0', 'kg-framework-public-sphere', 1, 'چارچوب فضای عمومی (Public Sphere Framework) نوع: FRAMEWORK چارچوبی که ساختار «فضای عمومی» (public sphere) و نقش آن در فرآیندهای دموکراتیک را نشان می‌دهد.', '7d54cfac421f48aba5d0b6755f828e3d254ac038cb0ca8360938f262f0fb81a9', 278, 'kc-kg-framework-public-sphere-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7d54cfac421f48aba5d0b6755f828e3d254ac038cb0ca8360938f262f0fb81a9', token_count=278, vector_point_id='kc-kg-framework-public-sphere-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-public-sphere-2', 'kg-framework-public-sphere', 2, 'Habermas (1962) چارچوب فضای عمومی را در سه سطح تعریف کرد: ۱) «فضای عمومی بورژوایی» (bürgerliche Öffentlichkeit): فضایی برای گفت‌وگوی منطقی شهروندان؛ ۲) «فضای عمومی توده‌ای» (mass public sphere): فضا در عصر رسانه‌های توده‌ای؛ ۳) «فضای عمومی جهانی» (global public sphere): فضا در عصر جهانی‌شدن. این چارچوب در مطالعات سیاسی و رسانه‌ای استفاده می‌شود.', '2e5bb8c628d05f1306008f0a422585d14d3782637141fb8f1464e12da70a5e87', 630, 'kc-kg-framework-public-sphere-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2e5bb8c628d05f1306008f0a422585d14d3782637141fb8f1464e12da70a5e87', token_count=630, vector_point_id='kc-kg-framework-public-sphere-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
