INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-qual-content-analysis-0', 'kg-framework-qual-content-analysis', 1, 'تحلیل محتوا (خانواده) (Content Analysis (family)) نوع: FRAMEWORK کدگذاری نظام‌مند متن برای توصیف، تفسیر و گاه شمارش معانی رسانه.', 'e6f2655778da610d05f437a02c8a45644ce24be725cd8aeb427a98980b563294', 232, 'kc-kg-framework-qual-content-analysis-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e6f2655778da610d05f437a02c8a45644ce24be725cd8aeb427a98980b563294', token_count=232, vector_point_id='kc-kg-framework-qual-content-analysis-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-qual-content-analysis-2', 'kg-framework-qual-content-analysis', 2, 'تحلیل محتوا پل بین روش‌های کمی و کیفی است: با کدگذاری نظام‌مند، متون رسانه‌ای خوانده، دسته‌بندی و تفسیر می‌شوند. سه شیوه‌ی قراردادی (آزگار)، جهت‌دار (کوزر) و تلخیصی (هاینز) در این خانواده است.', 'ba20d70eac2132eb8b450cca34c3fea0b732b78cdf9fcd269d5285ea6c07bd04', 349, 'kc-kg-framework-qual-content-analysis-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ba20d70eac2132eb8b450cca34c3fea0b732b78cdf9fcd269d5285ea6c07bd04', token_count=349, vector_point_id='kc-kg-framework-qual-content-analysis-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
