INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-qual-thematic-analysis-0', 'kg-framework-qual-thematic-analysis', 1, 'تحلیل مضمون (خانواده) (Thematic Analysis (family)) نوع: FRAMEWORK خانواده‌ای از روش‌های کیفی که داده‌ی مصاحبه و متن را برای یافتن مضامین تکرارشونده می‌کاود.', '5dd3f51a69b7b0b2e40fcbf892112e16305b03507cfe2f4ef46d42df614d8653', 283, 'kc-kg-framework-qual-thematic-analysis-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5dd3f51a69b7b0b2e40fcbf892112e16305b03507cfe2f4ef46d42df614d8653', token_count=283, vector_point_id='kc-kg-framework-qual-thematic-analysis-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-qual-thematic-analysis-2', 'kg-framework-qual-thematic-analysis', 2, 'تحلیل مضمون روی‌هم‌رنجیده‌ترین روش کیفی در علوم ارتباطات است. داده‌ها (مصاحبه، یادداشت، رسانه) بارها خوانده، کد شده و کدها در مضمون گرد هم می‌آیند. در این خانواده سه شیوه‌ی استقرایی، قیاسی و بازتابی شناخته می‌شود.', '5cdf6fc0cfdc5a6f8fa14d42e35083ef3e0c1fd8a73fddfe2c548d2b05f86cc8', 387, 'kc-kg-framework-qual-thematic-analysis-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5cdf6fc0cfdc5a6f8fa14d42e35083ef3e0c1fd8a73fddfe2c548d2b05f86cc8', token_count=387, vector_point_id='kc-kg-framework-qual-thematic-analysis-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
