INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-representation-0', 'kg-framework-representation', 1, 'مطالعات بازنمایی (Representation Studies) نوع: FRAMEWORK چارچوب تحلیلی مکتب بیرمنگام که رسانه را دستگاهی برای «ساختن» معنای اجتماعی می‌داند و زبان، تصویر و روایت را ابزارهای اصلی بازنمایی و در نتیجه‌ی قدرت می‌بیند.', 'f1fafcc65f02e211e2a56b638c3cf29fb32b258930b86ab4bb4a11b096932ba0', 389, 'kc-kg-framework-representation-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f1fafcc65f02e211e2a56b638c3cf29fb32b258930b86ab4bb4a11b096932ba0', token_count=389, vector_point_id='kc-kg-framework-representation-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-representation-2', 'kg-framework-representation', 2, 'بازنمایی (Representation) در مکتب بیرمنگام به این معناست که رسانه واقعیت را بازتاب نمی‌دهد، بلکه آن را می‌سازد. زبان و تصویر «مکانیزم‌های بازنمایی»‌اند و با انتخاب، حذف و چارچوب‌بندی، معنای اجتماعی و هویت را شکل می‌دهند و در نتیجه‌ی قدرت را بازتولید می‌کنند.', 'f3daf74da6c505518ebc6789027e078e1f87f57eb2106712c4458932247938dc', 469, 'kc-kg-framework-representation-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f3daf74da6c505518ebc6789027e078e1f87f57eb2106712c4458932247938dc', token_count=469, vector_point_id='kc-kg-framework-representation-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
