INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-saussurian-semiotics-0', 'kg-framework-saussurian-semiotics', 1, 'نشانه‌شناسی سوسوری (Saussurian Semiotics) نوع: FRAMEWORK چارچوب نظری نشانه‌شناسی بر پایه‌ی سوسور: نشانه (sign) از «مورف» (signifier) و «مضمون» (signified) تشکیل می‌شود و معنا در «اختلاف» ساختاری نشانه‌ها ساخته می‌شود.', '19001684b51c24dddf478950ba5b76615d26dacf8aa028706c97048d93c8febd', 394, 'kc-kg-framework-saussurian-semiotics-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='19001684b51c24dddf478950ba5b76615d26dacf8aa028706c97048d93c8febd', token_count=394, vector_point_id='kc-kg-framework-saussurian-semiotics-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-saussurian-semiotics-2', 'kg-framework-saussurian-semiotics', 2, 'نشانه‌شناسی سوسوری (Saussurian Semiotics) بر دو مفهومی بنیادین استوار است: «مورف» (signifier — شکل زبانی) و «مضمون» (signified — مفهوم). معنا نه ذاتی، بلکه در «اختلاف» (difference) ساختاری نشانه‌ها ساخته می‌شود.', 'd2b7abad8e8b6a9cfc057a203af1e359f8c40c9b331dd503df7ac3cc303ee5eb', 383, 'kc-kg-framework-saussurian-semiotics-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d2b7abad8e8b6a9cfc057a203af1e359f8c40c9b331dd503df7ac3cc303ee5eb', token_count=383, vector_point_id='kc-kg-framework-saussurian-semiotics-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
