INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-saussurian-semiotics-7', 'kg-framework-saussurian-semiotics', 7, '["تحلیل نشانه‌شناختی رسانه","تحلیل بازنمایی","پایه‌ی نشانه‌شناسی فرهنگی"]', 'e200a822735145e77678eb91e6afd2925c2f42db9c550ad6c1fa1c4ecfb4ac8e', 132, 'kc-kg-framework-saussurian-semiotics-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e200a822735145e77678eb91e6afd2925c2f42db9c550ad6c1fa1c4ecfb4ac8e', token_count=132, vector_point_id='kc-kg-framework-saussurian-semiotics-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-saussurian-semiotics-8', 'kg-framework-saussurian-semiotics', 8, '["Saussure (1916). Course in General Linguistics"]', 'bf4afad3a75727c4a32bf9698e572ec87d2c858f31891d7b98a7801f2a284b7e', 90, 'kc-kg-framework-saussurian-semiotics-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf4afad3a75727c4a32bf9698e572ec87d2c858f31891d7b98a7801f2a284b7e', token_count=90, vector_point_id='kc-kg-framework-saussurian-semiotics-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-0', 'kg-framework-semiotic-analysis', 1, 'چارچوب تحلیل نشانه‌شناختی (Semiotic Analysis Framework) نوع: FRAMEWORK چارچوب تحلیل نشانه‌شناختی که از «سنت ساختارگرایی و نشانه‌شناسی» استخراج شده و بر «تحلیل نشانه‌ها»، «ساختار» و «بازنمایی» تأکید می‌کند؛ چارچوبی که در مطالعات رسانه، زبان‌شناسی و تحلیل گفتمان کاربرد دارد.', '4745f83a9292f933ac6c33da2849f4f5c223afad7c8afb0a9ebc494fab33f829', 496, 'kc-kg-framework-semiotic-analysis-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4745f83a9292f933ac6c33da2849f4f5c223afad7c8afb0a9ebc494fab33f829', token_count=496, vector_point_id='kc-kg-framework-semiotic-analysis-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-2', 'kg-framework-semiotic-analysis', 2, 'چارچوب تحلیل نشانه‌شناختی (Semiotic Analysis Framework) که از «سنت ساختارگرایی و نشانه‌شناسی» استخراج شده، بر «تحلیل نشانه‌ها»، «ساختار» و «بازنمایی» تأکید می‌کند. این چارچوب، در مطالعات رسانه، زبان‌شناسی و تحلیل گفتمان کاربرد دارد. چارچوب تحلیل نشانه‌شناختی، «نشانه‌ها» (signs) را به‌عنوان «بازنمایی‌ها» (representations) تحلیل می‌کند و «ساختار» (structure) و «معنا» (meaning) را «موضوع تحلیل» قرار می‌دهد.', '23300a7b54060bce6ac1e3ac7ea5c9439f3062a29d8b1eb649959f384e41e001', 739, 'kc-kg-framework-semiotic-analysis-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='23300a7b54060bce6ac1e3ac7ea5c9439f3062a29d8b1eb649959f384e41e001', token_count=739, vector_point_id='kc-kg-framework-semiotic-analysis-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-3', 'kg-framework-semiotic-analysis', 3, 'مبانی فلسفی چارچوب تحلیل نشانه‌شناختی، بر «نشانه‌شناسی» (semiotics) فرناند دو ساسور (Ferdinand de Saussure) و رولان بارت (Roland Barthes) استوار است. این چارچوب، «نشانه‌ها» (signs) و «ساختار» (structure) را «موضوع تحلیل» قرار می‌دهد و «بازنمایی» (representation) و «معنا» (meaning) را «موضوع پژوهش» قرار می‌دهد.', '3f28b737b924cba8c084126c6698e67ffd03ddb16f1505bb63c0ae9b8a90983b', 565, 'kc-kg-framework-semiotic-analysis-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3f28b737b924cba8c084126c6698e67ffd03ddb16f1505bb63c0ae9b8a90983b', token_count=565, vector_point_id='kc-kg-framework-semiotic-analysis-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-4', 'kg-framework-semiotic-analysis', 4, '["رسانه، «بازنمایی» است نه «بازتاب»","«نشانه‌ها»، در «ساختار» خاصی «معنا» می‌سازند","«معنا»، در «ساختار» ساخته می‌شود","«بازنمایی»، «بازنمایی‌پذیر» است","تحلیل نشانه‌شناختی، «تحلیل ساختار» نشانه‌ها است"]', 'bdd06325a9ae53be19e226d882ce063c23c0bf1d1c668989a345dccd186035d3', 369, 'kc-kg-framework-semiotic-analysis-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bdd06325a9ae53be19e226d882ce063c23c0bf1d1c668989a345dccd186035d3', token_count=369, vector_point_id='kc-kg-framework-semiotic-analysis-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-5', 'kg-framework-semiotic-analysis', 5, '["فرناند دو ساسور","رولان بارت","چارلز سندرس پیرس"]', '14999fdc403faaf3ba9e48a96fd4b9420d65e1a7aa64fb6d9fb011d4a7f85614', 92, 'kc-kg-framework-semiotic-analysis-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='14999fdc403faaf3ba9e48a96fd4b9420d65e1a7aa64fb6d9fb011d4a7f85614', token_count=92, vector_point_id='kc-kg-framework-semiotic-analysis-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-6', 'kg-framework-semiotic-analysis', 6, '["زبان‌شناسی","مطالعات رسانه","تحلیل گفتمان","نشانه‌شناسی"]', '76b816248462d6ecc5f18aa0421674946d1430634ba37d2f4cbcaa0ff3ee8976', 107, 'kc-kg-framework-semiotic-analysis-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='76b816248462d6ecc5f18aa0421674946d1430634ba37d2f4cbcaa0ff3ee8976', token_count=107, vector_point_id='kc-kg-framework-semiotic-analysis-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-7', 'kg-framework-semiotic-analysis', 7, '["تحلیل ساختارهای زبانی در رسانه","تحلیل نشانه‌ها و «بازنمایی» در رسانه","تحلیل «معنا» و «بازنمایی» در رسانه"]', 'f0f66e57144f03dadd447a83f7813cbfd83ab5d7c28ed38589e135ab9313324a', 199, 'kc-kg-framework-semiotic-analysis-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f0f66e57144f03dadd447a83f7813cbfd83ab5d7c28ed38589e135ab9313324a', token_count=199, vector_point_id='kc-kg-framework-semiotic-analysis-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-8', 'kg-framework-semiotic-analysis', 8, '["پشتوانه‌ی فلسفی قوی","تحلیل عمیق «ساختار» و «نشانه»","بین‌رشته‌ای بودن"]', '0c517f13146ef4a77a583a2484bcb739222558657396819e7609418599cf5b99', 134, 'kc-kg-framework-semiotic-analysis-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0c517f13146ef4a77a583a2484bcb739222558657396819e7609418599cf5b99', token_count=134, vector_point_id='kc-kg-framework-semiotic-analysis-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-9', 'kg-framework-semiotic-analysis', 9, '["خودمحوری فرانسوی","سخت‌گیری در «ساختارگرایی»"]', '52b281c0028e6a70fca35ca1aac8f2ec970228796a97b983b8a1fff4ce38801c', 87, 'kc-kg-framework-semiotic-analysis-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='52b281c0028e6a70fca35ca1aac8f2ec970228796a97b983b8a1fff4ce38801c', token_count=87, vector_point_id='kc-kg-framework-semiotic-analysis-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-10', 'kg-framework-semiotic-analysis', 10, '["نقد از سوی پساساختارگرایان: چارچوب نشانه‌شناختی، «ساختار» را «ثابت» فرض می‌کند"]', 'a9fba1eb02aa7d3c135228fd72af7012749d50c6198e45c5715d1f657d6bb0a4', 149, 'kc-kg-framework-semiotic-analysis-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a9fba1eb02aa7d3c135228fd72af7012749d50c6198e45c5715d1f657d6bb0a4', token_count=149, vector_point_id='kc-kg-framework-semiotic-analysis-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-semiotic-analysis-11', 'kg-framework-semiotic-analysis', 11, '["Barthes (1964). Elements of Semiology"]', 'e4b854ca3500f68db4f1b9d9f5da67d08f8105c3d4d9be8aa10163ac3521f918', 74, 'kc-kg-framework-semiotic-analysis-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e4b854ca3500f68db4f1b9d9f5da67d08f8105c3d4d9be8aa10163ac3521f918', token_count=74, vector_point_id='kc-kg-framework-semiotic-analysis-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-social-semiotics-0', 'kg-framework-social-semiotics', 1, 'نشانه‌شناسی اجتماعی (Social Semiotics) نوع: FRAMEWORK چارچوب نظری نشانه‌شناسی اجتماعی که بر تحلیل «بازنمایی اجتماعی» معنا در بافت‌های فرهنگی و رسانه‌ای تمرکز دارد و نشانه را در «عمل» اجتماعی تحلیل می‌کند.', '7f53b25b7af9daf4c00bea140703fcc8712e10a91f61790879c00809dccc5b39', 370, 'kc-kg-framework-social-semiotics-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7f53b25b7af9daf4c00bea140703fcc8712e10a91f61790879c00809dccc5b39', token_count=370, vector_point_id='kc-kg-framework-social-semiotics-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-social-semiotics-2', 'kg-framework-social-semiotics', 2, 'نشانه‌شناسی اجتماعی (Social Semiotics) از هالیدای (Halliday) و کیر (Kress) می‌آید و نشانه را در «عمل» اجتماعی و بافت فرهنگی تحلیل می‌کند. این چارچوب، رسانه را «امکا» (semiotic resource) می‌داند و بر «بازنمایی اجتماعی» معنا تمرکز دارد.', '0b72f41a0bcd73b29f72b5717920583215aac59d5db111071ab4e19a0a0df60a', 425, 'kc-kg-framework-social-semiotics-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b72f41a0bcd73b29f72b5717920583215aac59d5db111071ab4e19a0a0df60a', token_count=425, vector_point_id='kc-kg-framework-social-semiotics-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
