INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-structuralism-0', 'kg-framework-structuralism', 1, 'ساختارگرایی (Structuralism) نوع: FRAMEWORK چارچوب نظری سنت ساختارگرایی که بر تحلیل «ساختار» پدیده‌ها (زبان، روایت، فرهنگ) تمرکز دارد و معنا را محصول «اختلاف» ساختاری می‌داند.', '1bd5c0d7b8adfa1fb187f15a4d09b2e7467832aa4a2db47131faf796d6f2d8ff', 316, 'kc-kg-framework-structuralism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1bd5c0d7b8adfa1fb187f15a4d09b2e7467832aa4a2db47131faf796d6f2d8ff', token_count=316, vector_point_id='kc-kg-framework-structuralism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-structuralism-2', 'kg-framework-structuralism', 2, 'ساختارگرایی (Structuralism) رویکردی است که بر «ساختار» پدیده‌ها تمرکز دارد: معنا نه در خودِ نشانه، بلکه در «اختلاف» و رابطه‌ی آن با سایر نشانه‌ها ساخته می‌شود. این چارچوب، پایه‌ی تحلیل نشانه‌شناختی و روایت‌شناختی است.', '1066b1dfdb58520300295c257c6b9da37edad98ad821fcffd6e9cf06ddea77ba', 394, 'kc-kg-framework-structuralism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1066b1dfdb58520300295c257c6b9da37edad98ad821fcffd6e9cf06ddea77ba', token_count=394, vector_point_id='kc-kg-framework-structuralism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
