INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-systemic-approach-0', 'kg-framework-systemic-approach', 1, 'رویکرد سیستمی به ارتباطات (Systems Approach to Communication) نوع: FRAMEWORK چارچوب نظری مکتب پالو آلتو که ارتباطات را در «سیستم» تحلیل می‌کند: کل بزرگ‌تر از اجزاست و معنای هر بخش در رابطه با کل سیستم تعیین می‌شود.', '4d53a7f1286595c5c70172fcc06afe690d78f926c641632498549d99a39dddf5', 389, 'kc-kg-framework-systemic-approach-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4d53a7f1286595c5c70172fcc06afe690d78f926c641632498549d99a39dddf5', token_count=389, vector_point_id='kc-kg-framework-systemic-approach-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
