INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-two-flow-0', 'kg-framework-two-flow', 1, 'چارچوب جریان دومرحله‌ای (Two-Step Flow Framework) نوع: FRAMEWORK چارچوبی که فرآیند انتقال پیام رسانه‌ای از رسانه به رهبران افکار و سپس به مخاطبان را نشان می‌دهد.', 'fa4aa8c2d9504074e84ea38468f328f8c366b684e1168f8d213fe0ad7b385498', 292, 'kc-kg-framework-two-flow-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fa4aa8c2d9504074e84ea38468f328f8c366b684e1168f8d213fe0ad7b385498', token_count=292, vector_point_id='kc-kg-framework-two-flow-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-two-flow-2', 'kg-framework-two-flow', 2, 'این چارچوب (که از نظریه جریان دومرحله‌ای Lazarsfeld استخراج شده) فرآیند انتقال پیام را در دو مرحله نشان می‌دهد: مرحله‌ی اول: رسانه به رهبران افکار؛ مرحله‌ی دوم: رهبران افکار به مخاطبان. این چارچوب در مطالعات اجتماعی و رسانه‌ای استفاده می‌شود.', 'cb725d3ecf69a0aad1262dfff28e8e99a528355eca08d47302455ccf80a71f00', 439, 'kc-kg-framework-two-flow-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cb725d3ecf69a0aad1262dfff28e8e99a528355eca08d47302455ccf80a71f00', token_count=439, vector_point_id='kc-kg-framework-two-flow-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
