INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-framework-uses-gratifications-2', 'kg-framework-uses-gratifications', 2, 'این چارچوب (که از نظریه استفاده و رضامندی Katz استخراج شده) فرآیند انتخاب رسانه را در چهار سطح نشان می‌دهد: ۱) نیازهای فردی؛ ۲) انتخاب رسانه؛ ۳) استفاده از رسانه؛ ۴) رضامندی‌ها. این چارچوب در مطالعات مخاطب و رسانه استفاده می‌شود.', '329f712c7edd62786ae73d8eba4b4de61c9cc572bed761921191883e9b6ff7da', 416, 'kc-kg-framework-uses-gratifications-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='329f712c7edd62786ae73d8eba4b4de61c9cc572bed761921191883e9b6ff7da', token_count=416, vector_point_id='kc-kg-framework-uses-gratifications-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
