INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-data-collection-0', 'kg-meth-data-collection', 1, 'روش‌های گردآوری داده (Data Collection Methods) نوع: METHODOLOGY مجموعه‌ای از فنون و روش‌هایی که داده‌ی پژوهش را در مرحله‌ی گردآوری تولید یا دریافت می‌کنند.', '492742fd9a56743a45075593bc97a72fc6d864330821f2daeac35831c74c4887', 281, 'kc-kg-meth-data-collection-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='492742fd9a56743a45075593bc97a72fc6d864330821f2daeac35831c74c4887', token_count=281, vector_point_id='kc-kg-meth-data-collection-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-data-collection-2', 'kg-meth-data-collection', 2, 'روش‌های گردآوری داده به چگونگی تولید یا دریافت داده در پژوهش اختصاص دارند و از «طرح پژوهش» (که چه چیزی و چرا سنجیده شود) متمایز‌اند. این خانواده در پنج دسته سازمان می‌یابد: پرسش‌محور (پرسشنامه و مصاحبه‌ها)، مشاهده‌محور، اسنادی و محتوایی، داده‌برداری دیجیتال، و سنجش و اندازه‌گیری.', '0e36c07ef3ec81d64ed7be5cd266e0cce9dd3d354cda2fe6dce27a19abc3c53a', 509, 'kc-kg-meth-data-collection-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0e36c07ef3ec81d64ed7be5cd266e0cce9dd3d354cda2fe6dce27a19abc3c53a', token_count=509, vector_point_id='kc-kg-meth-data-collection-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-data-collection-3', 'kg-meth-data-collection', 3, '["روش گردآوری از طرح پژوهش متمایز است: چگونگی دریافت داده در برابر چه چیزی و چرا سنجیده شود","پنج دسته‌ی اصلی: پرسش‌محور، مشاهده‌محور، اسنادی/محتوایی، داده‌برداری دیجیتال، سنجش/اندازه‌گیری"]', '4dcc465383c1d194738579aa789fd38c77f9e829dc029f7a2630900cb0bf3713', 345, 'kc-kg-meth-data-collection-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4dcc465383c1d194738579aa789fd38c77f9e829dc029f7a2630900cb0bf3713', token_count=345, vector_point_id='kc-kg-meth-data-collection-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-data-collection-4', 'kg-meth-data-collection', 4, '["Creswell & Creswell (2018), Research Design, 5th ed., SAGE","Bryman (2016), Social Research Methods, 5th ed., OUP","Babbie (2013), The Practice of Social Research, 14th ed., Wadsworth"]', '9a88b6a3612a7e677defc77d97eeb2c6ea61702b15aa60e9ada5917bf4d4cac2', 340, 'kc-kg-meth-data-collection-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9a88b6a3612a7e677defc77d97eeb2c6ea61702b15aa60e9ada5917bf4d4cac2', token_count=340, vector_point_id='kc-kg-meth-data-collection-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-0', 'kg-meth-sampling', 1, 'روش‌های نمونه‌گیری (Sampling Methods) نوع: METHODOLOGY خانواده‌ی مستقلی از روش‌ها برای انتخاب نمونه از جامعه‌ی آماری؛ در هم پژوهش کمّی و کیفی کاربرد دارد.', 'ed6b984238668d09fed0d684ba355d35bdfe8057e6517e432dfb5f64b200fe03', 280, 'kc-kg-meth-sampling-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ed6b984238668d09fed0d684ba355d35bdfe8057e6517e432dfb5f64b200fe03', token_count=280, vector_point_id='kc-kg-meth-sampling-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-2', 'kg-meth-sampling', 2, 'نمونه‌گیری به‌دلیل استفاده‌ی مشترک در پژوهش کمّی (برای تعمیم آماری) و کیفی (برای عمق و اشباع) خانواده‌ای مستقل از روش‌شناسی است. در دو شاخه‌ی احتمالی و غیراحتمالی سازمان می‌یابد و با مفاهیمی چون جامعه‌ی آماری، چارچوب نمونه‌گیری، حجم نمونه، توان آماری و اشباع نظری پیوند دارد.', 'e33f4cc93700e77b8eadb5191504c075098313e3af58c32529fdcb9fad23c439', 499, 'kc-kg-meth-sampling-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e33f4cc93700e77b8eadb5191504c075098313e3af58c32529fdcb9fad23c439', token_count=499, vector_point_id='kc-kg-meth-sampling-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-3', 'kg-meth-sampling', 3, '["نمونه‌گیری خانواده‌ای مستقل است چون هم در پژوهش کمّی و هم کیفی کاربرد دارد","در دو شاخه‌ی احتمالی (تعمیم آماری) و غیراحتمالی (عمق کیفی) سازمان می‌یابد"]', '779ec9abecc02552f60f4450a7ce599a5a27c23788b1bb0d3922e0745a41379f', 280, 'kc-kg-meth-sampling-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='779ec9abecc02552f60f4450a7ce599a5a27c23788b1bb0d3922e0745a41379f', token_count=280, vector_point_id='kc-kg-meth-sampling-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-4', 'kg-meth-sampling', 4, '["Bryman (2016), Social Research Methods","Sharma (2016), Research Methodology, 2nd ed., Pearson"]', '79129546e531078a0c551ff10aeed6b85d311a47546d95e7948610ff805532c1', 178, 'kc-kg-meth-sampling-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='79129546e531078a0c551ff10aeed6b85d311a47546d95e7948610ff805532c1', token_count=178, vector_point_id='kc-kg-meth-sampling-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-concepts-0', 'kg-meth-sampling-concepts', 1, 'مفاهیم پایه‌ی نمونه‌گیری (Core Sampling Concepts) نوع: METHODOLOGY دسته‌ای از مفاهیم بنیادین که هر فرایند نمونه‌گیری بر آن‌ها استوار است.', '13df2512ff09fc2db938d9e81ab61b9bfd100fa4ae17a75b08a830ceb581c490', 249, 'kc-kg-meth-sampling-concepts-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='13df2512ff09fc2db938d9e81ab61b9bfd100fa4ae17a75b08a830ceb581c490', token_count=249, vector_point_id='kc-kg-meth-sampling-concepts-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-concepts-2', 'kg-meth-sampling-concepts', 2, 'این دسته شامل جامعه‌ی آماری، چارچوب نمونه‌گیری، واحد نمونه، واحد تحلیل، حجم نمونه، اشباع نظری و داده، توان آماری، خطای نمونه‌گیری و سوگیری انتخاب نمونه است؛ مفاهیمی که طراحی هر نمونه‌گیری را شکل می‌دهند.', 'b93d3b2d21139b649c27c2acaffb66028b9c4dcb45c3970ba241cdaf17aac38a', 369, 'kc-kg-meth-sampling-concepts-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b93d3b2d21139b649c27c2acaffb66028b9c4dcb45c3970ba241cdaf17aac38a', token_count=369, vector_point_id='kc-kg-meth-sampling-concepts-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-concepts-3', 'kg-meth-sampling-concepts', 3, '["شامل ۱۰ مفهوم بنیادین طراحی نمونه‌گیری است","از کمّی (توان آماری، خطا) تا کیفی (اشباع نظری) را پوشش می‌دهد"]', '11834b21be2d4f2d05e34b888a09cc1ab6335911fbc6c8e88d08c75f7225091d', 199, 'kc-kg-meth-sampling-concepts-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='11834b21be2d4f2d05e34b888a09cc1ab6335911fbc6c8e88d08c75f7225091d', token_count=199, vector_point_id='kc-kg-meth-sampling-concepts-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-nonprobabilistic-0', 'kg-meth-sampling-nonprobabilistic', 1, 'نمونه‌گیری غیراحتمالی (Non-Probabilistic Sampling) نوع: METHODOLOGY نمونه‌گیری بر پایه‌ی قضاوت پژوهشگر؛ بنیان عمق کیفی و دسترسی به جوامع پنهان.', '6f118bae47d72fbf57928a044aa10a9820edf6f12a0135f0389c3c6c68cc0d29', 260, 'kc-kg-meth-sampling-nonprobabilistic-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6f118bae47d72fbf57928a044aa10a9820edf6f12a0135f0389c3c6c68cc0d29', token_count=260, vector_point_id='kc-kg-meth-sampling-nonprobabilistic-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-nonprobabilistic-2', 'kg-meth-sampling-nonprobabilistic', 2, 'در نمونه‌گیری غیراحتمالی انتخاب بر قضاوت پژوهشگر است نه شانس؛ در پژوهش‌های کیفی، مطالعات موردی و جوامعی که چارچوب نمونه در دسترس نیست (مانند جوامع آسیب‌پذیر) کاربرد دارد و هدف آن عمق و معنایی بودن داده است نه تعمیم آماری.', '72d1f963b9d2ca78cd6fe265f67c516859a730e511d0f06ae67e48d275d3047b', 401, 'kc-kg-meth-sampling-nonprobabilistic-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='72d1f963b9d2ca78cd6fe265f67c516859a730e511d0f06ae67e48d275d3047b', token_count=401, vector_point_id='kc-kg-meth-sampling-nonprobabilistic-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-nonprobabilistic-3', 'kg-meth-sampling-nonprobabilistic', 3, '["انتخاب بر قضاوت پژوهشگر است نه شانس","هدف عمق و معنایی بودن داده است نه تعمیم آماری","شامل ۱۰ روش از در دسترس تا متوالی"]', '671be4c9fa8918096835ed5ac680548305b3c3474e557505cec6c0503fbffd05', 223, 'kc-kg-meth-sampling-nonprobabilistic-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='671be4c9fa8918096835ed5ac680548305b3c3474e557505cec6c0503fbffd05', token_count=223, vector_point_id='kc-kg-meth-sampling-nonprobabilistic-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-probabilistic-0', 'kg-meth-sampling-probabilistic', 1, 'نمونه‌گیری احتمالی (Probabilistic Sampling) نوع: METHODOLOGY نمونه‌گیری بر پایه‌ی انتخاب تصادفی و شانس برابر؛ بنیان تعمیم آماری.', 'cb5b5adf921874ccb8f01e50d6e4ee4481170b2a2f42194a94e7b7c1975bbb93', 232, 'kc-kg-meth-sampling-probabilistic-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cb5b5adf921874ccb8f01e50d6e4ee4481170b2a2f42194a94e7b7c1975bbb93', token_count=232, vector_point_id='kc-kg-meth-sampling-probabilistic-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-probabilistic-2', 'kg-meth-sampling-probabilistic', 2, 'در نمونه‌گیری احتمالی هر واحد جامعه با احتمال معلوم و مثبت در نمونه قرار می‌گیرد؛ این ویژگی امکان محاسبه‌ی خطای نمونه و تعمیم آماری به جامعه را فراهم می‌کند و بنیان پژوهش‌های کمّی پیمایشی است.', 'ae328c4e81e0bdf2fc203b0611494d55edaa5352210411515a950c046e0ccd53', 349, 'kc-kg-meth-sampling-probabilistic-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ae328c4e81e0bdf2fc203b0611494d55edaa5352210411515a950c046e0ccd53', token_count=349, vector_point_id='kc-kg-meth-sampling-probabilistic-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-sampling-probabilistic-3', 'kg-meth-sampling-probabilistic', 3, '["هر واحد جامعه با احتمال معلوم و مثبت انتخاب می‌شود","خطای نمونه قابل محاسبه و تعمیم آماری امکان‌پذیر است","شامل ۷ روش از تصادفی ساده تا طبقه‌ای چندمرحله‌ای"]', 'd73b875f83ce30e92953c3dc63c92d0d8bb8d8410559a612cb6262f682a9c479', 289, 'kc-kg-meth-sampling-probabilistic-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d73b875f83ce30e92953c3dc63c92d0d8bb8d8410559a612cb6262f682a9c479', token_count=289, vector_point_id='kc-kg-meth-sampling-probabilistic-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-digital-0', 'kg-meth-techniques-digital', 1, 'روش‌های داده‌برداری دیجیتال (Digital Data Capture Methods) نوع: METHODOLOGY دسته‌ای از فنون گردآوری داده از منابع دیجیتال: وب، API، شبکه‌های اجتماعی، لاگ و حسگر.', 'fcd69597f17b899d936fa65257f7c2d1b223e9384f4774e0ffd9ca84abfe2234', 292, 'kc-kg-meth-techniques-digital-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fcd69597f17b899d936fa65257f7c2d1b223e9384f4774e0ffd9ca84abfe2234', token_count=292, vector_point_id='kc-kg-meth-techniques-digital-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-digital-2', 'kg-meth-techniques-digital', 2, 'با گسترش رسانه‌های دیجیتال، داده‌های ردپا (trace) به منبع اصلی پژوهش تبدیل شده‌اند؛ از استخراج از وب و API تا ردیابی رفتار کاربران و داده‌برداری از حسگرها.', '40c56e1d02d8301623a0c48215dc859e976c8fdcb299dcb06ef1a9da7eaa8466', 281, 'kc-kg-meth-techniques-digital-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='40c56e1d02d8301623a0c48215dc859e976c8fdcb299dcb06ef1a9da7eaa8466', token_count=281, vector_point_id='kc-kg-meth-techniques-digital-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-digital-3', 'kg-meth-techniques-digital', 3, '["داده‌های ردپا (trace) منبع اصلی پژوهش‌های دیجیتال‌محورند","شامل ۷ فن از استخراج وب و API تا تحلیل ردپاهای دیجیتال"]', '3cb2736522e52a306b83274df7d09c6817fdccc0b8ac39bfb6c7031a289e08a1', 212, 'kc-kg-meth-techniques-digital-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3cb2736522e52a306b83274df7d09c6817fdccc0b8ac39bfb6c7031a289e08a1', token_count=212, vector_point_id='kc-kg-meth-techniques-digital-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-documentary-0', 'kg-meth-techniques-documentary', 1, 'روش‌های اسنادی و محتوایی (Documentary & Content-Based Methods) نوع: METHODOLOGY دسته‌ای از فنون گردآوری داده بر پایه‌ی بررسی و تحلیل اسناد، متون و رسانه‌ها.', 'dba851e0651e1caf7855cf210c9406c677206eb6844cba82dad178475a6ec4da', 283, 'kc-kg-meth-techniques-documentary-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dba851e0651e1caf7855cf210c9406c677206eb6844cba82dad178475a6ec4da', token_count=283, vector_point_id='kc-kg-meth-techniques-documentary-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-documentary-2', 'kg-meth-techniques-documentary', 2, 'در این دسته داده از منابع موجود (اسناد رسمی، آرشیوها، اخبار، ویدئو، تصاویر و تولیدات کاربران) استخراج می‌شود؛ از بررسی ساده‌ی اسناد تا تحلیل نظام‌مند محتوای رسانه‌ای.', '43bff2bec9f10eb761a97de5ba6dc4405ae23a06176034777817e7f1dc1ed083', 301, 'kc-kg-meth-techniques-documentary-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='43bff2bec9f10eb761a97de5ba6dc4405ae23a06176034777817e7f1dc1ed083', token_count=301, vector_point_id='kc-kg-meth-techniques-documentary-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-documentary-3', 'kg-meth-techniques-documentary', 3, '["داده از منابع موجود و از پیش تولیدشده استخراج می‌شود","شامل ۸ فن از بررسی اسناد تا تحلیل تولیدات کاربران"]', '8aa3aa10fe2fac68cc2ac3e88dac7bf014dd6412668ac0ccb482314ffedf1f18', 196, 'kc-kg-meth-techniques-documentary-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8aa3aa10fe2fac68cc2ac3e88dac7bf014dd6412668ac0ccb482314ffedf1f18', token_count=196, vector_point_id='kc-kg-meth-techniques-documentary-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-measurement-0', 'kg-meth-techniques-measurement', 1, 'روش‌های سنجش و اندازه‌گیری (Measurement-Based Methods) نوع: METHODOLOGY دسته‌ای از فنون گردآوری داده بر پایه‌ی سنجش سازه‌های روان‌شناختی و فیزیولوژیک.', '58ae95d0af95075b4d44fd3bf101f10acd92c0dee736be037617fa96e05dc725', 272, 'kc-kg-meth-techniques-measurement-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='58ae95d0af95075b4d44fd3bf101f10acd92c0dee736be037617fa96e05dc725', token_count=272, vector_point_id='kc-kg-meth-techniques-measurement-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-measurement-2', 'kg-meth-techniques-measurement', 2, 'در این دسته داده با آزمون و مقیاس‌های اعتبارسنجی‌شده برای سنجش سازه‌هایی مانند نگرش، رضایت، اعتماد، یادآوری، توجه و پاسخ‌های فیزیولوژیک تولید می‌شود.', '49772643e24ebcc521d670a8b10ebe2b147ebbc89a8cc8fe41fde670573360f5', 270, 'kc-kg-meth-techniques-measurement-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='49772643e24ebcc521d670a8b10ebe2b147ebbc89a8cc8fe41fde670573360f5', token_count=270, vector_point_id='kc-kg-meth-techniques-measurement-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-measurement-3', 'kg-meth-techniques-measurement', 3, '["داده با ابزارهای سنجش‌شده و اعتبارسنجی‌شده تولید می‌شود","شامل ۷ فن از آزمون‌های روان‌سنجی تا اندازه‌گیری فیزیولوژیک"]', 'af43fc03b46f2825ae1f4e569c312d9c3d6674637750a357da145f64b1dede1d', 218, 'kc-kg-meth-techniques-measurement-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='af43fc03b46f2825ae1f4e569c312d9c3d6674637750a357da145f64b1dede1d', token_count=218, vector_point_id='kc-kg-meth-techniques-measurement-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-observation-0', 'kg-meth-techniques-observation', 1, 'روش‌های مشاهده‌محور (Observation-Based Methods) نوع: METHODOLOGY دسته‌ای از فنون گردآوری داده بر پایه‌ی دیدن، ثبت و تفسیر رفتار در بافت طبیعی یا کنترل‌شده.', '6ed087599920e39a466d4b88056dbb0f2c73114bb8d3d9744d41a7ef7f1623b4', 281, 'kc-kg-meth-techniques-observation-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6ed087599920e39a466d4b88056dbb0f2c73114bb8d3d9744d41a7ef7f1623b4', token_count=281, vector_point_id='kc-kg-meth-techniques-observation-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-observation-2', 'kg-meth-techniques-observation', 2, 'مشاهده، داده‌ی اول‌دستی درباره‌ی رفتار و تعاملات را مستقیماً از بافت پژوهش گردآوری می‌کند؛ در طیفی از مشاهده‌ی غیرمشارکتی و ساختاریافته تا مشارکتی، طبیعی، میدانی و دیجیتال.', '68b065a42dbbd1b615869e4efad7556ca3f9bf155dd9ca63725396f4f86d107d', 312, 'kc-kg-meth-techniques-observation-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='68b065a42dbbd1b615869e4efad7556ca3f9bf155dd9ca63725396f4f86d107d', token_count=312, vector_point_id='kc-kg-meth-techniques-observation-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-observation-3', 'kg-meth-techniques-observation', 3, '["داده از ثبت مستقیم رفتار در بافت تولید می‌شود نه خوداظهاری","شامل ۸ فن در طیف مشارکتی/غیرمشارکتی، ساختاریافته/طبیعی و میدانی/دیجیتال"]', 'a4a1aa2b4327f758dbc89b604d9fa57ef1cfddfbbb5e70c3e3f9ea1eee2abe00', 247, 'kc-kg-meth-techniques-observation-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a4a1aa2b4327f758dbc89b604d9fa57ef1cfddfbbb5e70c3e3f9ea1eee2abe00', token_count=247, vector_point_id='kc-kg-meth-techniques-observation-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-survey-0', 'kg-meth-techniques-survey', 1, 'روش‌های پرسش‌محور (Survey-Based Methods) نوع: METHODOLOGY دسته‌ای از فنون گردآوری داده بر پایه‌ی پرسش و خوداظهاری؛ از پرسشنامه تا دلفی.', '28b48acea3ee1bbd4431e01bc17db65138f4a604125521e648f6cddf558f0b93', 245, 'kc-kg-meth-techniques-survey-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='28b48acea3ee1bbd4431e01bc17db65138f4a604125521e648f6cddf558f0b93', token_count=245, vector_point_id='kc-kg-meth-techniques-survey-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-survey-2', 'kg-meth-techniques-survey', 2, 'در این دسته داده از طریق پرسش از پاسخدهندگان (مکاتبه‌ای، حضوری، تلفنی یا آنلاین) و خوداظهاری آن‌ها گردآوری می‌شود؛ از پرسشنامه‌ی ساختاریافته تا مصاحبه‌های نیمه‌ساختاریافته، گروه کانونی، دلفی و نظرسنجی آنلاین.', 'd301168fbb474457a6c3105c63299a0b2f46858e28125f415e6f03ff32cc7475', 378, 'kc-kg-meth-techniques-survey-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d301168fbb474457a6c3105c63299a0b2f46858e28125f415e6f03ff32cc7475', token_count=378, vector_point_id='kc-kg-meth-techniques-survey-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-meth-techniques-survey-3', 'kg-meth-techniques-survey', 3, '["داده از طریق پرسش و خوداظهاری پاسخدهندگان تولید می‌شود","شامل ۸ فن از پرسشنامه تا نظرسنجی آنلاین"]', '36424f70e59f0b3e9f05f06e2ba02c36fd4724cb243df6a466632d3dc660e0fd', 181, 'kc-kg-meth-techniques-survey-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='36424f70e59f0b3e9f05f06e2ba02c36fd4724cb243df6a466632d3dc660e0fd', token_count=181, vector_point_id='kc-kg-meth-techniques-survey-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-convergence-model-0', 'kg-model-convergence-model', 1, 'مدل همگرایی رسانه‌ای (Media Convergence Model) نوع: MODEL مدلی که فرآیند همگرایی رسانه‌ای را در پنج سطح (فناوری، اقتصادی، سازمانی، فرهنگی، مخاطب) نشان می‌دهد.', '04f346f2c092961f3d24c5b068b6be94558d3be702dd56334ca16f75cf3fdb08', 287, 'kc-kg-model-convergence-model-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='04f346f2c092961f3d24c5b068b6be94558d3be702dd56334ca16f75cf3fdb08', token_count=287, vector_point_id='kc-kg-model-convergence-model-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-convergence-model-2', 'kg-model-convergence-model', 2, 'Jenkins (2006) مدل همگرایی رسانه‌ای را در پنج سطح تعریف کرد: ۱) همگرایی فناوری؛ ۲) همگرایی اقتصادی (تلفیق شرکت‌های رسانه‌ای)؛ ۳) همگرایی سازمانی (تغییر ساختار سازمانی)؛ ۴) همگرایی فرهنگی (ترکیب سبک‌های فرهنگی)؛ ۵) همگرایی مخاطب (مشارکت فعال مخاطب).', 'd06734cfb6e354eabe1a827562bf8c229f37484d578266bdadee17e2ff604d49', 450, 'kc-kg-model-convergence-model-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d06734cfb6e354eabe1a827562bf8c229f37484d578266bdadee17e2ff604d49', token_count=450, vector_point_id='kc-kg-model-convergence-model-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-convergence-model-3', 'kg-model-convergence-model', 3, '["Henry Jenkins"]', '6fb847fdf7c417a70945b277fcf73a25a874f6e6363bd023498f15164deff127', 30, 'kc-kg-model-convergence-model-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6fb847fdf7c417a70945b277fcf73a25a874f6e6363bd023498f15164deff127', token_count=30, vector_point_id='kc-kg-model-convergence-model-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-convergence-model-4', 'kg-model-convergence-model', 4, '2006', '6f6a4e56098cfd9af29e3ae549503b370211a4e94421457fe4cfd39a38a1fa08', 7, 'kc-kg-model-convergence-model-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6f6a4e56098cfd9af29e3ae549503b370211a4e94421457fe4cfd39a38a1fa08', token_count=7, vector_point_id='kc-kg-model-convergence-model-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
