INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-convergence-model-6', 'kg-model-convergence-model', 6, '["Jenkins, 2006 - Convergence Culture"]', 'd0fc8eb089f153a18b172366eed6b6c020661b448eb37b7c51a40a78a8834a3a', 70, 'kc-kg-model-convergence-model-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d0fc8eb089f153a18b172366eed6b6c020661b448eb37b7c51a40a78a8834a3a', token_count=70, vector_point_id='kc-kg-model-convergence-model-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-nudge-model-0', 'kg-model-nudge-model', 1, 'مدل نورد (معماری انتخاب) (Nudge Model (Choice Architecture)) نوع: MODEL مدلی که فرآیند «هسته‌کردن» (nudge) رفتار کاربران را با طراحی عناصر بصری و ترتیب نشان می‌دهد.', 'de80044b763320ebb8a887be80c67dc10a6972b9ca1dce6bc230e1b85780072f', 298, 'kc-kg-model-nudge-model-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='de80044b763320ebb8a887be80c67dc10a6972b9ca1dce6bc230e1b85780072f', token_count=298, vector_point_id='kc-kg-model-nudge-model-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-nudge-model-2', 'kg-model-nudge-model', 2, 'Thaler و Sunstein (2008) مدل نورد را در «معماری انتخاب» تعریف کردند؛ طراحان رابط با طراحی عناصر بصری (مثل پیش‌تنظیم‌ها، ترتیب گزینه‌ها)، انتخاب‌های کاربر را به‌شکل غیرمستقیم هدایت می‌کنند.', '26fcb55274df776e4f87ae6976475a9709786141b78eaf8bd3192e2704e46238', 341, 'kc-kg-model-nudge-model-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='26fcb55274df776e4f87ae6976475a9709786141b78eaf8bd3192e2704e46238', token_count=341, vector_point_id='kc-kg-model-nudge-model-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-nudge-model-3', 'kg-model-nudge-model', 3, '["Thaler","Richard Sunstein"]', '24f72451abc657625cad67874909a16f2ad694e0be8d869c03cb2f6204e2bd54', 52, 'kc-kg-model-nudge-model-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='24f72451abc657625cad67874909a16f2ad694e0be8d869c03cb2f6204e2bd54', token_count=52, vector_point_id='kc-kg-model-nudge-model-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
