INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-nudge-model-6', 'kg-model-nudge-model', 6, '["Thaler & Sunstein, 2008 - Nudge"]', '58b6600d2153d71ec3100922c708bd0158dbf8f92790b3e910fe55a0d2ce8b59', 63, 'kc-kg-model-nudge-model-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='58b6600d2153d71ec3100922c708bd0158dbf8f92790b3e910fe55a0d2ce8b59', token_count=63, vector_point_id='kc-kg-model-nudge-model-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-onion-model-0', 'kg-model-onion-model', 1, 'مدل پیاز (نفوذ اجتماعی) (Onion Model (Social Penetration)) نوع: MODEL مدلی که فرآیند نفوذ در روابط بین‌فردی را به‌شکل لایه‌لایه (از بیرون به داخل) نشان می‌دهد.', 'cd30cb4f42e61bc762045d95febd845b14c98f76ff56bf769b1c9e1db1fc81d1', 289, 'kc-kg-model-onion-model-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cd30cb4f42e61bc762045d95febd845b14c98f76ff56bf769b1c9e1db1fc81d1', token_count=289, vector_point_id='kc-kg-model-onion-model-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-onion-model-2', 'kg-model-onion-model', 2, 'Altman و Taylor (1973) این مدل را در نظریه نفوذ اجتماعی پیشنهاد کردند؛ رابطه از لایه‌های بیرونی (موضوعات عمومی) به لایه‌های درونی (موضوعات شخصی و عمیق) نفوذ می‌کند.', '8f3532536b78602622eee8f99ab8494f3454b7848986009df2ef6f73aec09d03', 298, 'kc-kg-model-onion-model-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8f3532536b78602622eee8f99ab8494f3454b7848986009df2ef6f73aec09d03', token_count=298, vector_point_id='kc-kg-model-onion-model-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-onion-model-3', 'kg-model-onion-model', 3, '["Irwin Altman","Dalmas Taylor"]', '985c9d4e4f0d7bfce7a94661d496f3ab9a9e7308776d80f79a4a5f5e0e790ea0', 58, 'kc-kg-model-onion-model-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='985c9d4e4f0d7bfce7a94661d496f3ab9a9e7308776d80f79a4a5f5e0e790ea0', token_count=58, vector_point_id='kc-kg-model-onion-model-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
