INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-surveillance-capitalism-6', 'kg-model-surveillance-capitalism', 6, '["Zuboff, 2019 - The Age of Surveillance Capitalism"]', '3edaeb3715647edd00f937c36fd9ca9058b8075f83c8981fc4b2b390e5549d27', 96, 'kc-kg-model-surveillance-capitalism-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3edaeb3715647edd00f937c36fd9ca9058b8075f83c8981fc4b2b390e5549d27', token_count=96, vector_point_id='kc-kg-model-surveillance-capitalism-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-three-positions-0', 'kg-model-three-positions', 1, 'مدل سه موقعیت تفسیری (Three Interpretive Positions Model) نوع: MODEL مدلی که سه موقعیت تفسیری مخاطب (گالب، متوازن، مقاومتی) را نشان می‌دهد.', '09aab241d3d3e43f34a243d9526ad6c7b5c503b04cfb0bfc830a551d8e35e4d1', 252, 'kc-kg-model-three-positions-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='09aab241d3d3e43f34a243d9526ad6c7b5c503b04cfb0bfc830a551d8e35e4d1', token_count=252, vector_point_id='kc-kg-model-three-positions-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-three-positions-2', 'kg-model-three-positions', 2, 'Stuart Hall (1973) در مدل رمزگذاری/رمزگشایی، سه موقعیت تفسیری مخاطب را تعریف کرد: ۱) موقعیت گالب (dominant): مخاطب پیام را با معنای تولیدکننده می‌پذیرد؛ ۲) موقعیت متوازن (negotiated): مخاطب معنای تولیدکننده را به‌شکل نسبی می‌پذیرد اما برخی معانی را تغییر می‌دهد؛ ۳) موقعیت مقاومتی (oppositional): مخاطب پیام را در تفسیر مقاومتی می‌پذیرد.', 'aa5e7e8c78a2185df80f44942ed60f9ef84ac7a6dc5c9a549dc89f0fa951a0e9', 612, 'kc-kg-model-three-positions-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='aa5e7e8c78a2185df80f44942ed60f9ef84ac7a6dc5c9a549dc89f0fa951a0e9', token_count=612, vector_point_id='kc-kg-model-three-positions-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-three-positions-3', 'kg-model-three-positions', 3, '["Stuart Hall"]', '7ec3bfd85c9ffe2b18bfb0035cefa452900e337adeb4b636a7d353a0687b77f5', 27, 'kc-kg-model-three-positions-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7ec3bfd85c9ffe2b18bfb0035cefa452900e337adeb4b636a7d353a0687b77f5', token_count=27, vector_point_id='kc-kg-model-three-positions-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
