INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-model-three-positions-6', 'kg-model-three-positions', 6, '["Hall, 1973 - Encoding/Decoding"]', 'e2da97106606102523f0220efe5dfce76dbc3e75b6fe8017db60ed131c32ced6', 61, 'kc-kg-model-three-positions-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e2da97106606102523f0220efe5dfce76dbc3e75b6fe8017db60ed131c32ced6', token_count=61, vector_point_id='kc-kg-model-three-positions-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-constructivism-0', 'kg-paradigm-constructivism', 1, 'پارادایم برساخت‌گرایی (Constructivism) نوع: PARADIGM پارادایم که واقعیت را نه داده‌ای پیش‌بسته، بلکه برساختی اجتماعی و ذهنی می‌داند؛ پژوهشگر در پژوهش، بخشی از همان فرایند برساخت واقعیت است.', 'c2fd996d3cb23f06690d04337d47d9087e78c3c0f6c51816ca6210409a6b7e30', 343, 'kc-kg-paradigm-constructivism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c2fd996d3cb23f06690d04337d47d9087e78c3c0f6c51816ca6210409a6b7e30', token_count=343, vector_point_id='kc-kg-paradigm-constructivism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-constructivism-2', 'kg-paradigm-constructivism', 2, 'برساخت‌گرایی (سازه‌گرایی) گامی فراتر از تفسیرگرایی برمی‌دارد: نه‌تنها معنای اجتماعی، بلکه خودِ واقعیت پژوهشی را به‌عنوان محصول تعامل اجتماعی و شناختی می‌بیند. در این پارادایم، داده‌ها «کشف» نمی‌شوند، بلکه با مشارکت پژوهشگر «برساخته» می‌شوند. این پارادایم بنیان معرفت‌شناسی برساختی (social constructivism) و بنیان روش‌های نظریه‌پردازی داده‌بنیاد (grounded theory) است.', '6de39aecd9ac17cea65e4bbc65d79dd184bfee6c33e16e0d00b9fc9602a8213a', 667, 'kc-kg-paradigm-constructivism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6de39aecd9ac17cea65e4bbc65d79dd184bfee6c33e16e0d00b9fc9602a8213a', token_count=667, vector_point_id='kc-kg-paradigm-constructivism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-constructivism-3', 'kg-paradigm-constructivism', 3, 'از سنت برساخت‌گرایی اجتماعی (برگر و لکن، 1966) و برساخت‌گرایی شناختی (پیاژه، ویگوتسکی) در قرن بیستم رشد کرد.', 'dd854a4c5af5fd9a915f2a33886c0fe24eb9d31cf49da679f7cd4886dbb3e28b', 196, 'kc-kg-paradigm-constructivism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dd854a4c5af5fd9a915f2a33886c0fe24eb9d31cf49da679f7cd4886dbb3e28b', token_count=196, vector_point_id='kc-kg-paradigm-constructivism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-constructivism-4', 'kg-paradigm-constructivism', 4, 'هستی‌شناسی: واقعیت‌ها، برساخت‌های اجتماعی و ذهنی‌اند و در تعامل شکل می‌گیرند؛ معرفت‌شناسی: ذهنی و تعاملی؛ روش‌شناسی: کیفی و مشارکتی؛ اخلاقی: شفافیت درباره نقش پژوهشگر در برساخت واقعیت.', '5387fa317262588d6a49b32baa8297c19ddcfb7401d1bdf71b17d317ad9feb6d', 334, 'kc-kg-paradigm-constructivism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5387fa317262588d6a49b32baa8297c19ddcfb7401d1bdf71b17d317ad9feb6d', token_count=334, vector_point_id='kc-kg-paradigm-constructivism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-constructivism-5', 'kg-paradigm-constructivism', 5, '["واقعیت‌های اجتماعی، برساخت تعامل اجتماعی‌اند نه داده‌ی پیش‌بسته","پژوهشگر، در تولید داده، مشارکت فعال دارد (co-construction)","معنا و واقعیت، در فرایند پژوهش شکل می‌گیرند نه پیش از آن","روش‌های کیفی به‌ویژه مناسب‌اند چون بافت و فرایند را می‌گیرند"]', '354951b13dac83ae6998587c018cce91abf2c623662a6d7e3ad7fc95bd62ef7a', 454, 'kc-kg-paradigm-constructivism-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='354951b13dac83ae6998587c018cce91abf2c623662a6d7e3ad7fc95bd62ef7a', token_count=454, vector_point_id='kc-kg-paradigm-constructivism-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-constructivism-6', 'kg-paradigm-constructivism', 6, '["پیتر برگر","توماس لکن","جاناتان تسو","پولا اشتراوس"]', 'b571cd560c39ecf9b390eb2908d1e8b8a073e6c3402de2e12e5f8525b3d5a698', 98, 'kc-kg-paradigm-constructivism-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b571cd560c39ecf9b390eb2908d1e8b8a073e6c3402de2e12e5f8525b3d5a698', token_count=98, vector_point_id='kc-kg-paradigm-constructivism-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
