INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-constructivism-10', 'kg-paradigm-constructivism', 10, '["نظریه‌پردازی داده‌بنیاد","پژوهش کیفی مشارکتی","تحلیل گفتمان"]', '9d9b19a0e10608558b3020c4f5b4556202556e62fb0b94fcc7c0baa9b952e7a4', 114, 'kc-kg-paradigm-constructivism-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9d9b19a0e10608558b3020c4f5b4556202556e62fb0b94fcc7c0baa9b952e7a4', token_count=114, vector_point_id='kc-kg-paradigm-constructivism-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
