INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-constructivism-14', 'kg-paradigm-constructivism', 14, '["Berger, P. & Luckmann, T. (1966). The Social Construction of Reality","Strauss, A. & Corbin, J. (1990). Basics of Qualitative Research"]', 'e09a92f34b48807e3c46e1b199646f446f94662423fd9c1220dd34133b902077', 250, 'kc-kg-paradigm-constructivism-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e09a92f34b48807e3c46e1b199646f446f94662423fd9c1220dd34133b902077', token_count=250, vector_point_id='kc-kg-paradigm-constructivism-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-0', 'kg-paradigm-critical', 1, 'پارادایم انتقادی (Critical Paradigm) نوع: PARADIGM پارادایمی که پژوهش را ابزاری برای افشاگری روابط قدرت، ایدئولوژی و سلطه، و در نهایت رهایی‌بخشی کنشگران اجتماعی می‌داند.', '3126fafbe44edf59948a9e1f562d4def644844482db10d9a6452096fd1be9652', 307, 'kc-kg-paradigm-critical-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3126fafbe44edf59948a9e1f562d4def644844482db10d9a6452096fd1be9652', token_count=307, vector_point_id='kc-kg-paradigm-critical-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-2', 'kg-paradigm-critical', 2, 'پارادایم انتقادی، از مکتب فرانکفورت و نظریه‌ی انتقادی رشد کرده است. هدف آن نه صرفاً توصیف و تبیین، بلکه تغییر اجتماعی (emancipation) است. این پارادایم باور دارد که واقعیت، به‌ویژه در ابعاد قدرت و ایدئولوژی، توسط ساختارهای اجتماعی شکل می‌گیرد و پژوهش باید این ساختارها را افشا کند. در علوم ارتباطات، تحلیل گفتمان انتقادی (CDA) و مطالعات رسانه-قدرت-ایدئولوژی در این چارچوب جای می‌گیرند.', 'b1ebb406e5e449582cb44352c650c7f580daa7bf9d9ffaad80cbd3ee19922034', 698, 'kc-kg-paradigm-critical-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b1ebb406e5e449582cb44352c650c7f580daa7bf9d9ffaad80cbd3ee19922034', token_count=698, vector_point_id='kc-kg-paradigm-critical-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-3', 'kg-paradigm-critical', 3, 'از مکتب فرانکفورت (Adorno, Horkheimer, Marcuse) و سنت مارکسیستی انتقادی در ۱۹۲۰-۱۹۶۰ و در علوم اجتماعی با Habermas (نظریه‌ی عمل ارتباطی) و Gramsci (هژمونی) در ۱۹۷۰-۱۹۸۰ نهادینه شد.', '12fbc42bbf77a4ffd38697c1bd6b37085b631820dfa3a1619d1e63ea573a85c1', 327, 'kc-kg-paradigm-critical-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='12fbc42bbf77a4ffd38697c1bd6b37085b631820dfa3a1619d1e63ea573a85c1', token_count=327, vector_point_id='kc-kg-paradigm-critical-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-4', 'kg-paradigm-critical', 4, 'هستی‌شناسی: واقعیت، برساخت قدرت و ایدئولوژی است و هدف‌مند است؛ معرفت‌شناسی: ارزش‌محور (value-laden) و انتقادی؛ روش‌شناسی: ترکیبی، گاه کمّی-گفتاری، گاه کیفی-گفتاری؛ اخلاقی: تعهد به عدالت و رهایی‌بخشی.', '338ed4520d43f35c42e35a15eb73577ba5935772d3fe9c9f9479a7d38c3cbefb', 361, 'kc-kg-paradigm-critical-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='338ed4520d43f35c42e35a15eb73577ba5935772d3fe9c9f9479a7d38c3cbefb', token_count=361, vector_point_id='kc-kg-paradigm-critical-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-5', 'kg-paradigm-critical', 5, '["واقعیت، تحت سلطه‌ی ساختارهای قدرت و ایدئولوژی است","پژوهش باید روابط سلطه و ایدئولوژی را افشا کند","هدف پژوهش، رهایی‌بخشی و تغییر اجتماعی است","پژوهشگر باید موضع‌مندی‌اش (positionality) را صریح کند"]', '5b3a5a23a91b5ab445d69b2c121f40fc83a6049825d910b65f065a405d323a51', 365, 'kc-kg-paradigm-critical-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5b3a5a23a91b5ab445d69b2c121f40fc83a6049825d910b65f065a405d323a51', token_count=365, vector_point_id='kc-kg-paradigm-critical-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-6', 'kg-paradigm-critical', 6, '["آدورنو","هورکهایمر","مارکوزه","گرامشی","هابرماس","فوکو","فایربورن","فان‌دایک"]', '66a2307182f4dbe5d1f715ff730a15db8c75fc36e268e79a51cfa7058297e271', 145, 'kc-kg-paradigm-critical-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='66a2307182f4dbe5d1f715ff730a15db8c75fc36e268e79a51cfa7058297e271', token_count=145, vector_point_id='kc-kg-paradigm-critical-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
