INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-8', 'kg-paradigm-critical', 8, 'آلمان (فرانکفورت) و ایتالیا (سنت مارکسیستی)', '8f4ed2213133567238c86e05eaad79f72e201500299031c8db569fd0d2f717d7', 78, 'kc-kg-paradigm-critical-8', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8f4ed2213133567238c86e05eaad79f72e201500299031c8db569fd0d2f717d7', token_count=78, vector_point_id='kc-kg-paradigm-critical-8', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-9', 'kg-paradigm-critical', 9, '["فلسفه","جامعه‌شناسی","اقتصاد سیاسی رسانه","مطالعات فرهنگی"]', '3988f2816af9a41a722774609a6e4f42b83052ec1bf8cf2095299701fa7e0ae9', 110, 'kc-kg-paradigm-critical-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3988f2816af9a41a722774609a6e4f42b83052ec1bf8cf2095299701fa7e0ae9', token_count=110, vector_point_id='kc-kg-paradigm-critical-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-10', 'kg-paradigm-critical', 10, '["تحلیل گفتمان انتقادی","مطالعات ایدئولوژی رسانه","تحلیل قدرت در رسانه"]', '4113a4488f2cc03390c9b2e72cd03292ccf8caeb04d3cdd6260b0270e24f911c', 130, 'kc-kg-paradigm-critical-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4113a4488f2cc03390c9b2e72cd03292ccf8caeb04d3cdd6260b0270e24f911c', token_count=130, vector_point_id='kc-kg-paradigm-critical-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-11', 'kg-paradigm-critical', 11, '["عمق انتقادی","تعهد به تغییر اجتماعی","اتصال به سیاست"]', '57f14b48fd1d8321706959a594eb0f9a34aee07a2bc69ff7d0591e70cffeb51d', 101, 'kc-kg-paradigm-critical-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57f14b48fd1d8321706959a594eb0f9a34aee07a2bc69ff7d0591e70cffeb51d', token_count=101, vector_point_id='kc-kg-paradigm-critical-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-12', 'kg-paradigm-critical', 12, '["ممکن است به شعاربازی بیفتد","سخت‌تر است روش را با معیارهای کمّی بسنجاند","ممکن است ایدئولوژیک به نظر برسد"]', '42cd5aff978681e843870b60faa0d9c87a4bd8236c618ff174bae280ea585596', 198, 'kc-kg-paradigm-critical-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='42cd5aff978681e843870b60faa0d9c87a4bd8236c618ff174bae280ea585596', token_count=198, vector_point_id='kc-kg-paradigm-critical-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-13', 'kg-paradigm-critical', 13, '["نقد کارکردگرا: غیاب عینیت روش‌شناختی","نقد لیبرال: سیاسی‌شدن بیش از حد پژوهش"]', '5f81db914eae71bdd84c4451ada7e41a65f6d9ce2c2806653e62a89e70322c25', 145, 'kc-kg-paradigm-critical-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5f81db914eae71bdd84c4451ada7e41a65f6d9ce2c2806653e62a89e70322c25', token_count=145, vector_point_id='kc-kg-paradigm-critical-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-critical-14', 'kg-paradigm-critical', 14, '["Habermas, J. (1971). Knowledge and Human Interests","van Dijk, T. (2008). Discourse and Power","Fay, A. (1987). Critical Social Theory"]', '0810dd90a0a9332a383d72414d30e53506c83719e429bb405d12a464b79c21ba', 250, 'kc-kg-paradigm-critical-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0810dd90a0a9332a383d72414d30e53506c83719e429bb405d12a464b79c21ba', token_count=250, vector_point_id='kc-kg-paradigm-critical-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-feminist-0', 'kg-paradigm-feminist', 1, 'پارادایم فمینیستی (Feminist Paradigm) نوع: PARADIGM پارادایمی که دانش‌آفرینی را فرایندی سیاسی-معرفتی می‌داند و بر موضع‌مندی (positionality)، تجربه‌ی زنان و نقد سلطه‌ی مردسالارانه در پژوهش تأکید دارد.', '30aad77befdecebf7f1679847e69c27517f94c8993c04e88dc74fa62be734419', 361, 'kc-kg-paradigm-feminist-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='30aad77befdecebf7f1679847e69c27517f94c8993c04e88dc74fa62be734419', token_count=361, vector_point_id='kc-kg-paradigm-feminist-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-feminist-2', 'kg-paradigm-feminist', 2, 'پارادایم فمینیستی، دانش‌آفرینی را از «موضع بی‌طرف» جدا و آن را فرایندی متأثر از جنسیت، طبقه، نژاد و قدرت می‌داند. مفهوم «موضع‌مندی» (positionality) و «معرفت‌شناسی فمینیستی» (feminist epistemology) محورهای اصلی آن‌اند. این پارادایم روش‌های کیفی مشارکتی و بین‌رشته‌ای (interdisciplinary) را ترجیح می‌دهد و در مطالعات رسانه‌ی زنان و جنسیت کاربرد گسترده دارد.', '180a95d676cc588405fdb95ff59acc50137688465016b1eb758dbd747ff2eb15', 645, 'kc-kg-paradigm-feminist-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='180a95d676cc588405fdb95ff59acc50137688465016b1eb758dbd747ff2eb15', token_count=645, vector_point_id='kc-kg-paradigm-feminist-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-feminist-3', 'kg-paradigm-feminist', 3, 'از جنبش فمینیسم دوم (۱۹۶۰-۱۹۸۰) و با کارهای Haraway, Harding, and hooks در فلسفه‌ی علم و روش‌شناسی پژوهش اجتماعی در ۱۹۷۰-۱۹۹۰ نهادینه شد.', 'b69f17ba9ac87177a93f07087bb580a2ffbb4c490e410f686d42b7e1306599a9', 249, 'kc-kg-paradigm-feminist-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b69f17ba9ac87177a93f07087bb580a2ffbb4c490e410f686d42b7e1306599a9', token_count=249, vector_point_id='kc-kg-paradigm-feminist-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-feminist-4', 'kg-paradigm-feminist', 4, 'هستی‌شناسی: واقعیت، برساخت روابط جنسیتی و قدرت است؛ معرفت‌شناسی: موضع‌مند (situated knowledge)؛ روش‌شناسی: مشارکتی، کیفی، بین‌رشته‌ای؛ اخلاقی: حساسیت به سلطه و عدالت.', '3c790406f9d16471e9f9ccc49ffb2c7feb6b2d476293fc6634a37ab30471a692', 301, 'kc-kg-paradigm-feminist-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3c790406f9d16471e9f9ccc49ffb2c7feb6b2d476293fc6634a37ab30471a692', token_count=301, vector_point_id='kc-kg-paradigm-feminist-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-feminist-5', 'kg-paradigm-feminist', 5, '["دانش، بی‌طرف نیست و از موضع جنسیتی تولید می‌شود","معرفت‌شناسی فمینیستی، واقعیت را از دید تجربه‌ی زنان می‌پرسد","موضع‌مندی پژوهشگر باید صریح شود","پژوهش باید سلطه و تبعیض را افشا کند"]', 'f961ae837ce0432b277e50cd2e88e9e6cc9b7bd2782c3368022cee8a491c7612', 336, 'kc-kg-paradigm-feminist-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f961ae837ce0432b277e50cd2e88e9e6cc9b7bd2782c3368022cee8a491c7612', token_count=336, vector_point_id='kc-kg-paradigm-feminist-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-feminist-6', 'kg-paradigm-feminist', 6, '["دونا هاروی","ساندرا هاردینگ","بیلز هوکس"]', '2daf31c2400455b2cefea841d1a6d6d54ae766111421fe403fe64dbb0cf8680a', 78, 'kc-kg-paradigm-feminist-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2daf31c2400455b2cefea841d1a6d6d54ae766111421fe403fe64dbb0cf8680a', token_count=78, vector_point_id='kc-kg-paradigm-feminist-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
