INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-feminist-12', 'kg-paradigm-feminist', 12, '["ممکن است به «دانش زنان» تقلیل پیدا کند","سخت در تعریف عملیاتی معرفت‌شناسی"]', 'c88c5829fd55d8cb1de16e6aa8276cf43f04d8b195ac88ff2c4fd95e74cdb007', 140, 'kc-kg-paradigm-feminist-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c88c5829fd55d8cb1de16e6aa8276cf43f04d8b195ac88ff2c4fd95e74cdb007', token_count=140, vector_point_id='kc-kg-paradigm-feminist-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-feminist-13', 'kg-paradigm-feminist', 13, '["نقد لیبرال: سیاسی‌شدن بیش از حد پژوهش","نقد پسااستعماری: تکیه بر تجربه‌ی زنان سفیدپوست غربی"]', '6567869aa90901eba9eadeca9ca13bb0ab592ef880c95a86aed7424c855835ed', 172, 'kc-kg-paradigm-feminist-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6567869aa90901eba9eadeca9ca13bb0ab592ef880c95a86aed7424c855835ed', token_count=172, vector_point_id='kc-kg-paradigm-feminist-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-feminist-14', 'kg-paradigm-feminist', 14, '["Haraway, D. (1988). Situated Knowledges: The Science Question in Feminism and the Privilege of Partial Perspective","Harding, S. (1986). The Science Question in Feminism","hooks, b. (1984). Feminist Theory: From Margin to Center"]', '3069274d3b28dfc73c0b6a1b2e26f27f72b2bf4c674a0897479fe24493ebaf44', 421, 'kc-kg-paradigm-feminist-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3069274d3b28dfc73c0b6a1b2e26f27f72b2bf4c674a0897479fe24493ebaf44', token_count=421, vector_point_id='kc-kg-paradigm-feminist-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-interpretivism-0', 'kg-paradigm-interpretivism', 1, 'پارادایم تفسیرگرایی (Interpretivism) نوع: PARADIGM پارادایم پژوهشی که واقعیت را برساخت اجتماعی-معنایی کنشگران می‌داند و هدف پژوهش را «فهم» (Verstehen) معانی و تجربه‌های زیسته می‌داند، نه تبیین علّی.', '8350d62c0890ed4d27c03f4be3765f987981e37858e746083a8d3a07c3591919', 359, 'kc-kg-paradigm-interpretivism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8350d62c0890ed4d27c03f4be3765f987981e37858e746083a8d3a07c3591919', token_count=359, vector_point_id='kc-kg-paradigm-interpretivism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-interpretivism-2', 'kg-paradigm-interpretivism', 2, 'تفسیرگرایی (یا برداشت‌گرایی) بر این باور است که جهان اجتماعی را نمی‌توان مانند جهان طبیعی «از بیرون» تبیین کرد؛ پژوهشگر باید از درون تجربه‌ی کنشگران، معانی و نیت‌هایشان را بخواند. این پارادایم مبانی فلسفی پژوهش کیفی است و از سنت هرموتیک (Weber, Dilthey, Gadamer) و پدیدارشناسی رشد کرده است. در علوم ارتباطات، تحلیل گفتمان، قوم‌نگاری، پژوهش روایی و تحلیل مضمون معمولا‌ً در این پارادایم جای می‌گیرند.', '4e3f2be7e312e28fdef5a6157bc515c33f332fbb35899f996f578e86ca8d3e48', 723, 'kc-kg-paradigm-interpretivism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4e3f2be7e312e28fdef5a6157bc515c33f332fbb35899f996f578e86ca8d3e48', token_count=723, vector_point_id='kc-kg-paradigm-interpretivism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-interpretivism-3', 'kg-paradigm-interpretivism', 3, 'از مکاتب هگلی و هگل-مارکسیستی (دیلای، وبر) در اواخر قرن نوزدهم و با گسترش پدیدارشناسی هوسرل و هورموتیک هایدگر و گادامر در قرن بیستم شکل گرفت.', 'e285e136405ce5f0faf74c05b1d7221488b62d3ec46b76f45de1f7310f35b80e', 256, 'kc-kg-paradigm-interpretivism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e285e136405ce5f0faf74c05b1d7221488b62d3ec46b76f45de1f7310f35b80e', token_count=256, vector_point_id='kc-kg-paradigm-interpretivism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-interpretivism-4', 'kg-paradigm-interpretivism', 4, 'هستی‌شناسی: واقعیت‌های اجتماعی، برساخت معنایی و زمینه‌مند؛ معرفت‌شناسی: ذهنی و تعاملی (subject-object interaction)؛ روش‌شناسی: کیفی و استقرایی؛ اخلاقی: حساسیت به بافت و تجربه‌ی مشارکت‌کنندگان.', '9b9025013ee29f8a1eafa6a950caf9f8ec79fa6ef16965b80f3e62894b16dd16', 349, 'kc-kg-paradigm-interpretivism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9b9025013ee29f8a1eafa6a950caf9f8ec79fa6ef16965b80f3e62894b16dd16', token_count=349, vector_point_id='kc-kg-paradigm-interpretivism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-interpretivism-5', 'kg-paradigm-interpretivism', 5, '["معنای اجتماعی، در تعامل و زمینه ساخته می‌شود و از بیرون قابل‌سنجش مطلق نیست","هدف پژوهش، فهم عمیق معانی (Verstehen) است نه تبیین علّی","روش‌ها باید بافت‌مند (contextual) و انعطاف‌پذیر باشند","پژوهشگر و مشارکت‌کننده، هر دو در فرایند فهم، هم‌آفرین معنایند"]', '08374cb64307a487b18c1d3234a247bf3b6f1b77fc394819cb52227fcb85f542', 467, 'kc-kg-paradigm-interpretivism-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='08374cb64307a487b18c1d3234a247bf3b6f1b77fc394819cb52227fcb85f542', token_count=467, vector_point_id='kc-kg-paradigm-interpretivism-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-interpretivism-6', 'kg-paradigm-interpretivism', 6, '["ماکس وبر","ویلفرد دیلای","هانس-گئورگ گادامر","امیل دورکیم (به‌عنوان پیشامد)"]', '2a75150ed94bc8bada76ca850fbd69a6512aba6d1c11fad554f28eef6ed2ca6c', 143, 'kc-kg-paradigm-interpretivism-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2a75150ed94bc8bada76ca850fbd69a6512aba6d1c11fad554f28eef6ed2ca6c', token_count=143, vector_point_id='kc-kg-paradigm-interpretivism-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
