INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-interpretivism-12', 'kg-paradigm-interpretivism', 12, '["سخت‌تر است تعمیم دهد","وابسته به ماهر بودن پژوهشگر","احتمال ذهنی‌گرائی"]', '58f8c3c8bfcddf43a5afad14c0d2314d078cbf8be7a769331c83f7c5e071b984', 134, 'kc-kg-paradigm-interpretivism-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='58f8c3c8bfcddf43a5afad14c0d2314d078cbf8be7a769331c83f7c5e071b984', token_count=134, vector_point_id='kc-kg-paradigm-interpretivism-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-interpretivism-13', 'kg-paradigm-interpretivism', 13, '["نقد پساثبات‌گرا: عدم تکرارپذیری","نقد انتقادی: نادیده‌گرفتن ساختار قدرت"]', '197e5fc85fa1551362928348a103bcc8efbea6243378248131ca69a232b0a7e5', 136, 'kc-kg-paradigm-interpretivism-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='197e5fc85fa1551362928348a103bcc8efbea6243378248131ca69a232b0a7e5', token_count=136, vector_point_id='kc-kg-paradigm-interpretivism-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-interpretivism-14', 'kg-paradigm-interpretivism', 14, '["Weber, M. (1922). Wirtschaft und Gesellschaft","Gadamer, H.-G. (1960). Wahrheit und Methode"]', '1956f03a799b747bdd56d8727e57182009bcdf26ab499561d133010c410a0376', 172, 'kc-kg-paradigm-interpretivism-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1956f03a799b747bdd56d8727e57182009bcdf26ab499561d133010c410a0376', token_count=172, vector_point_id='kc-kg-paradigm-interpretivism-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-participatory-0', 'kg-paradigm-participatory', 1, 'پارادایم مشارکتی (Participatory Paradigm) نوع: PARADIGM پارادایمی که پژوهش را فرایندی هم‌آفرین (co-created) با مشارکت‌کنندگان می‌داند و مرز بین پژوهشگر و موضوع را از بین می‌برد.', '065a66eb49321e59384767561201fb1ca1bccd08dc1cf81b284202dc5c686340', 321, 'kc-kg-paradigm-participatory-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='065a66eb49321e59384767561201fb1ca1bccd08dc1cf81b284202dc5c686340', token_count=321, vector_point_id='kc-kg-paradigm-participatory-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-participatory-2', 'kg-paradigm-participatory', 2, 'پارادایم مشارکتی (participatory action research / PAR) ریشه در سنت فمینیستی و انتقادی دارد و بر «هم‌آفرینی دانش» (co-creation of knowledge) و «اقدام» (action) به‌عنوان هدف پژوهش تأکید می‌کند. در این پارادایم، مشارکت‌کنندگان نه صرفاً «موضوع» پژوهش، بلکه شریک آن‌اند. در علوم ارتباطات، پژوهش‌های مشارکتی در جوامع محلی، طراحی رسانه‌های مشارکتی و پژوهش‌های توسعه‌محور در این چارچوب صورت می‌گیرند.', '518033bd0bf21df95270eb171b3e4daddef615b835e1f96ea868534863cd1dd2', 712, 'kc-kg-paradigm-participatory-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='518033bd0bf21df95270eb171b3e4daddef615b835e1f96ea868534863cd1dd2', token_count=712, vector_point_id='kc-kg-paradigm-participatory-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-participatory-3', 'kg-paradigm-participatory', 3, 'از سنت‌های مشارکتی (Freire, Fals Borda) و با بازگشت به روش‌شناسی اجتماعی در ۱۹۷۰-۱۹۹۰ شکل گرفت و در مطالعات توسعه و ارتباطات محلی گسترش یافت.', '825f653d441d01454a50c7d60aa1f3913aba98eb858a8c46758fbd3be9056c19', 256, 'kc-kg-paradigm-participatory-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='825f653d441d01454a50c7d60aa1f3913aba98eb858a8c46758fbd3be9056c19', token_count=256, vector_point_id='kc-kg-paradigm-participatory-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-participatory-4', 'kg-paradigm-participatory', 4, 'هستی‌شناسی: واقعیت، در تعامل اجتماعی و مشارکتی شکل می‌گیرد؛ معرفت‌شناسی: هم‌آفرین (co-created)؛ روش‌شناسی: مشارکتی و اقدام‌محور؛ اخلاقی: عدالت مشارکتی و توانمندسازی.', '95141b43026dc1f5a841d03cd9afd140f20720141361a868987567472a820195', 300, 'kc-kg-paradigm-participatory-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='95141b43026dc1f5a841d03cd9afd140f20720141361a868987567472a820195', token_count=300, vector_point_id='kc-kg-paradigm-participatory-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-participatory-5', 'kg-paradigm-participatory', 5, '["پژوهش، باید با مشارکت موضوعات صورت گیرد نه روی آن‌ها","هدف پژوهش، هم دانش است و هم تغییر اجتماعی","مرز پژوهشگر و موضوع، در پژوهش مشارکتی از بین می‌رود","دانش، در جوامع محلی و با تجربه‌ی مشارکت‌کنندگان ساخته می‌شود"]', 'c892fec82a1e194bc9ce01dcd023751f62032c046ebcc2f6fa9f9a2b5b1c867e', 394, 'kc-kg-paradigm-participatory-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c892fec82a1e194bc9ce01dcd023751f62032c046ebcc2f6fa9f9a2b5b1c867e', token_count=394, vector_point_id='kc-kg-paradigm-participatory-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
