INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-participatory-11', 'kg-paradigm-participatory', 11, '["توانمندسازی مشارکت‌کنندگان","اتصال پژوهش به اقدام"]', '2b2a9a96ecec2ea12c048c47eec548b488c58376ddc40ed2a693d747deaeb70f', 96, 'kc-kg-paradigm-participatory-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2b2a9a96ecec2ea12c048c47eec548b488c58376ddc40ed2a693d747deaeb70f', token_count=96, vector_point_id='kc-kg-paradigm-participatory-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-participatory-12', 'kg-paradigm-participatory', 12, '["سخت در تعمیم","وابستگی به انگیزه‌ی مشارکت‌کنندگان","هزینه و زمان بالا"]', '48146a3087b191bc4a2a1a7bd7296933061bd32916a00b4fea04e8b147b5995d', 132, 'kc-kg-paradigm-participatory-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='48146a3087b191bc4a2a1a7bd7296933061bd32916a00b4fea04e8b147b5995d', token_count=132, vector_point_id='kc-kg-paradigm-participatory-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-participatory-13', 'kg-paradigm-participatory', 13, '["نقد پراگماتیست: بی‌رغبتی به روش‌های کمّی","نقد انتقادی: ممکن است به مشارکت کاذب بیفتد"]', '698a83ca58f608f9e7492818ac70bd044a8f4d5e7205b1608381c6d45775f7f9', 161, 'kc-kg-paradigm-participatory-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='698a83ca58f608f9e7492818ac70bd044a8f4d5e7205b1608381c6d45775f7f9', token_count=161, vector_point_id='kc-kg-paradigm-participatory-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-participatory-14', 'kg-paradigm-participatory', 14, '["Fals Borda, M. (1987). Research as Praxis","Freire, P. (1970). Pedagogy of the Oppressed","Chambers, R. (1997). Participatory Rural Appraisal"]', '9f9cd37b74d57cae37607fb94e0d6125d86546dfd20e763bf29c9943d007e6be', 263, 'kc-kg-paradigm-participatory-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9f9cd37b74d57cae37607fb94e0d6125d86546dfd20e763bf29c9943d007e6be', token_count=263, vector_point_id='kc-kg-paradigm-participatory-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-positivism-0', 'kg-paradigm-positivism', 1, 'پارادایم اثبات‌گرایی (Positivism) نوع: PARADIGM پارادایم پژوهشی مبتنی بر باور به واقعیتی عینی، واحد و قابل‌سنجش که از طریق مشاهده‌ی نظام‌مند و روش‌های کمی می‌توان آن را شناخت و تبیین علّی داد.', '7927da889baa3a9c9017e08f0417a47b9f934d7c8c749b39a077cbbea6144fe8', 349, 'kc-kg-paradigm-positivism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7927da889baa3a9c9017e08f0417a47b9f934d7c8c749b39a077cbbea6144fe8', token_count=349, vector_point_id='kc-kg-paradigm-positivism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-positivism-2', 'kg-paradigm-positivism', 2, 'اثبات‌گرایی مبانی هستی‌شناختی و معرفت‌شناختی پژوهش تجربی مدرن را مشخص می‌کند: واقعیت مستقل از ذهن پژوهشگر وجود دارد، حقیقت واحد است و تنها از طریق داده‌های تجربیِ قابل‌تکرار شناختنی است. در این پارادایم پژوهشگر باورهایش را در قالب فرضیه‌های آزمون‌پذیر بیان می‌کند، متغیرها را اندازه‌گیری می‌کند و به دنبال کشف قوانین و روابط علّی عمومی است. این پارادایم بنیاد فلسفی رویکرد کمّی و پژوهش‌های آزمایشی و پیمایشی در علوم اجتماعی و ارتباطات است و سنت پژوهش کلمبیا و پژوهش‌های اثرات رسانه را شکل داده است. بر اساس جدول مواضع بنیادی پارادایم‌ها (fulltext.txt، جدول ۷-۱)، اثباتگرایی واقعیت «قوانین و حقیقت واحد» را پنداشته و روش‌شناسی آن «کمّی و قیاسی» است.', 'add495c9926619e7199e1a1c69bfe90b3ef035512c370616ffe49b34954baf6d', 1178, 'kc-kg-paradigm-positivism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='add495c9926619e7199e1a1c69bfe90b3ef035512c370616ffe49b34954baf6d', token_count=1178, vector_point_id='kc-kg-paradigm-positivism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-positivism-3', 'kg-paradigm-positivism', 3, 'ریشه در فلسفه‌ی منطق‌گرا (پس‌پوزیتیویسم منطقی) و سنت علم‌گرایی قرن هجدهم و نوزدهم اروپا دارد؛ در علوم اجتماعی با آگست کنت و در علوم ارتباطات با پژوهش‌های تجربی کلمبیا (دهه‌های ۱۹۴۰-۱۹۶۰) نهادینه شد.', '6f3c0e4a569197c7b9af82c496a565758f216d1cf0738eaec68e989c74dc9760', 359, 'kc-kg-paradigm-positivism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6f3c0e4a569197c7b9af82c496a565758f216d1cf0738eaec68e989c74dc9760', token_count=359, vector_point_id='kc-kg-paradigm-positivism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-positivism-4', 'kg-paradigm-positivism', 4, 'هستی‌شناسی: واقعیت عینی با قوانین و حقیقت واحد؛ معرفت‌شناسی: عینی و منقطع از ارزش (value-free)؛ روش‌شناسی: کمّی و قیاسی (deductive)؛ اخلاقی: بی‌طرفی پژوهشگر.', 'a435ccb4f25e747b4e691982bb4dc777e6304bb45c8f3d6c0fc14f736d631fa7', 285, 'kc-kg-paradigm-positivism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a435ccb4f25e747b4e691982bb4dc777e6304bb45c8f3d6c0fc14f736d631fa7', token_count=285, vector_point_id='kc-kg-paradigm-positivism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-positivism-5', 'kg-paradigm-positivism', 5, '["واقعیت عینی، واحد و مستقل از ذهن است و قابل‌کشف است","دانش معتبر تنها از طریق مشاهده‌ی تجربی و اندازه‌گیری نظام‌مند حاصل می‌شود","پژوهش باید از طرح فرضیه و آزمون نظام‌مند آن پیروی کند (منطق قیاسی)","تبیین علّی و پیش‌بینی، اهداف بنیادی پژوهش است"]', '4ad4616046a3b08e0920dad1e78c2b1cf5930d054aac745ac9de776e947d599d', 450, 'kc-kg-paradigm-positivism-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4ad4616046a3b08e0920dad1e78c2b1cf5930d054aac745ac9de776e947d599d', token_count=450, vector_point_id='kc-kg-paradigm-positivism-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
