INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-positivism-12', 'kg-paradigm-positivism', 12, '["تقلیل پدیده‌های اجتماعی به متغیرهای سنجش‌پذیر","بی‌توجهی به معنا، بافت و تجربه‌ی زیسته","فرض عینیت مطلق واقعیت"]', '81e6d29f3f3b9921d11a139e69e04d28f43b95dde5f9df045073bda4486470d3', 207, 'kc-kg-paradigm-positivism-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='81e6d29f3f3b9921d11a139e69e04d28f43b95dde5f9df045073bda4486470d3', token_count=207, vector_point_id='kc-kg-paradigm-positivism-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-positivism-13', 'kg-paradigm-positivism', 13, '["نقد تفسیری: معنا در پژوهش‌گر فرو می‌رود","نقد انتقادی: پوشاندن روابط قدرت","نقد برساخت‌گرا: واقعیت، برساخت اجتماعی است"]', '2bd2d0a95e17eaee5d67b32229041d421b84157e1405e022aeb9df018c79054c', 221, 'kc-kg-paradigm-positivism-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2bd2d0a95e17eaee5d67b32229041d421b84157e1405e022aeb9df018c79054c', token_count=221, vector_point_id='kc-kg-paradigm-positivism-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-positivism-14', 'kg-paradigm-positivism', 14, '["Bryman, A. (2016). Social Research Methods, ch. 2 (paradigms)","Kothari, C.R. (2004). Research Methodology: Methods and Techniques, ch. 1"]', '0b41401056e2340df8e8210291f32e2850c30b39c1da0695763a754d607d919d', 256, 'kc-kg-paradigm-positivism-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0b41401056e2340df8e8210291f32e2850c30b39c1da0695763a754d607d919d', token_count=256, vector_point_id='kc-kg-paradigm-positivism-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postcolonial-0', 'kg-paradigm-postcolonial', 1, 'پارادایم پسااستعماری (Postcolonial Paradigm) نوع: PARADIGM پارادایمی که دانش‌آفرینی را از منظر سلطه‌ی استعماری و ساختارهای قدرت شمال-جنوب می‌سنجد و به دانش‌های بومی و «جنوب» مشروعیت می‌بخشد.', '79c675e6c534a82cad627f24e9f3c862918c21c20134ca29d9289403cc89b220', 345, 'kc-kg-paradigm-postcolonial-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='79c675e6c534a82cad627f24e9f3c862918c21c20134ca29d9289403cc89b220', token_count=345, vector_point_id='kc-kg-paradigm-postcolonial-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postcolonial-2', 'kg-paradigm-postcolonial', 2, 'پارادایم پسااستعماری، پژوهش را در بستر تاریخ سلطه‌ی استعماری می‌بیند و از مشروعیت دانش‌های «مرکز» (غرب) به چالش می‌کشد. این پارادایم بر «استعمارزدایی از دانش» (decolonizing knowledge) و «معرفت‌شناسی جنوب» (epistemology of the South) تأکید دارد. در علوم ارتباطات، تحلیل گفتمان رسانه‌های جهانی، مطالعات رسانه در کشورهای در حال توسعه و نقد امپریالیسم فرهنگی در این چارچوب قرار می‌گیرند.', 'f374ff214a05844ddbb302149fad6bb9d4e899d40d3b8ae793b0bf0531a27cfc', 696, 'kc-kg-paradigm-postcolonial-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f374ff214a05844ddbb302149fad6bb9d4e899d40d3b8ae793b0bf0531a27cfc', token_count=696, vector_point_id='kc-kg-paradigm-postcolonial-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postcolonial-3', 'kg-paradigm-postcolonial', 3, 'از سنت پسااستعماری (Said, Spivak, Bhabha, Fanon) در ۱۹۷۸-۱۹۹۴ و با بازخوانی روش‌شناسی پژوهش از دید جنوب جهانی (Chatterjee, Mignolo) در ۱۹۹۰-۲۰۱۰ شکل گرفت.', '8a8f31f9deccf9807ed5cd7168ab4665bfe52561f35d43fa1a16e49758c3abdf', 280, 'kc-kg-paradigm-postcolonial-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8a8f31f9deccf9807ed5cd7168ab4665bfe52561f35d43fa1a16e49758c3abdf', token_count=280, vector_point_id='kc-kg-paradigm-postcolonial-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postcolonial-4', 'kg-paradigm-postcolonial', 4, 'هستی‌شناسی: واقعیت، برساخت روابط استعماری و قدرت است؛ معرفت‌شناسی: موضع‌مند از دید جنوب جهانی؛ روش‌شناسی: ترکیبی، با تأکید بر دانش‌های بومی؛ اخلاقی: عدالت معرفتی و استعمارزدایی.', '603494384b4caaf3c647b4a4ecde1b18fd0181ecd9d5c0239340be7575e9982a', 321, 'kc-kg-paradigm-postcolonial-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='603494384b4caaf3c647b4a4ecde1b18fd0181ecd9d5c0239340be7575e9982a', token_count=321, vector_point_id='kc-kg-paradigm-postcolonial-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postcolonial-5', 'kg-paradigm-postcolonial', 5, '["دانش، محصول ساختارهای قدرت استعماری است","دانش‌های بومی و جنوب، مشروع و معتبرند","پژوهش باید ساختارهای سلطه‌ی معرفتی را افشا کند","مشارکت گروه‌های حاشیه‌ای، در تولید دانش ضروری است"]', 'd3b0766eb4f2006f083aeb46f1e7793cfaf927f81fd3e3e6ddc7689f851b52e5', 334, 'kc-kg-paradigm-postcolonial-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d3b0766eb4f2006f083aeb46f1e7793cfaf927f81fd3e3e6ddc7689f851b52e5', token_count=334, vector_point_id='kc-kg-paradigm-postcolonial-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
