INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postcolonial-12', 'kg-paradigm-postcolonial', 12, '["ممکن است به کلیشه‌ی «شرق در برابر غرب» بیفتد","سخت در تعریف روش"]', '55a25f12a9b430f4295132c33ab6b1cdaf307743e5650ab1cc8e5f4908658f52', 121, 'kc-kg-paradigm-postcolonial-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='55a25f12a9b430f4295132c33ab6b1cdaf307743e5650ab1cc8e5f4908658f52', token_count=121, vector_point_id='kc-kg-paradigm-postcolonial-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postcolonial-13', 'kg-paradigm-postcolonial', 13, '["نقد پراگماتیست: سیاست‌محور بودن بیش از حد","نقد پساساختارگرا: باقی‌ماندن در دوقطبی‌های قدیمی"]', 'ea3ceb32282e60728f3557a802dee2bad8e72384e87a20a919f1512588a3896b', 174, 'kc-kg-paradigm-postcolonial-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ea3ceb32282e60728f3557a802dee2bad8e72384e87a20a919f1512588a3896b', token_count=174, vector_point_id='kc-kg-paradigm-postcolonial-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postcolonial-14', 'kg-paradigm-postcolonial', 14, '["Said, E. (1978). Orientalism","Spivak, G.C. (1988). Can the Subaltern Speak?","Mignolo, W.D. (2011). The Darker Side of Western Modernity"]', '4ae5c141f91cd33784d2e75159c62a5baba9151ca464fb2d3fe0757f52e889b0', 256, 'kc-kg-paradigm-postcolonial-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4ae5c141f91cd33784d2e75159c62a5baba9151ca464fb2d3fe0757f52e889b0', token_count=256, vector_point_id='kc-kg-paradigm-postcolonial-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-0', 'kg-paradigm-postpositivism', 1, 'پارادایم پساثبات‌گرایی (Post-positivism) نوع: PARADIGM پارادایمی تعدیل‌یافته از اثبات‌گرایی که حقیقت واحد را می‌پذیرد اما آن را تنها قابل‌نزدیک‌شدن (approximable) می‌داند و روش‌شناسی‌اش را بر ابطال‌پذیری و واقع‌گرایی انتقادی استوار می‌سازد.', '1e66cc83772782e87249b65af78c705b7a4fef9baa6cbc98317b3606a9e15403', 436, 'kc-kg-paradigm-postpositivism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1e66cc83772782e87249b65af78c705b7a4fef9baa6cbc98317b3606a9e15403', token_count=436, vector_point_id='kc-kg-paradigm-postpositivism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-2', 'kg-paradigm-postpositivism', 2, 'پسااثبات‌گرایی اصلاحی روش‌مند بر اثبات‌گرایی است: همچنان بر وجود واقعیتی عینی و حقیقت واحد تأکید دارد، اما ادعای شناخت قطعی را کنار می‌گذارد و می‌گوید نظریه‌ها را می‌توان اثبات کرد، نه محض وجودشان را — فقط می‌توان از طریق ابطال (falsification) به آن‌ها نزدیک شد. این پارادایم مبانی «پژوهش کمّی واقع‌گرایانه» (realist quantitative research) را فراهم می‌کند و در عمل با روش‌های کمّی، طراحی نیمه‌آزمایشی و تحلیل علّی پیوند دارد.', '42517c7b029bf9e92057a08c300e858bad290be4b32f9e59af3ba80e70931616', 772, 'kc-kg-paradigm-postpositivism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='42517c7b029bf9e92057a08c300e858bad290be4b32f9e59af3ba80e70931616', token_count=772, vector_point_id='kc-kg-paradigm-postpositivism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-3', 'kg-paradigm-postpositivism', 3, 'از نقد کارل پوپر بر اثبات‌گرایی (falsificationism) در دهه‌ی ۱۹۳۰ و از نقد پیتر فایراباخ و سنت «علم نقدی» در ۱۹۶۰-۱۹۷۰ در فلسفه‌ی علم رشد کرد.', 'db3f385d341e7440ff4bb5be2844b50fd48b2e33cff3c578f12b1f1190842485', 256, 'kc-kg-paradigm-postpositivism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='db3f385d341e7440ff4bb5be2844b50fd48b2e33cff3c578f12b1f1190842485', token_count=256, vector_point_id='kc-kg-paradigm-postpositivism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-4', 'kg-paradigm-postpositivism', 4, 'هستی‌شناسی: واقعیت عینی اما قابل‌شناخت تنها تقریبی؛ معرفت‌شناسی: عینی اما شکی و ابطال‌پذیر؛ روش‌شناسی: کمّی با تأکید بر کنترل خطا و ابطال‌پذیری؛ اخلاقی: بی‌طرفی با پذیرش محدودیت‌های شناخت.', 'bf91f8caa35ed8a73bc5ce73459f7da3f562f953f9f5701a81a0cf5405c03387', 341, 'kc-kg-paradigm-postpositivism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bf91f8caa35ed8a73bc5ce73459f7da3f562f953f9f5701a81a0cf5405c03387', token_count=341, vector_point_id='kc-kg-paradigm-postpositivism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-5', 'kg-paradigm-postpositivism', 5, '["حقیقت واحد وجود دارد اما شناخت ما از آن همیشه شکی و قابل‌اصلاح است","نظریه‌ها ابطال‌پذیرند نه اثبات‌پذیر","روش‌های کمّی معتبرند اما باید خطا و سوگیری را صریح بدانند","واقع‌گرایی انتقادی: ساختارهای پنهان علّی، واقعیت را شکل می‌دهند"]', '9ff28167f7c5e87ce0e6fb04d901c0c50b0a16ec9ebdcd4b1efec82da13ced63', 425, 'kc-kg-paradigm-postpositivism-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9ff28167f7c5e87ce0e6fb04d901c0c50b0a16ec9ebdcd4b1efec82da13ced63', token_count=425, vector_point_id='kc-kg-paradigm-postpositivism-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-6', 'kg-paradigm-postpositivism', 6, '["کارل پوپر","پیتر فایراباخ"]', 'c30a43af6c12832ea89933d108a9bf7d2986f887af345798a9aedc7c2bade14c', 52, 'kc-kg-paradigm-postpositivism-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c30a43af6c12832ea89933d108a9bf7d2986f887af345798a9aedc7c2bade14c', token_count=52, vector_point_id='kc-kg-paradigm-postpositivism-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
