INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-9', 'kg-paradigm-postpositivism', 9, '["فلسفه‌ی علم","روان‌شناسی","علوم ارتباطات"]', 'a3f5e4ea0cdb4fff2ddd92c437e24b92642484cdd1e19d94673b161587223148', 80, 'kc-kg-paradigm-postpositivism-9', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a3f5e4ea0cdb4fff2ddd92c437e24b92642484cdd1e19d94673b161587223148', token_count=80, vector_point_id='kc-kg-paradigm-postpositivism-9', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-10', 'kg-paradigm-postpositivism', 10, '["پژوهش‌های کمّی با کنترل خطا","طراحی نیمه‌آزمایشی","استنباط علّی"]', '7e13178fcbd95b0a50f3b535b0d7a0ec5a7e96f424c83ed861cf1f362f3a0bf4', 121, 'kc-kg-paradigm-postpositivism-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7e13178fcbd95b0a50f3b535b0d7a0ec5a7e96f424c83ed861cf1f362f3a0bf4', token_count=121, vector_point_id='kc-kg-paradigm-postpositivism-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-11', 'kg-paradigm-postpositivism', 11, '["پذیرش واقعیت عینی همراه با انعطاف روش‌شناختی","تقویت اعتبار پژوهش کمّی"]', '7b3de84d31b31c0ba3cc7af37269d2016d7b08c8b8d4d10e312ea116a4e0b6e2', 134, 'kc-kg-paradigm-postpositivism-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7b3de84d31b31c0ba3cc7af37269d2016d7b08c8b8d4d10e312ea116a4e0b6e2', token_count=134, vector_point_id='kc-kg-paradigm-postpositivism-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-12', 'kg-paradigm-postpositivism', 12, '["هنگامی که پدیده‌ها عمق معنایی دارند، هنوز به بافت نمی‌رسد","در تحلیل گفتمان و روایت کاربرد محدود"]', '7d0935bcbb54f3cda0b18bafb8061a4bd58c8aa00ea72d5bbc7798b5681016db', 181, 'kc-kg-paradigm-postpositivism-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7d0935bcbb54f3cda0b18bafb8061a4bd58c8aa00ea72d5bbc7798b5681016db', token_count=181, vector_point_id='kc-kg-paradigm-postpositivism-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-13', 'kg-paradigm-postpositivism', 13, '["نقد تفسیری: معنای زیسته‌ی کنشگران نادیده گرفته می‌شود"]', '497b5746d7dc84784b2220bb18e20556167023e8dcfcb647be10f422b8638385', 103, 'kc-kg-paradigm-postpositivism-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='497b5746d7dc84784b2220bb18e20556167023e8dcfcb647be10f422b8638385', token_count=103, vector_point_id='kc-kg-paradigm-postpositivism-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-postpositivism-14', 'kg-paradigm-postpositivism', 14, '["Popper, K. (1934). Logik der Forschung","Bryman, A. (2016). Social Research Methods, ch. 2"]', '6348b0a0d2d2d8936111dad020143babc6a60e617dafea4f777b413028d8c493', 170, 'kc-kg-paradigm-postpositivism-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6348b0a0d2d2d8936111dad020143babc6a60e617dafea4f777b413028d8c493', token_count=170, vector_point_id='kc-kg-paradigm-postpositivism-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-0', 'kg-paradigm-pragmatism', 1, 'پارادایم پراگماتیسم (Pragmatism) نوع: PARADIGM پارادایم عمل‌گرایانه که واقعیت را نه ثابت و نه صرفاً برساخت، بلکه نتیجه‌ی تعامل کنشگر با محیط می‌داند و مبنای روش‌های آمیخته (mixed methods) است.', '37bccd3bdfe5ff1cee0f8c47562941169c1f3b58c080cfca8583e2860026e8b5', 349, 'kc-kg-paradigm-pragmatism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='37bccd3bdfe5ff1cee0f8c47562941169c1f3b58c080cfca8583e2860026e8b5', token_count=349, vector_point_id='kc-kg-paradigm-pragmatism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-2', 'kg-paradigm-pragmatism', 2, 'پراگماتیسم بر «کاربرد» و «حل مسئله» تمرکز دارد؛ نه به دنبال حقیقت مطلق، نه به دنبال فهم تفسیری صرف، بلکه به دنبال «آنچه عملی است». این پارادایم مرز سخت بین کمّی و کیفی را کنار می‌گذارد و مبنای فلسفی رویکرد آمیخته (mixed methods) در پژوهش است. در علوم ارتباطات، بسیاری از پژوهش‌های کمّی-کیفی هم‌زمان، در چارچوب پراگماتیستی صورت می‌گیرند.', '8114a6175f8980333eab3378aa54a5d1459c1d7665e4245a51f9c59fcab7ff1c', 610, 'kc-kg-paradigm-pragmatism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8114a6175f8980333eab3378aa54a5d1459c1d7665e4245a51f9c59fcab7ff1c', token_count=610, vector_point_id='kc-kg-paradigm-pragmatism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-3', 'kg-paradigm-pragmatism', 3, 'از سنت پراگماتیسم کلاسیک آمریکا (James, Dewey, Peirce) در اواخر قرن نوزدهم و با بازگشت پراگماتیسم جدید (neopragmatism) در ۱۹۸۰-۱۹۹۰ در روش‌شناسی پژوهش اجتماعی نهادینه شد.', '3133f1b172f515969a64719754a7f207fc891fc035f3f23257ff63842608005a', 309, 'kc-kg-paradigm-pragmatism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3133f1b172f515969a64719754a7f207fc891fc035f3f23257ff63842608005a', token_count=309, vector_point_id='kc-kg-paradigm-pragmatism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-4', 'kg-paradigm-pragmatism', 4, 'هستی‌شناسی: واقعیت، تعامل کنشگر و محیط است و چندوجهی است؛ معرفت‌شناسی: عمل‌محور و نتیجه‌محور؛ روش‌شناسی: ترکیبی (کمّی + کیفی)؛ اخلاقی: شفافیت درباره هدف پژوهش و کاربردی‌بودن آن.', '2d7dc800162a3f244d002dfbf4fb683c85bb607539fdc61d22723750e59da0b4', 321, 'kc-kg-paradigm-pragmatism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2d7dc800162a3f244d002dfbf4fb683c85bb607539fdc61d22723750e59da0b4', token_count=321, vector_point_id='kc-kg-paradigm-pragmatism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-5', 'kg-paradigm-pragmatism', 5, '["پرسش پژوهش، مهم‌تر از پارادایم است","بهترین روش، روشی است که به بهترین وجه به پرسش پاسخ می‌دهد","ترکیب کمّی و کیفی، برای درک کامل پدیده لازم است","واقعیت، در تعامل عملی شکل می‌گیرد نه پیش از آن"]', '442eb85ffda518ad14574fe3a9c4600838222457897df09b0828815177028b8e', 358, 'kc-kg-paradigm-pragmatism-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='442eb85ffda518ad14574fe3a9c4600838222457897df09b0828815177028b8e', token_count=358, vector_point_id='kc-kg-paradigm-pragmatism-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-6', 'kg-paradigm-pragmatism', 6, '["چارلز سندرس پیرس","ویلیام جیمز","جان دیویی","جو کریسول","مایکل یونگ"]', '3186f3629c8ba514fe7a943f654b43bcdb97cb0ff8e2eace0b4c3abe5d3393dc', 129, 'kc-kg-paradigm-pragmatism-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3186f3629c8ba514fe7a943f654b43bcdb97cb0ff8e2eace0b4c3abe5d3393dc', token_count=129, vector_point_id='kc-kg-paradigm-pragmatism-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
