INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-10', 'kg-paradigm-pragmatism', 10, '["روش‌های آمیخته (mixed methods)","پژوهش عملی-کاربردی","پژوهش‌های چندمرحله‌ای"]', '4e8ce4ff7022c60c6c1a308bae6eed166d2c9b97b050d20a55c91de4d1a664df', 143, 'kc-kg-paradigm-pragmatism-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4e8ce4ff7022c60c6c1a308bae6eed166d2c9b97b050d20a55c91de4d1a664df', token_count=143, vector_point_id='kc-kg-paradigm-pragmatism-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-11', 'kg-paradigm-pragmatism', 11, '["انعطاف روش‌شناختی","پاسخ‌گویی به پرسش","تقویت اعتبار با ترکیب روش‌ها"]', '029cbef92e08d60f3bbc5c0dac6a37169b90ba4387cc0962023d41caf1b0972c', 130, 'kc-kg-paradigm-pragmatism-11', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='029cbef92e08d60f3bbc5c0dac6a37169b90ba4387cc0962023d41caf1b0972c', token_count=130, vector_point_id='kc-kg-paradigm-pragmatism-11', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-12', 'kg-paradigm-pragmatism', 12, '["ممکن است به‌جای عمق فلسفی، «هر چه کار کند» شود","سخت‌تر است مبانی فلسفی صریحش را دفاع کرد"]', '83ff960b044ac8f703a0ad2c78b7deba922154cb05f9dbac87e5661be8243eba', 169, 'kc-kg-paradigm-pragmatism-12', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='83ff960b044ac8f703a0ad2c78b7deba922154cb05f9dbac87e5661be8243eba', token_count=169, vector_point_id='kc-kg-paradigm-pragmatism-12', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-13', 'kg-paradigm-pragmatism', 13, '["نقد انتقادی: بی‌توجهی به ایدئولوژی","نقد تفسیری: کم‌عمق‌شدن فهم"]', '900d58637ab674f1d5d17848b3f248c7c404cfac17059714a552fb35535b730a', 121, 'kc-kg-paradigm-pragmatism-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='900d58637ab674f1d5d17848b3f248c7c404cfac17059714a552fb35535b730a', token_count=121, vector_point_id='kc-kg-paradigm-pragmatism-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-pragmatism-14', 'kg-paradigm-pragmatism', 14, '["Creswell, J.W. & Plano Clark, V.L. (2018). Designing and Conducting Mixed Methods Research","Dewey, J. (1938). Logic: The Theory of Inquiry","Onwuegbuzie, T.C. & Johnson, R.B. (2006). The Philosophy of Pragmatism"]', '19477d48731f1f00920794a3ba610eea008a480765c01227e4bd7a5ba49067fb', 392, 'kc-kg-paradigm-pragmatism-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='19477d48731f1f00920794a3ba610eea008a480765c01227e4bd7a5ba49067fb', token_count=392, vector_point_id='kc-kg-paradigm-pragmatism-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-realism-0', 'kg-paradigm-realism', 1, 'پارادایم واقع‌گرایی (Realism (Scientific & Critical)) نوع: PARADIGM پارادایمی که واقعیت را مستقل از شناخت انسان می‌داند اما لایه‌های پنهان علّی و ساختاری در آن را به‌عنوان هدف اصلی تبیین می‌شمارد.', '7bcec1958c37fba4bf70ff560d121f8905a6d9c2217fe10de390759a834719e9', 356, 'kc-kg-paradigm-realism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7bcec1958c37fba4bf70ff560d121f8905a6d9c2217fe10de390759a834719e9', token_count=356, vector_point_id='kc-kg-paradigm-realism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-realism-2', 'kg-paradigm-realism', 2, 'واقع‌گرایی (به‌ویژه واقع‌گرایی علمی و واقع‌گرایی انتقادی) بین اثبات‌گرایی و تفسیرگرایی می‌ایستد: واقعیت مستقل از ذهن وجود دارد، اما قابل‌شناخت نیست در سطح ظاهر، بلکه در سطح ساختارهای علّی پنهان. بوریس و هاپتورن، بنیان‌گذاران واقع‌گرایی انتقادی، می‌گویند پژوهش باید از سطح «منابع تجربه» (empirical) عبور کند و به سطح «واقع» (real) و ساختارهای علّی برسد. این پارادایم در علوم ارتباطات کمتر رایج است اما در مطالعات علّی رسانه و تحلیل ساختاری کاربرد دارد.', 'c6995cf3fe01d9e47388d0faacc7b821dbbd1c57b5cd4fc52eac7adf71e462f6', 819, 'kc-kg-paradigm-realism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c6995cf3fe01d9e47388d0faacc7b821dbbd1c57b5cd4fc52eac7adf71e462f6', token_count=819, vector_point_id='kc-kg-paradigm-realism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-realism-3', 'kg-paradigm-realism', 3, 'از فلسفه‌ی واقع‌گرایی علمی (scientific realism) در فیزیک و با کارهای بوریس و هاپتورن (Bhaskar, 1975) در فلسفه‌ی اجتماعی در دهه‌ی ۱۹۷۰ به روش‌شناسی پژوهش اجتماعی راه یافت.', 'ee111ad25b1a988ef823c11c4fb2991f7998ffe923962daa12c221de142959e8', 309, 'kc-kg-paradigm-realism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ee111ad25b1a988ef823c11c4fb2991f7998ffe923962daa12c221de142959e8', token_count=309, vector_point_id='kc-kg-paradigm-realism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-realism-4', 'kg-paradigm-realism', 4, 'هستی‌شناسی: واقعیت، مستقل از شناخت، چندلایه (منابع تجربه، رویدادها، ساختارهای علّی)؛ معرفت‌شناسی: عینی اما محدودشونده به ساختارها؛ روش‌شناسی: ترکیبی، ترجیحاً علّی؛ اخلاقی: تعهد به کشف ساختارهای علّی.', 'abe68076a56ac3435d3336f4a32468b9e03ff2d031a9744923d5ac6a282fb078', 361, 'kc-kg-paradigm-realism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='abe68076a56ac3435d3336f4a32468b9e03ff2d031a9744923d5ac6a282fb078', token_count=361, vector_point_id='kc-kg-paradigm-realism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-paradigm-realism-5', 'kg-paradigm-realism', 5, '["واقعیت، مستقل از ذهن است و ساختارهای علّی پنهان دارد","پژوهش باید از سطح تجربه به سطح ساختار برسد","تبیین علّی (causal explanation) هدف اصلی است","روش‌های کمّی و کیفی هر دو برای درک علل لازم‌اند"]', '99849adf221c7a007b72a60948cf6ded7e246724309d8c3dfd563e8b8cf69db2', 359, 'kc-kg-paradigm-realism-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='99849adf221c7a007b72a60948cf6ded7e246724309d8c3dfd563e8b8cf69db2', token_count=359, vector_point_id='kc-kg-paradigm-realism-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
