INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-quality-confirmability-0', 'kg-quality-confirmability', 1, 'تأییدپذیری (Confirmability) نوع: QUALITY معادل کیفی بی‌طرفی: یافته‌ها محصول داده‌ها، نه پیش‌فرض پژوهشگر.', '9bd1582bfb2535c810e9ad16d186773692a6e12fbcec1b4001825b98c496f3a9', 189, 'kc-kg-quality-confirmability-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9bd1582bfb2535c810e9ad16d186773692a6e12fbcec1b4001825b98c496f3a9', token_count=189, vector_point_id='kc-kg-quality-confirmability-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-quality-confirmability-2', 'kg-quality-confirmability', 2, 'طبق بخش ۱۱ سند (سطر ۴۴۴) «تأییدپذیری (Confirmability)» یکی از ۹ معیار کیفی است؛ با بازاندیشی پژوهشگر، ممیزی و شفافیت تصمیم‌گیری‌ها، بی‌طرفی و وابستگی یافته‌ها به داده‌ها را تأیید می‌کند.', '5803310919638258c2e76127416b9c784932b147cac552e7ef760d0dcbc92197', 338, 'kc-kg-quality-confirmability-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5803310919638258c2e76127416b9c784932b147cac552e7ef760d0dcbc92197', token_count=338, vector_point_id='kc-kg-quality-confirmability-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
