INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-sampling-selection-bias-2', 'kg-sampling-selection-bias', 2, 'سوگیری انتخاب (Selection Bias) خطای سیستماتیک است که در فرایند انتخاب نمونه ایجاد می‌شود و نمایندگی نمونه از جامعه را از بین می‌برد؛ در هر روش نمونه‌گیری (به‌ویژه غیراحتمالی) باید به‌صورت صریح کنترل شود.', 'e63556958945687f3c0e523b74622cad6a3288655dc36b7458180f6069d454de', 369, 'kc-kg-sampling-selection-bias-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e63556958945687f3c0e523b74622cad6a3288655dc36b7458180f6069d454de', token_count=369, vector_point_id='kc-kg-sampling-selection-bias-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
