INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-sampling-simple-random-0', 'kg-sampling-simple-random', 1, 'نمونه‌گیری تصادفی ساده (Simple Random Sampling) نوع: SAMPLING انتخاب تصادفی ساده (SRS): هر نمونه با شانس برابر و مستقل از بقیه.', 'abba54539cadbdc3d85ebe3f9abe77acd66d4a4e77da1c15fc193f4aa13cac66', 230, 'kc-kg-sampling-simple-random-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='abba54539cadbdc3d85ebe3f9abe77acd66d4a4e77da1c15fc193f4aa13cac66', token_count=230, vector_point_id='kc-kg-sampling-simple-random-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-sampling-simple-random-2', 'kg-sampling-simple-random', 2, 'در تصادفی ساده، هر واحد جامعه با احتمال برابر و مستقل از بقیه انتخاب می‌شود (با یا بدون جایگزینی). این ساده‌ترین و رایج‌ترین روش احتمالی است که تعمیم آماری را ممکن می‌سازد.', '528452f22a5dcce63f64f9da7770822602ca80cc0ed3377a7552230a5a292446', 312, 'kc-kg-sampling-simple-random-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='528452f22a5dcce63f64f9da7770822602ca80cc0ed3377a7552230a5a292446', token_count=312, vector_point_id='kc-kg-sampling-simple-random-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
