INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-sampling-theoretical-2', 'kg-sampling-theoretical', 2, 'نمونه‌گیری نظری، بنیادی‌ترین روش نمونه‌گیری در نظریه‌پردازی داده‌بنیاد است: انتخاب واحد‌های جدید بر اساس مفاهیم و فرضیه‌های در حال شکل‌گیری، تا نظریه‌ی در حال شکل‌گیری عمیق‌تر و دقیق‌تر شود.', 'cf1806c71d3914561d76fd0bb96db72a746dab441a7a96e9ac7e6164c744e8b1', 345, 'kc-kg-sampling-theoretical-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cf1806c71d3914561d76fd0bb96db72a746dab441a7a96e9ac7e6164c744e8b1', token_count=345, vector_point_id='kc-kg-sampling-theoretical-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
