INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-actor-network-theory-0', 'kg-subfield-actor-network-theory', 1, 'نظریه کنشگر-شبکه (Actor-Network Theory (ANT)) نوع: SUBFIELD نظریه کنشگر-شبکه (ANT) برونو لاتوُر و مایکل کالنون که انسان‌ها و غیرانسان‌ها را هم‌سطح تحلیل می‌کند.', '5b406fc49b723000cd4bcb429054b727271db0e914ae0cc41a018043b9236760', 290, 'kc-kg-subfield-actor-network-theory-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5b406fc49b723000cd4bcb429054b727271db0e914ae0cc41a018043b9236760', token_count=290, vector_point_id='kc-kg-subfield-actor-network-theory-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-actor-network-theory-2', 'kg-subfield-actor-network-theory', 2, 'ANT بر سه اصل استوار است: (1) «ژنرالیزاسیون» (generalization)، (2) «ترکیب‌بندی» (association) و (3) «تعقیب» (following the actors). در رسانه، الگوریتم‌ها، اپلیکیشن‌ها و داده‌ها هم‌سطح با انسان‌ها در شبکه تحلیل می‌شوند.', 'e759a90a6243148c8ad93749bab8ccf6fb794753a826312f635fec3092f941f1', 396, 'kc-kg-subfield-actor-network-theory-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e759a90a6243148c8ad93749bab8ccf6fb794753a826312f635fec3092f941f1', token_count=396, vector_point_id='kc-kg-subfield-actor-network-theory-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
