INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-advertising-pr-2', 'kg-subfield-advertising-pr', 2, 'این حوزه بر «اثربخشی تبلیغات» (Advertising Effectiveness)، «بازنمایی در تبلیغات» (Representation in Ads)، «اعتماد سازمانی» (Organizational Trust) و «مدیریت روابط» (Relationship Management) تمرکز دارد. از مدل‌های تبلیغات کلاسیک تا تحلیل انتقادی تبلیغات.', '2af2f8daffe317885b18ac95ccd8aacfa048163ef381cbf5866027f8e4224b15', 458, 'kc-kg-subfield-advertising-pr-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2af2f8daffe317885b18ac95ccd8aacfa048163ef381cbf5866027f8e4224b15', token_count=458, vector_point_id='kc-kg-subfield-advertising-pr-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
