INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-crisis-comm-2', 'kg-subfield-crisis-comm', 2, 'این حوزه بر «مدیریت ارتباطات بحران» (Crisis Communication Management)، «اعتماد» (Trust)، «ارتباطات ریسک» (Risk Communication) و «بحران عمومی» (Public Crisis) تمرکز دارد. از مدل‌های کلاسیک مدیریت بحران (Coombs) تا تحلیل الگوریتمی بحران.', 'ae3c9a9e954a6f5f207a1314140c24578061be2312a170c0c896592503b9e6ff', 427, 'kc-kg-subfield-crisis-comm-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ae3c9a9e954a6f5f207a1314140c24578061be2312a170c0c896592503b9e6ff', token_count=427, vector_point_id='kc-kg-subfield-crisis-comm-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
