INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-development-comm-2', 'kg-subfield-development-comm', 2, 'این حوزه بر «ارتباطات توسعه‌ای» (Development Communication)، «توانمندسازی» (Empowerment)، «مشارکت» (Participation) و «تغییر رفتار» (Behavior Change) تمرکز دارد. از مدل‌های کلاسیک ارتباطات توسعه (Rogers) تا نقد پسااستعماری.', '76207cdb13b26dec77111a8abdb8dde1b573637781972b4ba037f99148718360', 403, 'kc-kg-subfield-development-comm-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='76207cdb13b26dec77111a8abdb8dde1b573637781972b4ba037f99148718360', token_count=403, vector_point_id='kc-kg-subfield-development-comm-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
