INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-digital-games-2', 'kg-subfield-digital-games', 2, 'این حوزه بر «روایت تعاملی» (Interactive Narrative)، «بازی‌سازی» (Game Design)، «اقتصاد بازی» (Game Economy) و «هویت بازیکن» تمرکز دارد. از نظریه‌های روایت‌شناسی تا تحلیل «بازی به‌عنوان متن» (Game as Text).', 'b1b48e71339a15c6afd385b9221ade1a38029fc47a997c08cdc79b744ee8d4aa', 372, 'kc-kg-subfield-digital-games-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b1b48e71339a15c6afd385b9221ade1a38029fc47a997c08cdc79b744ee8d4aa', token_count=372, vector_point_id='kc-kg-subfield-digital-games-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
