INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-digital-media-0', 'kg-subfield-digital-media', 1, 'نظریه‌های رسانه‌های دیجیتال (Digital Media Theories) نوع: SUBFIELD نظریه‌هایی که ویژگی‌های رسانه‌های دیجیتال، پلتفرمی، الگوریتمی و شبکه‌ای را تبیین می‌کنند.', 'efa704dc09145a63caa6acf50d4faa979ef7dd5e7800e2dc56ffbed6a35726b5', 283, 'kc-kg-subfield-digital-media-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='efa704dc09145a63caa6acf50d4faa979ef7dd5e7800e2dc56ffbed6a35726b5', token_count=283, vector_point_id='kc-kg-subfield-digital-media-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
