INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-film-tv-2', 'kg-subfield-film-tv', 2, 'این حوزه بر «تحلیل روایت» (Narratology)، «ژانر» (Genre)، «بازنمایی» (Representation) و «تحلیل بصری» (Visual Analysis) تمرکز دارد؛ از نظریه‌های ساختارگرای سینما تا تحلیل نشانه‌شناختی (Metz, Kraco) و تحلیل بصری (Bal, Sturrock).', '474c3a2f48d4b6f16dc8b3f4aaa8854438bcd728132ce5368febe8901c423096', 409, 'kc-kg-subfield-film-tv-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='474c3a2f48d4b6f16dc8b3f4aaa8854438bcd728132ce5368febe8901c423096', token_count=409, vector_point_id='kc-kg-subfield-film-tv-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
