INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-journalism-2', 'kg-subfield-journalism', 2, 'این حوزه بر تحلیل «نقش خبر»، «مالکیت رسانه»، «کارکرد مطبوعات» (Lippmann, Lee), «روایت‌های خبری» (framing, agenda-setting) و «خبر در عصر دیجیتال» (convergence journalism) تمرکز دارد.', '614e3c0ad2fe4207291debd53d47ce07281f3c70687045bf24121917a43a83c0', 329, 'kc-kg-subfield-journalism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='614e3c0ad2fe4207291debd53d47ce07281f3c70687045bf24121917a43a83c0', token_count=329, vector_point_id='kc-kg-subfield-journalism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
