INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-media-effects-0', 'kg-subfield-media-effects', 1, 'نظریه‌های اثرات رسانه (Media Effects Theories) نوع: SUBFIELD مجموعه‌ای از نظریه‌ها که به بررسی اثرات پیام‌های رسانه‌ای بر نگرش، شناخت، نگرش و رفتار مخاطبان می‌پردازند.', '45c12f6a98e69648863643ecb49d35c458a6c4797914e522bb86be940ba837e5', 303, 'kc-kg-subfield-media-effects-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='45c12f6a98e69648863643ecb49d35c458a6c4797914e522bb86be940ba837e5', token_count=303, vector_point_id='kc-kg-subfield-media-effects-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-media-effects-2', 'kg-subfield-media-effects', 2, 'این حوزه به پرسش «رسانه چه می‌کند با مخاطب؟» پاسخ می‌دهد؛ از مدل خطی اثرات قوی (گلوله جادویی) در دهه‌ی ۱۹۲۰-۱۹۴۰، از راه پژوهش‌های کلمبیا و پیمایشی، تا نظریه‌های اثرات میانه و بلندمدت مانند برجسته‌سازی، چارچوب‌سازی، کاشت و وابستگی که در دهه‌های ۱۹۶۰-۱۹۹۰ شکل گرفتند.', 'c4f9ec2e09044fae1cff5ade48c38896e9e251633d82706488b6580bb9c96f43', 483, 'kc-kg-subfield-media-effects-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c4f9ec2e09044fae1cff5ade48c38896e9e251633d82706488b6580bb9c96f43', token_count=483, vector_point_id='kc-kg-subfield-media-effects-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
