INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-media-literacy-2', 'kg-subfield-media-literacy', 2, 'این حوزه بر «درک رسانه» (Media Understanding)، «تحلیل انتقادی» (Critical Analysis)، «تولید رسانه‌ای» (Media Production) و «سواد دیجیتال» (Digital Literacy) تمرکز دارد. از سواد رسانه‌ای کلاسیک تا سواد الگوریتمی.', '4a8e0c85c80a955af33321aeaeba8f3bf3531253cbd906eaa1f4c72e1aa021a7', 381, 'kc-kg-subfield-media-literacy-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4a8e0c85c80a955af33321aeaeba8f3bf3531253cbd906eaa1f4c72e1aa021a7', token_count=381, vector_point_id='kc-kg-subfield-media-literacy-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
