INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-media-ownership-economics-0', 'kg-subfield-media-ownership-economics', 1, 'مطالعات مالکیت و اقتصاد رسانه (Media Ownership & Economics Studies) نوع: SUBFIELD حوزه‌ی تخصصی مطالعات رسانه: مطالعات مالکیت و اقتصاد رسانه', '50d998cbf157b5eef19ffc45fef834a654638ed5abde604df704289d2489e27d', 252, 'kc-kg-subfield-media-ownership-economics-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='50d998cbf157b5eef19ffc45fef834a654638ed5abde604df704289d2489e27d', token_count=252, vector_point_id='kc-kg-subfield-media-ownership-economics-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-media-ownership-economics-2', 'kg-subfield-media-ownership-economics', 2, 'این حوزه بر «تمرکز مالکیت» (Ownership Concentration)، «اقتصاد رسانه» (Media Economics)، «سرمایه‌داری رسانه‌ای» (Media Capitalism) و «اقتصاد دیجیتال» تمرکز دارد. از نظریه‌های کلاسیک اقتصاد رسانه تا تحلیل انتقادی اقتصاد پلتفرم.', 'fa960b1e5cd7001af0863fdcb76e58106d9b141c29880d107e97148f73846660', 409, 'kc-kg-subfield-media-ownership-economics-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fa960b1e5cd7001af0863fdcb76e58106d9b141c29880d107e97148f73846660', token_count=409, vector_point_id='kc-kg-subfield-media-ownership-economics-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
