INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-networked-society-0', 'kg-subfield-networked-society', 1, 'جامعه شبکه‌ای (Networked Society) نوع: SUBFIELD حوزه‌ی تخصصی مانوئل کاستلز (1996) که شبکه را ساختار بنیادین جامعه معاصر می‌داند.', '5c3de1c5c3a0c9521f99203cf6604d39dbea80c9727a84e13474aeb5e2ad1fc1', 232, 'kc-kg-subfield-networked-society-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5c3de1c5c3a0c9521f99203cf6604d39dbea80c9727a84e13474aeb5e2ad1fc1', token_count=232, vector_point_id='kc-kg-subfield-networked-society-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-networked-society-2', 'kg-subfield-networked-society', 2, 'کاستلز «جامعه شبکه‌ای» را با سه ویژگی می‌شناسد: (1) شبکه‌سازی به‌عنوان شکل بنیادین سازمان‌دهی، (2) الکترونیک‌شدن اطلاعات و (3) جداسازی مکان و زمان. در رسانه، الگوریتم‌ها، پلتفرم‌ها و رسانه‌های اجتماعی نمونه‌های بارز شبکه‌های جامعه‌ای کاستلز هستند.', 'fb330cbd861efa8581fb1e124876338ef7a40465e4774f7d207260dd9c2e129a', 449, 'kc-kg-subfield-networked-society-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fb330cbd861efa8581fb1e124876338ef7a40465e4774f7d207260dd9c2e129a', token_count=449, vector_point_id='kc-kg-subfield-networked-society-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-networked-society-3', 'kg-subfield-networked-society', 3, 'نظریه شبکه و جامعه‌شناسی.', 'ee969c39804463e9c505b3962d77809449e6bc44522c7f1d991a84e3e8ce6ae0', 45, 'kc-kg-subfield-networked-society-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ee969c39804463e9c505b3962d77809449e6bc44522c7f1d991a84e3e8ce6ae0', token_count=45, vector_point_id='kc-kg-subfield-networked-society-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-networked-society-4', 'kg-subfield-networked-society', 4, '["شبکه ساختار بنیادین جامعه معاصر است","جداسازی مکان و زمان ویژگی کلیدی شبکه‌ای است"]', '7fd1b83eb92213841754c0043b1bc0f5fa4e2e341df6ff45b4db01f2912eeb36', 154, 'kc-kg-subfield-networked-society-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7fd1b83eb92213841754c0043b1bc0f5fa4e2e341df6ff45b4db01f2912eeb36', token_count=154, vector_point_id='kc-kg-subfield-networked-society-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
