INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-platform-studies-2', 'kg-subfield-platform-studies', 2, 'این حوزه بر «پلتفرم‌سازی» (Platformization)، «معماری پلتفرم» (Platform Architecture)، «اقتصاد پلتفرم» (Platform Economy) و «حکمرانی پلتفرم» (Platform Governance) تمرکز دارد. نیکوسیوس و لافور (2017) و لوفون و بوس (2018) از بنیان‌گذاران این حوزه‌اند.', '56fc98f50d6dbd6f387799559b3b6031bb4766bf5171121623fba2f3b553423f', 450, 'kc-kg-subfield-platform-studies-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='56fc98f50d6dbd6f387799559b3b6031bb4766bf5171121623fba2f3b553423f', token_count=450, vector_point_id='kc-kg-subfield-platform-studies-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
