INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-political-0', 'kg-subfield-political', 1, 'نظریه‌های ارتباطات سیاسی (Political Communication Theories) نوع: SUBFIELD نظریه‌هایی که نقش رسانه و پیام در فرآیندهای سیاسی، رأی‌آوری و مشارکت مدنی را تبیین می‌کنند.', '5f4023c595e2f85c6858832c724be55880380e1a777fcc0d9ef8bb5418f16f36', 300, 'kc-kg-subfield-political-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5f4023c595e2f85c6858832c724be55880380e1a777fcc0d9ef8bb5418f16f36', token_count=300, vector_point_id='kc-kg-subfield-political-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
