INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-social-media-2', 'kg-subfield-social-media', 2, 'این حوزه بر «مشارکت مخاطب»، «انتشار اطلاعات»، «الگوریتم‌های پیشنهادی»، «هویت دیجیتال» و «اقتصاد توجه» تمرکز دارد. الگوریتم‌ها، داده‌ها و تعاملات شبکه‌ای ابزار اصلی این حوزه‌اند.', 'ecb7d4ff83c32f8358e6b64502578b9768c52c5d548500e8a0333b3d79de0f49', 321, 'kc-kg-subfield-social-media-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ecb7d4ff83c32f8358e6b64502578b9768c52c5d548500e8a0333b3d79de0f49', token_count=321, vector_point_id='kc-kg-subfield-social-media-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
