INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-social-networks-0', 'kg-subfield-social-networks', 1, 'شبکه‌های اجتماعی (Social Networks) نوع: SUBFIELD حوزه‌ی تخصصی تحلیل شبکه‌های اجتماعی (SNA) به‌عنوان ساختارهای روابط بین اشخاص و گروه‌ها.', 'b03c28465467034a3aac380cf2bb213ae416247b4dab339b9317548141392e55', 247, 'kc-kg-subfield-social-networks-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b03c28465467034a3aac380cf2bb213ae416247b4dab339b9317548141392e55', token_count=247, vector_point_id='kc-kg-subfield-social-networks-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-social-networks-2', 'kg-subfield-social-networks', 2, 'SNA (Wasserman & Faust, Freeman, Burt) روابط بین گره‌ها را با شاخص‌هایی مانند «مرکزیت» (centrality)، «شکل» (structure) و «جریان» (flow) تحلیل می‌کند. در رسانه، تحلیل شبکه‌های اجتماعی ابزار اصلی فهم انتشار اطلاعات و نفوذ است.', '88fdcb027bc0db5c8cc5182af4837aa08796df7e25a0acc3dac060d580047850', 407, 'kc-kg-subfield-social-networks-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='88fdcb027bc0db5c8cc5182af4837aa08796df7e25a0acc3dac060d580047850', token_count=407, vector_point_id='kc-kg-subfield-social-networks-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
