INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-society-media-2', 'kg-subfield-society-media', 2, 'از تحلیل جامعه توده‌ای و هژمونی فرهنگی در سنت انتقادی تا نظریه‌های جامعه اطلاعاتی و شبکه‌ای، این حوزه رسانه را در بستر اقتصاد، سیاست و فرهنگ کلان می‌بیند.', '12ca00a05de2e7d17ef6a0eeca0594309336dd164cfe200202c850d28a53dee3', 280, 'kc-kg-subfield-society-media-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='12ca00a05de2e7d17ef6a0eeca0594309336dd164cfe200202c850d28a53dee3', token_count=280, vector_point_id='kc-kg-subfield-society-media-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
