INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-sociology-of-science-0', 'kg-subfield-sociology-of-science', 1, 'جامعه‌شناسی علم (Sociology of Scientific Knowledge (SSK)) نوع: SUBFIELD حوزه‌ی تخصصی STS که ساختارهای اجتماعی علم (مؤسسه، نخبگی، جریان) را تحلیل می‌کند.', '80847f94db8f8e57066d0927fdc3c3c23d7c84f20eb6ed2475fa8467a7fd4b00', 276, 'kc-kg-subfield-sociology-of-science-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='80847f94db8f8e57066d0927fdc3c3c23d7c84f20eb6ed2475fa8467a7fd4b00', token_count=276, vector_point_id='kc-kg-subfield-sociology-of-science-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-subfield-sociology-of-science-2', 'kg-subfield-sociology-of-science', 2, 'SSK (Barnes, Mulkay, Bloor، «برنامه‌ی ادینبرو») نشان می‌دهد «واقعیت علمی» از طریق مذاکره اجتماعی و «قوه‌ی اعتبار» (social accountability) ساخته می‌شود. در رسانه، تحلیل تولید علم و رسانه در عصر هوش مصنوعی نمونه‌های معاصر این حوزه‌اند.', 'ea443f2eff76f0e67d0012eca366dd9786c1cfd64c4f5df8cc5a0dd2bbe778a0', 423, 'kc-kg-subfield-sociology-of-science-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ea443f2eff76f0e67d0012eca366dd9786c1cfd64c4f5df8cc5a0dd2bbe778a0', token_count=423, vector_point_id='kc-kg-subfield-sociology-of-science-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
