INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-technique-structured-interview-2', 'kg-technique-structured-interview', 2, 'در مصاحبه‌ی ساختاریافته فهرست سؤالات، ترتیب و کدگزارش‌ها از پیش مشخص است؛ عملاً پرسشنامه‌ای شفاهی که امکان مقایسه‌ی آماری داده‌ها را فراهم می‌کند و در طرح‌های آزمایشی و پیمایشی کاربرد دارد.', 'cd7e06ed0a07197d6e85b78ce07d69e38bfdfb47189adfea9c3dfb5df3b6634e', 343, 'kc-kg-technique-structured-interview-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cd7e06ed0a07197d6e85b78ce07d69e38bfdfb47189adfea9c3dfb5df3b6634e', token_count=343, vector_point_id='kc-kg-technique-structured-interview-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-technique-structured-interview-3', 'kg-technique-structured-interview', 3, '["سؤالات و ترتیب آن‌ها برای همه‌ی مشارکت‌کنندگان یکسان است","داده‌ها قابل کدگذاری یکپارچه و تحلیل کمّی‌اند"]', 'd0cd022423128065daa07e80ce498896d8c1e7d73be7347bdfae4f2fd5a85991', 196, 'kc-kg-technique-structured-interview-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d0cd022423128065daa07e80ce498896d8c1e7d73be7347bdfae4f2fd5a85991', token_count=196, vector_point_id='kc-kg-technique-structured-interview-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
