INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-technique-web-scraping-2', 'kg-technique-web-scraping', 2, 'استخراج داده از وب (Web Scraping) با استفاده از کد و ابزارهای خودکار، داده را از صفحات وب استخراج می‌کند؛ برای پژوهش‌های کمّی بزرگ و محاسباتی کاربرد دارد.', '6eacc5550a02ca247a7320f605d4e9654c23a61b0f307efe3fd3ab0e70db6673', 280, 'kc-kg-technique-web-scraping-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6eacc5550a02ca247a7320f605d4e9654c23a61b0f307efe3fd3ab0e70db6673', token_count=280, vector_point_id='kc-kg-technique-web-scraping-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
