INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-active-audience-0', 'kg-theory-active-audience', 1, 'نظریه مخاطب فعال (Active Audience Theory) نوع: THEORY نظریه‌ای که مخاطب را فعال، تفسیرکننده و منتقد می‌داند و با مدل‌های منفعل مخاطب در تضاد است.', '64145047593ad3fa7b9d19ef69d3b6355e03ac533f4f8d1f152ccc7f0a6529b6', 263, 'kc-kg-theory-active-audience-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='64145047593ad3fa7b9d19ef69d3b6355e03ac533f4f8d1f152ccc7f0a6529b6', token_count=263, vector_point_id='kc-kg-theory-active-audience-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-active-audience-2', 'kg-theory-active-audience', 2, 'این نظریه (که بیشتر به‌عنوان سنت و رویکرد در مطالعات فرهنگی و دریافت شناخته می‌شود) می‌گوید مخاطب صرفاً مصرف‌کننده نیست، بلکه فعالانه با پیام رسانه‌ای تعامل دارد، معنای خود را می‌سازد و در صورت نیاز مقاومت می‌کند.', '5d316407b60bbb7abea773a972c986ad6a0ecbe02c97af732ee6d965432e3fc4', 387, 'kc-kg-theory-active-audience-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5d316407b60bbb7abea773a972c986ad6a0ecbe02c97af732ee6d965432e3fc4', token_count=387, vector_point_id='kc-kg-theory-active-audience-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-active-audience-3', 'kg-theory-active-audience', 3, '["مخاطب فعال و تفسیرکننده است","معنا در تعامل مخاطب با پیام ساخته می‌شود","مخاطب می‌تواند پیام را مقاومت کند"]', '392e7de2791854668ba38a347a2bc1213a00b23f83cf3ac997d3ce80632368ed', 199, 'kc-kg-theory-active-audience-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='392e7de2791854668ba38a347a2bc1213a00b23f83cf3ac997d3ce80632368ed', token_count=199, vector_point_id='kc-kg-theory-active-audience-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
