INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-agenda-setting-0', 'kg-theory-agenda-setting', 1, 'نظریه برجسته‌سازی (Agenda-Setting Theory) نوع: THEORY نظریه‌ای که می‌گوید رسانه نمی‌گوید «به چه چیزی فکر کنیم» بلکه «به چه چیزی فکر کنیم» را تعیین می‌کند.', '8c79d707113774fdaf22c3265076be1e33711039814662cc500439d5044f555d', 280, 'kc-kg-theory-agenda-setting-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8c79d707113774fdaf22c3265076be1e33711039814662cc500439d5044f555d', token_count=280, vector_point_id='kc-kg-theory-agenda-setting-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-agenda-setting-2', 'kg-theory-agenda-setting', 2, 'McCombs و Shaw در مطالعه‌ی کلب City (1972) نشان دادند درجه‌ی برجستگی موضوعی در رسانه با درجه‌ی اهمیت آن در ذهن مخاطبان همبستگی دارد. شکل‌های بعدی (اتصال اجسام، بین‌فرهنگی، اجتماعی) این نظریه را گسترش دادند.', '5f53b926bb9e8654cfcc101d9cfa874a35f6ab45f7d74a2e20faba5f508bc423', 374, 'kc-kg-theory-agenda-setting-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5f53b926bb9e8654cfcc101d9cfa874a35f6ab45f7d74a2e20faba5f508bc423', token_count=374, vector_point_id='kc-kg-theory-agenda-setting-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-agenda-setting-3', 'kg-theory-agenda-setting', 3, '["برجستگی موضوعی در رسانه اهمیت ذهنی آن را در مخاطب بالا می‌برد","رسانه اولویت‌بندی اجندای ذهنی مخاطب را شکل می‌دهد","اگر موضوعی کمتر پوشش داده شود، کمتر در ذهن مخاطب مهم است"]', 'b49a40004dd782be412f24c73ed74db5ce91542be3b81b0837321b204d1f42d4', 320, 'kc-kg-theory-agenda-setting-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b49a40004dd782be412f24c73ed74db5ce91542be3b81b0837321b204d1f42d4', token_count=320, vector_point_id='kc-kg-theory-agenda-setting-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-agenda-setting-4', 'kg-theory-agenda-setting', 4, '["Maxwell McCombs","Donald Shaw"]', '8ce37f05eb1af4c523e00bb7f35a310a7195e5d591cafa6a8edc26de84216042', 59, 'kc-kg-theory-agenda-setting-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8ce37f05eb1af4c523e00bb7f35a310a7195e5d591cafa6a8edc26de84216042', token_count=59, vector_point_id='kc-kg-theory-agenda-setting-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
