INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-agenda-setting-7', 'kg-theory-agenda-setting', 7, '["McCombs & Shaw, 1972 - The Agenda Setting Function of Mass Media"]', 'ad35bc64dbe1da1e3183f4393c62e9415a7a8168a1dc393b66ffbc6334b0db85', 123, 'kc-kg-theory-agenda-setting-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ad35bc64dbe1da1e3183f4393c62e9415a7a8168a1dc393b66ffbc6334b0db85', token_count=123, vector_point_id='kc-kg-theory-agenda-setting-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-algorithmic-agency-0', 'kg-theory-algorithmic-agency', 1, 'نظریه عاملیت الگوریتمی (Algorithmic Agency Theory) نوع: THEORY نظریه‌ای که «عاملیت الگوریتمی» (algorithmic agency) را در عصر دیجیتال تبیین می‌کند.', '8a4ec39b6aaea4186f0d2bbb5c7c8599b1f444a45560b0412e9d218481a2869f', 265, 'kc-kg-theory-algorithmic-agency-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8a4ec39b6aaea4186f0d2bbb5c7c8599b1f444a45560b0412e9d218481a2869f', token_count=265, vector_point_id='kc-kg-theory-algorithmic-agency-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-algorithmic-agency-2', 'kg-theory-algorithmic-agency', 2, 'Couldry و Hepp (2017) و همکاران (Zuboff) عاملیت الگوریتمی را به‌عنوان پدیده‌ای توصیف کردند که در آن الگوریتم‌ها به‌عنوان «عامل» (agent) در تولید، توزیع و شخصی‌سازی محتوا عمل می‌کنند و این عاملیت، ساختار قدرت رسانه‌ای را دگرگون می‌کند.', '21c184c9bc86d57d2e55436fd5f40b0b7d7ee6de6b9088380f094beefa8b7cb0', 425, 'kc-kg-theory-algorithmic-agency-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='21c184c9bc86d57d2e55436fd5f40b0b7d7ee6de6b9088380f094beefa8b7cb0', token_count=425, vector_point_id='kc-kg-theory-algorithmic-agency-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-algorithmic-agency-3', 'kg-theory-algorithmic-agency', 3, '["الگوریتم‌ها، عاملیت مستقل در تولید و توزیع محتوا دارند","عاملیت الگوریتمی، ساختار قدرت رسانه‌ای را دگرگون می‌کند","الگوریتم‌ها، قواعد بازی شبکه‌ای را تعیین می‌کنند"]', '1ff56c0ce61c83040bdfa259f0491479b6b7062d07e0644bda9b679d3ace2870', 303, 'kc-kg-theory-algorithmic-agency-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1ff56c0ce61c83040bdfa259f0491479b6b7062d07e0644bda9b679d3ace2870', token_count=303, vector_point_id='kc-kg-theory-algorithmic-agency-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
