INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-algorithmic-agency-7', 'kg-theory-algorithmic-agency', 7, '["Zuboff, 2019 - The Age of Surveillance Capitalism","Couldry & Hepp, 2017 - The Platformization of Cultural Industry"]', 'e7c5a2129ce90d16adefd8431eb51977cbcaf3d9f1a6a03c6a3503993ed8d068', 216, 'kc-kg-theory-algorithmic-agency-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e7c5a2129ce90d16adefd8431eb51977cbcaf3d9f1a6a03c6a3503993ed8d068', token_count=216, vector_point_id='kc-kg-theory-algorithmic-agency-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-attention-economy-0', 'kg-theory-attention-economy', 1, 'نظریه اقتصاد توجه (Attention Economy Theory) نوع: THEORY نظریه‌ای که «اقتصاد توجه» (attention economy) را در عصر دیجیتال تبیین می‌کند.', '9c2ce81375f692fc088854b6ddfc9dc321e602ae9a16a83c5e455bbb4ac1c245', 243, 'kc-kg-theory-attention-economy-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9c2ce81375f692fc088854b6ddfc9dc321e602ae9a16a83c5e455bbb4ac1c245', token_count=243, vector_point_id='kc-kg-theory-attention-economy-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-attention-economy-2', 'kg-theory-attention-economy', 2, 'Davenport و Beck (1999) و همکاران (Goldberg) اقتصاد توجه را به‌عنوان اقتصادیتی توصیف کردند که در آن «توجه» مخاطبان به‌عنوان منبع کمیاب، کالایی می‌شود که رسانه‌ها و پلتفرم‌ها آن را جمع‌آوری، تبدیل و به تبلیغ‌دهندگان می‌فروشند.', '7078a4937a001c57fb69736a0536b24112d511d33f19d4e451d17fb30b8067d3', 409, 'kc-kg-theory-attention-economy-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7078a4937a001c57fb69736a0536b24112d511d33f19d4e451d17fb30b8067d3', token_count=409, vector_point_id='kc-kg-theory-attention-economy-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-attention-economy-3', 'kg-theory-attention-economy', 3, '["توجه مخاطب، کالای کمیاب و ارزشمندی است","رسانه‌ها و پلتفرم‌ها، توجه را جمع‌آوری و می‌فروشند","اقتصاد توجه، ساختار درآمدی رسانه‌های دیجیتال را شکل می‌دهد"]', 'c8191e5d0a6f3c26fac55a50e263ec49c98e9166c72687108f7fc59e8a0cf417', 283, 'kc-kg-theory-attention-economy-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c8191e5d0a6f3c26fac55a50e263ec49c98e9166c72687108f7fc59e8a0cf417', token_count=283, vector_point_id='kc-kg-theory-attention-economy-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-attention-economy-4', 'kg-theory-attention-economy', 4, '["Davenport","John Beck","T. R. O''Reilly"]', 'e176681342a4e2e7f3f98b7f311a0908671ce5ba11f58c5d8d2ad5bd35f9bd02', 76, 'kc-kg-theory-attention-economy-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e176681342a4e2e7f3f98b7f311a0908671ce5ba11f58c5d8d2ad5bd35f9bd02', token_count=76, vector_point_id='kc-kg-theory-attention-economy-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
