INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-audience-participation-0', 'kg-theory-audience-participation', 1, 'نظریه مشارکت مخاطب (Audience Participation Theory) نوع: THEORY نظریه‌ای که مشارکت فعال مخاطب در تولید و انتشار محتوا (به‌ویژه در رسانه‌های دیجیتال) را تبیین می‌کند.', '3510dfd07d9ffd62558d7a6694458860182890655e263eb9f2e894065839a2db', 298, 'kc-kg-theory-audience-participation-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3510dfd07d9ffd62558d7a6694458860182890655e263eb9f2e894065839a2db', token_count=298, vector_point_id='kc-kg-theory-audience-participation-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-audience-participation-2', 'kg-theory-audience-participation', 2, 'با ظهور رسانه‌های دیجیتال و وب ۲.۰، این نظریه (که بیشتر در مطالعات فرهنگ مشارکتی Jenkins و مطالعات مخاطب دیجیتال استفاده می‌شود) به نقش مخاطب به‌عنوان هم‌تولیدکننده محتوا می‌پردازد.', 'd0ec1bda29f04cd71c42f890928f99a2f2efa6242c7fd31e41436bf0165d554b', 329, 'kc-kg-theory-audience-participation-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d0ec1bda29f04cd71c42f890928f99a2f2efa6242c7fd31e41436bf0165d554b', token_count=329, vector_point_id='kc-kg-theory-audience-participation-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-audience-participation-3', 'kg-theory-audience-participation', 3, '["مخاطب صرفاً مصرف‌کننده نیست، بلکه هم‌تولیدکننده محتوا است","مشارکت، شکل پیشرفته‌ی فعال‌کنندگی مخاطب است","رسانه‌های دیجیتال مشارکت مخاطب را تسهیل می‌کنند"]', '53af911db257b26565943380a484f02e3ed68d57f542b7665825ea00b038e075', 285, 'kc-kg-theory-audience-participation-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='53af911db257b26565943380a484f02e3ed68d57f542b7665825ea00b038e075', token_count=285, vector_point_id='kc-kg-theory-audience-participation-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-audience-participation-4', 'kg-theory-audience-participation', 4, '["Henry Jenkins","Danaher Boyd"]', '8080de0360eee011986cf6a31f1e33dba24f6fd3f358416f163602b4461f17d0', 58, 'kc-kg-theory-audience-participation-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8080de0360eee011986cf6a31f1e33dba24f6fd3f358416f163602b4461f17d0', token_count=58, vector_point_id='kc-kg-theory-audience-participation-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
