INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-choice-architecture-0', 'kg-theory-choice-architecture', 1, 'نظریه معماری انتخاب (Choice Architecture Theory) نوع: THEORY نظریه‌ای که «معماری انتخاب» (choice architecture) را در طراحی رابط و تجربه کاربر تبیین می‌کند.', '0183eef636d62ffa34c7557f637d8f5d38be8074e301a250bc9e87d1c51b678f', 281, 'kc-kg-theory-choice-architecture-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0183eef636d62ffa34c7557f637d8f5d38be8074e301a250bc9e87d1c51b678f', token_count=281, vector_point_id='kc-kg-theory-choice-architecture-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-choice-architecture-2', 'kg-theory-choice-architecture', 2, 'Thaler و Sunstein (2008) و همکاران (نورس) معماری انتخاب را به‌عنوان فرآیندی توصیف کردند که در آن طراحان رابط (UI/UX) با طراحی عناصر بصری، ترتیب و فرآیندها، انتخاب‌های کاربر را «هسته» (nudge) می‌کنند و این معماری، رفتار کاربران را شکل می‌دهد.', 'a9b3077a9313c7259d8663c0fccbe85d7df19a62a0e1f22cb87fc7632773227c', 438, 'kc-kg-theory-choice-architecture-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a9b3077a9313c7259d8663c0fccbe85d7df19a62a0e1f22cb87fc7632773227c', token_count=438, vector_point_id='kc-kg-theory-choice-architecture-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-choice-architecture-3', 'kg-theory-choice-architecture', 3, '["طراحان رابط، انتخاب‌های کاربر را با طراحی عناصر بصری و ترتیب، «هسته» می‌کنند","معماری انتخاب، رفتار کاربران را شکل می‌دهد","نورد (nudge)، فرآیند غیرمستقیم و هدفمند است"]', 'ae961ee875409419b0fc45cddd9b8b59b79bfd9670828454b56076d655ca3b7a', 310, 'kc-kg-theory-choice-architecture-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ae961ee875409419b0fc45cddd9b8b59b79bfd9670828454b56076d655ca3b7a', token_count=310, vector_point_id='kc-kg-theory-choice-architecture-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
