INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-choice-architecture-7', 'kg-theory-choice-architecture', 7, '["Thaler & Sunstein, 2008 - Nudge: Improving Decisions About Health, Wealth, and Happiness"]', '43f5d0af2a6cf7723144a69ffb7a5913679f5f025808c76549984a574cff7e59', 167, 'kc-kg-theory-choice-architecture-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='43f5d0af2a6cf7723144a69ffb7a5913679f5f025808c76549984a574cff7e59', token_count=167, vector_point_id='kc-kg-theory-choice-architecture-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-communication-management-0', 'kg-theory-communication-management', 1, 'نظریه مدیریت ارتباطات (Communication Management Theory) نوع: THEORY نظریه‌ای که فرآیند «مدیریت» ارتباطات در روابط بین‌فردی و سازمانی را تبیین می‌کند.', 'ea27c35e6b278049413830412000a2a914fe4ee824dcdb511e575810644c5762', 270, 'kc-kg-theory-communication-management-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ea27c35e6b278049413830412000a2a914fe4ee824dcdb511e575810644c5762', token_count=270, vector_point_id='kc-kg-theory-communication-management-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-communication-management-2', 'kg-theory-communication-management', 2, 'Grunig و همکاران (و در حوزه‌ی ارتباطات بین‌فردی، McQuail) پیشنهاد کردند مدیریت ارتباطات فرآیند برنامه‌ریزی، اجرا و ارزیابی ارتباطات است و در روابط بین‌فردی، مدیریت ارتباطات به معنای تنظیم پیام‌ها و واکنش‌ها برای حفظ کیفیت رابطه است.', '90f2ab511358c92a523d7f9159a8ed3aa8ff2408ba782f1b0d5832cec6e78a55', 421, 'kc-kg-theory-communication-management-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='90f2ab511358c92a523d7f9159a8ed3aa8ff2408ba782f1b0d5832cec6e78a55', token_count=421, vector_point_id='kc-kg-theory-communication-management-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-communication-management-3', 'kg-theory-communication-management', 3, '["مدیریت ارتباطات، فرآیند برنامه‌ریزی و ارزیابی ارتباطات است","در روابط بین‌فردی، مدیریت ارتباطات به حفظ کیفیت رابطه کمک می‌کند","مدیریت ارتباطات، فرآیند فعال و هدفمند است"]', '2fd4757156b0236bdfb7b94c2d232a6200f523a96f0c761514ea870cd831b678', 314, 'kc-kg-theory-communication-management-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2fd4757156b0236bdfb7b94c2d232a6200f523a96f0c761514ea870cd831b678', token_count=314, vector_point_id='kc-kg-theory-communication-management-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
