INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-cultivation-0', 'kg-theory-cultivation', 1, 'نظریه کاشت (Cultivation Theory) نوع: THEORY نظریه‌ای که اثرات تدریجی و بلندمدت تماشای تلویزیون بر دیدگاه و نگرش‌های مخاطب را تبیین می‌کند.', '4c43392c704aa2985ab88c077e9c7e255ba1700065ce50cb3f960b754e33a54b', 250, 'kc-kg-theory-cultivation-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c43392c704aa2985ab88c077e9c7e255ba1700065ce50cb3f960b754e33a54b', token_count=250, vector_point_id='kc-kg-theory-cultivation-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-cultivation-2', 'kg-theory-cultivation', 2, 'Gerbner و همکاران در دهه‌ی ۱۹۶۰-۱۹۷۰ نشان دادند تماشای مداوم و زیاد تلویزیون، نگرش‌های مخاطب را در طول زمان «کاشته» و دگرگون می‌کند؛ مثلاً باور به «جهان خشن» از سوی تماشای زیاد خشونت تلویزیونی.', 'dca21a1071b98b3d92a4ad271cba54a7108621f3d2b9ddfc7bd6345d0f538497', 350, 'kc-kg-theory-cultivation-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dca21a1071b98b3d92a4ad271cba54a7108621f3d2b9ddfc7bd6345d0f538497', token_count=350, vector_point_id='kc-kg-theory-cultivation-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-cultivation-3', 'kg-theory-cultivation', 3, '["تماشای طولانی‌مدت تلویزیون نگرش‌های مخاطب را تدریجاً دگرگون می‌کند","تماشاکنندگان زیاد و کم، جهان را متفاوت می‌بینند","اثر کاشت یک فرآیند تدریجی و بلندمدت است"]', '0903218cb42eb8278ddcad3144eb4051e3350596a8694cb0ed2f796003a06be3', 294, 'kc-kg-theory-cultivation-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0903218cb42eb8278ddcad3144eb4051e3350596a8694cb0ed2f796003a06be3', token_count=294, vector_point_id='kc-kg-theory-cultivation-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-cultivation-4', 'kg-theory-cultivation', 4, '["George Gerbner","Lilly Gruner","Michael Morgan"]', 'e6600a05973cd315e3cfa736423a799bb22e2d5f321bb4366e3ec480f46db924', 90, 'kc-kg-theory-cultivation-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e6600a05973cd315e3cfa736423a799bb22e2d5f321bb4366e3ec480f46db924', token_count=90, vector_point_id='kc-kg-theory-cultivation-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
