INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-cultural-imperialism-0', 'kg-theory-cultural-imperialism', 1, 'نظریه امپریالیسم فرهنگی (Cultural Imperialism Theory) نوع: THEORY نظریه‌ای که گسترش فرهنگ و رسانه‌های کشورهای قدرتمند به کشورها و فرهنگ‌های ضعیف‌تر را «امپریالیسم فرهنگی» می‌نامد.', '5b8f577d653afb816aaff6871100b86731ad2d0de70adfa6dbc6507e6ff47130', 325, 'kc-kg-theory-cultural-imperialism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5b8f577d653afb816aaff6871100b86731ad2d0de70adfa6dbc6507e6ff47130', token_count=325, vector_point_id='kc-kg-theory-cultural-imperialism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-cultural-imperialism-2', 'kg-theory-cultural-imperialism', 2, 'Schiller (1976) و همکاران نشان دادند رسانه‌های توده‌ای (به‌ویژه شبکه‌های تلویزیونی و فیلم) به‌عنوان ابزار گسترش ایدئولوژی و فرهنگ کشورهای صنعتی به کشورهای در حال توسعه عمل می‌کنند و فرهنگ محلی را تضعیف می‌کنند.', '90462d6258941ece4c73f4b95149fc6d2b01801a1dd6ed341a21d7e01d634a89', 381, 'kc-kg-theory-cultural-imperialism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='90462d6258941ece4c73f4b95149fc6d2b01801a1dd6ed341a21d7e01d634a89', token_count=381, vector_point_id='kc-kg-theory-cultural-imperialism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-cultural-imperialism-3', 'kg-theory-cultural-imperialism', 3, '["رسانه‌های کشورهای قدرتمند، فرهنگ محلی را تضعیف می‌کنند","جریان رسانه‌ای اغلب یک‌طرفه (از شمال به جنوب) است","امپریالیسم فرهنگی، شکل معاصر استعمار است"]', 'aac8240f1229cfdccc4e017ae6b3449e8b2cc65f643f77660706b72c1b9c4107', 278, 'kc-kg-theory-cultural-imperialism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='aac8240f1229cfdccc4e017ae6b3449e8b2cc65f643f77660706b72c1b9c4107', token_count=278, vector_point_id='kc-kg-theory-cultural-imperialism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
