INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-culture-industry-0', 'kg-theory-culture-industry', 1, 'نظریه صنعت فرهنگ (Culture Industry Theory) نوع: THEORY نظریه‌ای که رسانه و صنعت فرهنگ را ابزاری برای تولید انبوه و ایدئولوژیک فرهنگ می‌داند که انفعال و مصرف‌گرایی را تقویت می‌کند.', '86f49b42de7a1db34d13460b0becf216440660691028d74cc0c9f50318834954', 325, 'kc-kg-theory-culture-industry-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='86f49b42de7a1db34d13460b0becf216440660691028d74cc0c9f50318834954', token_count=325, vector_point_id='kc-kg-theory-culture-industry-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-culture-industry-2', 'kg-theory-culture-industry', 2, 'Adorno و Horkheimer (1944) در «دیالکتیک روشنگری» صنعت فرهنگ را به‌عنوان سیستمی تحلیل کردند که محصولات فرهنگی را به‌شکل انبوه، استاندارد و ایدئولوژیک تولید می‌کند و با ایجاد سرگرمی، قدرت نقدی توده‌ها را خنثی می‌کند.', '06aed587ff40687bf0f2f0f5b854cd8e00c6893f4ff2c2ed30da1e09dcbca632', 389, 'kc-kg-theory-culture-industry-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='06aed587ff40687bf0f2f0f5b854cd8e00c6893f4ff2c2ed30da1e09dcbca632', token_count=389, vector_point_id='kc-kg-theory-culture-industry-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-culture-industry-3', 'kg-theory-culture-industry', 3, '["صنعت فرهنگ محصولات فرهنگی را انبوه و استاندارد تولید می‌کند","فرهنگ توده‌ای ابزار ایدئولوژیک کنترل است","سرگرمی، قدرت نقدی توده‌ها را خنثی می‌کند"]', 'ba00474057c29e421fedf8fb1e1cb74351baac9602458392de19b07f37a62937', 270, 'kc-kg-theory-culture-industry-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ba00474057c29e421fedf8fb1e1cb74351baac9602458392de19b07f37a62937', token_count=270, vector_point_id='kc-kg-theory-culture-industry-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
