INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-dependence-0', 'kg-theory-dependence', 1, 'نظریه وابستگی به رسانه (Media Dependence Theory) نوع: THEORY نظریه‌ای که وابستگی مخاطب به رسانه را نتیجه‌ی نیازهای فردی، ساختار اجتماعی و ماهیت رسانه می‌داند.', '4393b23ecf2bb025b7ece11e40edb98a8fab610769c76d1d7cc83d4d67011277', 287, 'kc-kg-theory-dependence-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4393b23ecf2bb025b7ece11e40edb98a8fab610769c76d1d7cc83d4d67011277', token_count=287, vector_point_id='kc-kg-theory-dependence-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-dependence-2', 'kg-theory-dependence', 2, 'Ball-Rokeach و DeFleur (1976) سه‌جانبه‌ای را پیشنهاد کردند: نیازهای اجتماعی، ساختار اجتماعی و ویژگی‌های رسانه، با هم «وابستگی» مخاطب به رسانه را شکل می‌دهند و این وابستگی خود اثرات رسانه را تبیین می‌کند.', '10c79cff957d18736b92b2230ebcec23495dd57a20cfa0aeba5c14bcf5d05368', 369, 'kc-kg-theory-dependence-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='10c79cff957d18736b92b2230ebcec23495dd57a20cfa0aeba5c14bcf5d05368', token_count=369, vector_point_id='kc-kg-theory-dependence-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-dependence-3', 'kg-theory-dependence', 3, '["اثرات رسانه تابع درجه‌ی وابستگی مخاطب به آن رسانه است","وابستگی از نیازهای فردی، ساختار اجتماعی و ویژگی رسانه شکل می‌گیرد","مخاطبان با وابستگی بیشتر، بیشتر تحت تأثیر قرار می‌گیرند"]', 'eae33f5402cd3fc1c4892baf428368896ad2cb2b23e3b0e504d6695890cc1733', 332, 'kc-kg-theory-dependence-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='eae33f5402cd3fc1c4892baf428368896ad2cb2b23e3b0e504d6695890cc1733', token_count=332, vector_point_id='kc-kg-theory-dependence-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
