INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-election-communication-0', 'kg-theory-election-communication', 1, 'نظریه ارتباطات انتخاباتی (Election Communication Theory) نوع: THEORY نظریه‌ای که فرآیندهای «ارتباطات انتخاباتی» (مناظره، تبلیغات، رسانه) را تبیین می‌کند.', '0800211f24274875f5d1d2242fa81e439a229e8f689692d29f82eca2867a3bdf', 278, 'kc-kg-theory-election-communication-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0800211f24274875f5d1d2242fa81e439a229e8f689692d29f82eca2867a3bdf', token_count=278, vector_point_id='kc-kg-theory-election-communication-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-election-communication-2', 'kg-theory-election-communication', 2, 'این نظریه (که ترکیبی از نظریه‌های اثرات رسانه، چارچوب‌بندی و تبلیغات سیاسی است) به این می‌پردازد که چگونه ارتباطات انتخاباتی (مناظره‌ها، تبلیغات، پوشش رسانه‌ای) بر نگرش و رفتار رأی‌دهندگان اثر می‌گذارند.', '5eddeb964e3e7a8bcd60a2ec2fcc50ee15100fa31ff963605a1d956d0838b703', 369, 'kc-kg-theory-election-communication-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5eddeb964e3e7a8bcd60a2ec2fcc50ee15100fa31ff963605a1d956d0838b703', token_count=369, vector_point_id='kc-kg-theory-election-communication-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-election-communication-3', 'kg-theory-election-communication', 3, '["ارتباطات انتخاباتی، نگرش و رفتار رأی‌دهندگان را شکل می‌دهد","مناظره‌ها، فرآیند هدفمند و استراتژیک‌اند","پوشش رسانه‌ای، میانجی‌گری در ارتباطات انتخاباتی است"]', '8c62a13b2c13e02ec1491482659326011205c797d6a1d53c358301359e75b19a', 289, 'kc-kg-theory-election-communication-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8c62a13b2c13e02ec1491482659326011205c797d6a1d53c358301359e75b19a', token_count=289, vector_point_id='kc-kg-theory-election-communication-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
