INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-expectancy-violation-0', 'kg-theory-expectancy-violation', 1, 'نظریه نقض انتظارات (Expectancy Violation Theory) نوع: THEORY نظریه‌ای که واکنش افراد به «نقض انتظارات» در تعاملات بین‌فردی را تبیین می‌کند.', '483bbe06aa0b28b04ab49500687cd484ddd23b2f86e70c25be88fe51a09fdcdf', 252, 'kc-kg-theory-expectancy-violation-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='483bbe06aa0b28b04ab49500687cd484ddd23b2f86e70c25be88fe51a09fdcdf', token_count=252, vector_point_id='kc-kg-theory-expectancy-violation-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-expectancy-violation-2', 'kg-theory-expectancy-violation', 2, 'Knapp (1978) و Burgoon (1983) پیشنهاد کردند افراد در تعاملات، انتظاراتی از رفتار مقابل دارند و هر نقض این انتظارات (مثلاً فاصله‌گیری نزدیک، نگاه طولانی) واکنش خاصی در فرد ایجاد می‌کند (مثلاً غرور، تحقیر، جذابیت).', '0c851e71c1c60c8f12ea5f4ddd01c9e54b651c4d880d6f55786671911011989d', 385, 'kc-kg-theory-expectancy-violation-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0c851e71c1c60c8f12ea5f4ddd01c9e54b651c4d880d6f55786671911011989d', token_count=385, vector_point_id='kc-kg-theory-expectancy-violation-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-expectancy-violation-3', 'kg-theory-expectancy-violation', 3, '["افراد انتظاراتی از رفتار مقابل دارند","نقض انتظارات، واکنش عاطفی و شناختی ایجاد می‌کند","نوع واکنش به درجه‌ی نقض و ویژگی طرف مقابل بستگی دارد"]', '4b7592740fb6dd448381abee737053789249f174d67c271cc5d4eaecc6d66a6f', 263, 'kc-kg-theory-expectancy-violation-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4b7592740fb6dd448381abee737053789249f174d67c271cc5d4eaecc6d66a6f', token_count=263, vector_point_id='kc-kg-theory-expectancy-violation-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-expectancy-violation-4', 'kg-theory-expectancy-violation', 4, '["Judith Knapp","James Burgoon","Joseph Samter"]', '461d72aa6c0b2ac4362503e6a286eab5f0024ac586d1a773d31818d0b96767c6', 87, 'kc-kg-theory-expectancy-violation-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='461d72aa6c0b2ac4362503e6a286eab5f0024ac586d1a773d31818d0b96767c6', token_count=87, vector_point_id='kc-kg-theory-expectancy-violation-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
