INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-framing-0', 'kg-theory-framing', 1, 'نظریه چارچوب‌سازی (Framing Theory) نوع: THEORY نظریه‌ای که تأکید بر «نحوه‌ی چارچوب‌بندی» موضوع را در رسانه بر تفسیر و درک مخاطب می‌داند.', 'a53c32b2461741363a2fdc67fd9410654ba8e66a2e8a6f6aa3fa4d439bcf969b', 247, 'kc-kg-theory-framing-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a53c32b2461741363a2fdc67fd9410654ba8e66a2e8a6f6aa3fa4d439bcf969b', token_count=247, vector_point_id='kc-kg-theory-framing-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-framing-2', 'kg-theory-framing', 2, 'این نظریه (با ریشه در نظریه شناختی) می‌گوید چگونه یک رویداد در رسانه «قاب» بسته می‌شود، بر درک و ارزیابی آن توسط مخاطب اثر می‌گذارد. Entman و Goffman از بنیان‌گذاران اصلی آن‌اند.', '7989b73a50af203eab90f55432729d9e9959daed9f23b0ce166ba6f625e941d4', 323, 'kc-kg-theory-framing-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7989b73a50af203eab90f55432729d9e9959daed9f23b0ce166ba6f625e941d4', token_count=323, vector_point_id='kc-kg-theory-framing-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-framing-3', 'kg-theory-framing', 3, '["نحوه‌ی بیان (قاب) یک رویداد بر تفسیر مخاطب اثر می‌گذارد","چارچوب‌های مختلف یک رویداد، درک‌های متفاوتی می‌سازند","چارچوب‌بندی رسانه‌ای، انتخاب برخی وجوه رویداد و تأکید بر آن‌هاست"]', '1208cd1ff133bfe08be1b31a64d7c80e4ee7f2d84e94095ba34e942b20815fcd', 329, 'kc-kg-theory-framing-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1208cd1ff133bfe08be1b31a64d7c80e4ee7f2d84e94095ba34e942b20815fcd', token_count=329, vector_point_id='kc-kg-theory-framing-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
