INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-information-society-0', 'kg-theory-information-society', 1, 'نظریه جامعه اطلاعاتی (Information Society Theory) نوع: THEORY نظریه‌ای که گذار از جامعه صنعتی به «جامعه اطلاعاتی» را بر پایه‌ی تولید و توزیع اطلاعات تبیین می‌کند.', 'bbb46b53309bb01ac9dd1006f14d3ea0c779f1ccc1381456b5597d7bf9ebe28f', 294, 'kc-kg-theory-information-society-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bbb46b53309bb01ac9dd1006f14d3ea0c779f1ccc1381456b5597d7bf9ebe28f', token_count=294, vector_point_id='kc-kg-theory-information-society-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-information-society-2', 'kg-theory-information-society', 2, 'طوکل و همکاران (Toffler) و مورایاما (Miyamoto) در دهه‌ی ۱۹۶۰-۱۹۹۰ نشان دادند فناوری اطلاعات ساختار اقتصادی، سیاسی و فرهنگی جامعه را دگرگون می‌کند و اطلاعات به کالای بنیادین تبدیل می‌شود.', 'c5188097d3b25d47af0d739a1c15d9f782ed332cb8d722529cfa502e7d4ab6f3', 338, 'kc-kg-theory-information-society-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c5188097d3b25d47af0d739a1c15d9f782ed332cb8d722529cfa502e7d4ab6f3', token_count=338, vector_point_id='kc-kg-theory-information-society-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-information-society-3', 'kg-theory-information-society', 3, '["اطلاعات کالای بنیادین در جامعه مدرن است","فناوری اطلاعات ساختار اقتصادی و اجتماعی را دگرگون می‌کند","گذار از تولید صنعتی به تولید اطلاعاتی"]', '975e5e7168e9835cb520196964015d929d526adf6aeae6c417a7825b10252aab', 258, 'kc-kg-theory-information-society-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='975e5e7168e9835cb520196964015d929d526adf6aeae6c417a7825b10252aab', token_count=258, vector_point_id='kc-kg-theory-information-society-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
