INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-knowledge-gap-0', 'kg-theory-knowledge-gap', 1, 'نظریه شکاف آگاهی (Knowledge Gap Theory) نوع: THEORY نظریه‌ای که می‌گوید با افزایش اطلاعات رسانه‌ای، شکاف آگاهی بین اقشار کم‌برون و پربرون‌تر گسترش می‌یابد نه تنگ.', '78f5bd7cc9753a69db038e1b4379898290ebaea4bfa6f168c726308c0af1de50', 294, 'kc-kg-theory-knowledge-gap-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='78f5bd7cc9753a69db038e1b4379898290ebaea4bfa6f168c726308c0af1de50', token_count=294, vector_point_id='kc-kg-theory-knowledge-gap-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-knowledge-gap-2', 'kg-theory-knowledge-gap', 2, 'Tichenor, Donohue و Olien (1970) فرض کردند وقتی حجم اطلاعات رسانه‌ای درباره موضوعات اجتماعی افزایش می‌یابد، اقشار با سطح اجتماعی و اقتصادی بالاتر سریع‌تر اطلاعات می‌گیرند و شکاف آگاهی با اقشار پایین‌تر افزایش می‌یابد.', 'bcf3f028a58cc046dcdc3756bca710c191d5f32139a4771641e1bf3cd027674e', 394, 'kc-kg-theory-knowledge-gap-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bcf3f028a58cc046dcdc3756bca710c191d5f32139a4771641e1bf3cd027674e', token_count=394, vector_point_id='kc-kg-theory-knowledge-gap-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-knowledge-gap-3', 'kg-theory-knowledge-gap', 3, '["افزایش اطلاعات رسانه‌ای شکاف آگاهی را گسترش می‌دهد","اعضا با منابع اجتماعی و اقتصادی بیشتر، سریع‌تر اطلاعات می‌گیرند","فقدان منابع، مهار خوانداری، شبکه اجتماعی عوامل شکاف‌ساز"]', '8d5e9895843b0691ab14981b955773de96564397a4a28a66ea3c77b3576bb540', 323, 'kc-kg-theory-knowledge-gap-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8d5e9895843b0691ab14981b955773de96564397a4a28a66ea3c77b3576bb540', token_count=323, vector_point_id='kc-kg-theory-knowledge-gap-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
