INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-magic-bullet-0', 'kg-theory-magic-bullet', 1, 'نظریه تزریقی (گلوله جادویی) (Hypodermic / Magic Bullet Theory) نوع: THEORY مدل خطی و یک‌سویه‌ای که رسانه را ابزاری قدرتمند و مستقیم بر باور و رفتار مخاطب می‌داند.', 'c1f98053b83a0d967a265bee31022c56f453478bba4d3891495de4f1949ede2c', 294, 'kc-kg-theory-magic-bullet-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c1f98053b83a0d967a265bee31022c56f453478bba4d3891495de4f1949ede2c', token_count=294, vector_point_id='kc-kg-theory-magic-bullet-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-magic-bullet-2', 'kg-theory-magic-bullet', 2, 'این نظریه (که بیشتر به‌عنوان تکیه‌گاه انتقادی از پژوهش‌های دهه‌ی ۱۹۴۰ شناخته می‌شود) فرض می‌کند پیام رسانه‌ای به‌شکل مستقیم و یکسان به «ذهن مخاطب» تزریق می‌شود و اثر سریع و قوی دارد. پژوهش‌های پیمایشی کلمبیا (مثل مطالعه‌ی Laswell درباره‌ی جنگ) این مدل را تقویت کردند، اما مطالعات بعدی (مثل Lazarsfeld) آن را تضعیف کردند.', '71f705bc8e60e45c6ef0fc36f12e0760ff60af763e6dbbe2e577d4ffd3fd7102', 581, 'kc-kg-theory-magic-bullet-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='71f705bc8e60e45c6ef0fc36f12e0760ff60af763e6dbbe2e577d4ffd3fd7102', token_count=581, vector_point_id='kc-kg-theory-magic-bullet-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-magic-bullet-3', 'kg-theory-magic-bullet', 3, '["رسانه اثر مستقیم و قوی بر مخاطب دارد","مخاطب منفعل و یکسان است","مکانیسم تزریق یک‌طرفه"]', 'b8910a65072bc8cb645386d9603aaa5e43c723acd1405afc69481cd52e856f8c', 163, 'kc-kg-theory-magic-bullet-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b8910a65072bc8cb645386d9603aaa5e43c723acd1405afc69481cd52e856f8c', token_count=163, vector_point_id='kc-kg-theory-magic-bullet-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
