INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-mass-society-0', 'kg-theory-mass-society', 1, 'نظریه جامعه توده‌ای (Mass Society Theory) نوع: THEORY نظریه‌ای که «جامعه توده‌ای» را جامعه‌ای می‌داند که در آن افراد از پیوندهای اجتماعی سنتی جدا شده‌اند و به‌شکل منفعل در معرض رسانه‌های توده‌ای قرار می‌گیرند.', 'cd54787372e19520d31e6e12c1a6383429dee90b1ec5dd807158d234ca488b30', 379, 'kc-kg-theory-mass-society-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cd54787372e19520d31e6e12c1a6383429dee90b1ec5dd807158d234ca488b30', token_count=379, vector_point_id='kc-kg-theory-mass-society-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-mass-society-2', 'kg-theory-mass-society', 2, 'در دوران میانه‌ی قرن بیستم، در واکنش به ترس از توده‌گرایی و ایدئولوژی‌های توده‌ای، این نظریه (به‌ویژه در مکتب فرانکفورت) رسانه‌های توده‌ای را ابزاری برای کنترل و انفعال توده‌ها دید.', '525454e598498da782caa6d25c2c580e08bd0a6012e17ec0382f12abe8757175', 329, 'kc-kg-theory-mass-society-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='525454e598498da782caa6d25c2c580e08bd0a6012e17ec0382f12abe8757175', token_count=329, vector_point_id='kc-kg-theory-mass-society-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-mass-society-3', 'kg-theory-mass-society', 3, '["جامعه توده‌ای با انفعال و فقدان پیوندهای اجتماعی قوی مشخص می‌شود","رسانه‌های توده‌ای ابزارهای ایدئولوژیک کنترل توده‌ها","توده‌ها منفعل و قابل هدایت‌اند"]', '212b464211b90ba30d70dbbd47078adcf8ce766b68de8c196fe347183e373018', 281, 'kc-kg-theory-mass-society-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='212b464211b90ba30d70dbbd47078adcf8ce766b68de8c196fe347183e373018', token_count=281, vector_point_id='kc-kg-theory-mass-society-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
