INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-consumption-0', 'kg-theory-media-consumption', 1, 'نظریه مصرف رسانه‌ای (Media Consumption Theory) نوع: THEORY نظریه‌ای که الگوها و فرآیندهای «مصرف» رسانه‌ای (نه صرفاً دریافت) را تبیین می‌کند.', '205b4f39b11f2056871ee7520202a328beab22d9f3c64377d8dbe0a0bf4d631a', 254, 'kc-kg-theory-media-consumption-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='205b4f39b11f2056871ee7520202a328beab22d9f3c64377d8dbe0a0bf4d631a', token_count=254, vector_point_id='kc-kg-theory-media-consumption-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-consumption-2', 'kg-theory-media-consumption', 2, 'این نظریه (که ترکیبی از اقتصاد سیاسی رسانه و مطالعات فرهنگی است) به رسانه به‌عنوان کالای مصرفی می‌نگرد و الگوهای مصرف رسانه‌ای، انتخاب رسانه و مصرف فرهنگی را بررسی می‌کند.', '0030a9ff1c2c9027977c257c63c78b2114469df0e89c584c866ca1f5c2384bbe', 310, 'kc-kg-theory-media-consumption-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0030a9ff1c2c9027977c257c63c78b2114469df0e89c584c866ca1f5c2384bbe', token_count=310, vector_point_id='kc-kg-theory-media-consumption-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-consumption-3', 'kg-theory-media-consumption', 3, '["رسانه، کالای مصرفی است","الگوهای مصرف رسانه‌ای توسط عوامل اقتصادی، فرهنگی و اجتماعی شکل می‌گیرند","مصرف رسانه، فرآیند فعالانه‌ی معناسازی است"]', 'b07d9b0fb4a36ca06293b7c40be58411292eb256828bb1cf1fd297be07dbe0fb', 261, 'kc-kg-theory-media-consumption-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b07d9b0fb4a36ca06293b7c40be58411292eb256828bb1cf1fd297be07dbe0fb', token_count=261, vector_point_id='kc-kg-theory-media-consumption-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
