INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-consumption-7', 'kg-theory-media-consumption', 7, '["Ang, 1991 - International Television Audience Studies"]', '09a76652b5981976847510e1350e0fa856e8f8a87d945f18fe6f9eb398ca5eca', 103, 'kc-kg-theory-media-consumption-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='09a76652b5981976847510e1350e0fa856e8f8a87d945f18fe6f9eb398ca5eca', token_count=103, vector_point_id='kc-kg-theory-media-consumption-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-convergence-0', 'kg-theory-media-convergence', 1, 'نظریه همگرایی رسانه‌ای (Media Convergence Theory) نوع: THEORY نظریه‌ای که فرآیند «همگرایی» (convergence) رسانه‌ای (ترکیب فناوری‌ها، محتوا و پلتفرم‌ها) را تبیین می‌کند.', '7e0ee864c0e9a8d9f12e2efd2ee3e15fc6aac897988f7a1b7b3f73ae886aed2e', 303, 'kc-kg-theory-media-convergence-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7e0ee864c0e9a8d9f12e2efd2ee3e15fc6aac897988f7a1b7b3f73ae886aed2e', token_count=303, vector_point_id='kc-kg-theory-media-convergence-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-convergence-2', 'kg-theory-media-convergence', 2, 'Henry Jenkins (2003, 2006) همگرایی رسانه‌ای را به‌عنوان فرآیندی توصیف کرد که در آن رسانه‌ها از جنبه‌های فناوری، اقتصادی، سازمانی و فرهنگی با یکدیگر ترکیب می‌شوند و این همگرایی، مدل‌های تولید و مصرف محتوا را دگرگون می‌کند.', '1b3527bc9964c0b660231c8851c966b4db1dd37b00da938b72f07ba6ad21bb83', 401, 'kc-kg-theory-media-convergence-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1b3527bc9964c0b660231c8851c966b4db1dd37b00da938b72f07ba6ad21bb83', token_count=401, vector_point_id='kc-kg-theory-media-convergence-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-convergence-3', 'kg-theory-media-convergence', 3, '["رسانه‌ها از جنبه‌های فناوری، اقتصادی و فرهنگی با یکدیگر ترکیب می‌شوند","همگرایی، مدل‌های تولید و مصرف محتوا را دگرگون می‌کند","مشارکت مخاطب، نتیجه‌ی همگرایی است"]', 'd65900e6a98d245c7b5c6b90777b067ab4544ad703287ba8427a52ea69af0361', 298, 'kc-kg-theory-media-convergence-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d65900e6a98d245c7b5c6b90777b067ab4544ad703287ba8427a52ea69af0361', token_count=298, vector_point_id='kc-kg-theory-media-convergence-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
