INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-globalization-0', 'kg-theory-media-globalization', 1, 'نظریه جهانی‌شدن رسانه (Media Globalization Theory) نوع: THEORY نظریه‌ای که گسترش و یکپارچه‌سازی شبکه‌های رسانه‌ای در سطح جهانی را تبیین می‌کند.', '73fc61e0a2c877ceaa54c7b944e64ffc1232a44c1e121df7d4cbdad643ec44ec', 260, 'kc-kg-theory-media-globalization-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='73fc61e0a2c877ceaa54c7b944e64ffc1232a44c1e121df7d4cbdad643ec44ec', token_count=260, vector_point_id='kc-kg-theory-media-globalization-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-globalization-2', 'kg-theory-media-globalization', 2, 'این نظریه (که ترکیبی از رویکردهای اقتصادی-سیاسی و فرهنگی است) به فرآیند جهانی‌شدن جریان‌های رسانه‌ای و هم‌زمان به مقاومت و بومی‌سازی (glocalization) می‌پردازد.', 'd441723bb6f11157af0881f3e010c5791cd50cb71c94a85d768b87446ba35c35', 289, 'kc-kg-theory-media-globalization-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d441723bb6f11157af0881f3e010c5791cd50cb71c94a85d768b87446ba35c35', token_count=289, vector_point_id='kc-kg-theory-media-globalization-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-globalization-3', 'kg-theory-media-globalization', 3, '["رسانه‌ها در سطح جهانی یکپارچه می‌شوند","جریان رسانه‌ای هم‌زمان جهانی‌شدن و مقاومت محلی (glocalization) دارد","مالکیت چندملیتی، جهانی‌شدن رسانه را تسریع می‌کند"]', '4ba9807c0a6b06f589d446c81c9b546de98b6c43d5f51db9bc89a60f011e827e', 294, 'kc-kg-theory-media-globalization-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4ba9807c0a6b06f589d446c81c9b546de98b6c43d5f51db9bc89a60f011e827e', token_count=294, vector_point_id='kc-kg-theory-media-globalization-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-globalization-4', 'kg-theory-media-globalization', 4, '["Dennis McQuail","Arjun Appadurai","Roland Robertson"]', 'f9b8c08620227906408adb6012e1f77eee7f356230d7171bbd23841a6ff9f00b', 99, 'kc-kg-theory-media-globalization-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f9b8c08620227906408adb6012e1f77eee7f356230d7171bbd23841a6ff9f00b', token_count=99, vector_point_id='kc-kg-theory-media-globalization-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
