INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-media-globalization-7', 'kg-theory-media-globalization', 7, '["McQuail, 1995 - Mass Communication Theory","Appadurai, 1996 - Modularity of Culture"]', '5c350a0fc8174e826d9442ebccc816475aba53529df4d7b936a666fe6fe30fb2', 158, 'kc-kg-theory-media-globalization-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5c350a0fc8174e826d9442ebccc816475aba53529df4d7b936a666fe6fe30fb2', token_count=158, vector_point_id='kc-kg-theory-media-globalization-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-network-society-0', 'kg-theory-network-society', 1, 'نظریه جامعه شبکه‌ای (Network Society Theory) نوع: THEORY نظریه‌ای که شکل‌گیری «جامعه شبکه‌ای» را بر پایه‌ی شبکه‌های ارتباطی و فناوری اطلاعات تبیین می‌کند.', '1ba8aa219ae9c9367830b4aa2c6f89e2de32780095c1d84c58ce5a651f9e1bf7', 280, 'kc-kg-theory-network-society-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1ba8aa219ae9c9367830b4aa2c6f89e2de32780095c1d84c58ce5a651f9e1bf7', token_count=280, vector_point_id='kc-kg-theory-network-society-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-network-society-2', 'kg-theory-network-society', 2, 'Castells (1996-) می‌گوید انقلاب اطلاعاتی منجر به شکل‌گیری «جامعه شبکه‌ای» شده است که در آن سازمان‌دهی اجتماعی بر مبنای شبکه‌ها (نه سلسله‌مراتب) صورت می‌گیرد و قدرت از طریق کنترل شبکه‌ها اعمال می‌شود.', '4e85a06fbdf8ac13f7f0a1becad53424de4983ba20c80fa461fb3fdd14081ddf', 361, 'kc-kg-theory-network-society-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4e85a06fbdf8ac13f7f0a1becad53424de4983ba20c80fa461fb3fdd14081ddf', token_count=361, vector_point_id='kc-kg-theory-network-society-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-network-society-3', 'kg-theory-network-society', 3, '["ساختار اجتماعی بر پایه‌ی شبکه‌ها سازمان‌یافته است","فناوری اطلاعات شکل‌دهنده‌ی ساختار قدرت و فرهنگ است","قدرت از طریق کنترل نقاط گره‌ای شبکه اعمال می‌شود"]', '6c7bb7f95b31a73d374dc117641acb9ebf53eab57e47d33719db35cfdfd1e588', 285, 'kc-kg-theory-network-society-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6c7bb7f95b31a73d374dc117641acb9ebf53eab57e47d33719db35cfdfd1e588', token_count=285, vector_point_id='kc-kg-theory-network-society-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
