INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-networked-communication-0', 'kg-theory-networked-communication', 1, 'نظریه ارتباطات شبکه‌ای (Networked Communication Theory) نوع: THEORY نظریه‌ای که فرآیندهای «ارتباطات شبکه‌ای» در عصر دیجیتال تبیین می‌کند.', '29d4565ffdf0aed07db5dbdc47f25b62cb5f7470caa338566b35f59cd27aaa33', 249, 'kc-kg-theory-networked-communication-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='29d4565ffdf0aed07db5dbdc47f25b62cb5f7470caa338566b35f59cd27aaa33', token_count=249, vector_point_id='kc-kg-theory-networked-communication-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-networked-communication-2', 'kg-theory-networked-communication', 2, 'Castells (1996-2010) و همکاران (Pew, Rainie) ارتباطات شبکه‌ای را به‌عنوان ارتباطاتی توصیف کردند که در آن شبکه‌ها (نه سلسله‌مراتب) نقش اصلی در ساختاردهی به ارتباطات، تولید معنا و تمرکز قدرت دارند.', '0fe40ed2b5e59579f1270f7848741872eecef748598939d23f12cb9cb5725772', 354, 'kc-kg-theory-networked-communication-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0fe40ed2b5e59579f1270f7848741872eecef748598939d23f12cb9cb5725772', token_count=354, vector_point_id='kc-kg-theory-networked-communication-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-networked-communication-3', 'kg-theory-networked-communication', 3, '["ارتباطات بر پایه‌ی شبکه‌ها (نه سلسله‌مراتب) سازمان‌یافته‌اند","قدرت از طریق کنترل شبکه‌ها اعمال می‌شود","ارتباطات شبکه‌ای، فرآیندهای سیاسی و اجتماعی را دگرگون می‌کنند"]', '070c92ce3aacfe56ea9b3e78c470daf6944713020e46d04748fa626f4b2a67d8', 309, 'kc-kg-theory-networked-communication-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='070c92ce3aacfe56ea9b3e78c470daf6944713020e46d04748fa626f4b2a67d8', token_count=309, vector_point_id='kc-kg-theory-networked-communication-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
