INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-participatory-culture-0', 'kg-theory-participatory-culture', 1, 'نظریه مشارکت و فرهنگ مشارکتی (Participatory Culture Theory) نوع: THEORY نظریه‌ای که «فرهنگ مشارکتی» (participatory culture) را در عصر دیجیتال تبیین می‌کند.', 'c8e53f8312fab44502a4a2a871db8cd4faa5761035b5c8a0d608d6038e3a21b9', 281, 'kc-kg-theory-participatory-culture-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c8e53f8312fab44502a4a2a871db8cd4faa5761035b5c8a0d608d6038e3a21b9', token_count=281, vector_point_id='kc-kg-theory-participatory-culture-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-participatory-culture-2', 'kg-theory-participatory-culture', 2, 'Jenkins (2006) و همکاران (Rosen, Deuze) فرهنگ مشارکتی را به‌عنوان فرهنگی توصیف کردند که در آن مخاطبان به‌شکل فعالانه در تولید، توزیع و تفسیر محتوا مشارکت می‌کنند و این فرهنگ، بر پایه‌ی شبکه‌های اجتماعی و وب ۲.۰ استوار است.', 'cff0b6c017d4614017e2c892886505c486386bda9bee3e03e04f119105a23b02', 403, 'kc-kg-theory-participatory-culture-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cff0b6c017d4614017e2c892886505c486386bda9bee3e03e04f119105a23b02', token_count=403, vector_point_id='kc-kg-theory-participatory-culture-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-participatory-culture-3', 'kg-theory-participatory-culture', 3, '["مخاطبان به‌شکل فعالانه در تولید و تفسیر محتوا مشارکت می‌کنند","فرهنگ مشارکتی، بر پایه‌ی شبکه‌های اجتماعی و وب ۲.۰ است","مشارکت، شکل پیشرفته‌ی فعال‌کنندگی مخاطب است"]', '055420ada31347cbb51770fa509e2a444f308251bf9d03571ab4e7b28178c6c7', 303, 'kc-kg-theory-participatory-culture-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='055420ada31347cbb51770fa509e2a444f308251bf9d03571ab4e7b28178c6c7', token_count=303, vector_point_id='kc-kg-theory-participatory-culture-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
