INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-platform-society-0', 'kg-theory-platform-society', 1, 'نظریه جامعه پلتفرمی (Platform Society Theory) نوع: THEORY نظریه‌ای که «جامعه پلتفرمی» (platform society) را در عصر دیجیتال تبیین می‌کند.', '25e73c43bc15c3d2bf61bd743dda01e3541d368bf001b14acc179c916a33d579', 247, 'kc-kg-theory-platform-society-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='25e73c43bc15c3d2bf61bd743dda01e3541d368bf001b14acc179c916a33d579', token_count=247, vector_point_id='kc-kg-theory-platform-society-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-platform-society-2', 'kg-theory-platform-society', 2, 'Srnicek (2017) و همکاران (van Dijck) جامعه پلتفرمی را به‌عنوان جامعه‌ای توصیف کردند که در آن پلتفرم‌های دیجیتال (نه شرکت‌های سنتی) نقش اصلی در ساختاردهی به اقتصاد، سیاست و فرهنگ دارند و این جامعه، بر پایه‌ی شبکه‌های اجتماعی و الگوریتم‌ها استوار است.', '9b92167c7fbfb16e1feef56f7e9407ac1f30f3cc3dc8364b1971fb29b25244e2', 452, 'kc-kg-theory-platform-society-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9b92167c7fbfb16e1feef56f7e9407ac1f30f3cc3dc8364b1971fb29b25244e2', token_count=452, vector_point_id='kc-kg-theory-platform-society-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-platform-society-3', 'kg-theory-platform-society', 3, '["پلتفرم‌های دیجیتال، نقش اصلی در ساختاردهی به اقتصاد، سیاست و فرهنگ","جامعه پلتفرمی، بر پایه‌ی شبکه‌های اجتماعی و الگوریتم‌ها است","قدرت از طریق کنترل پلتفرم‌ها اعمال می‌شود"]', 'e47ad1a7176b758d93227fcac2e425e81c5e8f3b7658ccec71fb74388e2c0092', 320, 'kc-kg-theory-platform-society-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e47ad1a7176b758d93227fcac2e425e81c5e8f3b7658ccec71fb74388e2c0092', token_count=320, vector_point_id='kc-kg-theory-platform-society-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
