INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-platform-society-7', 'kg-theory-platform-society', 7, '["Srnicek, 2017 - Platform Capitalism","van Dijck, 2013 - The Culture of Networks"]', '1a78bee3120f706e8fd74d0c2ff6980d96bcfc3b1fc467d0d884ff9e4e19fda5', 150, 'kc-kg-theory-platform-society-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1a78bee3120f706e8fd74d0c2ff6980d96bcfc3b1fc467d0d884ff9e4e19fda5', token_count=150, vector_point_id='kc-kg-theory-platform-society-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-platformization-0', 'kg-theory-platformization', 1, 'نظریه پلتفرمی‌شدن (Platformization Theory) نوع: THEORY نظریه‌ای که فرآیند «پلتفرمی‌شدن» (platformization) را در عصر دیجیتال تبیین می‌کند.', '746844d2b5fdce65d45b117dabbee13efe9feb10f618ddd8aadf55bbf9bf8c7a', 249, 'kc-kg-theory-platformization-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='746844d2b5fdce65d45b117dabbee13efe9feb10f618ddd8aadf55bbf9bf8c7a', token_count=249, vector_point_id='kc-kg-theory-platformization-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-platformization-2', 'kg-theory-platformization', 2, 'Couldry و Hepp (2017) و van Dijck (2013) پلتفرمی‌شدن را به‌عنوان فرآیندی توصیف کردند که در آن شرکت‌های پلتفرمی (مثل Meta، Google، Amazon) به‌عنوان میانجی‌های کلیدی در تولید، توزیع و مصرف محتوا عمل می‌کنند و این پلتفرم‌ها، قواعد بازی (قواعد شبکه‌ای، الگوریتم‌ها) را تعیین می‌کنند.', 'e9a5c11acf20cc778a2c7fae6667750e8390af6d5c0174201980da65eb6a641f', 507, 'kc-kg-theory-platformization-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e9a5c11acf20cc778a2c7fae6667750e8390af6d5c0174201980da65eb6a641f', token_count=507, vector_point_id='kc-kg-theory-platformization-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-platformization-3', 'kg-theory-platformization', 3, '["شرکت‌های پلتفرمی، میانجی‌های کلیدی در تولید و مصرف محتوا","پلتفرم‌ها، قواعد شبکه‌ای و الگوریتم‌ها را تعیین می‌کنند","پلتفرمی‌شدن، ساختار قدرت رسانه‌ای را دگرگون می‌کند"]', 'e28fba4e26fdbba86120af419d25769708839fc72d3d14c67f786beba1dcae80', 310, 'kc-kg-theory-platformization-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e28fba4e26fdbba86120af419d25769708839fc72d3d14c67f786beba1dcae80', token_count=310, vector_point_id='kc-kg-theory-platformization-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
