INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-platformization-7', 'kg-theory-platformization', 7, '["van Dijck, 2013 - The Culture of Networks","Couldry & Hepp, 2017 - The Platformization of Cultural Industry"]', '4dc1c606f8531baa96755b2f9377d2f4d22b247eb27911e0819b39238e6a1e58', 201, 'kc-kg-theory-platformization-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4dc1c606f8531baa96755b2f9377d2f4d22b247eb27911e0819b39238e6a1e58', token_count=201, vector_point_id='kc-kg-theory-platformization-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-policy-brokerage-0', 'kg-theory-policy-brokerage', 1, 'نظریه میانجی‌گری سیاست (Policy Brokerage / Policy Intermediation Theory) نوع: THEORY نظریه‌ای که نقش رسانه به‌عنوان «میانجی» در فرآیندهای سیاست‌گذاری و سیاسی را تبیین می‌کند.', '2ce5014e55e33a009bfeeb07a27aedf41377ec9f18e03c8bfc03bc0c52902339', 316, 'kc-kg-theory-policy-brokerage-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2ce5014e55e33a009bfeeb07a27aedf41377ec9f18e03c8bfc03bc0c52902339', token_count=316, vector_point_id='kc-kg-theory-policy-brokerage-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-policy-brokerage-2', 'kg-theory-policy-brokerage', 2, 'این نظریه (که در مطالعات ارتباطات سیاسی و سیاست‌گذاری رسانه استفاده می‌شود) به این می‌پردازد که چگونه رسانه‌ها به‌عنوان میانجی‌ها (intermediaries) در فرآیندهای سیاست‌گذاری، انتقال اطلاعات و شکل‌دهی به نگرش‌های سیاسی عمل می‌کنند.', '992ea426f72048f1cd27e995fe16dd6845861de42975261db8046aa830c0e265', 414, 'kc-kg-theory-policy-brokerage-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='992ea426f72048f1cd27e995fe16dd6845861de42975261db8046aa830c0e265', token_count=414, vector_point_id='kc-kg-theory-policy-brokerage-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-policy-brokerage-3', 'kg-theory-policy-brokerage', 3, '["رسانه‌ها به‌عنوان میانجی در فرآیندهای سیاست‌گذاری عمل می‌کنند","رسانه، انتقال‌دهنده و شکل‌دهنده‌ی اطلاعات سیاسی است","میانجی‌گری رسانه، فرآیند فعال و هدفمند است"]', 'a2fff9011d15ce2c024472f9adf58d62286c1c6f4f7428e75cbd889996ea85c3', 298, 'kc-kg-theory-policy-brokerage-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a2fff9011d15ce2c024472f9adf58d62286c1c6f4f7428e75cbd889996ea85c3', token_count=298, vector_point_id='kc-kg-theory-policy-brokerage-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
