INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-advertising-0', 'kg-theory-political-advertising', 1, 'نظریه تبلیغات سیاسی (Political Advertising Theory) نوع: THEORY نظریه‌ای که فرآیندها و اثرات «تبلیغات سیاسی» بر نگرش و رفتار رأی‌دهندگان را تبیین می‌کند.', '6013254d989a3da0da9880c9d6e8fec391baac663d6a18e33959c16e0d27f0fc', 276, 'kc-kg-theory-political-advertising-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6013254d989a3da0da9880c9d6e8fec391baac663d6a18e33959c16e0d27f0fc', token_count=276, vector_point_id='kc-kg-theory-political-advertising-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-advertising-2', 'kg-theory-political-advertising', 2, 'این نظریه (که ترکیبی از روان‌شناسی سیاسی و نظریه‌های اثرات رسانه است) به این می‌پردازد که چگونه تبلیغات سیاسی (مثلاً آژانس‌ها، پیام‌ها، رسانه‌ها) بر نگرش و رفتار رأی‌دهندگان اثر می‌گذارند.', 'f91b1cd9a8c1c2ce7b115f1999c7c748d58d9835c26a679d5ed0bf091c721bbf', 341, 'kc-kg-theory-political-advertising-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f91b1cd9a8c1c2ce7b115f1999c7c748d58d9835c26a679d5ed0bf091c721bbf', token_count=341, vector_point_id='kc-kg-theory-political-advertising-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-advertising-3', 'kg-theory-political-advertising', 3, '["تبلیغات سیاسی، نگرش و رفتار رأی‌دهندگان را شکل می‌دهد","نوع پیام (منفی/مثبت) بر اثر تبلیغ اثر می‌گذارد","تبلیغات سیاسی، فرآیند هدفمند و استراتژیک است"]', '3f10ab5403efd5003fb88fd4426a6d562018ecf7a0f07d285dddcb398731c9ca', 278, 'kc-kg-theory-political-advertising-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3f10ab5403efd5003fb88fd4426a6d562018ecf7a0f07d285dddcb398731c9ca', token_count=278, vector_point_id='kc-kg-theory-political-advertising-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
