INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-agenda-0', 'kg-theory-political-agenda', 1, 'نظریه دستور کار سیاسی (Political Agenda-Setting Theory) نوع: THEORY نظریه‌ای که تأثیر رسانه بر «دستور کار» سیاسی (priority of political issues) را تبیین می‌کند.', 'c2a37c61f483d0dc00bc342b0818e66d6f50db5c4aa8ca237f0d3a81208feca4', 290, 'kc-kg-theory-political-agenda-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c2a37c61f483d0dc00bc342b0818e66d6f50db5c4aa8ca237f0d3a81208feca4', token_count=290, vector_point_id='kc-kg-theory-political-agenda-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-agenda-2', 'kg-theory-political-agenda', 2, 'این نظریه (که شکل سیاسی‌شده‌ی نظریه برجسته‌سازی است) نشان می‌دهد رسانه با برجسته‌سازی برخی مسائل سیاسی، «دستور کار» سیاسی را شکل می‌دهد و تعیین می‌کند که چه مسائلی در اولویت بحث‌های سیاسی قرار گیرند.', 'b6015dbed096833638d9016294a3d5730a4f30c33ea7da5bb0458feb88896c01', 361, 'kc-kg-theory-political-agenda-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b6015dbed096833638d9016294a3d5730a4f30c33ea7da5bb0458feb88896c01', token_count=361, vector_point_id='kc-kg-theory-political-agenda-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-agenda-3', 'kg-theory-political-agenda', 3, '["رسانه با برجسته‌سازی برخی مسائل، دستور کار سیاسی را شکل می‌دهد","اولویت‌بندی رسانه، اولویت‌بندی ذهنی مخاطب سیاسی است","رسانه «به چه مسئله‌ای فکر کنیم» را تعیین می‌کند"]', '469b5af352f9f08b4d1728652e228996b6a723af52df78e51e4c189eff7c3d0c', 309, 'kc-kg-theory-political-agenda-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='469b5af352f9f08b4d1728652e228996b6a723af52df78e51e4c189eff7c3d0c', token_count=309, vector_point_id='kc-kg-theory-political-agenda-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
