INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-framing-0', 'kg-theory-political-framing', 1, 'نظریه چارچوب‌بندی سیاسی (Political Framing Theory) نوع: THEORY نظریه‌ای که تأثیر «چارچوب‌بندی» مسائل سیاسی توسط رسانه بر تفسیر و نگرش سیاسی مخاطب را تبیین می‌کند.', '374b006fca489131440586e32a186f6e24a673418efea2c6d35c1ddad5246f4d', 294, 'kc-kg-theory-political-framing-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='374b006fca489131440586e32a186f6e24a673418efea2c6d35c1ddad5246f4d', token_count=294, vector_point_id='kc-kg-theory-political-framing-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-framing-2', 'kg-theory-political-framing', 2, 'این نظریه (که شکل سیاسی‌شده‌ی نظریه چارچوب‌سازی است) به این می‌پردازد که چگونه رسانه با چارچوب‌بندی مسائل سیاسی (مثلاً مهاجرت، اقتصاد، امنیت)، تفسیر و نگرش سیاسی مخاطب را شکل می‌دهد.', '2f11acdae07d51a241dc73843e09ab770b1d3592929f4adc9c3f6446778227d4', 330, 'kc-kg-theory-political-framing-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2f11acdae07d51a241dc73843e09ab770b1d3592929f4adc9c3f6446778227d4', token_count=330, vector_point_id='kc-kg-theory-political-framing-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-framing-3', 'kg-theory-political-framing', 3, '["چارچوب‌بندی رسانه‌ای مسائل سیاسی، تفسیر مخاطب را شکل می‌دهد","چارچوب‌های مختلف یک مسئله‌ی سیاسی، درک‌های متفاوتی می‌سازند","چارچوب‌بندی، ابزاری قدرتمند برای هدایت نگرش سیاسی است"]', '3e1bf20ebfc8e5070f4b075974acfa5127f1e7c8c6f1b253e5c5773fb0f37c20', 329, 'kc-kg-theory-political-framing-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3e1bf20ebfc8e5070f4b075974acfa5127f1e7c8c6f1b253e5c5773fb0f37c20', token_count=329, vector_point_id='kc-kg-theory-political-framing-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
