INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-public-sphere-0', 'kg-theory-political-public-sphere', 1, 'نظریه حوزه عمومی (Public Sphere Theory (Political)) نوع: THEORY نظریه‌ای که نقش «حوزه عمومی» در فرآیندهای دموکراتیک و سیاسی را تبیین می‌کند.', '5987b2c63916a42472b305d6ca406007438cf36e3cfbc008720bf1839638b72c', 254, 'kc-kg-theory-political-public-sphere-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5987b2c63916a42472b305d6ca406007438cf36e3cfbc008720bf1839638b72c', token_count=254, vector_point_id='kc-kg-theory-political-public-sphere-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-public-sphere-2', 'kg-theory-political-public-sphere', 2, 'این نظریه (که شکل سیاسی‌شده‌ی نظریه فضای عمومی Habermas است) به این می‌پردازد که چگونه «حوزه عمومی» به‌عنوان فضایی برای گفت‌وگوی سیاسی دموکراتیک عمل می‌کند و چگونه رسانه‌های توده‌ای این فضا را تجاری‌سازی و ایدئولوژیک کرده‌اند.', 'b225f198bd9f555a609214b5b9f55007e3c116683d17812e8544569e01c48bd7', 410, 'kc-kg-theory-political-public-sphere-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b225f198bd9f555a609214b5b9f55007e3c116683d17812e8544569e01c48bd7', token_count=410, vector_point_id='kc-kg-theory-political-public-sphere-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-public-sphere-3', 'kg-theory-political-public-sphere', 3, '["حوزه عمومی، فضایی برای گفت‌وگوی سیاسی دموکراتیک است","رسانه‌های توده‌ای حوزه عمومی را تجاری‌سازی کرده‌اند","دموکراسی، نیازمند حوزه عمومی سالم است"]', 'fe9225e7b742b239e1b37ddfbb963cb0bdbb41e6b0aa9ce3f1d440dcbef09305', 270, 'kc-kg-theory-political-public-sphere-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fe9225e7b742b239e1b37ddfbb963cb0bdbb41e6b0aa9ce3f1d440dcbef09305', token_count=270, vector_point_id='kc-kg-theory-political-public-sphere-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
