INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-spiral-0', 'kg-theory-political-spiral', 1, 'نظریه مارپیچ سکوت (Spiral of Silence Theory) نوع: THEORY نظریه‌ای که می‌گوید در حوزه‌ی سیاسی، افراد در صورت احساس اقلیت‌بودن، نظر خود را بیان نمی‌کنند و «سکوت» می‌کنند.', '45bdd26d4a256e09ffd829f0f7da3bab8664631c1964e46b5b341b84b454ba02', 305, 'kc-kg-theory-political-spiral-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='45bdd26d4a256e09ffd829f0f7da3bab8664631c1964e46b5b341b84b454ba02', token_count=305, vector_point_id='kc-kg-theory-political-spiral-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-spiral-2', 'kg-theory-political-spiral', 2, 'این نظریه (که شکل سیاسی‌شده‌ی نظریه مارپیچ سکوت Noelle-Neumann است) به این می‌پردازد که چگونه در انتخابات و بحث‌های سیاسی، ترس از انزجار اجتماعی باعث می‌شود افراد با نظر اقلیت سکوت کنند و این پدیده، یک «مارپیچ» می‌سازد.', '8a0d9a2bf3815b383b1aae5dec9f0cc9c34453d297323a480d49b0a0b8461006', 398, 'kc-kg-theory-political-spiral-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8a0d9a2bf3815b383b1aae5dec9f0cc9c34453d297323a480d49b0a0b8461006', token_count=398, vector_point_id='kc-kg-theory-political-spiral-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-political-spiral-3', 'kg-theory-political-spiral', 3, '["افراد در حوزه‌ی سیاسی در صورت احساس اقلیت‌بودن سکوت می‌کنند","ترس از انزجار اجتماعی، نیروی محرک است","این سکوت، اکثریت‌سازی ظاهری و تقویت رای غالب می‌سازد"]', '72e2b18088447fae155483aded355392943210584a6a28c9cb8040b4818687ca', 287, 'kc-kg-theory-political-spiral-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='72e2b18088447fae155483aded355392943210584a6a28c9cb8040b4818687ca', token_count=287, vector_point_id='kc-kg-theory-political-spiral-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
