INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-public-sphere-0', 'kg-theory-public-sphere', 1, 'نظریه فضای عمومی (Public Sphere Theory) نوع: THEORY نظریه‌ای که «فضای عمومی» را فضایی می‌داند که در آن شهروندان درباره‌ی مسائل عمومی به‌صورت منطقی و بدون اجبار به گفت‌وگو می‌پردازند.', '979612a03106cb90ad9f6181ff281d2daea58d9339633c31a9054b866948ce7b', 330, 'kc-kg-theory-public-sphere-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='979612a03106cb90ad9f6181ff281d2daea58d9339633c31a9054b866948ce7b', token_count=330, vector_point_id='kc-kg-theory-public-sphere-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-public-sphere-2', 'kg-theory-public-sphere', 2, 'Jürgen Habermas (1962) در «ساختار تحول جامعه‌ی توده‌ای» فضای عمومی را ساختاری دموکراتیک تحلیل کرد که در آن شهروندان به‌عنوان معادل به بحث و گفت‌وگو می‌پردازند؛ اما در عصر رسانه‌های توده‌ای، این فضا به‌دلیل ایدئولوژی‌گرایی و تجاری‌سازی رسانه‌ها در خطر است.', '3bfcdaf9ee13dffb8abdc20db339948722c46ea7740f647587917d3c8f728187', 463, 'kc-kg-theory-public-sphere-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3bfcdaf9ee13dffb8abdc20db339948722c46ea7740f647587917d3c8f728187', token_count=463, vector_point_id='kc-kg-theory-public-sphere-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-public-sphere-3', 'kg-theory-public-sphere', 3, '["فضای عمومی فضایی برای گفت‌وگوی منطقی و آزاد شهروندان است","رسانه‌های توده‌ای در عصر مدرن فضا را تجاری‌سازی و ایدئولوژیک کرده‌اند","دموکراسی نیازمند فضای عمومی سالم است"]', '6bd3f36dded0b8941ff2a47af5d539c8e24a7ec82e9d16390ca5acba839605c6', 310, 'kc-kg-theory-public-sphere-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6bd3f36dded0b8941ff2a47af5d539c8e24a7ec82e9d16390ca5acba839605c6', token_count=310, vector_point_id='kc-kg-theory-public-sphere-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
