INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-reception-0', 'kg-theory-reception', 1, 'نظریه دریافت (Reception Theory) نوع: THEORY نظریه‌ای که «دریافت» مخاطب را محور اصلی تحلیل رسانه می‌داند و بر نقش فعال مخاطب در ساختن معنا تأکید دارد.', '2862ea5b3e607a43942a6092f3d46d230e56f9044a435d7f06d7a6a9595ac22d', 270, 'kc-kg-theory-reception-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2862ea5b3e607a43942a6092f3d46d230e56f9044a435d7f06d7a6a9595ac22d', token_count=270, vector_point_id='kc-kg-theory-reception-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-reception-2', 'kg-theory-reception', 2, 'ریشه در نظریه‌های دانشگاه کونigsberg (Iser, Jauss) در مطالعات ادبی دارد و به رسانه و رسانه‌های بصری گسترش یافت (به‌ویژه توسط محققان بریتانیایی مانند Morcraft و Hirsch). این نظریه می‌گوید معنای نهایی یک اثر، در فرآیند تفسیر مخاطب ساخته می‌شود، نه صرفاً در تولید.', 'bd211bec12d48586e2554a324120bee068dc63c34b4ea62caebf8baf31efae66', 474, 'kc-kg-theory-reception-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bd211bec12d48586e2554a324120bee068dc63c34b4ea62caebf8baf31efae66', token_count=474, vector_point_id='kc-kg-theory-reception-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-reception-3', 'kg-theory-reception', 3, '["معنا در فرآیند تفسیر مخاطب ساخته می‌شود","مخاطب فعال و تفسیرکننده است","«افق انتظار» مخاطب بر تفسیر اثر تعیین‌کننده است"]', 'ee678aa2fc2bef51569e4808a52b56fadafa65507d6d7e36fed288b406bdac92', 223, 'kc-kg-theory-reception-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ee678aa2fc2bef51569e4808a52b56fadafa65507d6d7e36fed288b406bdac92', token_count=223, vector_point_id='kc-kg-theory-reception-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
