INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-resisting-audience-0', 'kg-theory-resisting-audience', 1, 'نظریه مخاطب مقاومت‌کننده (Resisting / Oppositional Audience Theory) نوع: THEORY نظریه‌ای که برخی مخاطبان می‌توانند پیام رسانه‌ای را در موقعیت مقاومتی تفسیر و رد کنند.', '13dc14a7b663bfc6c195bf71301fa9d9dd29130c1858d54bdf213f7b71c1f379', 301, 'kc-kg-theory-resisting-audience-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='13dc14a7b663bfc6c195bf71301fa9d9dd29130c1858d54bdf213f7b71c1f379', token_count=301, vector_point_id='kc-kg-theory-resisting-audience-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-resisting-audience-2', 'kg-theory-resisting-audience', 2, 'این نظریه (که اغلب در چارچوب مدل رمزگذاری/رمزگشایی Hall قرار می‌گیرد) بر این نکته تأکید دارد که برخی مخاطبان به‌ویژه در موقعیت‌های حاشیه‌ای (جنسیتی، طبقه‌ای، نژادی) پیام‌های غالب رسانه‌ای را تفسیر مقاومتی می‌کنند.', '546e2ad8dca80b3c9afd4190d5e05353a2a26b49cb3a45aab0079cd10a11b97d', 387, 'kc-kg-theory-resisting-audience-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='546e2ad8dca80b3c9afd4190d5e05353a2a26b49cb3a45aab0079cd10a11b97d', token_count=387, vector_point_id='kc-kg-theory-resisting-audience-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-resisting-audience-3', 'kg-theory-resisting-audience', 3, '["بعضی مخاطبان پیام‌های غالب را تفسیر مقاومتی می‌کنند","مقاومت، شکل فعال‌کنندگی مخاطب است","مقاومت به‌ویژه در گروه‌های حاشیه‌ای بیشتر است"]', '7366e3f53bd5e8b2068280c6eac53822ea40c940c3a400bda8a2bf20bac14f46', 252, 'kc-kg-theory-resisting-audience-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7366e3f53bd5e8b2068280c6eac53822ea40c940c3a400bda8a2bf20bac14f46', token_count=252, vector_point_id='kc-kg-theory-resisting-audience-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
