INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-sensemaking-0', 'kg-theory-sensemaking', 1, 'نظریه مدیریت هماهنگ معنا (Meaning Coordination / Sensemaking Theory) نوع: THEORY نظریه‌ای که فرآیند هماهنگ‌سازی معنایی در مکالمات بین‌فردی را تبیین می‌کند.', '16c5d009c48a8fe869d8be16278c111cdf9328e84eddc342da6e8566e68bc802', 281, 'kc-kg-theory-sensemaking-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='16c5d009c48a8fe869d8be16278c111cdf9328e84eddc342da6e8566e68bc802', token_count=281, vector_point_id='kc-kg-theory-sensemaking-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-sensemaking-2', 'kg-theory-sensemaking', 2, 'Giddens و همکاران (و در حوزه‌ی ارتباطات، Gergen و همکاران) پیشنهاد کردند در مکالمات، طرفین «معنا» را به‌شکل تعاملی و تدریجی هماهنگ می‌کنند و این هماهنگ‌سازی، پایه‌ی شکل‌گیری درک مشترک است.', 'cd21d7c9c3040d1b110c51e07f8fd06da4027e2432bb81e79119dc17d3e60c54', 341, 'kc-kg-theory-sensemaking-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cd21d7c9c3040d1b110c51e07f8fd06da4027e2432bb81e79119dc17d3e60c54', token_count=341, vector_point_id='kc-kg-theory-sensemaking-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-sensemaking-3', 'kg-theory-sensemaking', 3, '["مکالمه، فرآیند هماهنگ‌سازی معنایی است","طرفین در مکالمه، درک مشترک را تدریجاً می‌سازند","هماهنگ‌سازی معنا، فرآیندی پویا و تعاملی است"]', 'c74adc8810b5e556f3b8ee544c62782190dc962650395b7f0c6d8674c45d0c77', 247, 'kc-kg-theory-sensemaking-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c74adc8810b5e556f3b8ee544c62782190dc962650395b7f0c6d8674c45d0c77', token_count=247, vector_point_id='kc-kg-theory-sensemaking-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
