INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-sensemaking-7', 'kg-theory-sensemaking', 7, '["Gergen, 1989 - Social Constructionism"]', '0933a9109b207cf0e41509b780c0a2e18cf691a93315c920a2f1a13b2c393027', 74, 'kc-kg-theory-sensemaking-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0933a9109b207cf0e41509b780c0a2e18cf691a93315c920a2f1a13b2c393027', token_count=74, vector_point_id='kc-kg-theory-sensemaking-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-exchange-0', 'kg-theory-social-exchange', 1, 'نظریه تبادل اجتماعی (Social Exchange Theory) نوع: THEORY نظریه‌ای که روابط بین‌فردی را بر پایه‌ی «تبادل» منافع و هزینه‌ها تبیین می‌کند.', '75292ef5325ab679ffaff15be41dda3a4a646ed2cfee95b1c67199c80339e347', 245, 'kc-kg-theory-social-exchange-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='75292ef5325ab679ffaff15be41dda3a4a646ed2cfee95b1c67199c80339e347', token_count=245, vector_point_id='kc-kg-theory-social-exchange-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-exchange-2', 'kg-theory-social-exchange', 2, 'Homans (1958) و Blau (1964) (و در حوزه‌ی ارتباطات، McLeod) پیشنهاد کردند افراد در روابط، منافع و هزینه‌ها را می‌سنجند و در صورتی که منافع از هزینه‌ها بیشتر باشد، رابطه ادامه می‌یابد. این نظریه از اقتصاد و نظریه بازی گرفته شده است.', 'f7b64f48e73d7658bb4bbaf12f568eeeddc7d57df11928de383bb70180989495', 418, 'kc-kg-theory-social-exchange-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7b64f48e73d7658bb4bbaf12f568eeeddc7d57df11928de383bb70180989495', token_count=418, vector_point_id='kc-kg-theory-social-exchange-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-exchange-3', 'kg-theory-social-exchange', 3, '["روابط بر پایه‌ی تبادل منافع و هزینه‌ها هستند","افراد در صورتی که منافع بیشتر از هزینه‌ها باشد، رابطه را ادامه می‌دهند","برابری در تبادل، پایایی رابطه را افزایش می‌دهد"]', 'd05eba177b7f439ba847e1a27c45dae79375b36bcee8f64092aca1002ffa234b', 309, 'kc-kg-theory-social-exchange-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d05eba177b7f439ba847e1a27c45dae79375b36bcee8f64092aca1002ffa234b', token_count=309, vector_point_id='kc-kg-theory-social-exchange-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-exchange-4', 'kg-theory-social-exchange', 4, '["George Homans","Peter Blau","John McLeod"]', '2e0d9407ea960114494d7faf6c85f5d3c3a29488a720be106b951bd0a1d81892', 80, 'kc-kg-theory-social-exchange-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2e0d9407ea960114494d7faf6c85f5d3c3a29488a720be106b951bd0a1d81892', token_count=80, vector_point_id='kc-kg-theory-social-exchange-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
