INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-exchange-6', 'kg-theory-social-exchange', 6, 'آمریکا', '75a08574f6b41d316d5c915494c8ce566e1270189177f02e7d155e4e54fe8525', 10, 'kc-kg-theory-social-exchange-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='75a08574f6b41d316d5c915494c8ce566e1270189177f02e7d155e4e54fe8525', token_count=10, vector_point_id='kc-kg-theory-social-exchange-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-exchange-7', 'kg-theory-social-exchange', 7, '["Homans, 1958 - Social Behavior as Exchange","Blau, 1964 - Exchange and Power in Social Life"]', '3c80bfceb6b589565f60f5b3cc21c9b9dae485e29cd0056d5413460026935dad', 172, 'kc-kg-theory-social-exchange-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3c80bfceb6b589565f60f5b3cc21c9b9dae485e29cd0056d5413460026935dad', token_count=172, vector_point_id='kc-kg-theory-social-exchange-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-penetration-0', 'kg-theory-social-penetration', 1, 'نظریه نفوذ اجتماعی (Social Penetration Theory) نوع: THEORY نظریه‌ای که فرآیند «نفوذ» در روابط بین‌فردی را به‌شکل لایه‌لایه تبیین می‌کند.', 'e66a0eb729d82bc0b4d25011c8b6abce7499666fc4811e289501cb8c2b6f237c', 247, 'kc-kg-theory-social-penetration-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e66a0eb729d82bc0b4d25011c8b6abce7499666fc4811e289501cb8c2b6f237c', token_count=247, vector_point_id='kc-kg-theory-social-penetration-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-penetration-2', 'kg-theory-social-penetration', 2, 'Altman و Taylor (1973) در مدل «کاغذ‌پیچ» (onion model) پیشنهاد کردند روابط از لایه‌های بیرونی (موضوعات سطحی) به لایه‌های درونی (موضوعات عمیق و شخصی) نفوذ می‌کنند و این فرآیند، خوداشکاف‌تدریجی و متقابل است.', '5319d27e0601d02355bc702cf09ebc5dd5a7801be3cfdf1f107da8a8c20bb304', 372, 'kc-kg-theory-social-penetration-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5319d27e0601d02355bc702cf09ebc5dd5a7801be3cfdf1f107da8a8c20bb304', token_count=372, vector_point_id='kc-kg-theory-social-penetration-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-penetration-3', 'kg-theory-social-penetration', 3, '["روابط از لایه‌های بیرونی به درونی نفوذ می‌کنند","خوداشکاف، فرآیند متقابل و تدریجی است","نفوذ، کیفیت رابطه را افزایش می‌دهد"]', 'aaeb144a40d4b47fe92c49f09b47e66fd47e5931674f4351f6e30266f5ff8868', 229, 'kc-kg-theory-social-penetration-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='aaeb144a40d4b47fe92c49f09b47e66fd47e5931674f4351f6e30266f5ff8868', token_count=229, vector_point_id='kc-kg-theory-social-penetration-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-penetration-4', 'kg-theory-social-penetration', 4, '["Irwin Altman","Dalmas Taylor"]', '985c9d4e4f0d7bfce7a94661d496f3ab9a9e7308776d80f79a4a5f5e0e790ea0', 58, 'kc-kg-theory-social-penetration-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='985c9d4e4f0d7bfce7a94661d496f3ab9a9e7308776d80f79a4a5f5e0e790ea0', token_count=58, vector_point_id='kc-kg-theory-social-penetration-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
