INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-social-penetration-7', 'kg-theory-social-penetration', 7, '["Altman & Taylor, 1973 - Social Penetration: The Development of Interpersonal Relationships"]', 'ea0f9796c25e2972cddaa0f4603d5abf8bcf8aa985e4106f1f132968f320b4ed', 170, 'kc-kg-theory-social-penetration-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ea0f9796c25e2972cddaa0f4603d5abf8bcf8aa985e4106f1f132968f320b4ed', token_count=170, vector_point_id='kc-kg-theory-social-penetration-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-spiral-silence-0', 'kg-theory-spiral-silence', 1, 'نظریه مارپیچ سکوت (Spiral of Silence Theory) نوع: THEORY نظریه‌ای که می‌گوید افراد در مواجهه با «رأی عمومی» که بر خلاف نظر خودشان حس می‌کنند، در بیان آن بازمی‌مانند (سکوت می‌کنند).', 'a56645c5b4ae6d77e2347b8ff4516afa9549ce15ba9db4106938fba764cba536', 327, 'kc-kg-theory-spiral-silence-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a56645c5b4ae6d77e2347b8ff4516afa9549ce15ba9db4106938fba764cba536', token_count=327, vector_point_id='kc-kg-theory-spiral-silence-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-spiral-silence-2', 'kg-theory-spiral-silence', 2, 'Noelle-Neumann (1974) در بحث سیاست‌های نازی و در ادامه مطالعات خود نشان دادند افراد تمایل دارند نظر خود را بیان کنند اگر آن را رایج بدانند و در غیر این صورت سکوت کنند؛ این پدیده یک «مارپیچ» می‌سازد.', '9ed561d4dc584a1ee615392a8cee5354948c55112b57f193a30cca875efc2e11', 359, 'kc-kg-theory-spiral-silence-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9ed561d4dc584a1ee615392a8cee5354948c55112b57f193a30cca875efc2e11', token_count=359, vector_point_id='kc-kg-theory-spiral-silence-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-spiral-silence-3', 'kg-theory-spiral-silence', 3, '["افراد در صورت احساس اقلیت‌بودن سکوت می‌کنند","این سکوت، اکثریت‌سازی ظاهری و تقویت رای غالب می‌سازد","ترس از انزجار اجتماعی نیروی محرک است"]', '0ae77736eebc837a1cfcb45cc4f627214f988de96e1f330f619698cdad9474b6', 256, 'kc-kg-theory-spiral-silence-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0ae77736eebc837a1cfcb45cc4f627214f988de96e1f330f619698cdad9474b6', token_count=256, vector_point_id='kc-kg-theory-spiral-silence-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-spiral-silence-4', 'kg-theory-spiral-silence', 4, '["Elisabeth Noelle-Neumann"]', 'f7ed40e8c4cbcdbc1998bb4264200e95288af5ff085b20b7c0e715bb4921df99', 50, 'kc-kg-theory-spiral-silence-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f7ed40e8c4cbcdbc1998bb4264200e95288af5ff085b20b7c0e715bb4921df99', token_count=50, vector_point_id='kc-kg-theory-spiral-silence-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
