INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-third-person-0', 'kg-theory-third-person', 1, 'نظریه اثر شخص ثالث (Third-Person Effect Theory) نوع: THEORY نظریه‌ای که می‌گوید مردم بر این باورند که پیام‌های رسانه‌ای بیشتر بر دیگران اثر می‌گذارند تا بر خودشان.', '4d383ef0555b06f8c19482441de50a139237a8e8af0f25e09911beb6836de0e5', 296, 'kc-kg-theory-third-person-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4d383ef0555b06f8c19482441de50a139237a8e8af0f25e09911beb6836de0e5', token_count=296, vector_point_id='kc-kg-theory-third-person-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-third-person-2', 'kg-theory-third-person', 2, 'Davison (1983) این پدیده را در زمینه‌ی تبلیغات و خشونت رسانه‌ای شناسایی کرد؛ افراد اثر پیام‌های رسانه‌ای را بیشتر بر «شخص ثالث» (دیگران) حس می‌کنند تا بر خودشان. این باور می‌تواند حمایت از خودسنسور و محدودیت‌های رسانه را توجیه کند.', '785df3186016757b07ed9327a2be1a7396715308d64d36f1773f02d4daf4b6e6', 419, 'kc-kg-theory-third-person-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='785df3186016757b07ed9327a2be1a7396715308d64d36f1773f02d4daf4b6e6', token_count=419, vector_point_id='kc-kg-theory-third-person-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-third-person-3', 'kg-theory-third-person', 3, '["افراد اثر رسانه را بیشتر بر دیگران می‌بینند تا بر خود","این باور، حمایت از محدودیت‌های رسانه و خودسنسور را تقویت می‌کند","ریشه در سوگیری‌های شناختی (مثلاً تعصب و خودمحوری)"]', 'ab26715c06a6b235797138e48cb09e71ccf077c6e0c530b2c9ca14844667bed2', 318, 'kc-kg-theory-third-person-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ab26715c06a6b235797138e48cb09e71ccf077c6e0c530b2c9ca14844667bed2', token_count=318, vector_point_id='kc-kg-theory-third-person-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-third-person-4', 'kg-theory-third-person', 4, '["Walter Davison"]', 'bb2786516ca318c1f66ad6a7608bda6305164c7786b0247cc48f7f6466545e07', 32, 'kc-kg-theory-third-person-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bb2786516ca318c1f66ad6a7608bda6305164c7786b0247cc48f7f6466545e07', token_count=32, vector_point_id='kc-kg-theory-third-person-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
