INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-third-person-7', 'kg-theory-third-person', 7, '["Davison, 1983 - The Third Person Perspective in Communication Research"]', '73073a83f4fdb62c4b4c6009fc884e28833edfd4b8784fb7d7428a6e7c33562e', 134, 'kc-kg-theory-third-person-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='73073a83f4fdb62c4b4c6009fc884e28833edfd4b8784fb7d7428a6e7c33562e', token_count=134, vector_point_id='kc-kg-theory-third-person-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-two-step-0', 'kg-theory-two-step', 1, 'نظریه جریان دومرحله‌ای ارتباطات (Two-Step Flow of Communication Theory) نوع: THEORY نظریه‌ای که اثر رسانه را دو مرحله‌ای می‌داند: ابتدا از رسانه به رهبران افکار، سپس از رهبران افکار به مخاطبان.', '857d569f70187a6c7ca20578ed57b901bfe71c025ea42cff59bde9b4e4bf5504', 350, 'kc-kg-theory-two-step-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='857d569f70187a6c7ca20578ed57b901bfe71c025ea42cff59bde9b4e4bf5504', token_count=350, vector_point_id='kc-kg-theory-two-step-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-two-step-2', 'kg-theory-two-step', 2, 'Lazarsfeld و همکاران در مطالعه‌ی ۱۹۴۴ درباره‌ی رای‌آوری انتخابات (People''s Choice) نشان دادند پیام رسانه به‌جای مستقیم، از طریق «رهبران افکار» (opinion leaders) به مخاطبان می‌رسد و این رهبران پیام را تفسیر و بازتولید می‌کنند.', 'eb8ea3f5296839cdaf20b18a424e3d8e5cd4779f9b451532eae920f9190d1b1f', 409, 'kc-kg-theory-two-step-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='eb8ea3f5296839cdaf20b18a424e3d8e5cd4779f9b451532eae920f9190d1b1f', token_count=409, vector_point_id='kc-kg-theory-two-step-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-two-step-3', 'kg-theory-two-step', 3, '["مخاطب ابتدا از رهبرافکار می‌پذیرد، نه مستقیماً از رسانه","رهبران افکار پیام را تفسیر و فیلتر می‌کنند","اثرات اجتماعی رسانه واسطه‌گرایانه است"]', '1bdf57e1f3c352f3ffa5769bd4c1ef66630a2d5af6a9d87a42a6aef30a08b57e', 261, 'kc-kg-theory-two-step-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='1bdf57e1f3c352f3ffa5769bd4c1ef66630a2d5af6a9d87a42a6aef30a08b57e', token_count=261, vector_point_id='kc-kg-theory-two-step-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-two-step-4', 'kg-theory-two-step', 4, '["Paul Lazarsfeld","Robert Merton","Bernard Berelson"]', '53ee17820171f9a876ba3e7efb38cb41a4529ac188f95c69efc1dc49e4b47214', 98, 'kc-kg-theory-two-step-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='53ee17820171f9a876ba3e7efb38cb41a4529ac188f95c69efc1dc49e4b47214', token_count=98, vector_point_id='kc-kg-theory-two-step-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
