INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-two-step-7', 'kg-theory-two-step', 7, '["Lazarsfeld, Berelson & Gaudet, 1944 - The People''s Choice"]', '2ceb01e78b2cfd3de53b95067fad5ee3617b5a4bc19d1c3335becbf69ede940a', 110, 'kc-kg-theory-two-step-7', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2ceb01e78b2cfd3de53b95067fad5ee3617b5a4bc19d1c3335becbf69ede940a', token_count=110, vector_point_id='kc-kg-theory-two-step-7', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-uncertainty-reduction-0', 'kg-theory-uncertainty-reduction', 1, 'نظریه کاهش عدم قطعیت (Uncertainty Reduction Theory) نوع: THEORY نظریه‌ای که فرآیند کاهش عدم قطعیت در شکل‌گیری روابط بین‌فردی را تبیین می‌کند.', '7eb684c1106e38b22e0f1626b2ba5c353859813ee104511782c56bd0f5e55048', 256, 'kc-kg-theory-uncertainty-reduction-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='7eb684c1106e38b22e0f1626b2ba5c353859813ee104511782c56bd0f5e55048', token_count=256, vector_point_id='kc-kg-theory-uncertainty-reduction-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-uncertainty-reduction-2', 'kg-theory-uncertainty-reduction', 2, 'Berger و Calabrese (1975) فرض کردند وقتی دو فرد تازه‌یاب با هم تعامل می‌کنند، هدف اصلی آن‌ها کاهش عدم قطعیت درباره‌ی یکدیگر است و برای این کار از راهبردهای مختلف (پاسیو، فعال، تعاملی) استفاده می‌کنند.', 'fa2e2551bf086a581414989c3362e5cdc1503dbc75ce01bb1a0a4ef3a96a0fcb', 363, 'kc-kg-theory-uncertainty-reduction-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fa2e2551bf086a581414989c3362e5cdc1503dbc75ce01bb1a0a4ef3a96a0fcb', token_count=363, vector_point_id='kc-kg-theory-uncertainty-reduction-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-uncertainty-reduction-3', 'kg-theory-uncertainty-reduction', 3, '["افراد در شکل‌گیری رابطه، تمایل دارند عدم قطعیت را کاهش دهند","کاهش عدم قطعیت، پیش‌بینی‌پذیری رفتار طرف مقابل را افزایش می‌دهد","راهبردهای مختلف برای کاهش عدم قطعیت وجود دارد"]', 'e8de6e6e8b23a61a1e26dad1c96a386e3b9718a76624df6c829c0136b9dac31c', 321, 'kc-kg-theory-uncertainty-reduction-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e8de6e6e8b23a61a1e26dad1c96a386e3b9718a76624df6c829c0136b9dac31c', token_count=321, vector_point_id='kc-kg-theory-uncertainty-reduction-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-uncertainty-reduction-4', 'kg-theory-uncertainty-reduction', 4, '["Charles Berger","Richard Calabrese"]', '667261784fc437e0724d244bdd46c408ceb6a20472ba9fac14b35af712a62d85', 69, 'kc-kg-theory-uncertainty-reduction-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='667261784fc437e0724d244bdd46c408ceb6a20472ba9fac14b35af712a62d85', token_count=69, vector_point_id='kc-kg-theory-uncertainty-reduction-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-uncertainty-reduction-5', 'kg-theory-uncertainty-reduction', 5, '1975-1990', '62bf12f893508b2edc6028659e5215ea4192a4a31b756af3b78a42b00d59dfed', 16, 'kc-kg-theory-uncertainty-reduction-5', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='62bf12f893508b2edc6028659e5215ea4192a4a31b756af3b78a42b00d59dfed', token_count=16, vector_point_id='kc-kg-theory-uncertainty-reduction-5', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-uncertainty-reduction-6', 'kg-theory-uncertainty-reduction', 6, 'آمریکا', '75a08574f6b41d316d5c915494c8ce566e1270189177f02e7d155e4e54fe8525', 10, 'kc-kg-theory-uncertainty-reduction-6', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='75a08574f6b41d316d5c915494c8ce566e1270189177f02e7d155e4e54fe8525', token_count=10, vector_point_id='kc-kg-theory-uncertainty-reduction-6', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
