INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-uses-and-gratifications-0', 'kg-theory-uses-and-gratifications', 1, 'نظریه استفاده و رضامندی (Uses and Gratifications Theory) نوع: THEORY نظریه‌ای که از مخاطب‌محوری استفاده می‌کند و می‌پرسد مخاطب برای چه نیازها و رضامندی‌هایی از رسانه استفاده می‌کند.', 'ed0b77b401d9781bc24df55f9dc74c70358523fd14b2350267ffd64b2d45a25d', 329, 'kc-kg-theory-uses-and-gratifications-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ed0b77b401d9781bc24df55f9dc74c70358523fd14b2350267ffd64b2d45a25d', token_count=329, vector_point_id='kc-kg-theory-uses-and-gratifications-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-uses-and-gratifications-2', 'kg-theory-uses-and-gratifications', 2, 'برخلاف مدل‌های اثر-محور، این نظریه می‌پرسد «مخاطب با رسانه چه می‌کند؟» و فرض می‌کند مخاطب فعال است و برای برآورده‌سازی نیازهای شناختی، عاطفی و اجتماعی (مثل سرگرمی، اطلاعات، هویت‌سازی) رسانه را انتخاب می‌کند.', 'a8eb16f72394bed1b664180a16fb87b896c2935619da0ea5107299b4007aa706', 376, 'kc-kg-theory-uses-and-gratifications-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a8eb16f72394bed1b664180a16fb87b896c2935619da0ea5107299b4007aa706', token_count=376, vector_point_id='kc-kg-theory-uses-and-gratifications-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-uses-and-gratifications-3', 'kg-theory-uses-and-gratifications', 3, '["مخاطب فعال و هدفمند است","انتخاب رسانه پاسخ به نیازهای فردی است","اثر رسانه تابع استفاده است نه برعکس"]', 'ac6764675d0496bbb868c0e0919cbc250568c6bb545bc6dc2bb8f6091eda3525', 190, 'kc-kg-theory-uses-and-gratifications-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ac6764675d0496bbb868c0e0919cbc250568c6bb545bc6dc2bb8f6091eda3525', token_count=190, vector_point_id='kc-kg-theory-uses-and-gratifications-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-theory-uses-and-gratifications-4', 'kg-theory-uses-and-gratifications', 4, '["Katz, Blumler & Gurevitch","Katz","Elihu Katz"]', 'cd0f6503de4e862b50dc8dc0e9ec8fccc5c140dbd24afa800ff6b3adb82a2895', 89, 'kc-kg-theory-uses-and-gratifications-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='cd0f6503de4e862b50dc8dc0e9ec8fccc5c140dbd24afa800ff6b3adb82a2895', token_count=89, vector_point_id='kc-kg-theory-uses-and-gratifications-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
