INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-audience-0', 'kg-tradition-audience', 1, 'مطالعات مخاطب (Audience Studies) نوع: TRADITION زیرشاخه‌ی مکتب بیرمنگام که مخاطب را نه مصرف‌کنندة منفعل پیام، بلکه فعال معنایی می‌داند که با «رمزگشایی» موقعیت‌مند خود، پیام را می‌پذیرد، می‌چیند یا مقاومت می‌کند.', '42ddd2f05c5769f88a1c173c8a349379eec2b88930e0b9c09fd8df7a5ac1398a', 383, 'kc-kg-tradition-audience-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='42ddd2f05c5769f88a1c173c8a349379eec2b88930e0b9c09fd8df7a5ac1398a', token_count=383, vector_point_id='kc-kg-tradition-audience-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-audience-2', 'kg-tradition-audience', 2, 'مطالعات مخاطب در مکتب بیرمنگام با مدل «رمزگذاری-رمزگشایی» استیو هال شکل گرفت. مخاطب در سه موقعیت پاسخ می‌دهد: هژمونی (پذیرش)، منظم (تنظیم) و مقاومت. این رویکرد، در مقابل مدل‌های خطی اثرات رسانه (مکتب کلمبیا) ایستاده است.', 'a33cfd5edbb869e10e8f138d8f14af0b8f418608eaf6a9dee43efd6d2e1e208d', 399, 'kc-kg-tradition-audience-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a33cfd5edbb869e10e8f138d8f14af0b8f418608eaf6a9dee43efd6d2e1e208d', token_count=399, vector_point_id='kc-kg-tradition-audience-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
