INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-columbia-0', 'kg-tradition-columbia', 1, 'سنت پژوهش‌های کلمبیا (Columbia Research Tradition) نوع: TRADITION زیرشاخه‌ی سنت پژوهش تجربی که در دانشگاه کلمبیا (لازرسفیلد، لاظاروس، بازر) شکل گرفت و بر پیمایش، سنجش اثر و تحلیل محتوا تمرکز دارد.', '12b2ef6536cd86286c37ba4edd44fede0a4180dd7808572a58f4a7a97fbe57e4', 356, 'kc-kg-tradition-columbia-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='12b2ef6536cd86286c37ba4edd44fede0a4180dd7808572a58f4a7a97fbe57e4', token_count=356, vector_point_id='kc-kg-tradition-columbia-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-columbia-2', 'kg-tradition-columbia', 2, 'سنت کلمبیا (Columbia School) در ۱۹۴۰ها با پژوهش‌های لاظاروس (The People''s Truman) و لاتنهاور (Personal Influence) شکل گرفت. این سنت، بر پیمایش بزرگ‌مقیاس، سنجش اثر و تحلیل محتوا تمرکز دارد و پایه‌ی پژوهش‌های کمی در ارتباطات است.', 'c5bcda8636fa9a4705e89f7b4567f003764beb1bd27fb125b79d333c8d91c75e', 414, 'kc-kg-tradition-columbia-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c5bcda8636fa9a4705e89f7b4567f003764beb1bd27fb125b79d333c8d91c75e', token_count=414, vector_point_id='kc-kg-tradition-columbia-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
