INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-comm-sociology-0', 'kg-tradition-comm-sociology', 1, 'جامعه‌شناسی ارتباطات (Communication Sociology) نوع: TRADITION زیرشاخه‌ی مکتب شیکاگو که ارتباطات را نه صرفاً انتقال پیام، بلکه فرایند ساختن اجتماعی معنا و تعامل می‌داند و رسانه را در بافت تعاملات اجتماعی تحلیل می‌کند.', '6af28c8f847d71c4754de77608ff0b928f62bd19ba79a1c5394c93f3e0b1bf83', 392, 'kc-kg-tradition-comm-sociology-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='6af28c8f847d71c4754de77608ff0b928f62bd19ba79a1c5394c93f3e0b1bf83', token_count=392, vector_point_id='kc-kg-tradition-comm-sociology-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-comm-sociology-2', 'kg-tradition-comm-sociology', 2, 'جامعه‌شناسی ارتباطات در مکتب شیکاگو، ارتباطات را از «انتقال یک‌سویه‌ی پیام» به «تعامل اجتماعی و ساختن معنا» تغییر جهت داد. رسانه در این دیدگاه، عرصه‌ی تعامل و هماهنگ‌سازی اجتماعی است.', 'b5e205f0e3083a9087eb1c4179e52443843a3385d5b936e832a112e7181edb0b', 332, 'kc-kg-tradition-comm-sociology-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b5e205f0e3083a9087eb1c4179e52443843a3385d5b936e832a112e7181edb0b', token_count=332, vector_point_id='kc-kg-tradition-comm-sociology-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
