INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-content-analysis-0', 'kg-tradition-content-analysis', 1, 'سنت تحلیل محتوا (Content Analysis Tradition) نوع: TRADITION زیرشاخه‌ی سنت پژوهش تجربی که بر «تحلیل محتوا» (content analysis) به‌عنوان روش اصلی تحلیل کمّی پیام رسانه‌ای (تواتر، بافت، الگو) تمرکز دارد.', 'f01cb1f5ca0417f08270571fc91dc229f2b28a7c03bb8dd3ac4a0370c0a2dce0', 361, 'kc-kg-tradition-content-analysis-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f01cb1f5ca0417f08270571fc91dc229f2b28a7c03bb8dd3ac4a0370c0a2dce0', token_count=361, vector_point_id='kc-kg-tradition-content-analysis-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-content-analysis-2', 'kg-tradition-content-analysis', 2, 'سنت تحلیل محتوا (Content Analysis Tradition) از بارت و لاظاروس می‌آید. تحلیل محتوا، روش کمّی و سیستماتیک برای شمارش، طبقه‌بندی و تحلیل ویژگی‌های پیام رسانه‌ای (تواتر، بافت، الگو) است و در بیشتر پژوهش‌های کمّی ارتباطات کاربرد دارد.', '27fc841828d9d146d6f7b9d939d48742594e7afb38aeb302115d8ea0b5efee83', 418, 'kc-kg-tradition-content-analysis-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='27fc841828d9d146d6f7b9d939d48742594e7afb38aeb302115d8ea0b5efee83', token_count=418, vector_point_id='kc-kg-tradition-content-analysis-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
