INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-critical-race-0', 'kg-tradition-critical-race', 1, 'نظریه‌ی انتقادی نژاد در رسانه (Critical Race Media Theory) نوع: TRADITION زیرشاخه‌ی مکتب انتقادی که ابزارهای نظریه‌ی انتقادی را بر تحلیل نژاد، بازنمایی و قدرت در رسانه‌ها به‌کار می‌گیرد و نژاد را ساختاری بنیادین در سازمان‌دهی رسانه می‌داند.', '0d0e6b9d0bff668ce310390ddcac584f2a3a80c1fe0cf1a8fcf0855c08b69e09', 436, 'kc-kg-tradition-critical-race-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0d0e6b9d0bff668ce310390ddcac584f2a3a80c1fe0cf1a8fcf0855c08b69e09', token_count=436, vector_point_id='kc-kg-tradition-critical-race-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-critical-race-2', 'kg-tradition-critical-race', 2, 'نظریه‌ی انتقادی نژاد (Critical Race Theory) در رسانه، مفاهیم مکتب انتقادی — ایدئولوژی، سلطه، بازنمایی — را بر تحلیل نژاد اعمال می‌کند. این سنت می‌گوید نژاد نه ویژگی ثابت بلکه ساختار قدرت است و رسانه، دستگاهی برای بازنمایی، استیثما و بازتولید سلسله‌مراتب نژادی است.', 'f4faa876a0fbbde5c3f8f274b95ccfa74a64cb10d797c23989d58b41836300b5', 479, 'kc-kg-tradition-critical-race-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f4faa876a0fbbde5c3f8f274b95ccfa74a64cb10d797c23989d58b41836300b5', token_count=479, vector_point_id='kc-kg-tradition-critical-race-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
