INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-critical-studies-0', 'kg-tradition-critical-studies', 1, 'مطالعات انتقادی (Critical Studies) نوع: TRADITION خاندان فکری بین‌رشته‌ای که قدرت، سلطه، نابرابری و ایدئولوژی را در مرکز تحلیل قرار می‌دهد.', '8c588fdb63ef3ee46d3c923348dc8cfa39550ec701dbab92e756da22be1260db', 252, 'kc-kg-tradition-critical-studies-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='8c588fdb63ef3ee46d3c923348dc8cfa39550ec701dbab92e756da22be1260db', token_count=252, vector_point_id='kc-kg-tradition-critical-studies-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-critical-studies-2', 'kg-tradition-critical-studies', 2, 'مطالعات انتقادی (Fraser, Freire, Habermas, Giroux, Apple) از نظریه انتقادی فراکفورت و نظریه انتقادی نسل جدید (Bustos) گرفته تا مطالعات نژاد (Critical Race Theory)، جنسیت (Critical Gender Studies) و طبقه (Critical Class Studies) را در بر می‌گیرد. در رسانه، تحلیل انتقادی ایدئولوژی، بازنمایی و مالکیت رسانه محور اصلی است.', 'd9715e956f09c59825ae0a47904ba17fc4da1ef97959f3f0204f8723a4069ca4', 580, 'kc-kg-tradition-critical-studies-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d9715e956f09c59825ae0a47904ba17fc4da1ef97959f3f0204f8723a4069ca4', token_count=580, vector_point_id='kc-kg-tradition-critical-studies-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
