INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-critical-studies-13', 'kg-tradition-critical-studies', 13, '["Habermas (1968), Legitimation Crisis","Freire (1968), Pedagogy of the Oppressed","Giroux (1992), Border Crossings"]', 'ac139d7bffb896d7e0dd92edc6c1c8354a2241d03471f2dcf623f1b23779fbe8', 212, 'kc-kg-tradition-critical-studies-13', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ac139d7bffb896d7e0dd92edc6c1c8354a2241d03471f2dcf623f1b23779fbe8', token_count=212, vector_point_id='kc-kg-tradition-critical-studies-13', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-critical-theory-0', 'kg-tradition-critical-theory', 1, 'سنت انتقادی مارکسیستی (نظریه‌ی انتقادی) (Critical Theory (Marxist Critical Tradition)) نوع: TRADITION سنت فکریِ نقد اجتماعی که با تلفیق مارکسیسم و فلسفه‌ی قاره‌ای، به‌جای صرف توصیف و پیش‌بینی، هدفش بازسازی شرایط آزادی و نقد ایدئولوژی و سلطه است؛ هسته‌ی نظری مکتب فرانکفورت.', '48c709eead8f63941eefd86f73bd395903b1de3349328cf8ccefc71c1ab9b6cb', 496, 'kc-kg-tradition-critical-theory-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='48c709eead8f63941eefd86f73bd395903b1de3349328cf8ccefc71c1ab9b6cb', token_count=496, vector_point_id='kc-kg-tradition-critical-theory-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-critical-theory-2', 'kg-tradition-critical-theory', 2, 'نظریه‌ی انتقادی (Kritische Theorie) خودِ پروژه‌ی بنیادین مکتب فرانکفورت است: دانشی که نه صرفاً «واقعیت‌های موجود» را توصیف می‌کند، بلکه ساختارهای سلطه و ایدئولوژی را آشکار و زمینه‌های رهایی را می‌بیند. این سنت از اقتصاد سیاسی مارکسیسم می‌آید اما آن را با نقد عقلانیت و فرهنگ ترکیب می‌کند.', '2a29cba77e45c3cec646932a93933a44f4f805bc672db6678ebcb5a472fe5c0b', 523, 'kc-kg-tradition-critical-theory-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2a29cba77e45c3cec646932a93933a44f4f805bc672db6678ebcb5a472fe5c0b', token_count=523, vector_point_id='kc-kg-tradition-critical-theory-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-critical-theory-3', 'kg-tradition-critical-theory', 3, 'نظریه‌ی ارزش و تحلیل غریبه‌سازی در مارکسیسم، دیالکتیک هگل و نقد روشنگری در فلسفه‌ی آلمانی؛ هدف نهایی، «جامعه‌ی آزاد» از طریق خودآگاهی و نقد ایدئولوژی است.', 'd743bc3ea42d228841eefa67aeb855a2ff3c75dfbf4511f88e86301491587b42', 280, 'kc-kg-tradition-critical-theory-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='d743bc3ea42d228841eefa67aeb855a2ff3c75dfbf4511f88e86301491587b42', token_count=280, vector_point_id='kc-kg-tradition-critical-theory-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-critical-theory-4', 'kg-tradition-critical-theory', 4, '["دانش باید هدفمند (purposeful) باشد نه صرفاً توصیفی","نقد ایدئولوژی، پیش‌نیاز تغییر اجتماعی است","تغییر واقعی، تغییر ساختارهای مالکیت و سلطه است"]', '394c45a0ecccaee36d949a94d3acf29cd73e2c6e65a67c7ad2b4ff88d5e7ea26', 267, 'kc-kg-tradition-critical-theory-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='394c45a0ecccaee36d949a94d3acf29cd73e2c6e65a67c7ad2b4ff88d5e7ea26', token_count=267, vector_point_id='kc-kg-tradition-critical-theory-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
