INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-critical-theory-10', 'kg-tradition-critical-theory', 10, '["Horkheimer (1937). Traditional and Critical Theory","Habermas (1968). Knowledge and Human Interests"]', 'ac69c2a2cd1165584e3d1d1954f7f1c0554744f1293f8087b9d8fa2028856132', 187, 'kc-kg-tradition-critical-theory-10', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ac69c2a2cd1165584e3d1d1954f7f1c0554744f1293f8087b9d8fa2028856132', token_count=187, vector_point_id='kc-kg-tradition-critical-theory-10', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-decolonial-0', 'kg-tradition-decolonial', 1, 'مطالعات استعمارزدایی (Decolonial Studies) نوع: TRADITION زیرشاخه‌ی مکتب بیرمنگام و مطالعات پسااستعماری که بر شکستن «جهان‌بینی اروپامحور» در دانش و رسانه تمرکز دارد و «کانون تاریکی» (Dark Continuum) را در مرکز تحلیل قرار می‌دهد.', '12aab2ab8359945898f23488687604274aa54c34a8b6bbd730d9da4c08d81538', 412, 'kc-kg-tradition-decolonial-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='12aab2ab8359945898f23488687604274aa54c34a8b6bbd730d9da4c08d81538', token_count=412, vector_point_id='kc-kg-tradition-decolonial-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-decolonial-2', 'kg-tradition-decolonial', 2, 'مطالعات استعمارزدایی (Decolonial Studies) از میراث مطالعات پسااستعماری و اندیشمندان آمریکای لاتین (آنیلوواتو، لوی) می‌آید. رسانه در این دیدگاه، نه صرفاً بازتاب‌دهندة «دیگر»، بلکه تولیدکنندة سلسله‌مراتب دانش و زبان است و «استعمارزدایی رسانه» هدف آن است.', '9504bd72b76e43a8a206a58bf909413fca1ff417846ced7f2492837e55645615', 458, 'kc-kg-tradition-decolonial-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9504bd72b76e43a8a206a58bf909413fca1ff417846ced7f2492837e55645615', token_count=458, vector_point_id='kc-kg-tradition-decolonial-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
