INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-empirical-audience-0', 'kg-tradition-empirical-audience', 1, 'پژوهش‌های تجربی مخاطب (Empirical Audience Research) نوع: TRADITION زیرشاخه‌ی سنت پژوهش تجربی که با روش‌های کمّی (پیمایش، آزمون)، «اثرات» رسانه بر نگرش، آگاهی و رفتار مخاطب را اندازه‌گیری می‌کند.', '947ec5e0540cc6bf935079c9639236c3706593b63e6f1f5b77d930af87b17fbd', 352, 'kc-kg-tradition-empirical-audience-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='947ec5e0540cc6bf935079c9639236c3706593b63e6f1f5b77d930af87b17fbd', token_count=352, vector_point_id='kc-kg-tradition-empirical-audience-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
