INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-feminism-0', 'kg-tradition-feminism', 1, 'فمینیسم (Feminism) نوع: TRADITION خاندان فکری-سیاسی که نابرابری جنسیتی را در مرکز تحلیل قدرت، ایدئولوژی و رسانه قرار می‌دهد.', '50dd5fa90488ea1f9be1c08f884953c466fc491871df3d7e6d8e9f556658e02b', 225, 'kc-kg-tradition-feminism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='50dd5fa90488ea1f9be1c08f884953c466fc491871df3d7e6d8e9f556658e02b', token_count=225, vector_point_id='kc-kg-tradition-feminism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-feminism-2', 'kg-tradition-feminism', 2, 'فمینیسم (Wollstonecraft, Beauvoir, de Beauvoir, Hooks, hooks) در رسانه چهار جریان اصلی دارد: لیبرال (برابری حقوق)، رادیکال (نقد ساختار سرمایه‌داری-فرپدرنشینی)، سوسیالیستی (پیوند طبقاتی-جنسیتی) و پست‌مدرن (ساخت‌شدگی جنسیت و بازنمایی). هر جریان رویکرد متفاوتی به بازنمایی جنسیت در رسانه دارد.', '85201b8021f7fcbf0d5649e626a35e3cb25f2d3eac58d0820493bd123fa54a5e', 527, 'kc-kg-tradition-feminism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='85201b8021f7fcbf0d5649e626a35e3cb25f2d3eac58d0820493bd123fa54a5e', token_count=527, vector_point_id='kc-kg-tradition-feminism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
