INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-functionalism-0', 'kg-tradition-functionalism', 1, 'کارکردگرایی (Functionalism) نوع: TRADITION خاندان فکری اجتماعی-فلسفی که پدیده‌های اجتماعی و رسانه را از منظر نقش و کارکردشان در حفظ تعادل اجتماعی تفسیر می‌کند.', '31da8f8806a019c44f8682e9418fc32a8e0aa2df3d619cc1203acb306c58cd71', 289, 'kc-kg-tradition-functionalism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='31da8f8806a019c44f8682e9418fc32a8e0aa2df3d619cc1203acb306c58cd71', token_count=289, vector_point_id='kc-kg-tradition-functionalism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-functionalism-2', 'kg-tradition-functionalism', 2, 'کارکردگرایی (Comte, Spencer, Durkheim, Parsons) جامعه را سیستمی از بخش‌های متقابل-وابسته می‌داند که هر بخش کارکردی برای بقای کل دارد. در رسانه، «کارکردهای اطلاعاتی، هماهنگ‌سازی‌کننده، تفریحی و بازتولید هنجار» (Lasswell, Lasswell & Lasswell) کارکردهای اصلی رسانه برای نظم اجتماعی هستند.', 'b13d0fb3034dbbe1a83cbca1c7a6c13cc99f2666ec298792bcdd76399cb1bfea', 518, 'kc-kg-tradition-functionalism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b13d0fb3034dbbe1a83cbca1c7a6c13cc99f2666ec298792bcdd76399cb1bfea', token_count=518, vector_point_id='kc-kg-tradition-functionalism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
