INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-hegemony-0', 'kg-tradition-hegemony', 1, 'مطالعات هژمونی (Hegemony Studies) نوع: TRADITION زیرشاخه‌ی مکتب انتقادی که بر مفهوم گرامشی «هژمونی» تمرکز دارد: سلطه‌ی یک طبقه نه صرفاً با اجبار، بلکه با ساختن اجماع و «خود-evident»های فرهنگی.', '0aebea7cea63b8218cb7a780177d1025f9027f11dba3e9875d787e80d152de6d', 349, 'kc-kg-tradition-hegemony-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0aebea7cea63b8218cb7a780177d1025f9027f11dba3e9875d787e80d152de6d', token_count=349, vector_point_id='kc-kg-tradition-hegemony-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-hegemony-2', 'kg-tradition-hegemony', 2, 'هژمونی (Hegemony) در مفهوم آنتونیو گرامشی، سازوکاری است که طبقه‌ی حاکم، ارزش‌ها و «خود-evidنت‌های» خود را به‌عنوان باورهای کل جامعه بازنمایی می‌کند. رسانه‌ها اصلی‌ترین دستگاه بازتولید هژمونی‌اند و در تحلیل‌های مکتب انتقادی رسانه، نقش محوری بازی می‌کنند.', 'a0d694d1d8dcc3e44fefbe6a556c74776614944421ed01b28635f24bf0e1e623', 459, 'kc-kg-tradition-hegemony-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a0d694d1d8dcc3e44fefbe6a556c74776614944421ed01b28635f24bf0e1e623', token_count=459, vector_point_id='kc-kg-tradition-hegemony-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
