INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-hermeneutics-0', 'kg-tradition-hermeneutics', 1, 'هرمنوتیک (Hermeneutics) نوع: TRADITION خاندان فکری فلسفی-تفسیری که تفسیر (بازگویی) متون و پدیده‌های معنادار را در مرکز قرار می‌دهد.', 'a83e014c4b7447605c8663129f5ad95a9e9d742e61f120a632a262366e5aa0e7', 238, 'kc-kg-tradition-hermeneutics-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='a83e014c4b7447605c8663129f5ad95a9e9d742e61f120a632a262366e5aa0e7', token_count=238, vector_point_id='kc-kg-tradition-hermeneutics-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-hermeneutics-2', 'kg-tradition-hermeneutics', 2, 'هرمنوتیک (Schleiermacher, Dilthey, Heidegger, Gadamer, Ricœur) از «هنر تفسیر» به «علم تفسیر» و سپس به «مبنای فهم انسان» تحول یافت. در رسانه، هرمنوتیک ابزار فهم تفسیری معنای متون رسانه‌ای (متن، تصویر، ویدئو) در بافت تاریخی-فرهنگی مخاطب است.', '4b2cf50f678a96f95191fd1b9649bfeeb59ed90712348a49abc5d5cc2dd223a2', 434, 'kc-kg-tradition-hermeneutics-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4b2cf50f678a96f95191fd1b9649bfeeb59ed90712348a49abc5d5cc2dd223a2', token_count=434, vector_point_id='kc-kg-tradition-hermeneutics-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-hermeneutics-3', 'kg-tradition-hermeneutics', 3, 'اواسط قرن نوزدهم، آلمان.', '9a31a713255ad716e6980e588d2f50204173d64926c7f31187a2ab94c1ba5a0a', 43, 'kc-kg-tradition-hermeneutics-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='9a31a713255ad716e6980e588d2f50204173d64926c7f31187a2ab94c1ba5a0a', token_count=43, vector_point_id='kc-kg-tradition-hermeneutics-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
