INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-human-ecology-0', 'kg-tradition-human-ecology', 1, 'بوم‌شناسی انسانی (Human Ecology) نوع: TRADITION زیرشاخه‌ی مکتب شیکاگو که شهر را یک «بوم‌شناختی» (ecology) از محله‌ها و تعاملات می‌بیند و الگوهای پراکندگی و رقابت اجتماعی را شبیه پدیده‌های طبیعی تحلیل می‌کند.', '94651309b65e0672a210a8949118f8220f6f726654a7a6d0866461b5c02b9054', 376, 'kc-kg-tradition-human-ecology-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='94651309b65e0672a210a8949118f8220f6f726654a7a6d0866461b5c02b9054', token_count=376, vector_point_id='kc-kg-tradition-human-ecology-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-human-ecology-2', 'kg-tradition-human-ecology', 2, 'بوم‌شناسی انسانی (Human Ecology) در مکتب شیکاگو، شهر را شبیه یک اکوسیستم می‌بیند: محله‌ها رقابت، تخصصی‌شدن و تعادل اجتماعی دارند. این سنت از اثرات زیست‌شناسی تکاملی بر جامعه‌شناسی شهری است.', '0d885e1dd962ff516cfeb13b9462953115f9b4d6b7f78fde088c74ac7cd7b76f', 343, 'kc-kg-tradition-human-ecology-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0d885e1dd962ff516cfeb13b9462953115f9b4d6b7f78fde088c74ac7cd7b76f', token_count=343, vector_point_id='kc-kg-tradition-human-ecology-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
