INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-identity-0', 'kg-tradition-identity', 1, 'مطالعات هویت و تفاوت (Identity & Difference Studies) نوع: TRADITION زیرشاخه‌ی مکتب بیرمنگام که هویت (نژاد، جنسیت، جنسیت، طبقة، ملیت) را نه ذات ثابت بلکه ساختار بازنمایی‌شده می‌داند و تفاوت را عرصه‌ی قدرت تحلیل می‌کند.', '504cf901f9d7042d97893943bcbf675a4d2cb2887413c2267e68b04e790f052d', 394, 'kc-kg-tradition-identity-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='504cf901f9d7042d97893943bcbf675a4d2cb2887413c2267e68b04e790f052d', token_count=394, vector_point_id='kc-kg-tradition-identity-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-identity-2', 'kg-tradition-identity', 2, 'مطالعات هویت و تفاوت در مکتب بیرمنگام از استیو هال آغاز شد و با مطالعات پسااستعماری و فمینیستی هم‌افزایی یافت. هویت در این دیدگاه، محصول بازنمایی رسانه‌ای و گفتمان است و «ما/دیگر» در رسانه ساخته می‌شود.', '57d09d786fd0068d8de94d365291c028f5bb0e25a77f291716464e93eb05c716', 367, 'kc-kg-tradition-identity-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='57d09d786fd0068d8de94d365291c028f5bb0e25a77f291716464e93eb05c716', token_count=367, vector_point_id='kc-kg-tradition-identity-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
