INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-ideology-0', 'kg-tradition-ideology', 1, 'مطالعات ایدئولوژی (Ideology Studies) نوع: TRADITION زیرشاخه‌ی مکتب انتقادی که به بررسی چگونگی شکل‌گیری، بازتولید و نقد نظام‌های باور، معنا و خود-evident (taken-for-granted) می‌پردازد که سلطه را مشروع می‌سازند.', '98d8669c7d05d8b4e9f52bcee4fd7bb615a29cf9910b40bd13cdf025f77d25fd', 379, 'kc-kg-tradition-ideology-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='98d8669c7d05d8b4e9f52bcee4fd7bb615a29cf9910b40bd13cdf025f77d25fd', token_count=379, vector_point_id='kc-kg-tradition-ideology-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-ideology-2', 'kg-tradition-ideology', 2, 'مطالعات ایدئولوژی در چارچوب مکتب فرانکفورت و سنت مارکسیستی، رسانه را دستگاهی می‌بیند که «خود-evident»های قدرت را می‌سازد. این زیرشاخه از مارکس (آیینه‌سازی) تا آلتوسر (دستگاه‌های ایدئولوژیک) و آنتونیو گرامشی (هژمونی) امتداد دارد.', '3a0545dfee00cac5dfaf29cb0ff4e88624ddcaee1a90864e3e435d8743e913f8', 414, 'kc-kg-tradition-ideology-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3a0545dfee00cac5dfaf29cb0ff4e88624ddcaee1a90864e3e435d8743e913f8', token_count=414, vector_point_id='kc-kg-tradition-ideology-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
