INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-interactionism-0', 'kg-tradition-interactionism', 1, 'کنش متقابل‌گرایی (Interactionism) نوع: TRADITION خاندان فکری خاسته از جامعه‌شناسی شیکاگو که تعاملات خردروان‌شناختی و نمادین را نقطه شروع فهم جامعه می‌داند.', '4c0cbc5a352e68d2b302b719bb6a38091ea19b054b3b01ff0981a002800c1c94', 281, 'kc-kg-tradition-interactionism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4c0cbc5a352e68d2b302b719bb6a38091ea19b054b3b01ff0981a002800c1c94', token_count=281, vector_point_id='kc-kg-tradition-interactionism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-interactionism-2', 'kg-tradition-interactionism', 2, 'کنش متقابل‌گرایی (Mead, Blumer, Blumer, Goffman) بر «تعامل‌گرایی نمادین» استوار است: معنا از طریق تعاملات نمادین (زبان، بدن، اشیاء) ساخته می‌شود. در رسانه، تعاملات روزمره مخاطب با رسانه (بازتولید، تفسیر، بازنمایی خودی) در مرکز تحلیل قرار می‌گیرد.', 'fa0afb70ecc4dc70f6b3cdba7638ee85091a449cbe4745131db3d48206be3fa1', 447, 'kc-kg-tradition-interactionism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='fa0afb70ecc4dc70f6b3cdba7638ee85091a449cbe4745131db3d48206be3fa1', token_count=447, vector_point_id='kc-kg-tradition-interactionism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
