INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-interpersonal-family-2', 'kg-tradition-interpersonal-family', 2, 'این سنت، الگوهای تکراری تعامل خانواده (مانند «دوگانه‌سازی» و «چرخه‌ی متقابل») را تحلیل می‌کند و در روان‌درمانی سیستمی کاربرد گسترده‌ای دارد.', '0787bda2d25509ba9e4bef364f403568f0aa73cd909d8d0afbbb3a519bdf87ef', 254, 'kc-kg-tradition-interpersonal-family-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='0787bda2d25509ba9e4bef364f403568f0aa73cd909d8d0afbbb3a519bdf87ef', token_count=254, vector_point_id='kc-kg-tradition-interpersonal-family-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
