INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-marxism-0', 'kg-tradition-marxism', 1, 'مارکسیسم و نئومارکسیسم (Marxism and Neo-Marxism) نوع: TRADITION خاندان فکری مبتنی بر نقد مادی‌تاریخی سرمایه‌داری که رسانه را زیرساخت ایدئولوژیک و ابزار تداوم روابط سلطه‌ای طبقاتی می‌بیند.', '46a213fd2969c3baccb48c4114f730ac3024f935f22bd98a38030c20a3b6afc6', 340, 'kc-kg-tradition-marxism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='46a213fd2969c3baccb48c4114f730ac3024f935f22bd98a38030c20a3b6afc6', token_count=340, vector_point_id='kc-kg-tradition-marxism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-marxism-2', 'kg-tradition-marxism', 2, 'مارکسیسم در تحلیل رسانه بر «عقلانی‌سازی سرمایه‌داری» (فریدمان/مارشال) و «کاراکترولوژی» (لوکاچ) تکیه دارد. نئومارکسیسم‌های آلتوسری (ایدئولوژی و دستگاه‌های ایدئولوژیک دولتی)، گرامشی‌ای (هژمونی و جبهه‌های مدنی) و مارکوزه‌ای (فرهنگ توده) رسانه را نه عین، بلکه بخشی از ایدئولوژی و کنترل اجتماعی تحلیل می‌کنند.', '4d2cbb88cc91765016b220c8e6fc5c14becb44625a54172c04a5f488a27bb9b9', 552, 'kc-kg-tradition-marxism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='4d2cbb88cc91765016b220c8e6fc5c14becb44625a54172c04a5f488a27bb9b9', token_count=552, vector_point_id='kc-kg-tradition-marxism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-marxism-3', 'kg-tradition-marxism', 3, 'ریشه‌ها: مارکس (1840s)، لنین (1900s)؛ بازخوانی‌های نئومارکسیستی 1960-80.', '78f0ff8d138526feea0911a84470bd8b9e74d1cf40dcf74f9fc1f8816a0b0fde', 130, 'kc-kg-tradition-marxism-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='78f0ff8d138526feea0911a84470bd8b9e74d1cf40dcf74f9fc1f8816a0b0fde', token_count=130, vector_point_id='kc-kg-tradition-marxism-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-marxism-4', 'kg-tradition-marxism', 4, 'مادی‌تاریخ، نظریه ایدئولوژی، نظریه ارزش اضافی و فراساختار.', '617f353b0abbdf57dbca7662ccc9d5c08a413b4332fb2a8dc1a3e6d1a2a7ad63', 105, 'kc-kg-tradition-marxism-4', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='617f353b0abbdf57dbca7662ccc9d5c08a413b4332fb2a8dc1a3e6d1a2a7ad63', token_count=105, vector_point_id='kc-kg-tradition-marxism-4', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
