INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-network-theory-0', 'kg-tradition-network-theory', 1, 'نظریه‌های شبکه (Network Theories) نوع: TRADITION خاندان فکری بین‌رشته‌ای که پدیده‌های اجتماعی را به‌عنوان شبکه‌هایی از گره‌ها و پیوندها تحلیل می‌کند.', '696ed231fe805c2becfc63776a58ba20fc25416bb7c85bb5274d4c2cd857e95c', 270, 'kc-kg-tradition-network-theory-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='696ed231fe805c2becfc63776a58ba20fc25416bb7c85bb5274d4c2cd857e95c', token_count=270, vector_point_id='kc-kg-tradition-network-theory-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-network-theory-2', 'kg-tradition-network-theory', 2, 'نظریه‌های شبکه (Granovetter, Wellman, Barabasi, Castells, Wasserman) از سه ریشه سرچشمه می‌گیرند: (1) ریاضی گراف (Graph Theory)، (2) جامعه‌شناسی شبکه (Granovetter 1973 «پاداش‌های پیوندهای ضعیف»، Wellman) و (3) جامعه شبکه‌ای (Castells 1996). در رسانه، تحلیل شبکه‌های اجتماعی، الگوریتم‌های انتشار و «مرکزیت» (centrality) کاربردهای اصلی این خاندان است.', '092dcb69debcee89f5bb38be1bd770b4fb7b1174c7b32996cb94a24d9b67b965', 632, 'kc-kg-tradition-network-theory-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='092dcb69debcee89f5bb38be1bd770b4fb7b1174c7b32996cb94a24d9b67b965', token_count=632, vector_point_id='kc-kg-tradition-network-theory-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
