INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-phenomenology-0', 'kg-tradition-phenomenology', 1, 'پدیدارشناسی (Phenomenology) نوع: TRADITION خاندان فکری فلسفی-اجتماعی که «پدیدارها را همان‌طور که ظاهر می‌شوند» بررسی می‌کند و تجربه زیسته را منبع اصلی معرفت می‌داند.', '5ab82b5811ad943440e0e5a11d61fa9354a093d9591aff928a035287337fe153', 300, 'kc-kg-tradition-phenomenology-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='5ab82b5811ad943440e0e5a11d61fa9354a093d9591aff928a035287337fe153', token_count=300, vector_point_id='kc-kg-tradition-phenomenology-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-phenomenology-2', 'kg-tradition-phenomenology', 2, 'پدیدارشناسی (Husserl, Heidegger, Schutz, Merleau-Ponty) از «پارانتز» (epoché) و «طرح‌به‌پشت‌گذاشتن پیش‌فرض‌ها» برای بازگشت به چیزهای خود آغاز می‌شود. در علوم اجتماعی (شوتز) تجربه زیسته، «جهان اجتماعی» و «فهم متقابل» (intersubjectivity) مبانی تحلیل رسانه به‌عنوان بخشی از جهان زیسته مخاطب می‌شوند.', 'c57b36346cd117346a9ead28299f6ec10514ada421a3f8be202534a2ac18c359', 538, 'kc-kg-tradition-phenomenology-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c57b36346cd117346a9ead28299f6ec10514ada421a3f8be202534a2ac18c359', token_count=538, vector_point_id='kc-kg-tradition-phenomenology-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-phenomenology-3', 'kg-tradition-phenomenology', 3, 'اوایل قرن بیستم، اتریش و آلمان.', 'b6d3e350671e1c6aac689f9205cee6a5742fec20238799df9f2d2364c6368ff0', 56, 'kc-kg-tradition-phenomenology-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='b6d3e350671e1c6aac689f9205cee6a5742fec20238799df9f2d2364c6368ff0', token_count=56, vector_point_id='kc-kg-tradition-phenomenology-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
