INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-phenomenology-14', 'kg-tradition-phenomenology', 14, '["Husserl (1913), Ideas I","Heidegger (1927), Being and Time","Schutz (1932), The Phenomenology of the Social World","Merleau-Ponty (1945), Phenomenology of Perception"]', 'f11099af21ba9e2f820fbbffd0c110dd0cb513bebd71e6a2f9be10fc1806db61', 307, 'kc-kg-tradition-phenomenology-14', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f11099af21ba9e2f820fbbffd0c110dd0cb513bebd71e6a2f9be10fc1806db61', token_count=307, vector_point_id='kc-kg-tradition-phenomenology-14', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-post-structuralism-0', 'kg-tradition-post-structuralism', 1, 'پساساختارگرایی (Post-structuralism) نوع: TRADITION زیرشاخه‌ی سنت ساختارگرایی که «ثبات» ساختار و «مرکز» معنا را به چالش می‌کشد؛ دریدا (محو بودن)، فوکو (قدرت-دانش) و بارت (مرگ نویسنده) از چهره‌های اصلی آن‌اند.', 'e083c74c563534a4a1debd00f0b8ac732ddeba487f9bdab0b49bdca8294d1fd2', 376, 'kc-kg-tradition-post-structuralism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e083c74c563534a4a1debd00f0b8ac732ddeba487f9bdab0b49bdca8294d1fd2', token_count=376, vector_point_id='kc-kg-tradition-post-structuralism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-post-structuralism-2', 'kg-tradition-post-structuralism', 2, 'پساساختارگرایی (Post-structuralism) از دریدا (1960s) و فوکو (1970s) و بارت (1967، «مرگ نویسنده») شکل گرفت. این سنت، «ثبات» ساختار و «مرکز» معنا را به چالش می‌کشد: معنا «محو» (différance) است و قدرت، نه صرفاً ساختار بلکه «رابطه» است.', 'ae799ead582c5726705f6f11df1945d18da3980142228150eca6bf366cd19eaf', 421, 'kc-kg-tradition-post-structuralism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ae799ead582c5726705f6f11df1945d18da3980142228150eca6bf366cd19eaf', token_count=421, vector_point_id='kc-kg-tradition-post-structuralism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
