INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-postcolonial-0', 'kg-tradition-postcolonial', 1, 'مطالعات پسااستعماری (Postcolonial Studies) نوع: TRADITION زیرشاخه‌ی مکتب بیرمنگام و مطالعات فرهنگی که به بررسی میراث استعمار، بازنمایی شرق و غرب و ساختن هویت‌های استعماری/پسااستعماری در رسانه می‌پردازد.', 'dbfd5f3a1008f97278cd3a7da83c0406aee97163667de20887df4f90705f451a', 367, 'kc-kg-tradition-postcolonial-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='dbfd5f3a1008f97278cd3a7da83c0406aee97163667de20887df4f90705f451a', token_count=367, vector_point_id='kc-kg-tradition-postcolonial-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-postcolonial-2', 'kg-tradition-postcolonial', 2, 'مطالعات پسااستعماری در مطالعات فرهنگی بریتانیا از استیو هال و اثرگذاری ادوارد ساید (شرق‌شناسی) شکل گرفت. رسانه در این دیدگاه، دستگاهی برای بازنمایی «دیگر» و بازتولید سلسله‌مراتب استعماری است و هویت‌های ملی و فراملی در بازنمایی رسانه‌ای ساخته می‌شوند.', 'ecb6913dbe6fb5db395228a9c0efa080d80a8f42e56a1e9a5cf6628d5c44cc09', 454, 'kc-kg-tradition-postcolonial-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ecb6913dbe6fb5db395228a9c0efa080d80a8f42e56a1e9a5cf6628d5c44cc09', token_count=454, vector_point_id='kc-kg-tradition-postcolonial-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
