INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-postcolonialism-0', 'kg-tradition-postcolonialism', 1, 'پسااستعمارگرایی (Postcolonialism) نوع: TRADITION خاندان فکری بین‌رشته‌ای که میراث استعمار را در بازنمایی، ایدئولوژی و رسانه تحلیل می‌کند.', '3179913f0e5b8bf8d1455f422f01367c42ad0f7526dbb0d39b542210e7253643', 249, 'kc-kg-tradition-postcolonialism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='3179913f0e5b8bf8d1455f422f01367c42ad0f7526dbb0d39b542210e7253643', token_count=249, vector_point_id='kc-kg-tradition-postcolonialism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-postcolonialism-2', 'kg-tradition-postcolonialism', 2, 'پسااستعمارگرایی (Said, Spivak, Bhabha, Hall, Mignolo) بر سه محور استوار است: (1) نقد «شرق‌شناسی» و بازنمایی استعماری (Said 1978)، (2) نقد «صداهای قابل درک‌پذیر» و حاشیه‌نشینی (Spivak 1988) و (3) «فضای میانی» و آمایگمه (Bhabha 1994). در رسانه، بازنمایی جنوب، جریان‌های رسانه‌ای شمال-جنوب و نظریه امپریالیسم فرهنگی در مرکز تحلیل قرار می‌گیرند.', '95b9b62361ad6d4b4f7e53f9712f23943c046e9b80dcec0cba8b823fa8af86fe', 620, 'kc-kg-tradition-postcolonialism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='95b9b62361ad6d4b4f7e53f9712f23943c046e9b80dcec0cba8b823fa8af86fe', token_count=620, vector_point_id='kc-kg-tradition-postcolonialism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
