INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-postmodernism-0', 'kg-tradition-postmodernism', 1, 'پست‌مدرنیسم (Postmodernism) نوع: TRADITION زیرشاخه‌ی سنت پست‌مدرن که «روایت‌های کلان» را به چالش می‌کشد و فرهنگ معاصر را «مستعار» (pastiche) و «استدلال» (parody) و «بدون مرکز» می‌داند.', '2abe6c697958b8e1c267bfac71fa34acfb22a7c3b4573b1c8370c22fbb5b317c', 334, 'kc-kg-tradition-postmodernism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='2abe6c697958b8e1c267bfac71fa34acfb22a7c3b4573b1c8370c22fbb5b317c', token_count=334, vector_point_id='kc-kg-tradition-postmodernism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-postmodernism-2', 'kg-tradition-postmodernism', 2, 'پست‌مدرنیسم (Postmodernism) از لیوتار (1979) و جیمزون (1991) شکل گرفت. این سنت، «روایت‌های کلان» (پیشرفت، آزادی، حقیقت) را به چالش می‌کشد و فرهنگ معاصر را «بدون مرکز»، «مستعار» و «استدلال‌گونه» می‌داند.', '50efc0a5c49fe5c4f73719366507a9c24e8281bc68f03a7f28cd800ca8fb97d8', 367, 'kc-kg-tradition-postmodernism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='50efc0a5c49fe5c4f73719366507a9c24e8281bc68f03a7f28cd800ca8fb97d8', token_count=367, vector_point_id='kc-kg-tradition-postmodernism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
