INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-pragmatism-0', 'kg-tradition-pragmatism', 1, 'پراگماتیسم (Pragmatism) نوع: TRADITION خاندان فکری آمریکایی که معنای مفاهیم را از پیامدهای عملی آن‌ها می‌سنجد و «عمل» را معیار معرفت می‌داند.', 'c6fa75f204b154656bd08c38d19a684b8ad12d03716eeaf8c302a43886ee0843', 256, 'kc-kg-tradition-pragmatism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='c6fa75f204b154656bd08c38d19a684b8ad12d03716eeaf8c302a43886ee0843', token_count=256, vector_point_id='kc-kg-tradition-pragmatism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-pragmatism-2', 'kg-tradition-pragmatism', 2, 'پراگماتیسم (Peirce, James, Dewey) بر «عمل‌گرایی»، «ابزارگرایی» و «حل مسئله» استوار است. در رسانه، پراگماتیسم رویکردی کاربردی به تحلیل پیام‌رسانی (نقش عملی پیام در تغییر رفتار) و پژوهش‌محور (پژوهش کاربردی، حل مسئله) است.', 'aacb6aea7cca5b1e84cbb193d3badb549619d4aca601ee45abadf5511ebf30a6', 398, 'kc-kg-tradition-pragmatism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='aacb6aea7cca5b1e84cbb193d3badb549619d4aca601ee45abadf5511ebf30a6', token_count=398, vector_point_id='kc-kg-tradition-pragmatism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
