INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-sts-0', 'kg-tradition-sts', 1, 'مطالعات علم و فناوری (Science and Technology Studies (STS)) نوع: TRADITION خاندان فکری بین‌رشته‌ای که علم و فناوری را نه طبیعی بلکه ساخته‌شده اجتماعی-سیاسی تحلیل می‌کند.', '90b1f340b94b424541f110638cca6b0072184853b7f910a9793ec0d01fde4ee8', 307, 'kc-kg-tradition-sts-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='90b1f340b94b424541f110638cca6b0072184853b7f910a9793ec0d01fde4ee8', token_count=307, vector_point_id='kc-kg-tradition-sts-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-sts-2', 'kg-tradition-sts', 2, 'STS (Latour, Callon, Bijker, Pinch, Trevor, Collins, Shapin) بر سه اصل استوار است: (1) «علم اجتماعی است» (علم‌سنجی)، (2) «فناوری ساخته‌شده است» (فناوری‌سنجی) و (3) «نظریه کنشگر-شبکه» (ANT). در رسانه، تحلیل الگوریتم‌ها، هوش مصنوعی و «عاملیت الگوریتمی» از طریق STS امکان‌پذیر است.', 'f30daac3be36967a754c6c703a61c81c0e5472499366f4b400b1f0e63d8442d6', 505, 'kc-kg-tradition-sts-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='f30daac3be36967a754c6c703a61c81c0e5472499366f4b400b1f0e63d8442d6', token_count=505, vector_point_id='kc-kg-tradition-sts-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
