INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-subaltern-0', 'kg-tradition-subaltern', 1, 'مطالعات فرودستان (Subaltern / Working-Class Studies) نوع: TRADITION زیرشاخه‌ی مکتب بیرمنگام که فرهنگ و رسانه از زاویه‌ی طبقات فرودست و کارگران را تحلیل می‌کند و به «زیرفرهنگ» و «مقاومت» در لایه‌های پایین اجتماعی توجه دارد.', '26ca082bfc52f437cb0543da8df173f7fe4f816156b254258a78bebc963d0aff', 403, 'kc-kg-tradition-subaltern-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='26ca082bfc52f437cb0543da8df173f7fe4f816156b254258a78bebc963d0aff', token_count=403, vector_point_id='kc-kg-tradition-subaltern-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-subaltern-2', 'kg-tradition-subaltern', 2, 'مطالعات فرودستان (Subaltern Studies) در مکتب بیرمنگام، فرهنگ کارگری و «زیرفرهنگ»‌ها را به‌عنوان پاسخ و مقاومت طبقه‌ی فرودست می‌بیند. این سنت از آثار دیوید مورگن و کارل رایتر (Subcultures) می‌آید و با گرامشی (هژمونی) پیوند دارد.', '25c5a2492cd142215f7f86ea72238e01520b9bc0055d6eae23583f48fde4d8a0', 412, 'kc-kg-tradition-subaltern-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='25c5a2492cd142215f7f86ea72238e01520b9bc0055d6eae23583f48fde4d8a0', token_count=412, vector_point_id='kc-kg-tradition-subaltern-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
