INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-systems-theory-0', 'kg-tradition-systems-theory', 1, 'نظریه سیستم‌ها (Systems Theory) نوع: TRADITION خاندان فکری بین‌رشته‌ای که پدیده‌ها را به‌عنوان سیستم‌هایی از اجزای متقابل‌وابسته و بازخوردی تحلیل می‌کند.', '01cbe702704a3a7f9bcad9c918217d2bf26a47c105996f53d2a4294b8bb80d82', 278, 'kc-kg-tradition-systems-theory-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='01cbe702704a3a7f9bcad9c918217d2bf26a47c105996f53d2a4294b8bb80d82', token_count=278, vector_point_id='kc-kg-tradition-systems-theory-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-systems-theory-2', 'kg-tradition-systems-theory', 2, 'نظریه سیستم‌ها (Bertalanffy, Shannon, Wiener, Luhmann, Bateson) در علوم ارتباطات از دو مسیر ورود کرد: (1) سیبرنتیک و تئوری اطلاعات (Shannon & Weaver 1949) و (2) نظام‌های اجتماعی (Luhmann, Merton, Parsons). در رسانه، تحلیل «سیستم ارتباطی» (فرستنده، پیام، رسانه، گیرنده، نویز، بازخورد) و «سیستم‌های خودرؤیت‌بخش» (autopoietic) از مبانی این خاندان است.', 'ff4ccc54cd638c0a14d0b9fd6bc78d598c184193aed55f866fb0d293034c6768', 632, 'kc-kg-tradition-systems-theory-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='ff4ccc54cd638c0a14d0b9fd6bc78d598c184193aed55f866fb0d293034c6768', token_count=632, vector_point_id='kc-kg-tradition-systems-theory-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-systems-theory-3', 'kg-tradition-systems-theory', 3, 'اواسط قرن بیستم.', 'e6e56236b61093889268c4c8b3933913f004f3eaee33aafb0e39701bd176390e', 29, 'kc-kg-tradition-systems-theory-3', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e6e56236b61093889268c4c8b3933913f004f3eaee33aafb0e39701bd176390e', token_count=29, vector_point_id='kc-kg-tradition-systems-theory-3', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
