INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-technological-determinism-0', 'kg-tradition-technological-determinism', 1, 'جبرگرایی فناورانه (Technological Determinism) نوع: TRADITION زیرشاخه‌ی مکتب تورنتو که فناوری (به‌ویژه رسانه) را نیروی اصلی و مستقل تغییر اجتماعی می‌داند و ساختارهای اجتماعی را تابع فناوری می‌بیند.', '06ce9e7fbddbc5aa467c36783f6594f807d1d9fcb294dea5e340795598515111', 356, 'kc-kg-tradition-technological-determinism-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='06ce9e7fbddbc5aa467c36783f6594f807d1d9fcb294dea5e340795598515111', token_count=356, vector_point_id='kc-kg-tradition-technological-determinism-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-technological-determinism-2', 'kg-tradition-technological-determinism', 2, 'جبرگرایی فناورانه (Technological Determinism) در مکتب تورنتو، فناوری را «عامل مستقل» تغییر اجتماعی می‌داند: تغییر فناوری → تغییر ادراک → تغییر ساختار اجتماعی. این دیدگاه، نقد اصلی اقتصاد سیاسی رسانه (مکتب فرانکفورت) است.', 'e0005ea0b35cb1faca2c9fa143f9c888dbc4f159e545df43b33aa5913ac38bc8', 399, 'kc-kg-tradition-technological-determinism-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='e0005ea0b35cb1faca2c9fa143f9c888dbc4f159e545df43b33aa5913ac38bc8', token_count=399, vector_point_id='kc-kg-tradition-technological-determinism-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
