INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-theory-of-action-0', 'kg-tradition-theory-of-action', 1, 'نظریه کنش (Action Theory) نوع: TRADITION خاندان فکری فلسفی-جامعه‌شناختی که «کنش» (action) را واحد بنیادین تحلیل اجتماعی می‌داند.', 'bb207f3eb04dfbedd98b1b9b32a3221310a4dc89e8be0bfbf6f72f760475a946', 232, 'kc-kg-tradition-theory-of-action-0', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='bb207f3eb04dfbedd98b1b9b32a3221310a4dc89e8be0bfbf6f72f760475a946', token_count=232, vector_point_id='kc-kg-tradition-theory-of-action-0', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
INSERT INTO kg_chunks (id, entity_id, chunk_index, content, content_hash, token_count, vector_point_id, embedding_model, embedding_version) VALUES ('kc-kg-tradition-theory-of-action-2', 'kg-tradition-theory-of-action', 2, 'نظریه کنش (Schutz, Habermas, Giddens, Bourdieu) از پرسش «انسان چگونه در جهان عمل می‌کند؟» آغاز می‌شود. در رسانه، کنش مخاطب (انتخاب، تفسیر، بازتولید) نقطه آغاز تحلیل ارتباطات است؛ از کنش عقلانی تا کنش ارتباطی و ساختاری.', '48f62bdf930ed6d4d5f1c0d1907bd73c642cbf50912f140e2a297ae32601dbb0', 396, 'kc-kg-tradition-theory-of-action-2', 'Qwen3-Embedding-4B', '1') ON DUPLICATE KEY UPDATE content_hash='48f62bdf930ed6d4d5f1c0d1907bd73c642cbf50912f140e2a297ae32601dbb0', token_count=396, vector_point_id='kc-kg-tradition-theory-of-action-2', embedding_model='Qwen3-Embedding-4B', embedding_version='1';
